export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const palette = [
    { name: 'Red', hex: 0xff3b30 },
    { name: 'Orange', hex: 0xff9500 },
    { name: 'Yellow', hex: 0xffd60a },
    { name: 'Green', hex: 0x34c759 },
    { name: 'Cyan', hex: 0x22d3ee },
    { name: 'Blue', hex: 0x3b82ff },
    { name: 'Purple', hex: 0xaf52de },
    { name: 'Magenta', hex: 0xff2d92 },
  ];
  let index = 0;

  const current = new THREE.Color(palette[0].hex);
  const target = new THREE.Color(palette[0].hex);

  // Soft radial glow texture, generated synchronously
  const size = 64;
  const data = new Uint8Array(size * size * 4);
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = (x + 0.5) / size * 2 - 1;
      const dy = (y + 0.5) / size * 2 - 1;
      const d = Math.min(1, Math.sqrt(dx * dx + dy * dy));
      const a = Math.pow(1 - d, 2);
      const i = (y * size + x) * 4;
      data[i] = 255; data[i + 1] = 255; data[i + 2] = 255;
      data[i + 3] = Math.round(a * 255);
    }
  }
  const glowTex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  glowTex.needsUpdate = true;

  // Base
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.5, metalness: 0.6 });
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.095, 0.105, 0.03, 40), baseMat);
  base.name = 'ButtonBase';
  base.position.y = 0.015;
  root.add(base);

  // Glowing ring on the base
  const ringMat = new THREE.MeshStandardMaterial({ color: 0x111111, emissive: 0xffffff, emissiveIntensity: 1.2 });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.082, 0.005, 12, 48), ringMat);
  ring.rotation.x = Math.PI / 2;
  ring.position.y = 0.031;
  root.add(ring);

  // The button cap
  const capMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, emissive: 0xffffff, emissiveIntensity: 1.0, roughness: 0.25, metalness: 0.1,
  });
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.065, 0.07, 0.04, 40), capMat);
  cap.name = 'GlowButton';
  const capRestY = 0.05;
  cap.position.y = capRestY;
  root.add(cap);

  // Glow on the desk
  const discMat = new THREE.MeshBasicMaterial({
    map: glowTex, color: 0xffffff, transparent: true, opacity: 0.6,
    blending: THREE.AdditiveBlending, depthWrite: false,
  });
  const disc = new THREE.Mesh(new THREE.CircleGeometry(0.28, 40), discMat);
  disc.rotation.x = -Math.PI / 2;
  disc.position.y = 0.002;
  disc.raycast = () => {};
  root.add(disc);

  // Halo around the button
  const haloMat = new THREE.MeshBasicMaterial({
    map: glowTex, color: 0xffffff, transparent: true, opacity: 0.5,
    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
  });
  const halo = new THREE.Mesh(new THREE.PlaneGeometry(0.34, 0.34), haloMat);
  halo.position.y = 0.09;
  halo.raycast = () => {};
  root.add(halo);

  // Instruction panel
  const panel = ui(`
    <style>
      .card { flex-direction: column; align-items: center; gap: 8px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 28px; padding-right: 28px; border-radius: 20px; background-color: #1f2228; width: 460px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .name { color: #ff3b30; font-size: 40px; font-weight: 700; text-align: center; }
      .hint { color: #c9ced6; font-size: 22px; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Glow Button</span>
      <span class="name" id="name">Red</span>
      <span class="hint" id="hint">Press the button to change color</span>
    </div>`, { width: 0.34, position: [0, 0.25, -0.05] });
  root.add(panel.object3D);

  let pressT = 0;
  let pressCount = 0;

  traits(cap, {
    onPress: () => {
      pressCount++;
      index = (index + 1) % palette.length;
      const p = palette[index];
      target.setHex(p.hex);
      pressT = 1;
      panel.set('name', { text: p.name, color: '#' + target.getHexString() });
      panel.set('hint', { text: 'Pressed ' + pressCount + (pressCount === 1 ? ' time' : ' times') });
    },
  });
  panel.set('name', { color: '#' + target.getHexString() });

  return {
    root,
    update(time, delta) {
      current.lerp(target, Math.min(1, delta * 8));
      pressT = Math.max(0, pressT - delta * 4);

      const pulse = 0.9 + 0.25 * Math.sin(time * 2.0);
      const flash = pressT * 1.5;

      capMat.color.copy(current);
      capMat.emissive.copy(current);
      capMat.emissiveIntensity = pulse + flash;
      ringMat.emissive.copy(current);
      ringMat.emissiveIntensity = 1.0 + flash;

      discMat.color.copy(current);
      discMat.opacity = 0.45 + 0.1 * Math.sin(time * 2.0) + pressT * 0.3;
      haloMat.color.copy(current);
      haloMat.opacity = 0.35 + 0.1 * Math.sin(time * 2.0) + pressT * 0.35;
      const s = 1 + pressT * 0.2;
      halo.scale.set(s, s, 1);

      cap.position.y = capRestY - 0.018 * pressT;
    },
  };
}

