  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Helix parameters (enlarged, not to scale) ----
  const seq = 'ATGCGTACCTGAAGCTTCAGT'; // 21 base pairs = 2 full turns (10.5 bp per turn)
  const N = seq.length;
  const rise = 0.0145;                 // vertical distance between base pairs (m)
  const R = 0.05;                      // helix radius (m)
  const twist = (2 * Math.PI) / 10.5;  // rotation per base pair
  const strandOffset = 2.5;            // strand 2 sits ~143° around (major/minor groove)
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const baseColor = {
    A: new THREE.Color(0xff5a5a),
    T: new THREE.Color(0x4da3ff),
    G: new THREE.Color(0x4cd37a),
    C: new THREE.Color(0xffd34d),
  };

  const helix = new THREE.Group();
  helix.name = 'DNA';
  helix.position.set(0, 0.25, 0);
  root.add(helix);

  function strandPoint(s, offset, out) {
    const a = s * twist + offset;
    return out.set(R * Math.cos(a), (s - (N - 1) / 2) * rise, R * Math.sin(a));
  }

  // ---- Sugar-phosphate backbones (tubes) ----
  const backboneMats = [
    new THREE.MeshStandardMaterial({ color: 0xb9c2d0, roughness: 0.35, metalness: 0.2 }),
    new THREE.MeshStandardMaterial({ color: 0x8f9bb0, roughness: 0.35, metalness: 0.2 }),
  ];
  for (let k = 0; k < 2; k++) {
    const pts = [];
    for (let s = -0.5; s <= N - 0.5 + 1e-6; s += 0.25) {
      pts.push(strandPoint(s, k * strandOffset, new THREE.Vector3()));
    }
    const curve = new THREE.CatmullRomCurve3(pts);
    const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 220, 0.006, 8, false), backboneMats[k]);
    tube.name = k === 0 ? 'Backbone strand 1' : 'Backbone strand 2';
    helix.add(tube);
  }

  // ---- Base pairs: two coloured half-rungs per pair ----
  const rungGeo = new THREE.CylinderGeometry(0.0045, 0.0045, 1, 8);
  const rungMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 });
  const rungs = new THREE.InstancedMesh(rungGeo, rungMat, N * 2);
  rungs.name = 'Base pairs';
  const p1 = new THREE.Vector3(), p2 = new THREE.Vector3(), mid = new THREE.Vector3();
  const dir = new THREE.Vector3(), pos = new THREE.Vector3();
  const yAxis = new THREE.Vector3(0, 1, 0);
  const q = new THREE.Quaternion(), sc = new THREE.Vector3(), m = new THREE.Matrix4();

  function setHalf(index, from, to, color) {
    dir.subVectors(to, from);
    const len = dir.length();
    dir.normalize();
    q.setFromUnitVectors(yAxis, dir);
    pos.addVectors(from, to).multiplyScalar(0.5);
    sc.set(1, len, 1);
    m.compose(pos, q, sc);
    rungs.setMatrixAt(index, m);
    rungs.setColorAt(index, color);
  }
  for (let i = 0; i < N; i++) {
    strandPoint(i, 0, p1);
    strandPoint(i, strandOffset, p2);
    mid.addVectors(p1, p2).multiplyScalar(0.5);
    const b1 = seq[i];
    const b2 = comp[b1];
    setHalf(i * 2, p1, mid, baseColor[b1]);
    setHalf(i * 2 + 1, mid, p2, baseColor[b2]);
  }
  rungs.instanceMatrix.needsUpdate = true;
  rungs.instanceColor.needsUpdate = true;
  helix.add(rungs);

  // ---- Faint grab volume so the helix is easy to pinch ----
  const grabVol = new THREE.Mesh(
    new THREE.CylinderGeometry(0.075, 0.075, N * rise + 0.03, 20),
    new THREE.MeshBasicMaterial({ color: 0x88ccff, transparent: true, opacity: 0.07, depthWrite: false }),
  );
  grabVol.name = 'Grab volume';
  helix.add(grabVol);

  traits(helix, { grab: true });

  // ---- Info panel ----
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; width: 520px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; align-items: center; gap: 10px; }
      .chip { width: 22px; height: 22px; border-radius: 6px; }
      .lbl { color: #ffffff; font-size: 20px; }
      .btns { flex-direction: row; gap: 12px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
              border-radius: 12px; background-color: #3a3f48; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <div class="row">
        <div class="chip" style="background-color: #ff5a5a"></div><span class="lbl">A adenine</span>
        <div class="chip" style="background-color: #4da3ff"></div><span class="lbl">T thymine</span>
      </div>
      <div class="row">
        <div class="chip" style="background-color: #4cd37a"></div><span class="lbl">G guanine</span>
        <div class="chip" style="background-color: #ffd34d"></div><span class="lbl">C cytosine</span>
      </div>
      <span class="body" id="fact">Pinch the helix to pick it up and turn it. Each rung is a base pair: A with T, G with C.</span>
      <div class="btns">
        <button class="btn" id="next"><span class="btn-text">Next fact</span></button>
        <button class="btn2" id="spin"><span class="btn-text" id="spinTxt">Spin: on</span></button>
      </div>
    </div>`, { width: 0.28, position: [0.26, 0.25, 0], rotationY: -0.3 });
  root.add(info.object3D);

  const facts = [
    'A pairs with T using 2 hydrogen bonds; G pairs with C using 3, so G–C pairs are stronger.',
    'One full turn takes about 10.5 base pairs (≈ 3.4 nm). The real helix is only ≈ 2 nm wide.',
    'The two backbones are made of alternating sugar (deoxyribose) and phosphate groups.',
    'The strands are antiparallel: one runs 5′→3′, the other 3′→5′.',
    'The human genome has about 3.1 billion base pairs. This model shows just 21.',
    'Because of the pairing rules, one strand lets a cell rebuild the other when DNA is copied.',
  ];
  let factIndex = -1;
  info.on('next', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    info.set('fact', { text: facts[factIndex] });
  });

  let spinning = true;
  info.on('spin', 'click', () => {
    spinning = !spinning;
    info.set('spinTxt', { text: spinning ? 'Spin: on' : 'Spin: off' });
  });

  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) return;
      if (spinning) helix.rotateY(delta * 0.35);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Helix parameters (B-DNA, scaled up: 10 base pairs per turn) ----
  const N = 20;                 // base pairs (2 full turns)
  const rise = 0.0165;          // m per base pair
  const R = 0.05;               // helix radius
  const phase2 = 2.6;           // strand 2 offset (~150 deg) -> major/minor groove
  const height = rise * (N - 1);

  const helix = new THREE.Group();
  helix.name = 'DNA';
  helix.position.set(0, 0.22, 0);
  root.add(helix);

  const seq1 = 'ATGCGTACCTAGGCATTCGA';
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const baseColor = {
    A: new THREE.Color(0xe74c3c),
    T: new THREE.Color(0x3b8fe0),
    G: new THREE.Color(0x2ecc71),
    C: new THREE.Color(0xf4c20d),
  };

  // Right-handed helix around the Y axis
  function pt(i, strand, out) {
    const t = (i / 10) * Math.PI * 2 + (strand ? phase2 : 0);
    const y = (i - (N - 1) / 2) * rise;
    return out.set(R * Math.sin(t), y, R * Math.cos(t));
  }

  // ---- Sugar-phosphate backbones (tubes) ----
  const tubeMats = [
    new THREE.MeshStandardMaterial({ color: 0x8e9bff, roughness: 0.4, metalness: 0.1 }),
    new THREE.MeshStandardMaterial({ color: 0xff8fb1, roughness: 0.4, metalness: 0.1 }),
  ];
  for (let s = 0; s < 2; s++) {
    const pts = [];
    const steps = (N - 1) * 4;
    for (let k = 0; k <= steps; k++) pts.push(pt(k / 4, s, new THREE.Vector3()));
    const curve = new THREE.CatmullRomCurve3(pts);
    const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, 160, 0.0065, 8, false), tubeMats[s]);
    tube.name = s ? 'Backbone strand 2' : 'Backbone strand 1';
    helix.add(tube);
  }

  // ---- Backbone nodes (phosphate/sugar beads) ----
  const beadGeo = new THREE.SphereGeometry(0.0105, 16, 12);
  const beadMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.35 });
  const beads = new THREE.InstancedMesh(beadGeo, beadMat, N * 2);
  beads.name = 'Sugar-phosphate beads';
  const dummy = new THREE.Object3D();
  const c1 = new THREE.Color(0xc5ccff);
  const c2 = new THREE.Color(0xffc2d4);
  const a = new THREE.Vector3();
  const b = new THREE.Vector3();
  const mid = new THREE.Vector3();
  const dir = new THREE.Vector3();
  const up = new THREE.Vector3(0, 1, 0);
  for (let i = 0; i < N; i++) {
    pt(i, 0, a);
    dummy.position.copy(a);
    dummy.quaternion.identity();
    dummy.scale.set(1, 1, 1);
    dummy.updateMatrix();
    beads.setMatrixAt(i * 2, dummy.matrix);
    beads.setColorAt(i * 2, c1);
    pt(i, 1, b);
    dummy.position.copy(b);
    dummy.updateMatrix();
    beads.setMatrixAt(i * 2 + 1, dummy.matrix);
    beads.setColorAt(i * 2 + 1, c2);
  }
  helix.add(beads);

  // ---- Bases: two half-rungs per pair, colored by nucleotide ----
  const rungGeo = new THREE.CylinderGeometry(0.0055, 0.0055, 1, 10);
  const rungMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.45 });
  const rungs = new THREE.InstancedMesh(rungGeo, rungMat, N * 2);
  rungs.name = 'Base pairs';
  for (let i = 0; i < N; i++) {
    pt(i, 0, a);
    pt(i, 1, b);
    mid.copy(a).add(b).multiplyScalar(0.5);
    const l1 = seq1[i];
    const l2 = comp[l1];
    // The A–T pair meets in the middle; G–C likewise
    for (let h = 0; h < 2; h++) {
      const from = h === 0 ? a : b;
      dir.copy(mid).sub(from);
      const len = dir.length();
      dummy.position.copy(from).add(mid).multiplyScalar(0.5);
      dummy.quaternion.setFromUnitVectors(up, dir.normalize());
      dummy.scale.set(1, len, 1);
      dummy.updateMatrix();
      rungs.setMatrixAt(i * 2 + h, dummy.matrix);
      rungs.setColorAt(i * 2 + h, baseColor[h === 0 ? l1 : l2]);
    }
  }
  helix.add(rungs);

  // ---- Faint grab volume so the helix is easy to pinch ----
  const grabVol = new THREE.Mesh(
    new THREE.CylinderGeometry(R + 0.02, R + 0.02, height + 0.05, 24),
    new THREE.MeshBasicMaterial({ color: 0x9fd8ff, transparent: true, opacity: 0.07, depthWrite: false }),
  );
  grabVol.name = 'Grab volume';
  helix.add(grabVol);

  // Make the helix itself grabbable (direct child of root)
  traits(helix, { grab: true });

  // ---- Info panel ----
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; width: 520px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #9fd8ff; font-size: 21px; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; align-items: center; gap: 10px; }
      .legend { flex-direction: row; gap: 18px; justify-content: flex-start; }
