        <div class="row"><div class="sw" style="background-color:#3b8fe0"></div><span class="lt">T</span></div>
        <div class="row"><div class="sw" style="background-color:#2ecc71"></div><span class="lt">G</span></div>
        <div class="row"><div class="sw" style="background-color:#f4c20d"></div><span class="lt">C</span></div>
      </div>
