    'One full turn is about 10 base pairs, roughly 3.4 nm long.',
    'The helix is only about 2 nm wide. Human DNA has about 3.2 billion base pairs.',
    'The uneven spacing between the strands makes a wide major groove and a narrow minor groove.',
  ];
  let fi = -1;
  info.on('next', 'click', () => {
    fi = (fi + 1) % facts.length;
    info.set('fact', { text: facts[fi] });
  });

  let spinning = true;
  info.on('spin', 'click', () => {
    spinning = !spinning;
    info.set('spinLabel', { text: spinning ? 'Spin: on' : 'Spin: off' });
  });

  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) return;
      if (spinning) helix.rotation.y += delta * 0.3;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Materials ----------
  const woodMat = new THREE.MeshStandardMaterial({ color: 0x6b4a2f, roughness: 0.7 });
  const bezelMat = new THREE.MeshStandardMaterial({ color: 0xc9ccd2, metalness: 0.8, roughness: 0.3 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf6f3ea, roughness: 0.9 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x1b1d22, roughness: 0.5 });
  const accentMat = new THREE.MeshStandardMaterial({ color: 0xd9412f, roughness: 0.4 });

  // ---------- Clock (one grabbable group) ----------
  const clock = new THREE.Group();
  clock.name = 'Desk Clock';
  root.add(clock);

  const centerY = 0.14;

  const base = new THREE.Mesh(new THREE.BoxGeometry(0.17, 0.02, 0.09), woodMat);
  base.position.set(0, 0.01, 0);
  clock.add(base);

  const stand = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.03), woodMat);
  stand.position.set(0, 0.045, -0.01);
  clock.add(stand);

  const bezel = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.025, 40), bezelMat);
  bezel.rotation.x = Math.PI / 2;
  bezel.position.set(0, centerY, 0);
  clock.add(bezel);

  const face = new THREE.Mesh(new THREE.CylinderGeometry(0.081, 0.081, 0.005, 40), faceMat);
  face.rotation.x = Math.PI / 2;
  face.position.set(0, centerY, 0.0125);
  clock.add(face);

  // Hour ticks
  const tickGeoBig = new THREE.BoxGeometry(0.006, 0.014, 0.003);
  const tickGeoSmall = new THREE.BoxGeometry(0.004, 0.008, 0.003);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const major = i % 3 === 0;
    const tick = new THREE.Mesh(major ? tickGeoBig : tickGeoSmall, darkMat);
    const r = major ? 0.068 : 0.071;
    tick.position.set(Math.sin(a) * r, centerY + Math.cos(a) * r, 0.016);
    tick.rotation.z = -a;
    clock.add(tick);
  }

  // Hands: pivot groups, rotated around z
  function makeHand(length, width, z, mat) {
    const pivot = new THREE.Group();
    pivot.position.set(0, centerY, z);
    const bar = new THREE.Mesh(new THREE.BoxGeometry(width, length, 0.003), mat);
    bar.position.y = length / 2 - 0.006;
    pivot.add(bar);
    clock.add(pivot);
    return pivot;
  }
  const hourHand = makeHand(0.045, 0.008, 0.018, darkMat);
  hourHand.name = 'Hour hand';
  const minuteHand = makeHand(0.066, 0.005, 0.022, accentMat);
  minuteHand.name = 'Minute hand';

  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.008, 16), bezelMat);
  cap.rotation.x = Math.PI / 2;
  cap.position.set(0, centerY, 0.025);
  clock.add(cap);

  traits(clock, { grab: true });

  // ---------- Digital panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; align-items: center; gap: 8px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 26px; padding-right: 26px; border-radius: 20px; background-color: #1f2228; }
      .label { color: #9aa3b2; font-size: 22px; }
      .row { flex-direction: row; align-items: center; justify-content: center; gap: 10px; }
      .time { color: #ffffff; font-size: 84px; font-weight: 700; }
      .ampm { color: #ff8a6b; font-size: 30px; font-weight: 700; }
      .hint { color: #9aa3b2; font-size: 20px; text-align: center; }
      .btn { margin-top: 6px; padding-top: 10px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="label">Local time</span>
      <div class="row">
        <span class="time" id="time">--:--</span>
        <span class="ampm" id="ampm"></span>
      </div>
      <span class="hint">Pinch the clock to move it</span>
      <button class="btn" id="fmt"><span class="btn-text" id="fmtText">Switch to 24-hour</span></button>
    </div>`, { width: 0.3, position: [0.3, 0.13, 0.02], rotationY: -0.3 });
  root.add(panel.object3D);

  let use24 = false;
  let lastMinuteKey = -1;
  let lastColon = true;

  panel.on('fmt', 'click', () => {
    use24 = !use24;
    panel.set('fmtText', { text: use24 ? 'Switch to 12-hour' : 'Switch to 24-hour' });
    lastMinuteKey = -1; // force text refresh
  });

  // ---------- Time source ----------
  let tzOffsetMin = 0;
  let haveDate = false;
  try {
    tzOffsetMin = new Date().getTimezoneOffset();
    haveDate = typeof Date.now === 'function';
  } catch (e) {
    haveDate = false;
  }
  const fallbackStartMin = 12 * 60; // if no clock is available, start at 12:00

  function dayMinutes(time) {
    if (haveDate) {
      const totalMin = Date.now() / 60000 - tzOffsetMin;
      return ((totalMin % 1440) + 1440) % 1440;
    }
    return (fallbackStartMin + time / 60) % 1440;
  }

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  const TWO_PI = Math.PI * 2;

  return {
    root,
    update(time) {
      const dm = dayMinutes(time);

      // Smooth analog hands
      minuteHand.rotation.z = -((dm % 60) / 60) * TWO_PI;
      hourHand.rotation.z = -(((dm / 60) % 12) / 12) * TWO_PI;

      // Digital readout, only touched when the minute changes
      const minuteKey = Math.floor(dm);
      if (minuteKey !== lastMinuteKey) {
        lastMinuteKey = minuteKey;
        const h = Math.floor(minuteKey / 60);
        const m = minuteKey % 60;
        if (use24) {
          panel.set('time', { text: pad(h) + ':' + pad(m) });
          panel.set('ampm', { text: '' });
        } else {
          const h12 = h % 12 === 0 ? 12 : h % 12;
          panel.set('time', { text: h12 + ':' + pad(m) });
          panel.set('ampm', { text: h < 12 ? 'AM' : 'PM' });
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
