  // Hour ticks
  const bigTick = new THREE.BoxGeometry(0.006, 0.016, 0.002);
  const smallTick = new THREE.BoxGeometry(0.004, 0.009, 0.002);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * Math.PI * 2;
    const big = i % 3 === 0;
    const t = new THREE.Mesh(big ? bigTick : smallTick, tickMat);
    const r = big ? 0.074 : 0.077;
    t.position.set(Math.sin(a) * r, CY + Math.cos(a) * r, 0.0175);
    t.rotation.z = -a;
    clock.add(t);
  }

  // Hands (pivot groups rotate about the clock center)
  function makeHand(length, width, mat, z) {
    const pivot = new THREE.Group();
    const geo = new THREE.BoxGeometry(width, length, 0.003);
    geo.translate(0, length / 2 - 0.01, 0);
    const m = new THREE.Mesh(geo, mat);
    pivot.add(m);
