      .ampm { color: #7fb0ff; font-size: 28px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="label">Local time</span>
      <span class="time" id="time">--:--</span>
      <span class="ampm" id="ampm"> </span>
      <button class="btn" id="fmt"><span class="btn-text">Switch 12h / 24h</span></button>
    </div>`, { width: 0.2, position: [0.2, 0.11, 0], rotationY: -0.3 });
  root.add(panel.object3D);

  let use24 = true;
  let lastMinute = -1;
  let lastMode = null;
  panel.on('fmt', 'click', () => {
    use24 = !use24;
    lastMinute = -1; // force refresh
  });

  // ---------- Time source ----------
  const hasDate = typeof Date !== 'undefined';
  const tzMs = hasDate ? new Date().getTimezoneOffset() * 60000 : 0;
  const startMs = 12 * 3600000; // fallback: starts at 12:00
  const TWO_PI = Math.PI * 2;

  function pad(n) { return n < 10 ? '0' + n : '' + n; }

  return {
    root,
    update(time) {
      const localMs = hasDate ? Date.now() - tzMs : startMs + time * 1000;
      const totalMin = localMs / 60000;
      const dayMin = totalMin % 1440;
      const minuteFrac = totalMin % 60;
      const hourFrac = (localMs / 3600000) % 12;

      // Smooth analog hands
      minuteHand.rotation.z = -(minuteFrac / 60) * TWO_PI;
      hourHand.rotation.z = -(hourFrac / 12) * TWO_PI;

      // Digital readout: only update when the minute or format changes
      const minuteInt = Math.floor(dayMin);
      if (minuteInt !== lastMinute || use24 !== lastMode) {
        lastMinute = minuteInt;
        lastMode = use24;
        const h = Math.floor(minuteInt / 60);
        const m = minuteInt % 60;
        if (use24) {
          panel.set('time', { text: pad(h) + ':' + pad(m) });
          panel.set('ampm', { text: '24-hour' });
        } else {
          const h12 = h % 12 === 0 ? 12 : h % 12;
          panel.set('time', { text: h12 + ':' + pad(m) });
          panel.set('ampm', { text: h < 12 ? 'AM' : 'PM' });
        }
      }

      // Keep the digital panel next to the clock when it is moved
      panel.object3D.position.set(clock.position.x + 0.2, clock.position.y + 0.11, clock.position.z);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const lamp = new THREE.Group();
  lamp.name = 'DeskLamp';
  root.add(lamp);

  const metal = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.4, metalness: 0.7 });
  const shadeMat = new THREE.MeshStandardMaterial({
    color: 0x2e7d5b, roughness: 0.5, metalness: 0.3, side: THREE.DoubleSide,
    emissive: 0xffa640, emissiveIntensity: 0,
  });
  const bulbMat = new THREE.MeshStandardMaterial({
    color: 0xfff1c9, emissive: 0xffc76a, emissiveIntensity: 0, roughness: 0.3,
  });
  const beamMat = new THREE.MeshBasicMaterial({
    color: 0xffd9954 & 0xffffff, transparent: true, opacity: 0, depthWrite: false,
    blending: THREE.AdditiveBlending, side: THREE.DoubleSide,
  });
  beamMat.color.set(0xffd58a);
  const poolMat = new THREE.MeshBasicMaterial({
    color: 0xffd58a, transparent: true, opacity: 0, depthWrite: false,
    blending: THREE.AdditiveBlending,
  });

  // Base
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.02, 32), metal);
  base.name = 'LampBase';
  base.position.set(-0.12, 0.01, 0);
  lamp.add(base);

  // Arm helper: cylinder between two points
  const up = new THREE.Vector3(0, 1, 0);
  const armGeo = new THREE.CylinderGeometry(0.008, 0.008, 1, 12);
  function arm(a, b) {
    const m = new THREE.Mesh(armGeo, metal);
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    m.scale.set(1, len, 1);
    m.position.copy(a).addScaledVector(dir, 0.5);
    m.quaternion.setFromUnitVectors(up, dir.normalize());
    lamp.add(m);
    return m;
  }
  const P0 = new THREE.Vector3(-0.12, 0.02, 0);
  const P1 = new THREE.Vector3(-0.07, 0.21, 0);
  const P2 = new THREE.Vector3(0.05, 0.3, 0);
  arm(P0, P1).name = 'LowerArm';
  arm(P1, P2).name = 'UpperArm';

  const jointGeo = new THREE.SphereGeometry(0.014, 16, 12);
  for (const p of [P1, P2]) {
    const j = new THREE.Mesh(jointGeo, metal);
    j.position.copy(p);
    lamp.add(j);
  }

  // Head: shade + bulb
  const head = new THREE.Group();
  head.position.copy(P2).add(new THREE.Vector3(0, -0.01, 0));
  lamp.add(head);

  const shade = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.065, 0.07, 32, 1, true), shadeMat);
  shade.name = 'Shade';
  head.add(shade);

  const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.022, 24, 12), bulbMat);
  bulb.name = 'Bulb';
  bulb.position.y = -0.025;
  head.add(bulb);

  // Light beam and pool of light on the desk (not pressable, just visual)
  const deskDist = head.position.y - 0.002;
  const beamH = deskDist - 0.035;
  const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.063, 0.17, beamH, 32, 1, true), beamMat);
  beam.position.y = -0.035 - beamH / 2;
  beam.raycast = () => {};
  head.add(beam);

  const pool = new THREE.Mesh(new THREE.CircleGeometry(0.17, 40), poolMat);
  pool.rotation.x = -Math.PI / 2;
  pool.position.set(P2.x, 0.002, 0);
  pool.raycast = () => {};
  lamp.add(pool);

  // State
  let on = false;
  let level = 0;

  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #3a3f48; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="body" id="state">Light is OFF. Press the lamp to switch it on.</span>
      <button class="btn" id="toggle"><span class="btn-text" id="label">Turn on</span></button>
    </div>`, { width: 0.3, position: [0.3, 0.15, 0], rotationY: -0.35 });
  root.add(panel.object3D);

  function toggle() {
    on = !on;
    panel.set('state', { text: on ? 'Light is ON. Press the lamp to switch it off.' : 'Light is OFF. Press the lamp to switch it on.' });
    panel.set('label', { text: on ? 'Turn off' : 'Turn on' });
    panel.set('toggle', { backgroundColor: on ? '#d9902f' : '#3a3f48' });
  }
  panel.on('toggle', 'click', toggle);
  traits(lamp, { grab: true, onPress: toggle });

  return {
    root,
    update(time, delta) {
      const target = on ? 1 : 0;
      level += (target - level) * Math.min(1, delta * 8);
      if (Math.abs(target - level) < 0.001) level = target;
      bulbMat.emissiveIntensity = level * 2.5;
      shadeMat.emissiveIntensity = level * 0.35;
      beamMat.opacity = level * 0.13;
      poolMat.opacity = level * 0.35;
    },
  };
}

