  const beamLen = t - 0.04;
  const beam = new THREE.Mesh(
    new THREE.CylinderGeometry(0.065, 0.15, beamLen, 32, 1, true), beamMat);
  beam.position.y = -0.04 - beamLen / 2;
  head.add(beam);

  // Light pool on the desk (world-space relative to lamp)
  const pool = new THREE.Mesh(new THREE.CircleGeometry(0.15, 40), poolMat);
  pool.rotation.x = -Math.PI / 2;
  pool.scale.set(1, 1.15, 1);
  pool.position.set(p2.x + t * Math.sin(theta), 0.002, 0);
  lamp.add(pool);

  // UI panel
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228;
              width: 440px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #3a3f48; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="body" id="status">Lamp is OFF. Press the lamp to switch it on.</span>
      <button class="btn" id="toggle"><span class="btn-text" id="toggleText">Turn on</span></button>
    </div>`, { width: 0.28, position: [0.3, 0.17, 0.02], rotationY: -0.3 });
  root.add(panel.object3D);

  let on = false;
  let level = 0;

  function toggle() {
    on = !on;
    panel.set('status', { text: on ? 'Lamp is ON. Press again to switch it off.' : 'Lamp is OFF. Press the lamp to switch it on.' });
    panel.set('toggleText', { text: on ? 'Turn off' : 'Turn on' });
    panel.set('toggle', { backgroundColor: on ? '#c98a1a' : '#3a3f48' });
  }

  traits(lamp, { onPress: toggle });
  panel.on('toggle', 'click', toggle);

  return {
    root,
    update(time, delta) {
      const target = on ? 1 : 0;
      const k = Math.min(1, delta * 8);
      level += (target - level) * k;
      if (Math.abs(target - level) < 0.001) level = target;
      const flicker = on && level > 0.95 ? 1 + Math.sin(time * 40) * 0.01 : 1;
      bulbMat.emissiveIntensity = level * 2.0 * flicker;
      shadeMat.emissiveIntensity = level * 0.25;
      beamMat.opacity = level * 0.14;
      poolMat.opacity = level * 0.28;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Scale: Earth radius 6371 km -> 0.13 m. The crust is drawn thicker than true scale.
  const CENTER_Y = 0.17;
  const PHI0 = (3 * Math.PI) / 4;   // wedge missing between 45° and 135° (faces the user)
  const PHIL = 1.5 * Math.PI;
  const S = Math.SQRT1_2;

  const defs = [
    {
      id: 'crust', name: 'Crust', rIn: 0.122, rOut: 0.13, color: 0x4a8f5a, hex: '#4a8f5a', base: 0.08,
      depth: '0 – 70 km deep', side: -1, labelY: 0.36, anchor: [0.11, 0.065],
      state: 'Solid rock · up to ~400 °C at its base',
      body: 'Oceanic crust is only 5–10 km thick; continental crust is 30–70 km thick. It is broken into tectonic plates.',
      note: 'Drawn thicker than true scale so you can see it.',
    },
    {
      id: 'mantle', name: 'Mantle', rIn: 0.071, rOut: 0.122, color: 0xc0462b, hex: '#c0462b', base: 0.12,
      depth: 'to ~2,900 km deep', side: -1, labelY: 0.2, anchor: [0.095, -0.03],
      state: 'Hot solid rock that slowly flows · ~1,000–3,700 °C',
      body: 'About 84% of Earth\'s volume. Slow convection currents in the mantle move the tectonic plates above.',
      note: '',
    },
    {
      id: 'outer', name: 'Outer core', rIn: 0.0247, rOut: 0.071, color: 0xff8a1f, hex: '#ff8a1f', base: 0.35,
      depth: '2,900 – 5,150 km deep', side: 1, labelY: 0.2, anchor: [0.05, -0.01],
      state: 'LIQUID iron and nickel · ~4,000–5,000 °C',
      body: 'Swirling liquid metal acts as a dynamo and generates Earth\'s magnetic field.',
      note: '',
    },
    {
      id: 'inner', name: 'Inner core', rIn: 0.0, rOut: 0.0247, color: 0xffd54a, hex: '#ffd54a', base: 0.6,
      depth: '5,150 – 6,371 km deep', side: 1, labelY: 0.36, anchor: [0.01, 0.005],
      state: 'SOLID iron and nickel · ~5,200–5,400 °C',
      body: 'About 1,220 km in radius. Despite the heat it stays solid because of the immense pressure (over 3 million atmospheres).',
      note: '',
    },
  ];

  const faceGeoCache = {};
  const layers = [];

  defs.forEach((d, i) => {
    const mat = new THREE.MeshStandardMaterial({
      color: d.color, roughness: 0.7, emissive: d.color, emissiveIntensity: d.base,
      side: THREE.DoubleSide,
    });
    const group = new THREE.Group();
    group.name = d.name;
    group.position.set(0, CENTER_Y, 0);

    const shell = new THREE.Mesh(new THREE.SphereGeometry(d.rOut, 48, 24, PHI0, PHIL), mat);
    shell.name = d.name + ' shell';
    group.add(shell);

    const faceGeo = new THREE.RingGeometry(d.rIn, d.rOut, 32, 1, -Math.PI / 2, Math.PI);
    const faceA = new THREE.Mesh(faceGeo, mat);
    faceA.rotation.y = -Math.PI / 4;
    faceA.name = d.name + ' cut face R';
    const faceB = new THREE.Mesh(faceGeo, mat);
    faceB.rotation.y = -3 * Math.PI / 4;
    faceB.name = d.name + ' cut face L';
    group.add(faceA, faceB);

    root.add(group);
    layers.push({ def: d, mat, group, index: i });
  });

  // Leader lines and dots
  const lineMat = new THREE.LineBasicMaterial({ color: 0xffffff, depthTest: false, transparent: true });
  const dotGeo = new THREE.SphereGeometry(0.0045, 12, 8);
  const dotMat = new THREE.MeshBasicMaterial({ color: 0xffffff, depthTest: false });

  const panelStyle = `
    <style>
      .lbl { flex-direction: column; gap: 4px; padding-top: 12px; padding-bottom: 12px;
             padding-left: 18px; padding-right: 18px; border-radius: 16px;
             background-color: #23272e; border-width: 4px; }
      .name { color: #ffffff; font-size: 32px; font-weight: 700; }
      .depth { color: #cfd5de; font-size: 22px; }
    </style>`;

  const labels = {};
  layers.forEach((L) => {
    const d = L.def;
    const h = ui(`${panelStyle}
      <button class="lbl" id="${d.id}" style="border-color: ${d.hex};">
        <span class="name">${d.name}</span>
        <span class="depth">${d.depth}</span>
      </button>`, {
      width: 0.2,
      position: [d.side * 0.33, d.labelY, 0.04],
      rotationY: -d.side * 0.3,
    });
    root.add(h.object3D);
    labels[d.id] = h;
    h.on(d.id, 'click', () => select(L.index));

    // leader line to the cut face
    const ax = d.side * S * d.anchor[0];
    const ay = CENTER_Y + d.anchor[1];
    const az = S * d.anchor[0];
    const sx = d.side * 0.225;
    const pts = [new THREE.Vector3(sx, d.labelY, 0.04), new THREE.Vector3(ax, ay, az)];
    const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat);
    line.renderOrder = 10;
    root.add(line);
    const dot = new THREE.Mesh(dotGeo, dotMat);
    dot.position.set(ax, ay, az);
    dot.renderOrder = 11;
    root.add(dot);
  });

  // Info panel
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 24px; padding-right: 24px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 34px; font-weight: 700; }
      .state { color: #ffd54a; font-size: 24px; font-weight: 700; }
      .text { color: #d7dbe2; font-size: 22px; }
      .note { color: #9aa3b0; font-size: 18px; }
    </style>
    <div class="card">
      <span class="title" id="title">Layers of the Earth</span>
      <span class="state" id="state">Pinch or poke a layer, or press a label.</span>
      <span class="text" id="body">The wedge is cut away so you can see 4 layers: crust, mantle, outer core and inner core.</span>
      <span class="note" id="note">Earth's radius is 6,371 km.</span>
    </div>`, { width: 0.4, position: [0, 0.07, 0.2], rotationY: 0 });
  root.add(info.object3D);

  let selected = -1;
  function select(i) {
    selected = i;
    const d = defs[i];
    info.set('title', { text: d.name, color: '#ffffff' });
    info.set('state', { text: d.state });
    info.set('body', { text: d.body });
    info.set('note', { text: d.note || ('Depth: ' + d.depth) });
    defs.forEach((o, k) => {
      labels[o.id].set(o.id, { backgroundColor: k === i ? '#454c5a' : '#23272e' });
    });
  }

  layers.forEach((L) => {
    traits(L.group, { onPress: () => select(L.index) });
  });

  return {
    root,
    update(time) {
      layers.forEach((L) => {
        if (L.index === selected) {
          L.mat.emissiveIntensity = 0.35 + 0.25 * Math.sin(time * 4);
        } else {
          L.mat.emissiveIntensity = L.def.base;
        }
      });
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Plant ----------
  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.07, 0.08, 0.04, 24),
    new THREE.MeshStandardMaterial({ color: 0x5b3a22, roughness: 0.95 }),
  );
  soil.name = 'Soil';
  soil.position.set(0, 0.02, 0);
  root.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.007, 0.01, 0.28, 12),
    new THREE.MeshStandardMaterial({ color: 0x3b7d3a, roughness: 0.7 }),
  );
  stem.name = 'Stem';
  stem.position.set(0, 0.17, 0);
  root.add(stem);

  const leafGeo = new THREE.SphereGeometry(0.035, 20, 12);
  const leafMat = new THREE.MeshStandardMaterial({
    color: 0x3fa34d, roughness: 0.6, emissive: 0x1a6a2a, emissiveIntensity: 0.4,
  });
  const leafDefs = [
    [-0.06, 0.26, 0.35, 1.0],
    [0.06, 0.22, -0.35, 1.0],
    [0.055, 0.30, -0.3, 0.8],
    [-0.05, 0.17, 0.3, 0.8],
  ];
  leafDefs.forEach((d, i) => {
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.name = 'Leaf ' + (i + 1);
    leaf.position.set(d[0], d[1], 0);
    leaf.rotation.z = d[2];
    leaf.scale.set(1.7 * d[3], 0.22 * d[3], 1.0 * d[3]);
    root.add(leaf);
  });

  // ---------- Sun ----------
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff9a00, emissiveIntensity: 0.9 });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.04, 28, 14), sunMat);
  sun.name = 'Sun';
  sun.position.set(-0.3, 0.4, 0);
  root.add(sun);
  const haloMat = new THREE.MeshBasicMaterial({ color: 0xffd066, transparent: true, opacity: 0.2, depthWrite: false });
  const halo = new THREE.Mesh(new THREE.SphereGeometry(0.062, 20, 12), haloMat);
  halo.raycast = () => {};
  sun.add(halo);

  // ---------- Arrows ----------
  const hitMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
  const up = new THREE.Vector3(0, 1, 0);

  function makeArrow(key, from, to, color) {
    const a = new THREE.Vector3(...from);
    const b = new THREE.Vector3(...to);
    const d = new THREE.Vector3().subVectors(b, a);
    const len = d.length();
    d.normalize();
    const g = new THREE.Group();
    g.name = 'Arrow ' + key;
    g.position.copy(a);
    g.quaternion.setFromUnitVectors(up, d);
    const mat = new THREE.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.2, roughness: 0.5 });
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, len * 0.72, 12), mat);
    shaft.position.y = len * 0.36;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.017, len * 0.28, 16), mat);
    head.position.y = len * 0.86;
    const hit = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.025, len, 8), hitMat);
    hit.position.y = len * 0.5;
    g.add(shaft, head, hit);
    root.add(g);
    return {
      key, group: g, mat, color,
      fx: a.x, fy: a.y, fz: a.z,
      dx: b.x - a.x, dy: b.y - a.y, dz: b.z - a.z,
      flow: Math.random(),
    };
  }

  const arrows = {
    light: makeArrow('light', [-0.255, 0.37, 0], [-0.1, 0.285, 0], 0xffd23f),
    water: makeArrow('water', [-0.3, 0.035, 0], [-0.05, 0.035, 0], 0x3fa7ff),
    co2: makeArrow('co2', [0.3, 0.23, 0], [0.12, 0.23, 0], 0xb8c0cc),
    o2: makeArrow('o2', [0.1, 0.31, 0], [0.22, 0.41, 0], 0x6fe39a),
  };
  const arrowList = [arrows.light, arrows.water, arrows.co2, arrows.o2];

  // ---------- Flow particles ----------
  const PER = 3;
  const pMesh = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.008, 10, 8),
    new THREE.MeshBasicMaterial({ color: 0xffffff }),
    arrowList.length * PER,
  );
  pMesh.frustumCulled = false;
  const tmpColor = new THREE.Color();
  arrowList.forEach((a, ai) => {
    for (let k = 0; k < PER; k++) pMesh.setColorAt(ai * PER + k, tmpColor.set(a.color));
  });
  root.add(pMesh);

  const DROPS = 4;
  const dropMesh = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.007, 10, 8),
    new THREE.MeshBasicMaterial({ color: 0x5ab8ff }),
    DROPS,
  );
  dropMesh.frustumCulled = false;
  root.add(dropMesh);
  let dropFlow = 0;

  const dummy = new THREE.Object3D();

  // ---------- UI ----------
  const labelStyle = `
    <style>
      .lab { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
             border-radius: 12px; width: 220px; justify-content: center; align-items: center; }
      .labt { color: #14171b; font-size: 28px; font-weight: 700; text-align: center; }
    </style>`;
  function makeLabel(id, text, color, pos) {
    const hex = '#' + color.toString(16).padStart(6, '0');
    const h = ui(`${labelStyle}
      <button class="lab" id="${id}" style="background-color: ${hex};"><span class="labt">${text}</span></button>`,
      { width: 0.11, position: pos });
    root.add(h.object3D);
    h.set(id, { backgroundColor: hex });
    return h;
  }
  const labLight = makeLabel('lab', 'Light', 0xffd23f, [-0.31, 0.31, 0.01]);
  const labWater = makeLabel('lab', 'Water', 0x3fa7ff, [-0.24, 0.09, 0.01]);
  const labCo2 = makeLabel('lab', 'CO2', 0xb8c0cc, [0.28, 0.28, 0.01]);
  const labO2 = makeLabel('lab', 'O2', 0x6fe39a, [0.28, 0.44, 0.01]);

  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; width: 520px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .eqbox { flex-direction: column; gap: 4px; padding-top: 10px; padding-bottom: 10px; padding-left: 14px;
               padding-right: 14px; border-radius: 12px; background-color: #2a2e35; }
      .eq { color: #8fe3a8; font-size: 21px; font-weight: 700; }
      .small { color: #aeb4be; font-size: 19px; }
      .row { flex-direction: row; gap: 12px; align-items: center; justify-content: space-between; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #e0a526; }
      .btnt { color: #14171b; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title" id="title">Photosynthesis</span>
      <span class="body" id="body">Plants turn light, water and carbon dioxide into sugar and oxygen. Press an arrow, a label or the Sun.</span>
      <div class="eqbox">
        <span class="eq">6 CO2 + 6 H2O + light</span>
        <span class="eq">-> C6H12O6 (glucose) + 6 O2</span>
      </div>
      <div class="row">
        <span class="small" id="sugar">Glucose made: 0 units</span>
        <button class="btn" id="toggle"><span class="btnt" id="toggleText">Light: ON</span></button>
      </div>
    </div>`, { width: 0.26, position: [0.265, 0.1, 0.02], rotationY: -0.25 });
  root.add(info.object3D);

  const texts = {
    light: ['Sunlight', 'Chlorophyll in the chloroplasts of the leaves absorbs light energy. This energy powers the whole process.'],
    water: ['Water (H2O)', 'Roots absorb water from the soil. It travels up the stem through tubes called xylem to the leaves.'],
    co2: ['Carbon dioxide (CO2)', 'CO2 from the air enters the leaf through tiny pores called stomata. Its carbon is used to build sugar.'],
    o2: ['Oxygen (O2)', 'Oxygen is released through the stomata as a by-product. It comes from the splitting of water molecules.'],
  };

  let selected = null;
  let lightOn = true;

  function select(key) {
    selected = key;
    info.set('title', { text: texts[key][0] });
    info.set('body', { text: texts[key][1] });
  }

  function setLight(on) {
    lightOn = on;
    info.set('toggleText', { text: on ? 'Light: ON' : 'Light: OFF' });
    if (!on) {
      selected = null;
      info.set('title', { text: 'Light is off' });
      info.set('body', { text: 'Without light the plant cannot make sugar, so the flow slows down. Press the Sun to switch it back on.' });
    } else {
      info.set('title', { text: 'Photosynthesis' });
      info.set('body', { text: 'Light is back on! Plants turn light, water and CO2 into sugar and oxygen.' });
    }
  }

  const keys = ['light', 'water', 'co2', 'o2'];
  const labels = [labLight, labWater, labCo2, labO2];
  keys.forEach((k, i) => {
    traits(arrows[k].group, { onPress: () => select(k) });
    labels[i].on('lab', 'click', () => select(k));
  });
  traits(sun, { onPress: () => setLight(!lightOn) });
  info.on('toggle', 'click', () => setLight(!lightOn));

  // ---------- Animation ----------
  let level = 1;
  let sugar = 0;
  let lastSugar = 0;

  return {
    root,
    update(time, delta) {
      level += ((lightOn ? 1 : 0) - level) * Math.min(1, delta * 3);

      sunMat.emissiveIntensity = 0.1 + 0.8 * level;
      haloMat.opacity = 0.2 * level;
      halo.scale.setScalar(1 + 0.05 * Math.sin(time * 2));
      leafMat.emissiveIntensity = 0.05 + 0.35 * level;

      const rates = [level, 0.25 + 0.75 * level, level, level];
      for (let ai = 0; ai < arrowList.length; ai++) {
        const a = arrowList[ai];
        const rate = rates[ai];
        a.flow += delta * 0.3 * rate;
        const vis = Math.min(1, rate * 3);
        for (let k = 0; k < PER; k++) {
          const p = (a.flow + k / PER) % 1;
          dummy.position.set(a.fx + a.dx * p, a.fy + a.dy * p, a.fz + a.dz * p);
          dummy.scale.setScalar((0.3 + 0.7 * Math.sin(Math.PI * p)) * vis + 0.001);
          dummy.updateMatrix();
          pMesh.setMatrixAt(ai * PER + k, dummy.matrix);
        }
        const sel = selected === a.key;
        a.mat.emissiveIntensity = sel ? 0.6 + 0.3 * Math.sin(time * 5) : 0.2;
      }
      pMesh.instanceMatrix.needsUpdate = true;

      // water rising up the stem
      dropFlow += delta * 0.25 * rates[1];
      for (let i = 0; i < DROPS; i++) {
        const p = (dropFlow + i / DROPS) % 1;
        dummy.position.set(0, 0.05 + 0.22 * p, 0.012);
        dummy.scale.setScalar(0.4 + 0.6 * Math.sin(Math.PI * p) + 0.001);
        dummy.updateMatrix();
        dropMesh.setMatrixAt(i, dummy.matrix);
      }
      dropMesh.instanceMatrix.needsUpdate = true;

      // sugar counter
      sugar += delta * level * 0.4;
      const n = Math.floor(sugar);
      if (n !== lastSugar) {
        lastSugar = n;
        info.set('sugar', { text: 'Glucose made: ' + n + (n === 1 ? ' unit' : ' units') });
      }
    },
  };
}

