      text: 'A solid ball of iron and nickel with a radius of about 1,220 km. At around 5,400 °C it is as hot as the Sun\'s surface, but the immense pressure keeps it solid.',
    },
  ];

  // ---------- Earth shell with a quarter cut away ----------
  const shellMat = new THREE.MeshStandardMaterial({
    color: 0x2d6fb8, roughness: 0.55, emissive: 0x2d6fb8, emissiveIntensity: 0,
  });
  const shell = new THREE.Mesh(new THREE.SphereGeometry(R, 40, 24, 0, Math.PI * 1.5), shellMat);
  shell.name = 'Earth surface';
  shell.position.set(0, cy, 0);
  shell.rotation.y = rotY;
  root.add(shell);

  // ---------- Cut faces (two per layer) ----------
  const dotGeo = new THREE.SphereGeometry(0.004, 12, 8);
  const dotMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const lineMat = new THREE.LineBasicMaterial({ color: 0xffffff });

  layers.forEach((l, i) => {
    l.mat = new THREE.MeshStandardMaterial({
      color: l.color, roughness: 0.7, side: THREE.DoubleSide,
      emissive: l.color, emissiveIntensity: l.base,
    });
    const geo = l.inner === 0
      ? new THREE.CircleGeometry(l.outer, 40, -Math.PI / 2, Math.PI)
      : new THREE.RingGeometry(l.inner, l.outer, 48, 1, -Math.PI / 2, Math.PI);
    [rotA, rotB].forEach((rot, k) => {
      const m = new THREE.Mesh(geo, l.mat);
      m.name = l.name + ' (cut face ' + (k + 1) + ')';
      m.position.set(0, cy, 0);
      m.rotation.y = rot;
      root.add(m);
      traits(m, { onPress: () => select(i) });
    });
  });
  traits(shell, { onPress: () => select(0) });

  // ---------- Label panels with leader lines ----------
  const labelX = 0.25, labelZ = 0.2;
  layers.forEach((l, i) => {
    const h = ui(`
      <style>
        .wrap { flex-direction: row; }
        .lab { flex-direction: row; align-items: center; gap: 12px; width: 300px;
               padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 14px;
               border-radius: 14px; background-color: #1f2228; border-width: 2px; border-color: #3a3f48; }
        .chip { width: 14px; height: 52px; border-radius: 7px; background-color: ${hex(l.color)}; }
        .col { flex-direction: column; gap: 2px; }
        .name { color: #ffffff; font-size: 30px; font-weight: 700; }
        .depth { color: #c3c9d3; font-size: 20px; }
      </style>
      <div class="wrap">
        <button class="lab" id="btn">
          <div class="chip"></div>
          <div class="col">
            <span class="name">${l.name}</span>
            <span class="depth">${l.depth.replace('Depth: ', '')}</span>
          </div>
        </button>
      </div>`, { width: 0.2, position: [labelX, l.labelY, labelZ] });
    root.add(h.object3D);
    h.on('btn', 'click', () => select(i));
    l.label = h;

    const ax = S * l.anchor[0], ay = cy + l.anchor[1], az = S * l.anchor[0];
    const dot = new THREE.Mesh(dotGeo, dotMat);
    dot.position.set(ax, ay, az);
    root.add(dot);

    const lineGeo = new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(ax, ay, az),
      new THREE.Vector3(labelX - 0.105, l.labelY, labelZ),
    ]);
    root.add(new THREE.Line(lineGeo, lineMat));
  });

  // ---------- Info panel ----------
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; width: 520px; padding-top: 24px; padding-bottom: 24px;
              padding-left: 26px; padding-right: 26px; border-radius: 22px; background-color: #1f2228; }
      .head { color: #8fb8ff; font-size: 22px; font-weight: 700; }
      .title { color: #ffffff; font-size: 40px; font-weight: 700; }
      .depth { color: #c3c9d3; font-size: 24px; }
      .body { color: #e3e7ee; font-size: 24px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
             border-radius: 14px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 26px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="head">LAYERS OF THE EARTH</span>
      <span class="title" id="title">Cut-away Earth</span>
      <span class="depth" id="depth">Radius: 6,371 km</span>
      <span class="body" id="body">A quarter of the Earth has been cut away. Press a layer on the sphere, or its label, to learn about it.</span>
      <button class="btn" id="next"><span class="btn-text">Dive deeper</span></button>
    </div>`, { width: 0.32, position: [-0.34, 0.2, 0.04], rotationY: 0.35 });
  root.add(info.object3D);

  let selected = -1;
  function select(i) {
    selected = i;
    const l = layers[i];
    info.set('title', { text: l.name, color: hex(l.color) });
    info.set('depth', { text: l.depth });
    info.set('body', { text: l.text });
    layers.forEach((o, k) => {
      o.label.set('btn', { backgroundColor: k === i ? '#3b4250' : '#1f2228' });
    });
  }
  info.on('next', 'click', () => select((selected + 1) % layers.length));

  return {
    root,
    update(time) {
      const pulse = 0.5 + 0.5 * Math.sin(time * 4);
      for (let i = 0; i < layers.length; i++) {
        const l = layers[i];
        l.mat.emissiveIntensity = l.base + (i === selected ? 0.3 + 0.35 * pulse : 0);
      }
      shellMat.emissiveIntensity = selected === 0 ? 0.15 + 0.25 * pulse : 0;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Sample data (illustrative, not live) ----------
  const cities = [
    { name: 'Cairo',  kind: 'sun',  c: 33, cond: 'Sunny',        detail: 'Humidity 25% · Wind 14 km/h', color: '#3a2f1a', x: -0.26 },
    { name: 'London', kind: 'rain', c: 14, cond: 'Light rain',   detail: 'Humidity 82% · Wind 19 km/h', color: '#1f2b3a', x: 0 },
    { name: 'Oslo',   kind: 'snow', c: -3, cond: 'Snow showers', detail: 'Humidity 88% · Wind 9 km/h',  color: '#26303d', x: 0.26 },
  ];
  let useF = false;
  const fmt = (c) => (useF ? Math.round(c * 9 / 5 + 32) + '°F' : c + '°C');

  // ---------- Shared geometry & materials ----------
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc83d, emissive: 0xff9a00, emissiveIntensity: 0.8, roughness: 0.5 });
  const rayMat = new THREE.MeshStandardMaterial({ color: 0xffd966, emissive: 0xffa000, emissiveIntensity: 0.6 });
  const cloudMatLight = new THREE.MeshStandardMaterial({ color: 0xf2f5f9, roughness: 0.9 });
  const cloudMatDark = new THREE.MeshStandardMaterial({ color: 0x8f9aaa, roughness: 0.9 });
  const dropMat = new THREE.MeshStandardMaterial({ color: 0x4aa3ff, emissive: 0x1b5fb0, emissiveIntensity: 0.5 });
  const flakeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xaad4ff, emissiveIntensity: 0.4 });
  const sphereGeo = new THREE.SphereGeometry(1, 24, 12);
  const rayGeo = new THREE.BoxGeometry(0.008, 0.026, 0.008);

  function makeCloud(mat) {
    const g = new THREE.Group();
    const parts = [
      [-0.03, 0, 0.03, 0.8],
      [0.0, 0.016, 0.04, 0.85],
      [0.032, 0.0, 0.03, 0.8],
    ];
    for (const [x, y, r, sy] of parts) {
      const m = new THREE.Mesh(sphereGeo, mat);
      m.position.set(x, y, 0);
      m.scale.set(r, r * sy, r);
      g.add(m);
    }
    return g;
  }

  // ---------- Build icons ----------
  const falling = [];   // { mesh, offset, speed, sway, baseX, kind }
  const spinners = [];
  const icons = [];

  cities.forEach((city, i) => {
    const icon = new THREE.Group();
    icon.name = city.name + ' ' + city.cond + ' icon';
    icon.position.set(city.x, 0.25, 0);
    root.add(icon);

    if (city.kind === 'sun') {
      const core = new THREE.Mesh(sphereGeo, sunMat);
      core.scale.setScalar(0.035);
      core.name = 'Sun';
      icon.add(core);
      const pivot = new THREE.Group();
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2;
        const ray = new THREE.Mesh(rayGeo, rayMat);
        ray.position.set(Math.cos(a) * 0.06, Math.sin(a) * 0.06, 0);
        ray.rotation.z = a - Math.PI / 2;
        pivot.add(ray);
      }
      icon.add(pivot);
      spinners.push(pivot);
    } else {
      const cloud = makeCloud(city.kind === 'rain' ? cloudMatDark : cloudMatLight);
      cloud.name = 'Cloud';
      cloud.position.y = 0.02;
      icon.add(cloud);
      for (let k = 0; k < 6; k++) {
        const isRain = city.kind === 'rain';
        const m = new THREE.Mesh(sphereGeo, isRain ? dropMat : flakeMat);
        if (isRain) m.scale.set(0.006, 0.016, 0.006);
        else m.scale.setScalar(0.007);
        const baseX = -0.04 + k * 0.016;
        m.position.set(baseX, -0.03, 0);
        icon.add(m);
        falling.push({
          mesh: m, offset: k / 6 + (k % 2) * 0.08,
          speed: isRain ? 0.7 : 0.25, sway: isRain ? 0 : 0.008, baseX, rain: isRain, phase: k * 1.3,
        });
      }
    }
    icons.push(icon);
  });

  // ---------- Panels ----------
  const cityPanels = cities.map((city, i) => {
    const p = ui(`
      <style>
        .card { flex-direction: column; align-items: center; gap: 6px; width: 440px;
                padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px;
                border-radius: 22px; background-color: ${city.color}; }
        .city { color: #ffffff; font-size: 34px; font-weight: 700; }
        .temp { color: #ffd966; font-size: 72px; font-weight: 700; }
        .cond { color: #e6ebf2; font-size: 28px; }
        .detail { color: #aab4c3; font-size: 22px; text-align: center; }
      </style>
      <div class="card">
        <span class="city">${city.name}</span>
        <span class="temp" id="temp">${fmt(city.c)}</span>
        <span class="cond" id="cond">${city.cond}</span>
        <span class="detail" id="detail">Press the icon for details</span>
      </div>`, { width: 0.22, position: [city.x, 0.09, 0.02] });
    root.add(p.object3D);
    return p;
  });

  const header = ui(`
    <style>
      .bar { flex-direction: row; align-items: center; justify-content: space-between; gap: 24px; width: 560px;
             padding-top: 14px; padding-bottom: 14px; padding-left: 24px; padding-right: 24px;
             border-radius: 20px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="bar">
      <span class="title">Weather Today</span>
      <button class="btn" id="unit"><span class="btn-text" id="unitLabel">Show °F</span></button>
    </div>`, { width: 0.34, position: [0, 0.4, 0.02] });
  root.add(header.object3D);

  header.on('unit', 'click', () => {
    useF = !useF;
    header.set('unitLabel', { text: useF ? 'Show °C' : 'Show °F' });
    cities.forEach((city, i) => cityPanels[i].set('temp', { text: fmt(city.c) }));
  });

  // ---------- Interaction ----------
  const showingDetail = [false, false, false];
  icons.forEach((icon, i) => {
    traits(icon, {
      grab: true,
      onPress: () => {
        showingDetail[i] = !showingDetail[i];
        cityPanels[i].set('detail', {
          text: showingDetail[i] ? cities[i].detail : 'Press the icon for details',
        });
      },
    });
  });

  // ---------- Animation (scenery inside icons only) ----------
  return {
    root,
    update(time) {
      for (let i = 0; i < spinners.length; i++) spinners[i].rotation.z = time * 0.4;
      for (let i = 0; i < falling.length; i++) {
        const f = falling[i];
        const t = (time * f.speed * 0.6 + f.offset) % 1;
        f.mesh.position.y = -0.02 - t * 0.055;
        f.mesh.position.x = f.baseX + (f.sway ? Math.sin(time * 2 + f.phase) * f.sway : 0);
        const s = t < 0.15 ? t / 0.15 : t > 0.85 ? (1 - t) / 0.15 : 1;
        if (f.rain) f.mesh.scale.set(0.006 * s, 0.016 * s, 0.006 * s);
        else f.mesh.scale.setScalar(0.007 * s);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Illustrative sample data (no live network access in this component).
  const cities = [
    { name: 'Madrid', cond: 'Sunny', c: 31, hi: 33, lo: 19, hum: 28, wind: 12, color: '#ffb02e', kind: 'sun' },
    { name: 'London', cond: 'Rain', c: 14, hi: 16, lo: 10, hum: 82, wind: 20, color: '#5aa9ff', kind: 'rain' },
    { name: 'Oslo', cond: 'Snow', c: -3, hi: -1, lo: -6, hum: 85, wind: 9, color: '#bfe6ff', kind: 'snow' },
  ];

  let useF = false;
  const fmt = (c) => (useF ? Math.round(c * 9 / 5 + 32) + '°F' : Math.round(c) + '°C');

  // Shared geometries and materials
  const sphereGeo = new THREE.SphereGeometry(1, 20, 12);
  const coneGeo = new THREE.ConeGeometry(0.006, 0.018, 8);
  const dropGeo = new THREE.CapsuleGeometry(0.0035, 0.012, 4, 8);
  const flakeGeo = new THREE.SphereGeometry(0.006, 10, 8);

  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff9a00, emissiveIntensity: 0.9 });
  const rayMat = new THREE.MeshStandardMaterial({ color: 0xffd55e, emissive: 0xffa500, emissiveIntensity: 0.8 });
  const grayCloudMat = new THREE.MeshStandardMaterial({ color: 0x8f98a3, roughness: 0.9 });
  const whiteCloudMat = new THREE.MeshStandardMaterial({ color: 0xe6ecf3, roughness: 0.9 });
  const dropMat = new THREE.MeshStandardMaterial({ color: 0x4aa3ff, emissive: 0x1a5fb0, emissiveIntensity: 0.5 });
  const flakeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xaad4ff, emissiveIntensity: 0.4 });

  function addCloud(group, mat) {
    const parts = [
      [-0.024, 0, 0.02], [0, 0.010, 0.027], [0.025, 0, 0.02], [0, -0.004, 0.022],
    ];
    parts.forEach((p) => {
      const m = new THREE.Mesh(sphereGeo, mat);
      m.position.set(p[0], p[1], 0);
      m.scale.setScalar(p[2]);
      group.add(m);
    });
  }

  const rayGroups = [];
  const falling = []; // { mesh, phase, x, speed, sway, baseY }

  function makeIcon(city, x) {
    const g = new THREE.Group();
    g.name = city.name + ' icon';
    g.position.set(x, 0.24, 0);
    if (city.kind === 'sun') {
      const sun = new THREE.Mesh(sphereGeo, sunMat);
      sun.scale.setScalar(0.026);
      g.add(sun);
      const rays = new THREE.Group();
      for (let k = 0; k < 8; k++) {
        const a = (k / 8) * Math.PI * 2;
        const r = new THREE.Mesh(coneGeo, rayMat);
        r.position.set(Math.cos(a) * 0.045, Math.sin(a) * 0.045, 0);
        r.rotation.z = a - Math.PI / 2;
        rays.add(r);
      }
      g.add(rays);
      rayGroups.push(rays);
    } else if (city.kind === 'rain') {
      addCloud(g, grayCloudMat);
      for (let k = 0; k < 5; k++) {
        const d = new THREE.Mesh(dropGeo, dropMat);
        const f = { mesh: d, phase: k * 0.2, x: -0.028 + k * 0.014, speed: 0.6, sway: 0, baseY: -0.035 };
        d.position.set(f.x, f.baseY, 0.005);
        g.add(d);
        falling.push(f);
      }
    } else {
      addCloud(g, whiteCloudMat);
      for (let k = 0; k < 5; k++) {
        const d = new THREE.Mesh(flakeGeo, flakeMat);
        const f = { mesh: d, phase: k * 0.2 + 0.07, x: -0.028 + k * 0.014, speed: 0.2, sway: 0.006, baseY: -0.035 };
        d.position.set(f.x, f.baseY, 0.005);
        g.add(d);
        falling.push(f);
      }
    }
    root.add(g);
    return g;
  }

  const style = `
    <style>
      .card { flex-direction: column; align-items: center; gap: 6px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 16px; padding-right: 16px; border-radius: 20px; background-color: #1f2228; }
      .name { color: #ffffff; font-size: 30px; font-weight: 700; }
      .temp { font-size: 64px; font-weight: 700; }
      .cond { color: #d7dbe2; font-size: 24px; }
      .range { color: #aab1bd; font-size: 20px; }
      .detail { color: #8fa0b5; font-size: 18px; text-align: center; }
    </style>`;

  const panels = [];
  cities.forEach((city, i) => {
    const x = (i - 1) * 0.26;
    const icon = makeIcon(city, x);
    const p = ui(`${style}
      <div class="card">
        <span class="name">${city.name}</span>
        <span class="temp" id="temp${i}" style="color:${city.color}">${fmt(city.c)}</span>
        <span class="cond">${city.cond}</span>
        <span class="range" id="range${i}">H ${fmt(city.hi)}  ·  L ${fmt(city.lo)}</span>
        <span class="detail" id="detail${i}">Press the icon for details</span>
      </div>`, { width: 0.22, position: [x, 0.09, 0] });
    p.set('temp' + i, { color: city.color });
    root.add(p.object3D);
    panels.push(p);

    let showDetail = false;
    traits(icon, {
      grab: true,
      onPress: () => {
        showDetail = !showDetail;
        p.set('detail' + i, {
          text: showDetail ? `Humidity ${city.hum}%  ·  Wind ${city.wind} km/h` : 'Press the icon for details',
        });
      },
    });
  });

  // Title + unit toggle
  const header = ui(`
    <style>
      .head { flex-direction: column; align-items: center; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #2a2e35; }
      .title { color: #ffffff; font-size: 34px; font-weight: 700; }
      .hint { color: #c3c9d3; font-size: 20px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 22px; padding-right: 22px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="head">
      <span class="title">Weather Now</span>
      <span class="hint">Sample data · grab icons to move them</span>
      <button class="btn" id="unit"><span class="btn-text" id="unitLabel">Switch to °F</span></button>
    </div>`, { width: 0.46, position: [0, 0.39, 0] });
  root.add(header.object3D);

  header.on('unit', 'click', () => {
    useF = !useF;
    header.set('unitLabel', { text: useF ? 'Switch to °C' : 'Switch to °F' });
    cities.forEach((city, i) => {
      panels[i].set('temp' + i, { text: fmt(city.c) });
      panels[i].set('range' + i, { text: `H ${fmt(city.hi)}  ·  L ${fmt(city.lo)}` });
    });
  });

  return {
    root,
    update(time) {
      for (let i = 0; i < rayGroups.length; i++) rayGroups[i].rotation.z = time * 0.3;
      for (let i = 0; i < falling.length; i++) {
        const f = falling[i];
        const t = (time * f.speed + f.phase) % 1;
        f.mesh.position.y = f.baseY - t * 0.05;
        f.mesh.position.x = f.x + Math.sin(time * 2 + f.phase * 10) * f.sway;
        f.mesh.scale.setScalar(t > 0.85 ? Math.max(0.01, (1 - t) / 0.15) : 1);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Coaster (stays on the desk when the mug is lifted)
  const coaster = new THREE.Mesh(
    new THREE.CylinderGeometry(0.06, 0.06, 0.006, 32),
    new THREE.MeshStandardMaterial({ color: 0x6b4a2f, roughness: 0.9 }),
  );
  coaster.name = 'Coaster';
  coaster.position.set(-0.1, 0.003, 0);
  root.add(coaster);

  // Mug (one grabbable group)
  const mug = new THREE.Group();
  mug.name = 'Mug';

  const glazeMat = new THREE.MeshStandardMaterial({
    color: 0xf1e8d8,
    roughness: 0.25,
    metalness: 0.05,
    side: THREE.DoubleSide,
  });

  // Hollow body from a lathe profile (x = radius, y = height), ~350 ml inside
  const profile = [
    new THREE.Vector2(0.0, 0.0),
    new THREE.Vector2(0.036, 0.0),
    new THREE.Vector2(0.04, 0.005),
    new THREE.Vector2(0.04, 0.09),
    new THREE.Vector2(0.0375, 0.09),
    new THREE.Vector2(0.0375, 0.01),
    new THREE.Vector2(0.0, 0.01),
  ];
  const body = new THREE.Mesh(new THREE.LatheGeometry(profile, 32), glazeMat);
  body.name = 'MugBody';
  mug.add(body);

  // Handle: half torus on the +X side
  const handle = new THREE.Mesh(
    new THREE.TorusGeometry(0.024, 0.006, 12, 24, Math.PI),
    glazeMat,
  );
  handle.name = 'MugHandle';
  handle.rotation.z = -Math.PI / 2;
  handle.position.set(0.038, 0.047, 0);
  mug.add(handle);

  // Coffee surface
  const coffee = new THREE.Mesh(
    new THREE.CircleGeometry(0.0372, 32),
    new THREE.MeshStandardMaterial({ color: 0x3b2314, roughness: 0.3 }),
  );
  coffee.name = 'Coffee';
  coffee.rotation.x = -Math.PI / 2;
  coffee.position.y = 0.078;
  mug.add(coffee);

  // Steam wisps (decorative, not hit by pinch rays)
  const wisps = [];
  for (let i = 0; i < 3; i++) {
    const m = new THREE.Mesh(
      new THREE.SphereGeometry(0.008, 12, 8),
      new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.2, depthWrite: false }),
    );
    m.raycast = () => {};
    m.userData.phase = i / 3;
    m.userData.ox = (i - 1) * 0.014;
    mug.add(m);
    wisps.push(m);
  }

  mug.position.set(-0.1, 0.006, 0);
  root.add(mug);
  traits(mug, { grab: true });

  // Info card
