  });

  return {
    root,
    update(time) {
      for (let i = 0; i < wisps.length; i++) {
        const w = wisps[i];
        const t = (time * 0.15 + w.userData.phase) % 1;
        w.position.set(
          w.userData.ox + Math.sin(time * 1.2 + i * 2) * 0.006 * t,
          0.085 + t * 0.07,
          Math.cos(time + i) * 0.006,
        );
        w.material.opacity = 0.22 * Math.sin(t * Math.PI);
        w.scale.setScalar(0.7 + t * 1.2);
      }
    },
  };
}

