        const p = puffs[i];
        p.position.set(Math.sin(time + i * 1.7) * 0.01 * t, 0.085 + t * 0.07, Math.cos(time * 0.8 + i) * 0.01 * t);
        p.scale.setScalar(0.6 + t * 1.2);
        p.material.opacity = 0.3 * (1 - t);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const std = (color, extra) =>
    new THREE.MeshStandardMaterial(Object.assign({ color: color, roughness: 0.7 }, extra || {}));

  const C_LIGHT = 0xffd54a, C_WATER = 0x4aa3ff, C_CO2 = 0xb4bcc8, C_O2 = 0xff8a9a;
  const hex = (c) => '#' + c.toString(16).padStart(6, '0');

  // ---------- Plant (pot, soil, stem, leaves) ----------
  const plant = new THREE.Group();
  plant.name = 'Plant';
  root.add(plant);

  const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.038, 0.07, 24), std(0xb5653a));
  pot.name = 'Pot';
  pot.position.y = 0.035;
  plant.add(pot);

  const soil = new THREE.Mesh(new THREE.CylinderGeometry(0.048, 0.048, 0.006, 24), std(0x4a3222, { roughness: 1 }));
  soil.name = 'Soil';
  soil.position.y = 0.071;
  plant.add(soil);

  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.009, 0.2, 12), std(0x3f8f3a));
  stem.name = 'Stem';
  stem.position.y = 0.17;
  plant.add(stem);

  const leafMat = std(0x3fbf4a, { roughness: 0.55 });
  const leafGeo = new THREE.SphereGeometry(1, 16, 10);
  const leafDefs = [
    [-0.055, 0.19, -0.35, 1.0],
    [0.055, 0.21, 0.35, 1.0],
    [-0.05, 0.255, -0.3, 0.9],
    [0.05, 0.275, 0.3, 0.9],
  ];
  leafDefs.forEach((d, i) => {
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.name = 'Leaf ' + (i + 1);
    leaf.scale.set(0.055 * d[3], 0.012, 0.027 * d[3]);
    leaf.position.set(d[0], d[1], 0);
    leaf.rotation.z = d[2];
    plant.add(leaf);
  });
  const bud = new THREE.Mesh(new THREE.SphereGeometry(0.011, 12, 8), leafMat);
  bud.position.set(0, 0.272, 0);
  plant.add(bud);

  // ---------- Sun (grabbable) ----------
  const sun = new THREE.Group();
  sun.name = 'Sun';
  sun.position.set(-0.3, 0.4, -0.03);
  root.add(sun);

  const sunMat = std(0xffc23d, { emissive: 0xff8a00, emissiveIntensity: 0.9, roughness: 0.4 });
  const sunBall = new THREE.Mesh(new THREE.SphereGeometry(0.04, 28, 16), sunMat);
  sunBall.name = 'Sun ball';
  sun.add(sunBall);

  const rayCount = 12;
  const rays = new THREE.InstancedMesh(
    new THREE.ConeGeometry(0.008, 0.03, 8),
    new THREE.MeshBasicMaterial({ color: 0xffd54a }),
    rayCount,
  );
  const dummy = new THREE.Object3D();
  for (let i = 0; i < rayCount; i++) {
    const a = (i / rayCount) * Math.PI * 2;
    dummy.position.set(Math.cos(a) * 0.063, Math.sin(a) * 0.063, 0);
    dummy.rotation.set(0, 0, a - Math.PI / 2);
    dummy.updateMatrix();
    rays.setMatrixAt(i, dummy.matrix);
  }
  sun.add(rays);
  traits(sun, { grab: true });

  // ---------- Arrows ----------
  const Y = new THREE.Vector3(0, 1, 0);
  const tmp = new THREE.Vector3();

  function makeArrow(color, len, name) {
    const g = new THREE.Group();
    g.name = name;
    const mat = std(color, { emissive: color, emissiveIntensity: 0.35 });
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.011, 0.011, len - 0.035, 12), mat);
    shaft.position.y = (len - 0.035) / 2;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.024, 0.035, 16), mat);
    head.position.y = len - 0.0175;
    g.add(shaft);
    g.add(head);
    return g;
  }
  function arrowBetween(color, from, to, name) {
    const len = from.distanceTo(to);
    const g = makeArrow(color, len, name);
    g.position.copy(from);
    tmp.subVectors(to, from).normalize();
    g.quaternion.setFromUnitVectors(Y, tmp);
    root.add(g);
    return g;
  }

  const LIGHT_LEN = 0.15;
  const lightTarget = new THREE.Vector3(-0.07, 0.27, 0.015);
  const lightArrow = makeArrow(C_LIGHT, LIGHT_LEN, 'Light arrow');
  root.add(lightArrow);

  const waterFrom = new THREE.Vector3(-0.29, 0.045, 0.012);
  const waterTo = new THREE.Vector3(-0.05, 0.045, 0.012);
  const waterArrow = arrowBetween(C_WATER, waterFrom, waterTo, 'Water arrow');

  const co2From = new THREE.Vector3(0.31, 0.27, 0.02);
  const co2To = new THREE.Vector3(0.125, 0.24, 0.02);
  const co2Arrow = arrowBetween(C_CO2, co2From, co2To, 'Carbon dioxide arrow');

  const o2From = new THREE.Vector3(0.105, 0.3, 0.0);
  const o2To = new THREE.Vector3(0.27, 0.38, 0.0);
  const o2Arrow = arrowBetween(C_O2, o2From, o2To, 'Oxygen arrow');

  // ---------- Flowing particles (scenery along each arrow) ----------
  const partGeo = new THREE.SphereGeometry(0.008, 12, 8);
  function makeFlow(color, pts, n) {
    const mat = std(color, { emissive: color, emissiveIntensity: 0.7, roughness: 0.4 });
    const meshes = [];
    for (let i = 0; i < n; i++) {
      const m = new THREE.Mesh(partGeo, mat);
      root.add(m);
      meshes.push(m);
    }
    const cum = [0];
    for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + pts[i].distanceTo(pts[i - 1]));
    return { pts: pts, cum: cum, meshes: meshes };
  }
  const V = (x, y, z) => new THREE.Vector3(x, y, z);

  const lightFlow = makeFlow(C_LIGHT, [V(0, 0, 0), V(0, 0, 0.1)], 3);
  const waterFlow = makeFlow(C_WATER, [waterFrom.clone(), V(0, 0.05, 0.012), V(0, 0.25, 0.014)], 4);
  const co2Flow = makeFlow(C_CO2, [co2From.clone(), co2To.clone()], 3);
  const o2Flow = makeFlow(C_O2, [o2From.clone(), o2To.clone()], 3);
  const flows = [lightFlow, waterFlow, co2Flow, o2Flow];
  const MPS = 0.07; // particle speed in meters per second

  function updateFlow(f, time, show) {
    const total = f.cum[f.cum.length - 1];
    const n = f.meshes.length;
    for (let i = 0; i < n; i++) {
      const m = f.meshes[i];
      m.visible = show;
      if (!show) continue;
      const u = (time * MPS / total + i / n) % 1;
      const d = u * total;
      let k = 1;
      while (k < f.cum.length - 1 && f.cum[k] < d) k++;
      const seg = f.cum[k] - f.cum[k - 1];
      const a = seg > 0 ? (d - f.cum[k - 1]) / seg : 0;
      m.position.lerpVectors(f.pts[k - 1], f.pts[k], a);
      m.scale.setScalar(0.4 + 0.6 * Math.sin(Math.PI * u));
    }
  }

  // ---------- Labels ----------
  function label(title, sub, color, pos) {
    const h = ui(`
      <style>
        .c { width: 240px; flex-direction: column; align-items: center; gap: 2px;
             padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px;
             background-color: #1a1d22; border-radius: 14px; border-color: ${hex(color)}; border-width: 3px; }
        .t { color: ${hex(color)}; font-size: 28px; font-weight: 700; text-align: center; }
        .s { color: #d7dbe2; font-size: 20px; text-align: center; }
      </style>
      <div class="c"><span class="t">${title}</span><span class="s">${sub}</span></div>`,
      { width: 0.14, position: pos });
    root.add(h.object3D);
    return h;
  }
  const lightLabel = label('Light', 'from the Sun', C_LIGHT, [-0.1, 0.38, 0.03]);
  const waterLabel = label('Water', 'H2O from the soil', C_WATER, [-0.2, 0.115, 0.03]);
  const co2Label = label('Carbon dioxide', 'CO2 from the air', C_CO2, [0.31, 0.2, 0.02]);
  const o2Label = label('Oxygen', 'O2 released', C_O2, [0.32, 0.44, 0.0]);

  // ---------- Info panel ----------
  const steps = [
    { title: 'Photosynthesis', color: '#ffffff', target: null,
      body: 'Plants turn light, water and carbon dioxide into sugar and oxygen. Press an arrow or the plant, or tap Next step.' },
    { title: 'Light', color: hex(C_LIGHT), target: lightArrow,
      body: 'Chlorophyll in the leaf cells (inside chloroplasts) absorbs sunlight, mostly red and blue. This energy powers the reaction.' },
    { title: 'Water (H2O)', color: hex(C_WATER), target: waterArrow,
      body: 'Roots take up water from the soil. It travels up the stem to the leaves.' },
    { title: 'Carbon dioxide (CO2)', color: hex(C_CO2), target: co2Arrow,
      body: 'CO2 from the air enters the leaf through tiny pores called stomata.' },
    { title: 'Oxygen (O2)', color: hex(C_O2), target: o2Arrow,
      body: 'Oxygen is made when light energy splits water. It is a by-product and leaves through the stomata.' },
    { title: 'Sugar (glucose)', color: '#8be28b', target: plant,
      body: 'The plant builds glucose, C6H12O6, from CO2 and water. It uses the sugar for energy and growth.' },
  ];

  const info = ui(`
    <style>
      .card { width: 560px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .eq { color: #ffd54a; font-size: 22px; font-weight: 700; }
      .row { flex-direction: row; gap: 14px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title" id="title">Photosynthesis</span>
      <span class="body" id="body">Plants turn light, water and carbon dioxide into sugar and oxygen.</span>
      <span class="eq">6 CO2 + 6 H2O + light -> C6H12O6 + 6 O2</span>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next step</span></button>
        <button class="btn" id="sun" style="background-color: #c98a00"><span class="btn-text" id="sunText">Sun: ON</span></button>
      </div>
    </div>`, { width: 0.4, position: [0, 0.09, 0.2] });
  root.add(info.object3D);

  let step = 0;
  let sunOn = true;
  let highlight = null;
  const pulsing = [lightArrow, waterArrow, co2Arrow, o2Arrow, plant];

  function showStep(i) {
    step = i;
    const s = steps[i];
    highlight = s.target;
    info.set('title', { text: s.title, color: s.color });
    info.set('body', { text: s.body });
  }
  function applySun() {
    sunMat.color.setHex(sunOn ? 0xffc23d : 0x8a7a50);
    sunMat.emissive.setHex(sunOn ? 0xff8a00 : 0x221100);
    sunMat.emissiveIntensity = sunOn ? 0.9 : 0.1;
    rays.visible = sunOn;
    lightArrow.visible = sunOn;
    lightLabel.object3D.visible = sunOn;
    leafMat.color.setHex(sunOn ? 0x3fbf4a : 0x2d7a35);
    info.set('sunText', { text: sunOn ? 'Sun: ON' : 'Sun: OFF' });
    info.set('sun', { backgroundColor: sunOn ? '#c98a00' : '#4a4f58' });
    if (sunOn) {
      showStep(step);
    } else {
      highlight = null;
      info.set('title', { text: 'No light, no photosynthesis', color: '#ff8a9a' });
      info.set('body', { text: 'Without light the leaf cannot split water, so no sugar is made and no oxygen is released. Turn the Sun back on!' });
    }
  }

  info.on('next', 'click', () => {
    if (!sunOn) { sunOn = true; applySun(); }
    showStep((step + 1) % steps.length);
  });
  info.on('sun', 'click', () => {
    sunOn = !sunOn;
    applySun();
  });

  function selectIfOn(i) {
    if (!sunOn) { sunOn = true; applySun(); }
    showStep(i);
  }
  traits(lightArrow, { onPress: () => selectIfOn(1) });
  traits(waterArrow, { onPress: () => selectIfOn(2) });
  traits(co2Arrow, { onPress: () => selectIfOn(3) });
  traits(o2Arrow, { onPress: () => selectIfOn(4) });
  traits(plant, { onPress: () => selectIfOn(5) });

  // ---------- Per-frame ----------
  const dir = new THREE.Vector3();
  const mid = new THREE.Vector3();

  return {
    root,
    update(time, delta) {
      rays.rotation.z += delta * 0.3;

      // Light arrow always points from the Sun to the leaf, even if the Sun is moved.
      dir.subVectors(lightTarget, sun.position);
      if (dir.lengthSq() < 1e-6) dir.set(1, 0, 0);
      dir.normalize();
      lightArrow.position.copy(lightTarget).addScaledVector(dir, -LIGHT_LEN);
      lightArrow.quaternion.setFromUnitVectors(Y, dir);

      lightFlow.pts[0].copy(lightArrow.position);
      lightFlow.pts[1].copy(lightTarget).addScaledVector(dir, -0.03);
      lightFlow.cum[1] = lightFlow.pts[0].distanceTo(lightFlow.pts[1]);

      mid.copy(lightArrow.position).addScaledVector(dir, LIGHT_LEN * 0.5);
      lightLabel.object3D.position.set(mid.x + 0.02, mid.y + 0.08, mid.z + 0.03);

      // Flowing particles (only while the sun shines)
      updateFlow(lightFlow, time, sunOn);
      updateFlow(waterFlow, time, sunOn);
      updateFlow(co2Flow, time, sunOn);
      updateFlow(o2Flow, time, sunOn);

      // Pulse the part currently explained
      const pulse = Math.sin(time * 4);
      for (let i = 0; i < pulsing.length; i++) {
        const o = pulsing[i];
        const base = 1;
        o.scale.setScalar(o === highlight ? base + (o === plant ? 0.03 : 0.12) * (0.5 + 0.5 * pulse) : base);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Quiz data ----------
  const questions = [
    { a: 6, b: 7 },
    { a: 8, b: 9 },
    { a: 7, b: 7 },
    { a: 9, b: 4 },
    { a: 8, b: 6 },
  ];
  let qi = 0, score = 0, answered = false, finished = false;
  let options = [];

  function makeOptions(q, index) {
    const c = q.a * q.b;
    const cands = [q.a * (q.b + 1), q.a * (q.b - 1), (q.a + 1) * q.b, (q.a - 1) * q.b, c + 10, c - 10, c + 2];
    const d = [];
    for (const v of cands) {
      if (v > 0 && v !== c && d.indexOf(v) === -1) d.push(v);
      if (d.length === 3) break;
    }
    const pos = (index * 3 + 1) % 4;
    const arr = [];
    let di = 0;
    for (let i = 0; i < 4; i++) arr.push(i === pos ? c : d[di++]);
    return arr;
  }

  // ---------- 3D array visualisation (rows x columns of balls) ----------
  const board = new THREE.Group();
  board.name = 'ArrayBoard';
  board.position.set(-0.22, 0.3, 0);
  root.add(board);

  const plate = new THREE.Mesh(
    new THREE.BoxGeometry(0.31, 0.31, 0.012),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.7 }),
  );
  plate.position.z = -0.012;
  board.add(plate);

  const ballGeo = new THREE.SphereGeometry(0.011, 16, 10);
  const ballMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.4 });
  const balls = new THREE.InstancedMesh(ballGeo, ballMat, 81);
  balls.name = 'Balls';
  board.add(balls);
  const dummy = new THREE.Object3D();
  const colA = new THREE.Color(0x4fa3ff);
  const colB = new THREE.Color(0xffb347);

  function layoutBalls(a, b) {
    const s = 0.03;
    let n = 0;
    for (let r = 0; r < a; r++) {
      for (let c = 0; c < b; c++) {
        dummy.position.set((c - (b - 1) / 2) * s, ((a - 1) / 2 - r) * s, 0);
        dummy.updateMatrix();
        balls.setMatrixAt(n, dummy.matrix);
        balls.setColorAt(n, r % 2 === 0 ? colA : colB);
        n++;
      }
    }
    balls.count = n;
    balls.instanceMatrix.needsUpdate = true;
    if (balls.instanceColor) balls.instanceColor.needsUpdate = true;
  }

  traits(board, { grab: true });

  // Feedback orb
  const orbMat = new THREE.MeshStandardMaterial({ color: 0x888888, emissive: 0x222222, emissiveIntensity: 0.8 });
  const orb = new THREE.Mesh(new THREE.SphereGeometry(0.025, 24, 12), orbMat);
  orb.name = 'FeedbackOrb';
  orb.position.set(-0.22, 0.51, 0);
  root.add(orb);
  function setOrb(hex) {
    orbMat.color.setHex(hex);
    orbMat.emissive.setHex(hex);
  }

  // ---------- UI panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 14px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 24px; padding-right: 24px; border-radius: 22px; background-color: #1f2228; width: 520px; }
      .row { flex-direction: row; justify-content: space-between; align-items: center; }
      .small { color: #aab2bf; font-size: 22px; }
      .score { color: #ffd166; font-size: 26px; font-weight: 700; }
      .q { color: #ffffff; font-size: 56px; font-weight: 700; text-align: center; }
      .hint { color: #d7dbe2; font-size: 22px; text-align: center; }
      .answers { flex-direction: row; gap: 14px; justify-content: center; }
      .ans { width: 230px; padding-top: 16px; padding-bottom: 16px; border-radius: 14px;
             background-color: #3a4a66; align-items: center; justify-content: center; }
      .ans-text { color: #ffffff; font-size: 34px; font-weight: 700; text-align: center; }
      .fb { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
      .next { padding-top: 14px; padding-bottom: 14px; border-radius: 14px; background-color: #2f9e6b;
              align-items: center; justify-content: center; }
      .next-text { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <div class="row">
        <span class="small" id="prog">Question 1 / 5</span>
        <span class="score" id="score">Score: 0</span>
      </div>
      <span class="q" id="q">6 × 7 = ?</span>
      <span class="hint" id="hint">6 rows of 7 balls</span>
      <div class="answers" id="rowA">
        <button class="ans" id="b0"><span class="ans-text" id="t0">0</span></button>
        <button class="ans" id="b1"><span class="ans-text" id="t1">0</span></button>
      </div>
      <div class="answers" id="rowB">
        <button class="ans" id="b2"><span class="ans-text" id="t2">0</span></button>
        <button class="ans" id="b3"><span class="ans-text" id="t3">0</span></button>
      </div>
      <span class="fb" id="fb">Pick an answer</span>
      <button class="next" id="next"><span class="next-text" id="nextText">Next question</span></button>
    </div>`, { width: 0.4, position: [0.17, 0.3, 0] });
  root.add(panel.object3D);

  const NEUTRAL = '#3a4a66', GOOD = '#2f9e6b', BAD = '#c0443f';

  function showQuestion() {
    const q = questions[qi];
    answered = false;
    options = makeOptions(q, qi);
    panel.set('prog', { text: 'Question ' + (qi + 1) + ' / ' + questions.length });
    panel.set('q', { text: q.a + ' × ' + q.b + ' = ?' });
    panel.set('hint', { text: q.a + ' rows of ' + q.b + ' balls' });
    for (let i = 0; i < 4; i++) {
      panel.set('t' + i, { text: String(options[i]) });
      panel.set('b' + i, { backgroundColor: NEUTRAL });
    }
    panel.set('rowA', { display: 'flex' });
    panel.set('rowB', { display: 'flex' });
    panel.set('fb', { text: 'Pick an answer', color: '#ffffff' });
    panel.set('next', { display: 'none' });
    layoutBalls(q.a, q.b);
    setOrb(0x888888);
  }

  function showFinal() {
    finished = true;
    panel.set('prog', { text: 'Finished!' });
    panel.set('q', { text: score + ' / ' + questions.length });
    panel.set('hint', { text: score === questions.length ? 'Perfect score! 🎉' : score >= 3 ? 'Nice work!' : 'Keep practising!' });
    panel.set('rowA', { display: 'none' });
    panel.set('rowB', { display: 'none' });
    panel.set('fb', { text: 'Final score: ' + score + ' out of ' + questions.length, color: '#ffd166' });
    panel.set('nextText', { text: 'Play again' });
    panel.set('next', { display: 'flex' });
    balls.count = 0;
    setOrb(0xffd166);
  }

  function choose(i) {
    if (answered || finished) return;
    answered = true;
    const q = questions[qi];
    const correct = q.a * q.b;
    const ok = options[i] === correct;
    if (ok) {
      score++;
      panel.set('b' + i, { backgroundColor: GOOD });
      panel.set('fb', { text: 'Correct! ' + q.a + ' × ' + q.b + ' = ' + correct, color: '#7be0a8' });
      setOrb(0x2fdc7a);
    } else {
      panel.set('b' + i, { backgroundColor: BAD });
      const ci = options.indexOf(correct);
      panel.set('b' + ci, { backgroundColor: GOOD });
      panel.set('fb', { text: 'Not quite: ' + q.a + ' × ' + q.b + ' = ' + correct, color: '#ff8a85' });
      setOrb(0xe04b45);
    }
    panel.set('score', { text: 'Score: ' + score });
    panel.set('nextText', { text: qi === questions.length - 1 ? 'See results' : 'Next question' });
    panel.set('next', { display: 'flex' });
  }

  for (let i = 0; i < 4; i++) {
    panel.on('b' + i, 'click', () => choose(i));
  }

  panel.on('next', 'click', () => {
    if (finished) {
      finished = false;
      qi = 0;
      score = 0;
      panel.set('score', { text: 'Score: 0' });
      showQuestion();
      return;
    }
    if (!answered) return;
    if (qi === questions.length - 1) {
      showFinal();
    } else {
      qi++;
      showQuestion();
    }
  });

  showQuestion();

  return {
    root,
    update(time) {
      // Gentle pulse on the feedback orb
      const s = 1 + Math.sin(time * 3) * 0.06;
      orb.scale.set(s, s, s);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Quiz data ----------
  const questions = [
    { a: 3, b: 4 },
    { a: 6, b: 7 },
    { a: 8, b: 5 },
    { a: 9, b: 6 },
    { a: 7, b: 8 },
  ];
  const correctSlots = [2, 0, 3, 1, 2];

  // Build 4 options per question: the correct product plus 3 plausible distractors.
  questions.forEach((q, i) => {
    const p = q.a * q.b;
    const cands = [p + q.a, p - q.a, p + q.b, p - q.b, p + 10, p - 10, p + 1, p - 1, p + 2, p - 2];
    const wrong = [];
    for (const c of cands) {
      if (c > 0 && c !== p && wrong.indexOf(c) < 0) wrong.push(c);
      if (wrong.length === 3) break;
    }
    const opts = [];
    let w = 0;
    for (let s = 0; s < 4; s++) {
      opts.push(s === correctSlots[i] ? p : wrong[w++]);
    }
    q.options = opts;
    q.answerSlot = correctSlots[i];
    q.product = p;
  });

  // ---------- State ----------
  let current = 0;
  let score = 0;
  let answered = false;
  let finished = false;
  const results = [null, null, null, null, null]; // null | true | false

  // ---------- 3D: multiplication array ----------
  const cubeSize = 0.022;
  const spacing = 0.025;
  const cubeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 });
  const cubes = new THREE.InstancedMesh(new THREE.BoxGeometry(cubeSize, cubeSize, cubeSize), cubeMat, 81);
  cubes.name = 'MultiplicationArray';
  cubes.position.set(-0.22, 0.17, 0);
  root.add(cubes);
  traits(cubes, { grab: true });

  const dummy = new THREE.Object3D();
  const tmpColor = new THREE.Color();

  function buildArray(a, b) {
    let i = 0;
    for (let r = 0; r < a; r++) {
      tmpColor.setHSL((r / 9) * 0.8 + 0.02, 0.65, 0.55);
      for (let c = 0; c < b; c++) {
        dummy.position.set((c - (b - 1) / 2) * spacing, (r - (a - 1) / 2) * spacing, 0);
        dummy.updateMatrix();
        cubes.setMatrixAt(i, dummy.matrix);
        cubes.setColorAt(i, tmpColor);
        i++;
      }
    }
    cubes.count = i;
    cubes.instanceMatrix.needsUpdate = true;
    if (cubes.instanceColor) cubes.instanceColor.needsUpdate = true;
    cubes.computeBoundingSphere();
    cubes.computeBoundingBox();
  }

  // ---------- 3D: progress gems ----------
  const gemGeo = new THREE.SphereGeometry(0.015, 24, 12);
  const gemMats = {
    pending: new THREE.MeshStandardMaterial({ color: 0x6b7280, roughness: 0.4 }),
    right: new THREE.MeshStandardMaterial({ color: 0x2fbf71, emissive: 0x1a8a4c, emissiveIntensity: 0.6 }),
    wrong: new THREE.MeshStandardMaterial({ color: 0xe5484d, emissive: 0xa02025, emissiveIntensity: 0.6 }),
  };
  const gems = [];
  for (let i = 0; i < 5; i++) {
    const g = new THREE.Mesh(gemGeo, gemMats.pending);
    g.name = 'ProgressGem' + (i + 1);
    g.position.set(-0.22 + (i - 2) * 0.045, 0.37, 0);
    root.add(g);
    gems.push(g);
  }

  function refreshGems() {
    for (let i = 0; i < 5; i++) {
      gems[i].material = results[i] === null ? gemMats.pending : results[i] ? gemMats.right : gemMats.wrong;
    }
  }

  // ---------- UI ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 14px; width: 500px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 24px; padding-right: 24px; border-radius: 22px; background-color: #1f2228; }
      .top { flex-direction: row; justify-content: space-between; align-items: center; }
      .small { color: #aab1bd; font-size: 22px; }
      .score { color: #ffd84d; font-size: 26px; font-weight: 700; }
      .question { color: #ffffff; font-size: 56px; font-weight: 700; text-align: center; }
      .row { flex-direction: row; gap: 14px; justify-content: center; }
      .ans { width: 224px; height: 78px; border-radius: 14px; background-color: #2f6fdb;
             align-items: center; justify-content: center; }
      .ans-text { color: #ffffff; font-size: 34px; font-weight: 700; text-align: center; }
      .feedback { color: #d7dbe2; font-size: 24px; text-align: center; }
      .actions { flex-direction: row; gap: 14px; justify-content: center; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #3a3f48; align-items: center; justify-content: center; }
      .next { background-color: #2fbf71; display: none; }
      .restart { background-color: #8a5cf5; display: none; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="top">
        <span class="small" id="progress">Question 1 of 5</span>
        <span class="score" id="score">Score: 0</span>
      </div>
      <span class="question" id="question">3 × 4 = ?</span>
      <div class="row" id="row1">
        <button class="ans" id="b0"><span class="ans-text" id="t0">0</span></button>
        <button class="ans" id="b1"><span class="ans-text" id="t1">0</span></button>
      </div>
      <div class="row" id="row2">
        <button class="ans" id="b2"><span class="ans-text" id="t2">0</span></button>
        <button class="ans" id="b3"><span class="ans-text" id="t3">0</span></button>
      </div>
      <span class="feedback" id="feedback">Pick the answer.</span>
      <div class="actions">
        <button class="btn" id="hint"><span class="btn-text">Show cubes</span></button>
        <button class="btn next" id="next"><span class="btn-text" id="nexttext">Next</span></button>
        <button class="btn restart" id="restart"><span class="btn-text">Play again</span></button>
      </div>
    </div>`, { width: 0.4, position: [0.2, 0.24, 0], rotationY: -0.15 });
  root.add(panel.object3D);

  const BLUE = '#2f6fdb';
  const GREEN = '#2fbf71';
  const RED = '#e5484d';
  const DIM = '#3d4350';

  function showQuestion() {
    const q = questions[current];
    answered = false;
    panel.set('progress', { text: 'Question ' + (current + 1) + ' of 5' });
    panel.set('score', { text: 'Score: ' + score });
    panel.set('question', { text: q.a + ' × ' + q.b + ' = ?' });
    for (let i = 0; i < 4; i++) {
      panel.set('t' + i, { text: String(q.options[i]) });
      panel.set('b' + i, { backgroundColor: BLUE });
    }
    panel.set('row1', { display: 'flex' });
    panel.set('row2', { display: 'flex' });
    panel.set('feedback', { text: 'Pick the answer.', color: '#d7dbe2' });
    panel.set('hint', { display: 'flex' });
    panel.set('next', { display: 'none' });
    panel.set('restart', { display: 'none' });
    cubes.visible = false;
    buildArray(q.a, q.b);
    refreshGems();
  }

  function showResults() {
    finished = true;
    const msg = score === 5 ? 'Perfect score!' : score >= 3 ? 'Nice work!' : 'Keep practicing!';
    panel.set('progress', { text: 'Quiz complete' });
    panel.set('score', { text: 'Score: ' + score + '/5' });
    panel.set('question', { text: score + ' / 5' });
    panel.set('row1', { display: 'none' });
    panel.set('row2', { display: 'none' });
    panel.set('feedback', { text: msg + ' Tap Play again to retry.', color: '#ffd84d' });
    panel.set('hint', { display: 'none' });
    panel.set('next', { display: 'none' });
    panel.set('restart', { display: 'flex' });
    cubes.visible = false;
  }

  function choose(slot) {
    if (answered || finished) return;
    answered = true;
    const q = questions[current];
    const ok = slot === q.answerSlot;
    results[current] = ok;
    if (ok) score++;
    for (let i = 0; i < 4; i++) {
      if (i === q.answerSlot) panel.set('b' + i, { backgroundColor: GREEN });
      else if (i === slot) panel.set('b' + i, { backgroundColor: RED });
      else panel.set('b' + i, { backgroundColor: DIM });
    }
    panel.set('score', { text: 'Score: ' + score });
    panel.set('feedback', {
      text: (ok ? 'Correct! ' : 'Not quite. ') + q.a + ' × ' + q.b + ' = ' + q.product +
        ' (' + q.a + ' rows of ' + q.b + ')',
      color: ok ? '#7de3a8' : '#ff8f93',
    });
    panel.set('nexttext', { text: current === questions.length - 1 ? 'See results' : 'Next' });
    panel.set('next', { display: 'flex' });
    panel.set('hint', { display: 'none' });
    cubes.visible = true;
    refreshGems();
  }

  for (let i = 0; i < 4; i++) {
    panel.on('b' + i, 'click', () => choose(i));
  }

  panel.on('hint', 'click', () => {
    if (finished) return;
    cubes.visible = true;
    panel.set('feedback', {
      text: 'Count the cubes: ' + questions[current].a + ' rows of ' + questions[current].b + '. Pinch to move them!',
      color: '#d7dbe2',
    });
  });

  panel.on('next', 'click', () => {
    if (!answered || finished) return;
    if (current < questions.length - 1) {
      current++;
      showQuestion();
    } else {
      showResults();
    }
  });

  panel.on('restart', 'click', () => {
    current = 0;
    score = 0;
    finished = false;
    for (let i = 0; i < 5; i++) results[i] = null;
    showQuestion();
  });

  showQuestion();

  return {
    root,
    update(time) {
      // Pulse the gem for the current question; the grabbable array is left alone.
      for (let i = 0; i < gems.length; i++) {
        const active = !finished && i === current && results[i] === null;
        const s = active ? 1 + Math.sin(time * 4) * 0.2 : 1;
        gems[i].scale.setScalar(s);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
