  let today = 3;
  try { today = (new Date().getDay() + 6) % 7; } catch (e) { today = 3; }

  const checked = habits.map(() => [false, false, false, false, false, false, false]);

  // Streak = consecutive checked days ending today (or yesterday if today isn't done yet)
  function streakOf(h) {
    let i = checked[h][today] ? today : today - 1;
    let n = 0;
    while (i >= 0 && checked[h][i]) { n++; i--; }
    return n;
