    });
    const crystal = new THREE.Mesh(crystalGeo, mat);
    crystal.name = 'Crystal ' + h.short;
    crystal.position.set(x, 0.065, 0.12);
    crystal.scale.setScalar(0.6);
    root.add(crystal);
    traits(crystal, { grab: true });
    crystals.push({ mesh: crystal, mat, baseY: 0.065, target: 0.6 });

    const label = ui(`
      <style>
        .l { padding-top: 6px; padding-bottom: 6px; padding-left: 10px; padding-right: 10px;
             border-radius: 10px; background-color: #1f2228; align-items: center; justify-content: center; }
        .lt { color: #ffffff; font-size: 24px; font-weight: 700; text-align: center; }
      </style>
      <div class="l"><span class="lt" id="lt">${h.short}: 0 days</span></div>`,
      { width: 0.15, position: [x, 0.0, 0.2] });
    // label sits in front of the base, lifted so it is readable
    label.object3D.position.y = 0.022;
    root.add(label.object3D);
    labels.push(label);
  });

  // ---------- Refresh ----------
  function refresh(hi) {
    const n = streakOf(hi);
    panel.set('s' + hi, { text: streakText(n), color: n > 0 ? habits[hi].color : '#ffffff' });
    labels[hi].set('lt', { text: habits[hi].short + ': ' + streakText(n) });
    crystals[hi].target = 0.6 + Math.min(n, 7) * 0.12;
    const done = checked[hi].filter(Boolean).length;
    crystals[hi].doneCount = done;
  }

  habits.forEach((h, hi) => {
    for (let d = 0; d < 7; d++) {
      panel.on(`c${hi}_${d}`, 'click', () => {
        checked[hi][d] = !checked[hi][d];
        const on = checked[hi][d];
        panel.set(`c${hi}_${d}`, {
          backgroundColor: on ? h.color : '#353a44',
          borderColor: d === today ? '#ffffff' : (on ? h.color : '#353a44'),
        });
        panel.set(`t${hi}_${d}`, { color: on ? '#111418' : '#8b93a0' });
        refresh(hi);
        const total = checked.reduce((a, r) => a + r.filter(Boolean).length, 0);
        panel.set('foot', { text: total + ' of 21 check-ins done this week.' });
      });
    }
    refresh(hi);
  });

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < crystals.length; i++) {
        const c = crystals[i];
        // grow or shrink smoothly with the streak
        const s = c.mesh.scale.x + (c.target - c.mesh.scale.x) * Math.min(1, delta * 3);
        c.mesh.scale.setScalar(s);
        const streakLevel = (c.target - 0.6) / 0.12;
        c.mat.emissiveIntensity = 0.05 + streakLevel * 0.12 + 0.05 * Math.sin(time * 2 + i);
        if (isGrabbed(c.mesh)) continue;
        c.mesh.rotation.y += delta * 0.6;
        c.mesh.position.y = c.baseY + s * 0.02 + Math.sin(time * 1.2 + i) * 0.004;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Atom definitions (CPK colours: oxygen red, hydrogen white) ----
  const R_O = 0.035;
  const R_H = 0.025;
  const defs = [
    { el: 'H', x: -0.30 },
    { el: 'O', x: -0.18 },
    { el: 'H', x: -0.06 },
    { el: 'H', x:  0.06 },
    { el: 'O', x:  0.18 },
    { el: 'H', x:  0.30 },
  ];
  const HOME_Y = 0.12;
  const HOME_Z = 0.08;

  const geoO = new THREE.SphereGeometry(R_O, 28, 16);
  const geoH = new THREE.SphereGeometry(R_H, 24, 14);

  const atoms = [];
  const glowUntil = [];
  defs.forEach((d, i) => {
    const isO = d.el === 'O';
    const mat = new THREE.MeshStandardMaterial({
      color: isO ? 0xe83a30 : 0xf4f4f4,
      roughness: 0.35,
      metalness: 0.0,
      emissive: 0x44ff99,
      emissiveIntensity: 0,
    });
    const m = new THREE.Mesh(isO ? geoO : geoH, mat);
    m.name = (isO ? 'Oxygen' : 'Hydrogen') + '_' + i;
    m.userData.el = d.el;
    m.userData.r = isO ? R_O : R_H;
    m.position.set(d.x, HOME_Y, HOME_Z);
    root.add(m);
    traits(m, { grab: true });
    atoms.push(m);
    glowUntil.push(0);
  });

  // ---- Bond sticks (pool, one per atom pair) ----
  const pairs = [];
  for (let i = 0; i < atoms.length; i++) {
    for (let j = i + 1; j < atoms.length; j++) pairs.push([i, j]);
  }
  const bondGeo = new THREE.CylinderGeometry(0.007, 0.007, 1, 10);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0xbfc5cf, roughness: 0.5 });
  const bondMeshes = pairs.map(() => {
    const b = new THREE.Mesh(bondGeo, bondMat);
    b.visible = false;
    b.name = 'Bond';
    root.add(b);
    return b;
  });

  const UP = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();

  function bonded(i, j) {
    const a = atoms[i], b = atoms[j];
    const d = a.position.distanceTo(b.position);
    return d < a.userData.r + b.userData.r + 0.025;
  }

  // ---- Instruction / result panel ----
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; width: 520px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .legend { flex-direction: row; align-items: center; gap: 10px; }
      .dotO { width: 22px; height: 22px; border-radius: 11px; background-color: #e83a30; }
      .dotH { width: 22px; height: 22px; border-radius: 11px; background-color: #f4f4f4; }
      .lg { color: #d7dbe2; font-size: 20px; }
      .result { color: #ffd166; font-size: 24px; font-weight: 700; }
      .row { flex-direction: row; gap: 14px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
              border-radius: 12px; background-color: #4a505b; }
      .bt { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body">Pinch atoms and push them together until they touch to form bonds.</span>
      <div class="legend">
        <div class="dotO"></div><span class="lg">Oxygen (O)</span>
        <div class="dotH"></div><span class="lg">Hydrogen (H)</span>
      </div>
      <span class="result" id="result">Build something, then press Check.</span>
      <div class="row">
        <button class="btn" id="check"><span class="bt">Check</span></button>
        <button class="btn2" id="reset"><span class="bt">Reset atoms</span></button>
      </div>
    </div>`, { width: 0.42, position: [0, 0.34, -0.1] });
  root.add(panel.object3D);

  const names = {
    H2O: 'water',
    H2O2: 'hydrogen peroxide',
    H2: 'hydrogen gas',
    O2: 'oxygen gas',
    HO: 'hydroxyl radical',
    H3O: 'hydronium-like ion',
  };

  function formula(h, o) {
    return (h > 0 ? 'H' + (h > 1 ? h : '') : '') + (o > 0 ? 'O' + (o > 1 ? o : '') : '');
  }

  let lastTime = 0;

  function analyze() {
    const n = atoms.length;
    const parent = [];
    for (let i = 0; i < n; i++) parent.push(i);
    const find = (x) => {
      while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
      return x;
    };
    for (const [i, j] of pairs) {
      if (bonded(i, j)) parent[find(i)] = find(j);
    }
    const groups = {};
    for (let i = 0; i < n; i++) {
      const r = find(i);
      if (!groups[r]) groups[r] = { members: [], h: 0, o: 0 };
      groups[r].members.push(i);
      if (atoms[i].userData.el === 'H') groups[r].h++; else groups[r].o++;
    }
    return Object.values(groups);
  }

  panel.on('check', 'click', () => {
    const groups = analyze();
    const molecules = groups.filter((g) => g.members.length > 1);
    const waters = molecules.filter((g) => g.h === 2 && g.o === 1);

    if (waters.length > 0) {
      waters.forEach((g) => g.members.forEach((i) => { glowUntil[i] = lastTime + 3; }));
      const msg = waters.length > 1
        ? 'Yes! You built ' + waters.length + ' water molecules (H2O).'
        : 'Yes! That is water, H2O: 2 hydrogen + 1 oxygen, bent at about 104.5 degrees.';
      panel.set('result', { text: msg, color: '#5de08a' });
    } else if (molecules.length === 0) {
      panel.set('result', { text: 'No bonds yet. Push atoms together until they touch.', color: '#ffd166' });
    } else {
      const list = molecules.map((g) => {
        const f = formula(g.h, g.o);
        return names[f] ? f + ' (' + names[f] + ')' : f;
      }).join(', ');
      panel.set('result', {
        text: 'Not water yet. You built: ' + list + '. Water needs exactly 2 H and 1 O.',
        color: '#ff9f5a',
      });
    }
  });

  panel.on('reset', 'click', () => {
    atoms.forEach((a, i) => {
      a.position.set(defs[i].x, HOME_Y, HOME_Z);
      glowUntil[i] = 0;
    });
    panel.set('result', { text: 'Atoms reset. Build something, then press Check.', color: '#ffd166' });
  });

  return {
    root,
    update(time) {
      lastTime = time;
      // Bond sticks
      for (let k = 0; k < pairs.length; k++) {
        const [i, j] = pairs[k];
        const b = bondMeshes[k];
        if (bonded(i, j)) {
          const a = atoms[i].position, c = atoms[j].position;
          dir.subVectors(c, a);
          const len = dir.length();
          if (len > 1e-5) {
            dir.multiplyScalar(1 / len);
            b.position.set((a.x + c.x) / 2, (a.y + c.y) / 2, (a.z + c.z) / 2);
            b.quaternion.setFromUnitVectors(UP, dir);
            b.scale.set(1, len, 1);
            b.visible = true;
          }
        } else {
          b.visible = false;
        }
      }
      // Success glow
      for (let i = 0; i < atoms.length; i++) {
        const on = glowUntil[i] > time;
        atoms[i].material.emissiveIntensity = on ? 0.4 + 0.2 * Math.sin(time * 8) : 0;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const HABITS = [
