  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 14px; width: 900px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 22px; padding-right: 22px; border-radius: 24px; background-color: #1f2228; }
      .head { flex-direction: row; justify-content: space-between; align-items: center; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .total { color: #aab1bd; font-size: 22px; }
      .row { flex-direction: row; align-items: center; gap: 16px; padding-top: 12px; padding-bottom: 12px;
