      .dot { width: 8px; height: 60px; border-radius: 4px; }
      .dot0 { background-color: #3aa0ff; }
      .dot1 { background-color: #ffb23d; }
      .dot2 { background-color: #4cd08a; }
      .names { flex-direction: column; gap: 2px; width: 170px; }
      .hname { color: #ffffff; font-size: 24px; font-weight: 700; }
      .hdone { color: #aab1bd; font-size: 20px; }
      .days { flex-direction: row; gap: 8px; }
      .day { width: 60px; height: 60px; border-radius: 14px; background-color: #3a3f48;
             align-items: center; justify-content: center; }
      .daytxt { color: #c9ced6; font-size: 20px; font-weight: 700; text-align: center; }
      .streak { flex-direction: column; align-items: center; width: 100px; }
      .snum { color: #ffffff; font-size: 38px; font-weight: 700; }
      .slab { color: #aab1bd; font-size: 20px; }
      .foot { flex-direction: row; justify-content: space-between; align-items: center; }
      .note { color: #8f97a3; font-size: 20px; }
      .reset { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
               border-radius: 12px; background-color: #c0443a; }
      .resettxt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="head">
        <span class="title">This Week</span>
        <span class="total" id="total">0 / 21 check-ins</span>
      </div>
      ${rows}
      <div class="foot">
        <span class="note">Tap a day. Streak = most days in a row.</span>
        <button class="reset" id="reset"><span class="resettxt">Reset week</span></button>
      </div>
    </div>`, { width: 0.6, position: [0, 0.29, -0.06] });
  root.add(panel.object3D);

  // ---------- 3D token board (mirrors the panel, also pressable) ----------
  const board = new THREE.Mesh(
    new THREE.BoxGeometry(0.54, 0.01, 0.22),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 }),
  );
  board.name = 'Board';
  board.position.set(0, 0.005, 0.15);
  root.add(board);

  const tokenGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.016, 24);
  const offMat = new THREE.MeshStandardMaterial({ color: 0x4a505a, roughness: 0.7 });
  const onMat = HABITS.map(h => new THREE.MeshStandardMaterial({
    color: h.hex, roughness: 0.4, emissive: h.hex, emissiveIntensity: 0.15 }));
  const glowMat = HABITS.map(h => new THREE.MeshStandardMaterial({
    color: h.hex, roughness: 0.3, emissive: h.hex, emissiveIntensity: 0.7 }));

  const rowZ = [0.09, 0.15, 0.21];
  const tokens = [];
  const scaleCur = [];
  const scaleTarget = [];
  HABITS.forEach((h, hi) => {
    tokens.push([]); scaleCur.push([]); scaleTarget.push([]);
    DAYS.forEach((d, di) => {
      const t = new THREE.Mesh(tokenGeo, offMat);
      t.name = `${h.name} ${d}`;
      t.position.set((di - 3) * 0.05 - 0.08, 0.018, rowZ[hi]);
      t.scale.y = 0.4;
      root.add(t);
      traits(t, { onPress: () => toggle(hi, di) });
      tokens[hi].push(t);
      scaleCur[hi].push(0.4);
      scaleTarget[hi].push(0.4);
    });
  });

  // streak bars (length = streak in days)
  const barGeo = new THREE.BoxGeometry(1, 0.012, 0.024);
  barGeo.translate(0.5, 0, 0);
  const bars = HABITS.map((h, hi) => {
    const b = new THREE.Mesh(barGeo, glowMat[hi]);
    b.name = `${h.name} streak bar`;
    b.position.set(0.11, 0.016, rowZ[hi]);
    b.scale.x = 0.001;
    b.visible = false;
    root.add(b);
    return b;
  });
  const barCur = [0, 0, 0];
  const barTarget = [0, 0, 0];

  // ---------- logic ----------
  function bestRun(arr) {
    let best = 0, bestStart = -1, cur = 0;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i]) {
        cur++;
        if (cur > best) { best = cur; bestStart = i - cur + 1; }
      } else cur = 0;
    }
    return { best, bestStart };
  }

  function refresh() {
    let total = 0;
    HABITS.forEach((h, hi) => {
      const arr = state[hi];
      const { best, bestStart } = bestRun(arr);
      const done = arr.filter(Boolean).length;
      total += done;
      panel.set(`dn_${hi}`, { text: `${done} / 7 done` });
      panel.set(`sn_${hi}`, { text: String(best), color: best > 0 ? h.color : '#ffffff' });
      DAYS.forEach((d, di) => {
        const on = arr[di];
        panel.set(`c_${hi}_${di}`, { backgroundColor: on ? h.color : OFF_BG });
        panel.set(`t_${hi}_${di}`, { color: on ? '#101215' : '#c9ced6' });
        const inRun = on && best >= 2 && di >= bestStart && di < bestStart + best;
        tokens[hi][di].material = on ? (inRun ? glowMat[hi] : onMat[hi]) : offMat;
        scaleTarget[hi][di] = on ? 1.4 : 0.4;
      });
      barTarget[hi] = best * 0.02;
      bars[hi].visible = best > 0;
    });
    panel.set('total', { text: `${total} / 21 check-ins` });
  }

  function toggle(hi, di) {
    state[hi][di] = !state[hi][di];
    refresh();
  }

  HABITS.forEach((h, hi) => {
    DAYS.forEach((d, di) => {
      panel.on(`c_${hi}_${di}`, 'click', () => toggle(hi, di));
    });
  });
  panel.on('reset', 'click', () => {
    for (let h = 0; h < state.length; h++) state[h].fill(false);
    refresh();
  });

  refresh();

  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 10);
      for (let hi = 0; hi < HABITS.length; hi++) {
        for (let di = 0; di < DAYS.length; di++) {
          const s = scaleCur[hi][di] + (scaleTarget[hi][di] - scaleCur[hi][di]) * k;
          scaleCur[hi][di] = s;
          const t = tokens[hi][di];
          t.scale.y = s;
          t.position.y = 0.01 + 0.008 * s;
        }
        barCur[hi] += (barTarget[hi] - barCur[hi]) * k;
        bars[hi].scale.x = Math.max(0.001, barCur[hi]);
        if (barTarget[hi] === 0 && barCur[hi] < 0.002) bars[hi].visible = false;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Atoms ----------
  const R_O = 0.045;
  const R_H = 0.032;
  const BOND_GAP = 0.05; // atoms connect when their surfaces are within 5 cm

  const geoO = new THREE.SphereGeometry(R_O, 28, 16);
  const geoH = new THREE.SphereGeometry(R_H, 24, 12);
  const matO = new THREE.MeshStandardMaterial({ color: 0xe03a3a, roughness: 0.4, metalness: 0.05 });
  const matH = new THREE.MeshStandardMaterial({ color: 0xf2f2f2, roughness: 0.4, metalness: 0.05 });

  // 2 oxygens (back row), 4 hydrogens (front row): enough to make water or a wrong answer
  const startPositions = [
    [-0.12, 0.1, -0.08], [0.12, 0.1, -0.08],
    [-0.27, 0.1, 0.1], [-0.09, 0.1, 0.1], [0.09, 0.1, 0.1], [0.27, 0.1, 0.1],
  ];
  const types = ['O', 'O', 'H', 'H', 'H', 'H'];
  const radii = types.map(t => (t === 'O' ? R_O : R_H));
  const atoms = [];

  for (let i = 0; i < types.length; i++) {
    const m = new THREE.Mesh(types[i] === 'O' ? geoO : geoH, types[i] === 'O' ? matO : matH);
    m.name = types[i] === 'O' ? 'Oxygen atom' : 'Hydrogen atom';
    m.position.set(...startPositions[i]);
    root.add(m);
    traits(m, { grab: true });
    atoms.push(m);
  }

  // Desk mat (decorative)
  const mat = new THREE.Mesh(
    new THREE.CylinderGeometry(0.34, 0.34, 0.004, 48),
    new THREE.MeshStandardMaterial({ color: 0x3a4250, roughness: 0.9, transparent: true, opacity: 0.55 }),
  );
  mat.position.set(0, 0.002, 0.01);
  root.add(mat);

  // ---------- Bonds (H–O and O–O; hydrogens do not bond to each other here) ----------
  const bondGeo = new THREE.CylinderGeometry(0.01, 0.01, 1, 10);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0xbfc7d5, roughness: 0.3, metalness: 0.4 });
  const pairs = [];
  for (let i = 0; i < atoms.length; i++) {
    for (let j = i + 1; j < atoms.length; j++) {
      if (types[i] === 'H' && types[j] === 'H') continue;
      const b = new THREE.Mesh(bondGeo, bondMat);
      b.name = 'Bond';
      b.visible = false;
      root.add(b);
      pairs.push({ i, j, mesh: b });
    }
  }

  const UP = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();

  function isBonded(i, j) {
    if (types[i] === 'H' && types[j] === 'H') return false;
    return atoms[i].position.distanceTo(atoms[j].position) < radii[i] + radii[j] + BOND_GAP;
  }

  // ---------- UI ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2329; width: 520px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .legend { flex-direction: row; gap: 18px; align-items: center; }
      .dotO { width: 22px; height: 22px; border-radius: 11px; background-color: #e03a3a; }
      .dotH { width: 22px; height: 22px; border-radius: 11px; background-color: #f2f2f2; }
      .row { flex-direction: row; gap: 14px; align-items: center; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
              border-radius: 12px; background-color: #444b57; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
      .result { color: #ffd966; font-size: 24px; font-weight: 600; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body">Pinch atoms and bring them together until a bond appears, then press Check.</span>
      <div class="legend">
        <div class="row"><div class="dotO"></div><span class="body">Oxygen (O)</span></div>
        <div class="row"><div class="dotH"></div><span class="body">Hydrogen (H)</span></div>
      </div>
      <div class="row">
        <button class="btn" id="check"><span class="btn-text">Check</span></button>
        <button class="btn2" id="reset"><span class="btn-text">Reset atoms</span></button>
      </div>
      <span class="result" id="result">Hint: you have extra atoms. Use only what you need!</span>
    </div>`, { width: 0.42, position: [0, 0.3, -0.2] });
  root.add(panel.object3D);

  // ---------- Checking ----------
  const names = {
    H2O: 'water',
    H2O2: 'hydrogen peroxide',
    O2: 'oxygen gas (O2)',
    HO: 'a hydroxyl radical (OH)',
    HO2: 'a hydroperoxyl radical (HO2)',
    H3O: 'a hydronium-like fragment (H3O)',
    O: 'a lone oxygen atom',
  };

  function formula(h, o) {
    let s = '';
    if (h > 0) s += 'H' + (h > 1 ? h : '');
    if (o > 0) s += 'O' + (o > 1 ? o : '');
    return s;
  }

  function check() {
    const n = atoms.length;
    const seen = new Array(n).fill(false);
    const molecules = []; // {h, o, size}
    for (let s = 0; s < n; s++) {
      if (seen[s]) continue;
      const stack = [s];
      seen[s] = true;
      let h = 0, o = 0, size = 0;
      while (stack.length) {
        const a = stack.pop();
        size++;
        if (types[a] === 'H') h++; else o++;
        for (let b = 0; b < n; b++) {
          if (!seen[b] && isBonded(a, b)) { seen[b] = true; stack.push(b); }
        }
      }
      molecules.push({ h, o, size });
    }

    const built = molecules.filter(m => m.size > 1);
    const water = built.filter(m => m.h === 2 && m.o === 1);

    if (built.length === 0) {
      panel.set('result', { text: 'Nothing is bonded yet. Move atoms until they connect.', color: '#ffd966' });
      return;
    }
    if (water.length > 0) {
      const extra = built.length > water.length;
      panel.set('result', {
        text: 'Yes, that is water, H2O! One oxygen shares bonds with two hydrogens (bond angle about 104.5 degrees).' +
          (extra ? ' You also built another molecule.' : ''),
        color: '#6ee08a',
      });
      return;
    }
    const m = built[0];
    const f = formula(m.h, m.o);
    const nm = names[f] || ('a molecule with ' + m.h + ' H and ' + m.o + ' O');
    panel.set('result', {
      text: 'Not water. You built ' + nm + '. Water needs exactly 2 H and 1 O bonded together.',
      color: '#ff7b6b',
    });
  }

  panel.on('check', 'click', check);
  panel.on('reset', 'click', () => {
    for (let i = 0; i < atoms.length; i++) {
      if (!isGrabbed(atoms[i])) atoms[i].position.set(...startPositions[i]);
    }
    panel.set('result', { text: 'Atoms reset. Build water: H2O.', color: '#ffd966' });
  });

  // ---------- Update: show bonds between nearby atoms ----------
  return {
    root,
    update() {
      for (let k = 0; k < pairs.length; k++) {
        const p = pairs[k];
        if (isBonded(p.i, p.j)) {
          const a = atoms[p.i].position;
          const b = atoms[p.j].position;
          dir.subVectors(b, a);
          const len = dir.length();
          p.mesh.visible = true;
          p.mesh.position.addVectors(a, b).multiplyScalar(0.5);
          p.mesh.scale.set(1, len, 1);
          p.mesh.quaternion.setFromUnitVectors(UP, dir.multiplyScalar(1 / (len || 1)));
        } else {
          p.mesh.visible = false;
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
