  const ringGeo = new THREE.TorusGeometry(1, 0.007, 8, 40);
  const ringMat = new THREE.MeshStandardMaterial({ color: 0x7a4f22, roughness: 0.9 });
  [[0.11, RIM_TOP], [0.1, 0.045], [0.093, 0.015]].forEach(([r, y]) => {
