  root.add(basket);

  // ---------- Fruits ----------
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x5a3a1a, roughness: 0.9 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x3fa34d, roughness: 0.7 });

  // Apple
  const apple = new THREE.Group();
  apple.name = 'Apple';
  const appleBody = new THREE.Mesh(
    new THREE.SphereGeometry(0.034, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0xd62828, roughness: 0.35 }),
  );
  appleBody.scale.set(1, 0.9, 1);
  apple.add(appleBody);
  const appleStem = new THREE.Mesh(new THREE.CylinderGeometry(0.002, 0.003, 0.014, 8), stemMat);
  appleStem.position.y = 0.032;
  apple.add(appleStem);
  const leaf = new THREE.Mesh(new THREE.SphereGeometry(0.01, 12, 8), leafMat);
  leaf.scale.set(1.4, 0.3, 0.7);
  leaf.position.set(0.01, 0.036, 0);
  apple.add(leaf);

  // Orange
  const orange = new THREE.Group();
  orange.name = 'Orange';
  const orangeBody = new THREE.Mesh(
    new THREE.SphereGeometry(0.036, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0xf28c12, roughness: 0.85 }),
  );
  orange.add(orangeBody);
  const nub = new THREE.Mesh(new THREE.SphereGeometry(0.006, 10, 8), leafMat);
  nub.position.y = 0.035;
  orange.add(nub);

  // Banana
  const banana = new THREE.Group();
  banana.name = 'Banana';
  const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-0.07, 0, 0.018),
    new THREE.Vector3(-0.035, 0, -0.002),
    new THREE.Vector3(0, 0, -0.01),
    new THREE.Vector3(0.035, 0, -0.002),
    new THREE.Vector3(0.07, 0, 0.018),
  ]);
  const bananaBody = new THREE.Mesh(
    new THREE.TubeGeometry(curve, 20, 0.017, 8),
    new THREE.MeshStandardMaterial({ color: 0xf6d743, roughness: 0.6 }),
  );
  banana.add(bananaBody);
  const tipMat = new THREE.MeshStandardMaterial({ color: 0x4a3418, roughness: 0.9 });
  const tipGeo = new THREE.SphereGeometry(0.01, 10, 8);
  [[-0.07, 0.018], [0.07, 0.018]].forEach(([x, z]) => {
    const tip = new THREE.Mesh(tipGeo, tipMat);
    tip.position.set(x, 0, z);
    banana.add(tip);
  });

  const fruits = [
    { obj: apple,  label: 'Apple',  id: 'apple',  price: 50, rest: 0.031, sep: 0.034, start: [-0.28, 0.05],  inBasket: false, vy: 0, last: null },
    { obj: orange, label: 'Orange', id: 'orange', price: 75, rest: 0.036, sep: 0.036, start: [-0.16, 0.05],  inBasket: false, vy: 0, last: null },
    { obj: banana, label: 'Banana', id: 'banana', price: 30, rest: 0.017, sep: 0.042, start: [-0.02, 0.05],  inBasket: false, vy: 0, last: null },
  ];
  fruits.forEach((f) => {
    f.obj.position.set(f.start[0], f.rest, f.start[1]);
    root.add(f.obj);
    traits(f.obj, { grab: true });
  });

  // ---------- UI ----------
  const money = (c) => '$' + (c / 100).toFixed(2);
  const rows = fruits.map((f) => `
      <div class="row">
        <span class="name" >${f.label}</span>
        <span class="price">${money(f.price)}</span>
        <span class="status" id="s_${f.id}">on the table</span>
      </div>`).join('');

  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; width: 520px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #b9c0cc; font-size: 20px; }
      .row { flex-direction: row; align-items: center; gap: 10px; }
      .name { color: #ffffff; font-size: 26px; width: 150px; }
      .price { color: #ffd966; font-size: 26px; width: 110px; }
      .status { color: #8b93a1; font-size: 22px; width: 200px; }
      .totalrow { flex-direction: row; align-items: center; justify-content: space-between;
                  padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px;
                  border-radius: 14px; background-color: #2a2e35; }
      .totlabel { color: #d7dbe2; font-size: 26px; }
      .total { color: #6ee7a0; font-size: 36px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #3b4252; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Stand</span>
      <span class="hint">Pinch a fruit, move it, and release it over the basket.</span>
      ${rows}
      <div class="totalrow">
        <span class="totlabel" id="count">Basket: 0 items</span>
        <span class="total" id="total">$0.00</span>
      </div>
      <button class="btn" id="reset"><span class="btn-text">Put everything back</span></button>
    </div>`, { width: 0.4, position: [0, 0.22, -0.13] });
  root.add(panel.object3D);

  panel.on('reset', 'click', () => {
    fruits.forEach((f) => {
      if (isGrabbed(f.obj)) return;
      f.obj.position.set(f.start[0], f.rest, f.start[1]);
      f.vy = 0;
    });
  });

  let lastTotal = -1, lastCount = -1;

  // ---------- Simulation ----------
  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);

      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const o = f.obj;
        if (isGrabbed(o)) { f.vy = 0; f.inBasket = false; continue; }

        const dx = o.position.x - BX, dz = o.position.z - BZ;
        const dist = Math.sqrt(dx * dx + dz * dz);
        const inRing = dist >= INNER_R && dist < OUTER_R + f.sep * 0.3;
        const inside = dist < INNER_R;

        let floor = f.rest;
        if (inside) floor = BASE_TOP + f.rest;
        else if (inRing) floor = RIM_TOP + f.rest;

        // gravity
        f.vy -= 2.0 * dt;
        o.position.y += f.vy * dt;
        if (o.position.y <= floor) { o.position.y = floor; f.vy = 0; }

        // fruit balanced on the rim slides off to the nearer side
        if (inRing && o.position.y <= floor + 0.002 && dist > 0.0001) {
          const mid = (INNER_R + OUTER_R) / 2;
          const dir = dist < mid ? -1 : 1;
          const step = 0.15 * dt * dir;
          o.position.x += (dx / dist) * step;
          o.position.z += (dz / dist) * step;
        }

        // keep inside the allowed area
        o.position.x = Math.max(-0.38, Math.min(0.38, o.position.x));
        o.position.z = Math.max(-0.2, Math.min(0.2, o.position.z));

        f.inBasket = inside && o.position.y < RIM_TOP + f.rest + 0.01;
      }

      // fruits in the basket gently push each other apart
      for (let i = 0; i < fruits.length; i++) {
        for (let j = i + 1; j < fruits.length; j++) {
          const a = fruits[i], b = fruits[j];
          if (!a.inBasket || !b.inBasket || isGrabbed(a.obj) || isGrabbed(b.obj)) continue;
          const ax = a.obj.position.x, az = a.obj.position.z;
          const bx = b.obj.position.x, bz = b.obj.position.z;
          let ddx = bx - ax, ddz = bz - az;
          let d = Math.sqrt(ddx * ddx + ddz * ddz);
          const min = a.sep + b.sep;
          if (d < min) {
            if (d < 0.0001) { ddx = 1; ddz = 0; d = 1; }
            const push = Math.min(0.1 * dt, (min - d) * 0.5);
            const nx = ddx / d, nz = ddz / d;
            a.obj.position.x -= nx * push; a.obj.position.z -= nz * push;
            b.obj.position.x += nx * push; b.obj.position.z += nz * push;
          }
        }
      }
      // keep basket fruit inside the walls
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        if (!f.inBasket || isGrabbed(f.obj)) continue;
        const dx = f.obj.position.x - BX, dz = f.obj.position.z - BZ;
        const d = Math.sqrt(dx * dx + dz * dz);
        const maxD = INNER_R - 0.004;
        if (d > maxD) {
          f.obj.position.x = BX + (dx / d) * maxD;
          f.obj.position.z = BZ + (dz / d) * maxD;
        }
      }

      // update the panel only when something changes
      let total = 0, count = 0;
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        if (f.inBasket) { total += f.price; count++; }
        if (f.last !== f.inBasket) {
          f.last = f.inBasket;
          panel.set('s_' + f.id, {
            text: f.inBasket ? 'in basket' : 'on the table',
            color: f.inBasket ? '#6ee7a0' : '#8b93a1',
          });
        }
      }
      if (total !== lastTotal) {
        lastTotal = total;
        panel.set('total', { text: money(total) });
      }
      if (count !== lastCount) {
        lastCount = count;
        panel.set('count', { text: 'Basket: ' + count + (count === 1 ? ' item' : ' items') });
      }
    },
  };
}

