          f.inBasket = inside;
          panel.set(f.rowId, inside
            ? { text: 'in basket', color: '#6ee7a0' }
            : { text: 'on the table', color: '#8b93a1' });
        }
        if (inside) { total += f.cents; count++; }
      }

      if (total !== lastTotal) {
        lastTotal = total;
        panel.set('total', { text: money(total) });
      }
      if (count !== lastCount) {
        lastCount = count;
        panel.set('count', { text: count + (count === 1 ? ' item' : ' items') });
      }
    },
  };
}

