  unit.add(glow);

  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 12px; width: 480px; background-color: #1a1d22; border-radius: 22px; padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      .sub { color: #b8bec9; font-size: 22px; text-align: center; }
      .row { display: flex; flex-direction: row; align-items: center; justify-content: center; gap: 14px; }
