      .btn-text { color: #111418; font-size: 24px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Glowing Button</span>
      <span class="sub">Poke the glowing dome — a new color every press. Pinch the base to move it.</span>
      <div class="row">
        <div class="dot" id="dot"></div>
        <span class="cname" id="cname">Blaze Red</span>
      </div>
      <span class="hex" id="hex">#FF3B30</span>
      <span class="count" id="count">Presses: 0</span>
      <button class="btn" id="again"><span class="btn-text">Surprise me</span></button>
    </div>
  `, { width: 0.32, position: [0.24, 0.26, -0.08], rotationY: -0.32 });
  root.add(panel.object3D);

  function applyColor() {
    const c = palette[cur];
    buttonMat.color.set(c.css);
    buttonMat.emissive.set(c.css);
    glowMat.color.set(c.css);
    ringMat.color.set(c.css);
    ringMat.emissive.set(c.css);
    panel.set('dot', { backgroundColor: c.css });
    panel.set('cname', { text: c.name });
    panel.set('hex', { text: c.css });
    panel.set('count', { text: 'Presses: ' + total });
  }

  function cycleColor() {
    let n = cur;
    if (palette.length > 1) {
      n = Math.floor(Math.random() * palette.length);
      if (n === cur) n = (cur + 1 + Math.floor(Math.random() * (palette.length - 1))) % palette.length;
    }
    cur = n;
    total += 1;
    pressFx = 1;
    applyColor();
  }

  traits(unit, { grab: true, onPress: cycleColor });
  panel.on('again', 'click', cycleColor);

  const basePressY = 0;
  let breathe = 0;

  return {
    root,
    update(time, delta) {
      pressFx = Math.max(0, pressFx - delta * 2.2);
      breathe = Math.sin(time * 2.2) * 0.5 + 0.5;

      const dip = pressFx * 0.011;
      pressGroup.position.y = basePressY - dip;

      const flash = pressFx * 1.6;
      buttonMat.emissiveIntensity = 1.05 + breathe * 0.35 + flash;
      ringMat.emissiveIntensity = 1.7 + breathe * 0.5 + flash * 0.8;
      glowMat.opacity = 0.16 + breathe * 0.08 + pressFx * 0.28;

      const s = 1 + breathe * 0.03 + pressFx * 0.12;
      glow.scale.set(s, 0.7 * s, s);

      if (!isGrabbed(unit)) {
        ring.rotation.z = time * 0.3;
      }
    }
  };
}

