    </div>`, { width: 0.3, position: [0.22, 0.24, -0.06], rotationY: -0.35 });
  root.add(info.object3D);

  function applyColor(i) {
    const p = palette[i];
    buttonMat.color.setHex(p.c);
    buttonMat.emissive.setHex(p.c);
    ringMat.color.setHex(p.c);
    haloMat.color.setHex(p.c);
    groundMat.color.setHex(p.c);
    sparkMat.color.setHex(p.c);
    info.set('swatch', { backgroundColor: p.hex });
    info.set('colorname', { text: p.name });
    info.set('hex', { text: p.hex });
  }

  function nextColor() {
    idx = (idx + 1) % palette.length;
    pressCount = pressCount + 1;
    press = 1;
    applyColor(idx);
    info.set('count', { text: 'Pressed ' + pressCount + ' times' });
  }

  info.on('next', 'click', nextColor);
  traits(rig, { grab: true, onPress: nextColor });

  return {
    root,
    update(time, delta) {
      if (delta > 0.1) delta = 0.1;
      press = press - delta * 3.5;
      if (press < 0) press = 0;

      const held = isGrabbed(rig);
      const idleBob = held ? 0 : Math.sin(time * 2.2) * 0.0012;
      buttonMove.position.y = baseButtonY - press * 0.012 + idleBob;

      const pulse = Math.sin(time * 3.0);
      buttonMat.emissiveIntensity = 1.3 + pulse * 0.25 + press * 1.2;
      haloMat.opacity = 0.16 + pulse * 0.03 + press * 0.18;
      groundMat.opacity = 0.32 + pulse * 0.05 + press * 0.2;

      const s = 1 + pulse * 0.03 + press * 0.18;
      glowRing.scale.set(s, s, s);
      if (!held) {
        glowRing.rotation.z = time * 0.4;
      }

      if (!held) {
        const orbitR = 0.1;
        for (let i = 0; i < SPARKS; i++) {
          const a = time * 0.45 + (i / SPARKS) * Math.PI * 2;
          const y = 0.1 + Math.sin(time * 1.8 + i * 1.3) * 0.015;
          dummy.position.set(Math.cos(a) * orbitR, y, Math.sin(a) * orbitR);
          dummy.updateMatrix();
          sparks.setMatrixAt(i, dummy.matrix);
        }
        sparks.instanceMatrix.needsUpdate = true;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- DNA parameters ----
  const PAIRS = 14;
  const H = 0.30;
  const R = 0.06;
  const TURNS = 1.4;
  const TOTAL_ANGLE = TURNS * Math.PI * 2;
  const seq1 = ['A', 'T', 'G', 'C', 'G', 'A', 'T', 'C', 'A', 'G', 'C', 'T', 'G', 'A'];
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };

  // ---- Holder (grabbable) + spinner (animated) ----
  const holder = new THREE.Group();
  holder.name = 'DNA Helix';
  holder.position.set(-0.08, 0.22, -0.06);
  root.add(holder);

  const spinner = new THREE.Group();
  holder.add(spinner);

  const backboneMat = new THREE.MeshStandardMaterial({ color: 0xdde6f0, roughness: 0.35, metalness: 0.05 });
  const matA = new THREE.MeshStandardMaterial({ color: 0x2fd47e, roughness: 0.45 });
  const matT = new THREE.MeshStandardMaterial({ color: 0xff5a5a, roughness: 0.45 });
  const matG = new THREE.MeshStandardMaterial({ color: 0xffc93c, roughness: 0.45 });
  const matC = new THREE.MeshStandardMaterial({ color: 0x4da6ff, roughness: 0.45 });
  function matFor(b) {
    if (b === 'A') return matA;
    if (b === 'T') return matT;
    if (b === 'G') return matG;
    return matC;
  }

  const pairY = [];
  const pairAngle = [];

  // backbone points
  const pts1 = [];
  const pts2 = [];
  for (let i = 0; i < PAIRS; i++) {
    const t = PAIRS === 1 ? 0.5 : i / (PAIRS - 1);
    const y = -H / 2 + t * H;
    const a = t * TOTAL_ANGLE;
    pairY.push(y);
    pairAngle.push(a);
    pts1.push(new THREE.Vector3(Math.cos(a) * R, y, Math.sin(a) * R));
    pts2.push(new THREE.Vector3(Math.cos(a + Math.PI) * R, y, Math.sin(a + Math.PI) * R));
  }

  const curve1 = new THREE.CatmullRomCurve3(pts1);
  const curve2 = new THREE.CatmullRomCurve3(pts2);
  const tubeGeo1 = new THREE.TubeGeometry(curve1, 80, 0.0072, 10, false);
  const tubeGeo2 = new THREE.TubeGeometry(curve2, 80, 0.0072, 10, false);
  const backbone1 = new THREE.Mesh(tubeGeo1, backboneMat);
  backbone1.name = 'Backbone 1';
  const backbone2 = new THREE.Mesh(tubeGeo2, backboneMat);
  backbone2.name = 'Backbone 2';
  spinner.add(backbone1);
  spinner.add(backbone2);

  // rungs: two half-cylinders per pair
  const rungLen = R - 0.006;
  const rungGeo = new THREE.CylinderGeometry(0.0052, 0.0052, rungLen, 12);
  rungGeo.rotateZ(Math.PI / 2);

  for (let i = 0; i < PAIRS; i++) {
    const b1 = seq1[i];
    const b2 = comp[b1];
    const g = new THREE.Group();
    g.position.y = pairY[i];
    g.rotation.y = -pairAngle[i];
    const left = new THREE.Mesh(rungGeo, matFor(b1));
    left.name = 'Pair' + (i + 1) + '-' + b1;
    left.position.x = R / 2;
    const right = new THREE.Mesh(rungGeo, matFor(b2));
    right.name = 'Pair' + (i + 1) + '-' + b2;
    right.position.x = -R / 2;
    g.add(left);
    g.add(right);
    spinner.add(g);
  }

  // sugar-phosphate nodes as one InstancedMesh
  const nodeGeo = new THREE.SphereGeometry(0.0095, 16, 12);
  const nodes = new THREE.InstancedMesh(nodeGeo, backboneMat, PAIRS * 2);
  nodes.name = 'Backbone nodes';
  const dummy = new THREE.Object3D();
  let ni = 0;
  for (let i = 0; i < PAIRS; i++) {
    dummy.position.copy(pts1[i]);
    dummy.updateMatrix();
    nodes.setMatrixAt(ni++, dummy.matrix);
    dummy.position.copy(pts2[i]);
    dummy.updateMatrix();
    nodes.setMatrixAt(ni++, dummy.matrix);
  }
  nodes.instanceMatrix.needsUpdate = true;
  spinner.add(nodes);

  // selection ring to highlight current pair
  const ringGeo = new THREE.TorusGeometry(0.08, 0.0028, 10, 48);
  const ringMat = new THREE.MeshBasicMaterial({ color: 0xffe45e });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.name = 'Selection ring';
  ring.rotation.x = Math.PI / 2;
  ring.position.y = pairY[2];
  spinner.add(ring);

  // soft ground shadow
  const shadowGeo = new THREE.CircleGeometry(0.11, 32);
  const shadowMat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.32, depthWrite: false });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(-0.08, 0.003, -0.06);
  root.add(shadow);

  traits(holder, { grab: true });

  // ---- UI panel ----
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #b9c2d0; font-size: 21px; }
      .fact { color: #ffe9a8; font-size: 22px; }
      .legend { flex-direction: row; gap: 8px; }
      .badgeA { color: #06281a; font-size: 20px; font-weight: 700; background-color: #2fd47e; border-radius: 8px; padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; }
      .badgeT { color: #3a0a0a; font-size: 20px; font-weight: 700; background-color: #ff5a5a; border-radius: 8px; padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; }
      .badgeG { color: #3a2700; font-size: 20px; font-weight: 700; background-color: #ffc93c; border-radius: 8px; padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; }
      .badgeC { color: #061a3a; font-size: 20px; font-weight: 700; background-color: #4da6ff; border-radius: 8px; padding-top: 4px; padding-bottom: 4px; padding-left: 10px; padding-right: 10px; }
      .row { flex-direction: row; gap: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #3a4048; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
