        <span class="badgeA">A</span>
        <span class="badgeT">T</span>
        <span class="badgeG">G</span>
        <span class="badgeC">C</span>
      </div>
      <div class="row">
        <button class="btn" id="spinBtn"><span class="btn-text" id="spinLabel">Pause spin</span></button>
        <button class="btn2" id="nextBtn"><span class="btn-text" id="nextLabel">Next pair</span></button>
      </div>
      <span class="hint" id="hint">A-T: 2 bonds. G-C: 3 bonds.</span>
    </div>`, { width: 0.34, position: [0.24, 0.24, 0.06], rotationY: -0.32 });
  root.add(panel.object3D);

  let spinOn = true;
  let sel = 2;

  function pairText(i) {
    const b1 = seq1[i];
    const b2 = comp[b1];
    const hb = (b1 === 'G' || b1 === 'C') ? 3 : 2;
    return 'Pair ' + (i + 1) + '/' + PAIRS + ': ' + b1 + '-' + b2 + ' - ' + hb + ' H-bonds';
  }

  panel.set('fact', { text: pairText(sel) });

  panel.on('spinBtn', 'click', () => {
    spinOn = !spinOn;
    panel.set('spinLabel', { text: spinOn ? 'Pause spin' : 'Spin' });
  });
  panel.on('nextBtn', 'click', () => {
    sel = (sel + 1) % PAIRS;
    ring.position.y = pairY[sel];
    panel.set('fact', { text: pairText(sel) });
  });

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(holder) && spinOn) {
        spinner.rotation.y += delta * 0.4;
      }
      const s = 1 + 0.06 * Math.sin(time * 3.0);
      ring.scale.set(s, s, 1);
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const R = 0.055;
  const H = 0.30;
  const PAIRS = 14;
  const TURNS = 1.5;
  const HOME_X = -0.09;
  const HOME_Y = 0.22;
  const HOME_Z = 0.0;

  const helixGroup = new THREE.Group();
  helixGroup.name = 'DNA Double Helix';
  helixGroup.position.set(HOME_X, HOME_Y, HOME_Z);
  root.add(helixGroup);

  const backboneMat = new THREE.MeshStandardMaterial({ color: 0xcbd5e1, roughness: 0.45, metalness: 0.15 });

  const baseColors = { A: 0x4ade80, T: 0xef4444, C: 0x60a5fa, G: 0xfbbf24 };
  const baseMats = {};
  const hiMats = {};
  for (const k of ['A', 'T', 'C', 'G']) {
    baseMats[k] = new THREE.MeshStandardMaterial({ color: baseColors[k], roughness: 0.4, metalness: 0.05 });
    hiMats[k] = new THREE.MeshStandardMaterial({
      color: baseColors[k], roughness: 0.3, metalness: 0.05,
      emissive: baseColors[k], emissiveIntensity: 0.85
    });
  }

  const UP = new THREE.Vector3(0, 1, 0);

  // Two backbone curves
  const SEG = 100;
  const ptsA = [];
  const ptsB = [];
  for (let s = 0; s <= SEG; s++) {
    const t = s / SEG;
    const ang = t * TURNS * Math.PI * 2;
    const y = (t - 0.5) * H;
    ptsA.push(new THREE.Vector3(Math.cos(ang) * R, y, Math.sin(ang) * R));
    ptsB.push(new THREE.Vector3(Math.cos(ang + Math.PI) * R, y, Math.sin(ang + Math.PI) * R));
  }
  const curveA = new THREE.CatmullRomCurve3(ptsA);
  const curveB = new THREE.CatmullRomCurve3(ptsB);
  const tubeGeoA = new THREE.TubeGeometry(curveA, 100, 0.0065, 8, false);
  const tubeGeoB = new THREE.TubeGeometry(curveB, 100, 0.0065, 8, false);
  const backA = new THREE.Mesh(tubeGeoA, backboneMat);
  backA.name = 'Backbone 1';
  const backB = new THREE.Mesh(tubeGeoB, backboneMat);
  backB.name = 'Backbone 2';
  helixGroup.add(backA);
  helixGroup.add(backB);

  const capGeo = new THREE.SphereGeometry(0.0068, 12, 8);
  const capPositions = [ptsA[0], ptsA[SEG], ptsB[0], ptsB[SEG]];
  for (let c = 0; c < 4; c++) {
    const m = new THREE.Mesh(capGeo, backboneMat);
    m.position.copy(capPositions[c]);
    m.name = 'Backbone cap';
    helixGroup.add(m);
  }

  // Base pairs
  const leftSeq = ['A', 'G', 'C', 'T', 'G', 'A', 'T', 'C', 'G', 'A', 'C', 'T', 'G', 'A'];
  const comp = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const rungGeo = new THREE.CylinderGeometry(0.0085, 0.0085, R, 12);
  const entries = [];

  for (let i = 0; i < PAIRS; i++) {
    const t = i / (PAIRS - 1);
    const ang = t * TURNS * Math.PI * 2;
    const y = (t - 0.5) * H;
    const cx = Math.cos(ang);
    const sz = Math.sin(ang);
    const left = leftSeq[i];
    const right = comp[left];

    const dirL = new THREE.Vector3(cx, 0, sz).normalize();
    const dirR = new THREE.Vector3(-cx, 0, -sz).normalize();

    const lm = new THREE.Mesh(rungGeo, baseMats[left]);
    lm.position.set(cx * R * 0.5, y, sz * R * 0.5);
    lm.quaternion.setFromUnitVectors(UP, dirL);
    lm.name = 'Pair ' + (i + 1) + ' ' + left;

    const rm = new THREE.Mesh(rungGeo, baseMats[right]);
    rm.position.set(-cx * R * 0.5, y, -sz * R * 0.5);
    rm.quaternion.setFromUnitVectors(UP, dirR);
    rm.name = 'Pair ' + (i + 1) + ' ' + right;

    helixGroup.add(lm);
    helixGroup.add(rm);
    entries.push({ left, right, y, leftMesh: lm, rightMesh: rm });
  }

  traits(helixGroup, { grab: true });

  // Home marker on desk
  const disc = new THREE.Mesh(
    new THREE.CircleGeometry(0.11, 32),
    new THREE.MeshBasicMaterial({ color: 0x2e333b, transparent: true, opacity: 0.6 })
  );
  disc.rotation.x = -Math.PI / 2;
  disc.position.set(HOME_X, 0.002, HOME_Z);
  disc.name = 'Home base';
  root.add(disc);

  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; width: 500px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .hint { color: #9fb3c8; font-size: 20px; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: left; }
      .row { display: flex; flex-direction: row; gap: 10px; align-items: center; justify-content: center; }
      .btn { background-color: #2f6fdb; border-radius: 12px; padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; }
      .btn2 { background-color: #363c45; border-radius: 12px; padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; text-align: center; }
      .legrow { display: flex; flex-direction: row; gap: 12px; align-items: center; justify-content: center; }
      .leglabel { color: #aeb6c2; font-size: 20px; }
      .la { color: #4ade80; font-size: 22px; font-weight: 700; }
      .lt { color: #ef4444; font-size: 22px; font-weight: 700; }
      .lc { color: #60a5fa; font-size: 22px; font-weight: 700; }
      .lg { color: #fbbf24; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="hint">Pinch to grab - turn it around</span>
      <span class="body" id="info">B-DNA: A pairs T, G pairs C. 14 pairs shown. Press Next pair to inspect.</span>
      <div class="row">
        <button class="btn" id="spin"><span class="btn-text" id="spinTxt">Pause spin</span></button>
        <button class="btn2" id="next"><span class="btn-text">Next pair</span></button>
        <button class="btn2" id="home"><span class="btn-text">Reset</span></button>
      </div>
      <div class="legrow">
        <span class="leglabel">Bases:</span>
        <span class="la">A</span>
        <span class="lt">T</span>
        <span class="lc">C</span>
        <span class="lg">G</span>
      </div>
    </div>`, { width: 0.34, position: [0.22, 0.22, 0.08], rotationY: -0.32 });
  root.add(panel.object3D);

  let spinning = true;
  let selected = -1;

  function describe(i) {
    const e = entries[i];
    const bonds = (e.left === 'A' || e.left === 'T') ? 2 : 3;
    return 'Pair ' + (i + 1) + ' of 14: ' + e.left + '-' + e.right + ' - ' + bonds + ' H-bonds. ' + (bonds === 3 ? 'G-C is stronger.' : 'A-T splits easier.');
  }

  panel.on('spin', 'click', () => {
    spinning = !spinning;
    panel.set('spinTxt', { text: spinning ? 'Pause spin' : 'Start spin' });
  });

  panel.on('next', 'click', () => {
    if (selected >= 0) {
      const old = entries[selected];
      old.leftMesh.material = baseMats[old.left];
      old.rightMesh.material = baseMats[old.right];
      old.leftMesh.scale.setScalar(1);
      old.rightMesh.scale.setScalar(1);
    }
    selected = (selected + 1) % PAIRS;
    const cur = entries[selected];
    cur.leftMesh.material = hiMats[cur.left];
    cur.rightMesh.material = hiMats[cur.right];
    panel.set('info', { text: describe(selected) });
  });

  panel.on('home', 'click', () => {
    helixGroup.position.set(HOME_X, HOME_Y, HOME_Z);
    helixGroup.rotation.set(0, 0, 0);
    panel.set('info', { text: 'Back home. Grab the helix and flip it to see the twist.' });
  });

  return {
    root,
    update(time, delta) {
      const held = isGrabbed(helixGroup);
      if (spinning && !held) {
        helixGroup.rotation.y += delta * 0.55;
      }
      if (selected >= 0) {
        const s = 1.0 + (Math.sin(time * 4.0) * 0.5 + 0.5) * 0.12;
        entries[selected].leftMesh.scale.setScalar(s);
        entries[selected].rightMesh.scale.setScalar(s);
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

