  const topGeo = new THREE.CylinderGeometry(0.015, 0.015, 0.012, 24);
  const topMat = new THREE.MeshStandardMaterial({ color: 0x444c58, roughness: 0.4, metalness: 0.4, emissive: 0x7dffb0, emissiveIntensity: 0 });
  const topBtn = new THREE.Mesh(topGeo, topMat);
  topBtn.name = 'LightButton3D';
  topBtn.position.set(0.09, 0.171, 0);
  clockGroup.add(topBtn);

  const ledGeo = new THREE.SphereGeometry(0.006, 16, 8);
  const ledMat = new THREE.MeshBasicMaterial({ color: 0xff4444 });
  const led = new THREE.Mesh(ledGeo, ledMat);
