  const glow = new THREE.Mesh(glowGeo, glowMat);
  glow.name = 'NightGlow';
  glow.position.set(0, 0.10, -0.036);
  glow.rotation.y = Math.PI;
  clockGroup.add(glow);

  const WEEK = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const MONTH = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  const clockUI = ui(`
    <style>
      .clock { flex-direction: column; align-items: center; justify-content: center; gap: 6px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; background-color: #0b0e12; border-radius: 16px; }
      .timerow { flex-direction: row; align-items: center; justify-content: center; gap: 10px; }
      .time { color: #7dffb0; font-size: 78px; font-weight: 700; text-align: center; }
      .ampm { color: #7dffb0; font-size: 26px; font-weight: 700; }
      .date { color: #9aa3b2; font-size: 22px; text-align: center; }
      .btnrow { flex-direction: row; align-items: center; justify-content: center; gap: 12px; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 16px; padding-right: 16px; border-radius: 10px; background-color: #2f6fdb; border-width: 0px; }
      .btn2 { padding-top: 8px; padding-bottom: 8px; padding-left: 16px; padding-right: 16px; border-radius: 10px; background-color: #3a404b; border-width: 0px; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="clock">
      <div class="timerow"><span class="time" id="time">-- --</span><span class="ampm" id="ampm">AM</span></div>
      <span class="date" id="date">---</span>
      <div class="btnrow"><button class="btn" id="formatBtn"><span class="btn-text" id="formatLabel">12H MODE</span></button><button class="btn2" id="lightBtn"><span class="btn-text" id="lightLabel">LIGHT OFF</span></button></div>
    </div>`, { width: 0.24, position: [0, 0.10, 0.032] });
  clockGroup.add(clockUI.object3D);

  const infoUI = ui(`
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 21px; }
      .hint { color: #9aa3b2; font-size: 19px; }
    </style>
    <div class="card">
      <span class="title">Desk Clock</span>
      <span class="body">Live hours + minutes from your device.</span>
      <span class="hint">Pinch clock to move it. Poke clock for night light. Buttons switch 12H / 24H.</span>
    </div>`, { width: 0.26, position: [0.20, 0.17, 0.05], rotationY: -0.3 });
  root.add(infoUI.object3D);

  let is24h = false;
  let lightOn = false;
  const nowD = new Date();
  let lastTimeText = '__init__';
  let lastAmPm = '__init__';
  let lastDateText = '__init__';

  function refreshClock(force) {
    const ms = Date.now();
    nowD.setTime(ms);
    const h24 = nowD.getHours();
    const m = nowD.getMinutes();
    const s = nowD.getSeconds();
    const colonOn = (s % 2 === 0);
    let hDisp = h24;
    let ampmStr = '';
    if (!is24h) {
      ampmStr = h24 < 12 ? 'AM' : 'PM';
      hDisp = h24 % 12;
      if (hDisp === 0) hDisp = 12;
    } else {
      ampmStr = '24H';
    }
    let hhStr;
    if (is24h) {
      hhStr = hDisp < 10 ? '0' + hDisp : '' + hDisp;
    } else {
      hhStr = '' + hDisp;
    }
    const mmStr = m < 10 ? '0' + m : '' + m;
    const sep = colonOn ? ':' : ' ';
    const timeStr = hhStr + sep + mmStr;
    if (force || timeStr !== lastTimeText) {
      clockUI.set('time', { text: timeStr });
      lastTimeText = timeStr;
    }
    if (force || ampmStr !== lastAmPm) {
      clockUI.set('ampm', { text: ampmStr });
      lastAmPm = ampmStr;
    }
    const dateStr = WEEK[nowD.getDay()] + ' ' + MONTH[nowD.getMonth()] + ' ' + nowD.getDate();
    if (force || dateStr !== lastDateText) {
      clockUI.set('date', { text: dateStr });
      lastDateText = dateStr;
    }
    led.visible = colonOn;
  }

  function toggleLight() {
    lightOn = !lightOn;
    topMat.emissiveIntensity = lightOn ? 0.9 : 0;
    glowMat.opacity = lightOn ? 0.22 : 0;
    clockUI.set('lightLabel', { text: lightOn ? 'LIGHT ON' : 'LIGHT OFF' });
    clockUI.set('lightBtn', { backgroundColor: lightOn ? '#2f6fdb' : '#3a404b' });
  }

  clockUI.on('formatBtn', 'click', () => {
    is24h = !is24h;
    clockUI.set('formatLabel', { text: is24h ? '24H MODE' : '12H MODE' });
    lastTimeText = '__force__';
    lastAmPm = '__force__';
    refreshClock(true);
  });
  clockUI.on('lightBtn', 'click', () => {
    toggleLight();
  });

  traits(clockGroup, {
    grab: true,
    onPress: () => {
      toggleLight();
    }
  });

  refreshClock(true);

  let lastCheck = -10;
  return {
    root,
    update(time) {
      if (time - lastCheck < 0.2) return;
      lastCheck = time;
      if (isGrabbed(clockGroup)) {
        refreshClock(false);
        return;
      }
      refreshClock(false);
    }
  };
}

