      <div class="row">
        <button class="btn" id="fmt"><span class="btn-text" id="fmtLabel">24-hour</span></button>
        <button class="btn2" id="sec"><span class="btn-text" id="secLabel">Seconds: on</span></button>
      </div>
      <span class="hint">Pinch the wooden clock to move it</span>
    </div>`, { width: 0.32, position: [0.19, 0.165, 0.04], rotationY: -0.28 });
  root.add(panel.object3D);

  let is24Hour = false;
  let showSeconds = true;
  let lastMin = -1;
  let lastHour = -1;
  let lastMode = -1;

  const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const monNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  function pad(n) {
    return (n < 10 ? '0' : '') + n;
  }

  panel.on('fmt', 'click', () => {
    is24Hour = !is24Hour;
    panel.set('fmtLabel', { text: is24Hour ? '12-hour' : '24-hour' });
    lastMin = -1;
  });
  panel.on('sec', 'click', () => {
    showSeconds = !showSeconds;
    panel.set('secLabel', { text: showSeconds ? 'Seconds: on' : 'Seconds: off' });
    secondPivot.visible = showSeconds;
  });

  function refreshDigital(h24, m, nowMs) {
    let timeStr;
    let ampm = h24 < 12 ? 'AM' : 'PM';
    if (is24Hour) {
      timeStr = pad(h24) + ':' + pad(m);
    } else {
      let h12 = h24 % 12;
      if (h12 === 0) h12 = 12;
      timeStr = h12 + ':' + pad(m);
    }
    panel.set('clock', { text: timeStr });
    // date line (updated only when minute changes, so one allocation per minute is fine)
    const d = new Date(nowMs);
    const sub = dayNames[d.getDay()] + ', ' + monNames[d.getMonth()] + ' ' + d.getDate() + (is24Hour ? '  •  24H' : '  •  ' + ampm);
    panel.set('date', { text: sub });
  }

  function update() {
    const nowMs = Date.now();
    const shifted = nowMs - tzOffsetMs;
    let secOfDay = Math.floor(shifted / 1000) % 86400;
    if (secOfDay < 0) secOfDay += 86400;
    const h24 = Math.floor(secOfDay / 3600);
    const m = Math.floor((secOfDay - h24 * 3600) / 60);
    const s = secOfDay - h24 * 3600 - m * 60;
    const frac = (shifted % 1000) / 1000;

    const secAngle = ((s + frac) / 60) * TWO_PI;
    const minAngle = ((m + s / 60 + frac / 3600) / 60) * TWO_PI;
    const hourAngle = (((h24 % 12) + m / 60 + s / 3600) / 12) * TWO_PI;

    secondPivot.rotation.z = -secAngle;
    minutePivot.rotation.z = -minAngle;
    hourPivot.rotation.z = -hourAngle;

    const modeKey = (is24Hour ? 2 : 0) + (showSeconds ? 1 : 0);
    if (m !== lastMin || h24 !== lastHour || modeKey !== lastMode) {
      lastMin = m;
      lastHour = h24;
      lastMode = modeKey;
      refreshDigital(h24, m, nowMs);
    }
  }

  return { root, update };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Materials ----------
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x2e333c, roughness: 0.5, metalness: 0.55 });
  const armMat = new THREE.MeshStandardMaterial({ color: 0xaab3c2, roughness: 0.32, metalness: 0.85 });
  const jointMat = new THREE.MeshStandardMaterial({ color: 0x1e2127, roughness: 0.4, metalness: 0.6 });
  const shadeMat = new THREE.MeshStandardMaterial({ color: 0xff6b2d, roughness: 0.45, metalness: 0.15, side: THREE.DoubleSide });
  const bulbMat = new THREE.MeshStandardMaterial({ color: 0xfff6d8, emissive: 0xffc25e, emissiveIntensity: 2.4, roughness: 0.3 });
  const switchMat = new THREE.MeshStandardMaterial({ color: 0x1f8a4a, emissive: 0x2bff7a, emissiveIntensity: 0.8, roughness: 0.4 });
  const beamMat = new THREE.MeshBasicMaterial({ color: 0xffd88a, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false });
  const poolMat = new THREE.MeshBasicMaterial({ color: 0xffd27a, transparent: true, opacity: 0.5, depthWrite: false });
  const poolHotMat = new THREE.MeshBasicMaterial({ color: 0xfff0c0, transparent: true, opacity: 0.75, depthWrite: false });
  const haloMat = new THREE.MeshBasicMaterial({ color: 0xffe6a8, transparent: true, opacity: 0.32, depthWrite: false });
  const moteMat = new THREE.MeshBasicMaterial({ color: 0xffe9b8, transparent: true, opacity: 0.85, depthWrite: false });

  // ---------- Lamp group (the pressable + grabbable object) ----------
  const lamp = new THREE.Group();
  lamp.position.set(-0.15, 0, -0.05);
  root.add(lamp);

  function tubeBetween(a, b, r, mat) {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    const geo = new THREE.CylinderGeometry(r, r, len, 16);
    const m = new THREE.Mesh(geo, mat);
    m.position.copy(a).addScaledVector(dir, 0.5);
    m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
    return m;
  }

  // Base
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.068, 0.03, 32), baseMat);
  base.position.set(0, 0.015, 0);
  base.name = 'Base';
  lamp.add(base);

  // Base trim ring
  const trim = new THREE.Mesh(new THREE.TorusGeometry(0.062, 0.004, 10, 40), armMat);
  trim.rotation.x = Math.PI / 2;
  trim.position.set(0, 0.004, 0);
  lamp.add(trim);

  // Lower arm + joint + upper arm
  const J = new THREE.Vector3(0, 0.225, 0);
  const H = new THREE.Vector3(0.12, 0.32, 0.10);
  const lowerArm = tubeBetween(new THREE.Vector3(0, 0.03, 0), J, 0.008, armMat);
  lowerArm.name = 'LowerArm';
  lamp.add(lowerArm);

  const joint = new THREE.Mesh(new THREE.SphereGeometry(0.014, 20, 12), jointMat);
  joint.position.copy(J);
  joint.name = 'Joint';
  lamp.add(joint);

  const upperArm = tubeBetween(J, H, 0.007, armMat);
  upperArm.name = 'UpperArm';
  lamp.add(upperArm);

  const headJoint = new THREE.Mesh(new THREE.SphereGeometry(0.011, 18, 12), jointMat);
  headJoint.position.copy(H);
  lamp.add(headJoint);

  // Light target (local to lamp group)
  const targetPos = new THREE.Vector3(0.20, 0.0, 0.15);

  // Shade: narrow top, wide opening toward desk
  const beamDir = new THREE.Vector3().subVectors(targetPos, H).normalize();
  const negDir = beamDir.clone().multiplyScalar(-1);
  const shade = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.062, 0.085, 32, 1, true), shadeMat);
  shade.name = 'Shade';
  const shadeCenter = H.clone().addScaledVector(beamDir, -0.01);
  shade.position.copy(shadeCenter);
  shade.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), negDir);
  lamp.add(shade);

  // Shade back cap
  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.028, 20, 12, 0, Math.PI * 2, 0, Math.PI / 2), shadeMat);
  cap.position.copy(H).addScaledVector(beamDir, -0.052);
  cap.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), negDir);
  lamp.add(cap);

  // Bulb just inside opening
  const bulbPos = H.clone().addScaledVector(beamDir, 0.025);
  const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.018, 24, 14), bulbMat);
  bulb.position.copy(bulbPos);
  bulb.name = 'Bulb';
  lamp.add(bulb);

  // Halo glow around bulb
  const halo = new THREE.Mesh(new THREE.SphereGeometry(0.032, 18, 12), haloMat);
  halo.position.copy(bulbPos);
  lamp.add(halo);

  // Beam volume (cone)
  const beamLen = bulbPos.distanceTo(targetPos);
  const beamGeo = new THREE.CylinderGeometry(0.024, 0.105, beamLen, 32, 1, true);
  const beam = new THREE.Mesh(beamGeo, beamMat);
  beam.position.copy(bulbPos).add(targetPos).multiplyScalar(0.5);
  const upDir = new THREE.Vector3().subVectors(bulbPos, targetPos).normalize();
  beam.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), upDir);
  beam.renderOrder = 2;
  beam.name = 'Beam';
  lamp.add(beam);

  // Light pools on desk
  const pool = new THREE.Mesh(new THREE.CircleGeometry(0.11, 32), poolMat);
  pool.rotation.x = -Math.PI / 2;
  pool.position.set(targetPos.x, 0.003, targetPos.z);
  pool.renderOrder = 1;
  pool.name = 'LightPool';
  lamp.add(pool);

  const poolHot = new THREE.Mesh(new THREE.CircleGeometry(0.055, 28), poolHotMat);
  poolHot.rotation.x = -Math.PI / 2;
  poolHot.position.set(targetPos.x, 0.0045, targetPos.z);
  poolHot.renderOrder = 1;
  lamp.add(poolHot);

  // Switch knob on base
  const knob = new THREE.Mesh(new THREE.CylinderGeometry(0.013, 0.013, 0.014, 20), switchMat);
  knob.position.set(0.038, 0.037, 0.015);
  knob.name = 'Switch';
  lamp.add(knob);
  const knobRing = new THREE.Mesh(new THREE.TorusGeometry(0.013, 0.0025, 8, 24), jointMat);
  knobRing.rotation.x = Math.PI / 2;
  knobRing.position.set(0.038, 0.031, 0.015);
  lamp.add(knobRing);

  // Dust motes drifting in beam (scenery, not grabbable)
  const MOTES = 10;
  const moteGeo = new THREE.SphereGeometry(0.004, 8, 6);
  const motes = [];
  const moteOffset = [];
  const moteAngle = [];
  const moteSpeed = [];
  for (let i = 0; i < MOTES; i++) {
    const m = new THREE.Mesh(moteGeo, moteMat);
    m.visible = true;
    lamp.add(m);
    motes.push(m);
    moteOffset.push((i * 0.137 + (i % 3) * 0.21) % 1);
    moteAngle.push(i * 2.4);
    moteSpeed.push(0.06 + (i % 4) * 0.015);
  }

  // ---------- Info panel ----------
  const info = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; width: 500px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: left; }
      .body { color: #d7dbe2; font-size: 22px; text-align: left; }
      .status { color: #7dff9e; font-size: 24px; font-weight: 700; text-align: left; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; border-color: #2f6fdb; border-width: 0px; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="body">Poke or pinch-press the lamp to switch it. Pinch and drag to move it.</span>
      <span class="status" id="status">ON — warming your desk</span>
      <button class="btn" id="toggle"><span class="btn-text" id="toggleLabel">Switch Off</span></button>
    </div>`, { width: 0.3, position: [0.23, 0.22, 0.05], rotationY: -0.3 });
  root.add(info.object3D);

  // ---------- State ----------
  let isOn = true;
  let popAnim = 1;

  function applyState() {
    if (isOn) {
      bulbMat.color.setHex(0xfff6d8);
      bulbMat.emissive.setHex(0xffc25e);
      bulbMat.emissiveIntensity = 2.4;
      switchMat.color.setHex(0x1f8a4a);
      switchMat.emissive.setHex(0x2bff7a);
      switchMat.emissiveIntensity = 0.8;
      beam.visible = true;
      pool.visible = true;
      poolHot.visible = true;
      halo.visible = true;
      for (let i = 0; i < motes.length; i++) motes[i].visible = true;
      info.set('status', { text: 'ON — warming your desk' });
      info.set('toggleLabel', { text: 'Switch Off' });
    } else {
      bulbMat.color.setHex(0x8a8f96);
      bulbMat.emissive.setHex(0x000000);
      bulbMat.emissiveIntensity = 0.05;
      switchMat.color.setHex(0x8a2a2a);
      switchMat.emissive.setHex(0xff3b3b);
      switchMat.emissiveIntensity = 0.9;
      beam.visible = false;
      pool.visible = false;
      poolHot.visible = false;
      halo.visible = false;
      for (let i = 0; i < motes.length; i++) motes[i].visible = false;
      info.set('status', { text: 'OFF — press the lamp' });
      info.set('toggleLabel', { text: 'Switch On' });
    }
  }

  function toggle() {
    isOn = !isOn;
    popAnim = 0;
    applyState();
  }

  traits(lamp, { grab: true, onPress: toggle });
  info.on('toggle', 'click', toggle);
  applyState();

  const bx = bulbPos.x, by = bulbPos.y, bz = bulbPos.z;
  const tx = targetPos.x, ty = targetPos.y, tz = targetPos.z;

  return {
    root,
    update(time, delta) {
      const d = delta > 0.05 ? 0.05 : delta;
      const held = isGrabbed(lamp);

      // Press pop on shade (skip while held so we never fight the hand)
      if (!held) {
        if (popAnim < 1) {
          popAnim = Math.min(1, popAnim + d * 3.5);
          const s = 1 + Math.sin(popAnim * Math.PI) * 0.16;
          shade.scale.set(s, s, s);
        } else {
          shade.scale.set(1, 1, 1);
        }
      }

      if (isOn) {
        const flick = Math.sin(time * 7.3) * 0.018 + Math.sin(time * 13.7) * 0.01;
        beamMat.opacity = 0.155 + flick;
        poolMat.opacity = 0.48 + flick * 0.8;
        poolHotMat.opacity = 0.72 + flick;
        bulbMat.emissiveIntensity = 2.35 + Math.sin(time * 9.1) * 0.18;
        const hs = 1 + Math.sin(time * 3.2) * 0.06;
        halo.scale.set(hs, hs, hs);
        // Dust drifting down the beam
        for (let i = 0; i < motes.length; i++) {
          let t = (time * moteSpeed[i] + moteOffset[i]) % 1;
          if (t < 0) t += 1;
          const spread = 0.012 + t * 0.075;
          const a = moteAngle[i] + time * (0.4 + (i % 3) * 0.2);
          const px = bx + (tx - bx) * t + Math.cos(a) * spread;
          const py = by + (ty - by) * t + Math.sin(a * 1.3) * 0.008;
          const pz = bz + (tz - bz) * t + Math.sin(a) * spread;
          motes[i].position.set(px, py, pz);
          const sc = 1 - t * 0.45;
          motes[i].scale.set(sc, sc, sc);
        }
      } else {
        // Invite a press: pulse the red switch knob
        switchMat.emissiveIntensity = 0.7 + Math.sin(time * 4.2) * 0.45;
      }
    }
  };
}

