      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: left; }
      .status { color: #ffe6a8; font-size: 26px; font-weight: 700; text-align: left; }
      .body { color: #d7dbe2; font-size: 22px; text-align: left; }
      .hint { color: #9aa0ab; font-size: 20px; text-align: left; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #e8a12c; }
      .btn-text { color: #1a1d22; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="status" id="status">ON</span>
