      const k = Math.min(1, delta * 12);
      lever.rotation.z = cur + (leverTarget - cur) * k;

      // Gentle glow pulse when on; frozen logic uses no allocation
      if (on && !isGrabbed(lamp)) {
        const s = Math.sin(time * 2.4);
        glowMat.opacity = 0.48 + s * 0.07;
        coneMat.opacity = 0.14 + s * 0.025;
      } else if (on) {
        glowMat.opacity = 0.5;
        coneMat.opacity = 0.15;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
