  const leafR = new THREE.Mesh(leafGeo, leafMat2);
  leafR.name = 'LeafRight';
  leafR.position.set(0.07, 0.235, 0.01);
  leafR.rotation.set(0.2, -0.3, -0.5);
  leafR.scale.set(1, 0.35, 0.6);
  root.add(leafR);

  const leafT = new THREE.Mesh(leafGeo, leafMat);
  leafT.name = 'LeafTop';
  leafT.position.set(0.005, 0.295, 0);
  leafT.rotation.set(0, 0, 0.15);
  leafT.scale.set(0.7, 0.28, 0.45);
  root.add(leafT);

  // ---------- sun ----------
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffd54a, emissive: 0xff9d00, emissiveIntensity: 1.2, roughness: 0.4 });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.05, 28, 16), sunMat);
  sun.position.set(-0.28, 0.38, -0.12);
  sun.name = 'Sun';
  root.add(sun);

  const glowMat = new THREE.MeshBasicMaterial({ color: 0xffc23d, transparent: true, opacity: 0.22 });
  const glow = new THREE.Mesh(new THREE.SphereGeometry(0.068, 24, 12), glowMat);
  glow.position.copy(sun.position);
  glow.name = 'SunGlow';
  root.add(glow);

  // rays around sun (flat boxes)
  const rayMat = new THREE.MeshBasicMaterial({ color: 0xffd54a });
  const rayGeo = new THREE.BoxGeometry(0.02, 0.008, 0.008);
  const sunRays = new THREE.Group();
  for (let i = 0; i < 8; i++) {
    const r = new THREE.Mesh(rayGeo, rayMat);
    const a = (i / 8) * Math.PI * 2;
    r.position.set(Math.cos(a) * 0.075, Math.sin(a) * 0.075, 0);
    r.rotation.z = a;
    sunRays.add(r);
  }
  sunRays.position.copy(sun.position);
