  const puddleMat = new THREE.MeshStandardMaterial({ color: 0x1e6fd6, roughness: 0.4, transparent: true, opacity: 0.7 });
  const puddle = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.006, 20), puddleMat);
  puddle.position.set(0.24, 0.013, 0.10);
  puddle.name = 'Puddle';
  root.add(puddle);

  // ---------- CO2 puff (grabbable) ----------
  const co2Mat = new THREE.MeshStandardMaterial({ color: 0x9aa3ad, roughness: 0.9, transparent: true, opacity: 0.9 });
  const co2Mesh = new THREE.Mesh(new THREE.IcosahedronGeometry(0.026, 1), co2Mat);
  co2Mesh.position.set(0.24, 0.30, -0.06);
  co2Mesh.name = 'CarbonDioxide';
  root.add(co2Mesh);
  const co2HomeY = 0.30;
  const co2Mini = new THREE.Mesh(new THREE.IcosahedronGeometry(0.015, 1), co2Mat);
  co2Mini.position.set(0.19, 0.335, -0.05);
  co2Mini.name = 'CarbonDioxide2';
  root.add(co2Mini);

  // ---------- arrows ----------
  function makeArrow(ax, ay, az, bx, by, bz, color, name) {
    const a = new THREE.Vector3(ax, ay, az);
    const b = new THREE.Vector3(bx, by, bz);
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    dir.normalize();
    const mat = new THREE.MeshBasicMaterial({ color });
    const g = new THREE.Group();
    g.name = name;
    const shaftLen = Math.max(0.02, len - 0.032);
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, shaftLen, 10), mat);
    shaft.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    shaft.position.set(a.x + dir.x * shaftLen * 0.5, a.y + dir.y * shaftLen * 0.5, a.z + dir.z * shaftLen * 0.5);
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.013, 0.03, 14), mat);
    head.quaternion.copy(shaft.quaternion);
    head.position.set(b.x - dir.x * 0.015, b.y - dir.y * 0.015, b.z - dir.z * 0.015);
    g.add(shaft);
    g.add(head);
    root.add(g);
    return { group: g, a, b };
  }
  const lightArrow = makeArrow(-0.225, 0.345, -0.10, -0.09, 0.25, -0.01, 0xffd54a, 'LightArrow');
  const waterArrow = makeArrow(0.19, 0.055, 0.085, 0.07, 0.085, 0.02, 0x2fa8ff, 'WaterArrow');
  const co2Arrow = makeArrow(0.195, 0.305, -0.055, 0.08, 0.25, -0.005, 0xb8bec6, 'CO2Arrow');
  const o2Arrow = makeArrow(-0.045, 0.26, 0.01, -0.135, 0.345, 0.03, 0x7ef0c8, 'OxygenArrow');

  // ---------- flow particles ----------
  const flowGroup = new THREE.Group();
  flowGroup.name = 'Flows';
  root.add(flowGroup);
  const dotGeo = new THREE.SphereGeometry(0.009, 12, 8);
  const lightDotMat = new THREE.MeshBasicMaterial({ color: 0xffe27a });
  const waterDotMat = new THREE.MeshBasicMaterial({ color: 0x4db8ff });
  const co2DotMat = new THREE.MeshBasicMaterial({ color: 0xd0d5db });
  const o2DotMat = new THREE.MeshBasicMaterial({ color: 0x7ef0c8 });

  function addDots(n, mat, a, b, speed) {
    const arr = [];
    for (let i = 0; i < n; i++) {
      const m = new THREE.Mesh(dotGeo, mat);
      flowGroup.add(m);
      arr.push({ m, a, b, off: i / n, speed });
    }
    return arr;
  }
  const waterUpA = new THREE.Vector3(0, 0.10, 0);
  const waterUpB = new THREE.Vector3(0, 0.24, 0);
  const o2A = new THREE.Vector3(-0.045, 0.27, 0.01);
  const o2B = new THREE.Vector3(-0.145, 0.40, 0.03);

  const lightDots = addDots(4, lightDotMat, lightArrow.a, lightArrow.b, 0.45);
  const waterDots = addDots(3, waterDotMat, waterUpA, waterUpB, 0.5);
  const co2Dots = addDots(3, co2DotMat, co2Arrow.a, co2Arrow.b, 0.4);
  const o2Dots = addDots(5, o2DotMat, o2A, o2B, 0.32);

  // ---------- state ----------
  let lightOn = true;
  let waterAmount = 0.9;
  let growth = 0;
  let statusTimer = 0;
  let factIdx = 0;
  const facts = [
    'Leaves trap light in green chlorophyll.',
    'Roots absorb water. It travels up the stem.',
    'CO2 enters through tiny leaf pores called stomata.',
    'Photosynthesis makes sugar + oxygen: 6CO2 + 6H2O + light.',
    'Oxygen you breathe comes from plants like this!'
  ];

  // ---------- main panel ----------
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; width: 500px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .eq { color: #aef1aa; font-size: 21px; text-align: center; }
      .status { color: #ffd54a; font-size: 22px; text-align: center; }
      .fact { color: #d7dbe2; font-size: 20px; text-align: center; }
      .hint { color: #9aa3ad; font-size: 19px; text-align: center; }
      .btnL { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #ffd54a; }
      .btnW { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; }
      .btnTL { color: #1a1d22; font-size: 22px; font-weight: 700; text-align: center; }
      .btnTW { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="eq">6CO2 + 6H2O + light go to sugar + 6O2</span>
      <span class="status" id="status">Light ON | Water full | Making O2!</span>
      <span class="fact" id="fact">Pinch the Sun or droplet. Poke a leaf!</span>
      <button class="btnL" id="lightBtn"><span class="btnTL" id="lightTxt">Turn light off</span></button>
      <button class="btnW" id="waterBtn"><span class="btnTW">Give water</span></button>
      <span class="hint">Follow arrows: yellow light, blue water, grey CO2, green O2</span>
    </div>`, { width: 0.30, position: [0.235, 0.235, 0.10], rotationY: -0.32 });
  root.add(info.object3D);

  function refreshStatus() {
    const wpct = Math.round(waterAmount * 100);
    const active = lightOn && waterAmount > 0.15;
    const txt = (lightOn ? 'Light ON' : 'Light OFF') + ' | Water ' + wpct + '% | ' + (active ? 'Making O2!' : 'No O2 yet');
    info.set('status', { text: txt, color: active ? '#aef1aa' : '#ff9a9a' });
    info.set('lightTxt', { text: lightOn ? 'Turn light off' : 'Turn light on' });
  }

  function toggleLight() {
    lightOn = !lightOn;
    sunMat.emissiveIntensity = lightOn ? 1.2 : 0.05;
    sunMat.color.setHex(lightOn ? 0xffd54a : 0x555a60);
    glowMat.opacity = lightOn ? 0.22 : 0.03;
    rayMat.color.setHex(lightOn ? 0xffd54a : 0x555a60);
    info.set('fact', { text: lightOn ? 'Sunshine! Chlorophyll catches light energy.' : 'Night! Without light, photosynthesis stops.' });
    refreshStatus();
  }
  function giveWater() {
    waterAmount = 1;
    info.set('fact', { text: 'Slurp! Roots take water up the stem to leaves.' });
    refreshStatus();
  }
  function leafPress() {
    factIdx = (factIdx + 1) % facts.length;
    info.set('fact', { text: facts[factIdx] });
  }
  function co2Press() {
    info.set('fact', { text: 'CO2 from air enters leaves. Carbon becomes sugar!' });
  }

  info.on('lightBtn', 'click', toggleLight);
  info.on('waterBtn', 'click', giveWater);

  traits(sun, { grab: true, onPress: toggleLight });
  traits(waterMesh, { grab: true, onPress: giveWater });
  traits(co2Mesh, { grab: true, onPress: co2Press });
  traits(leafR, { onPress: leafPress });
  traits(leafL, { onPress: leafPress });

  // ---------- small labels ----------
  function label(text, color, w, pos) {
    const h = ui(`
      <style>
        .pill { flex-direction: row; justify-content: center; align-items: center; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 18px; background-color: #1a1d22; width: 400px; }
        .txt { color: ${color}; font-size: 26px; font-weight: 700; text-align: center; }
      </style>
      <div class="pill"><span class="txt">${text}</span></div>`, { width: w, position: pos });
    root.add(h.object3D);
    return h;
  }
  label('Light', '#ffd54a', 0.12, [-0.175, 0.335, 0.0]);
  label('Water H2O', '#4db8ff', 0.15, [0.155, 0.125, 0.10]);
  label('CO2 in', '#d0d5db', 0.12, [0.165, 0.365, -0.01]);
  label('O2 out', '#7ef0c8', 0.12, [-0.19, 0.395, 0.04]);

  refreshStatus();

  return {
    root,
    update(time, delta) {
      // water decay + growth
      waterAmount = Math.max(0, waterAmount - delta * 0.03);
      const active = lightOn && waterAmount > 0.15;
      if (active) growth = Math.min(1, growth + delta * 0.04);

      // gentle idle bobs (skip when held)
      if (!isGrabbed(sun)) {
        sun.position.y = 0.38 + Math.sin(time * 1.1) * 0.004;
        sunRays.position.copy(sun.position);
        sunRays.rotation.z = time * 0.2;
        glow.position.copy(sun.position);
        const s = 1 + Math.sin(time * 2.2) * 0.05;
        glow.scale.set(s, s, s);
      }
      if (!isGrabbed(waterMesh)) {
        waterMesh.position.y = waterHomeY + Math.sin(time * 1.8) * 0.008;
      }
      if (!isGrabbed(co2Mesh)) {
        co2Mesh.position.y = co2HomeY + Math.sin(time * 1.6 + 1.2) * 0.008;
        co2Mesh.rotation.y = time * 0.6;
      }

      // leaf sway + growth scale
      const g = 1 + growth * 0.35;
      leafL.rotation.z = 0.5 + Math.sin(time * 1.2) * 0.07;
      leafR.rotation.z = -0.5 - Math.sin(time * 1.2 + 0.6) * 0.07;
      leafL.scale.set(1 * g, 0.35 * g, 0.6 * g);
      leafR.scale.set(1 * g, 0.35 * g, 0.6 * g);
      leafT.scale.set(0.7 * g, 0.28 * g, 0.45 * g);
      leafT.position.y = 0.295 + Math.sin(time * 1.4) * 0.003;

      // flows
      let i, t, p;
      for (i = 0; i < lightDots.length; i++) {
        p = lightDots[i];
        p.m.visible = lightOn;
        if (lightOn) {
          t = (time * p.speed + p.off) % 1;
          p.m.position.lerpVectors(p.a, p.b, t);
        }
      }
      const showWater = waterAmount > 0.05;
      for (i = 0; i < waterDots.length; i++) {
        p = waterDots[i];
        p.m.visible = showWater;
        if (showWater) {
          t = (time * p.speed + p.off) % 1;
          p.m.position.lerpVectors(p.a, p.b, t);
        }
      }
      for (i = 0; i < co2Dots.length; i++) {
        p = co2Dots[i];
        p.m.visible = active;
        if (active) {
          t = (time * p.speed + p.off) % 1;
          p.m.position.lerpVectors(p.a, p.b, t);
        }
      }
      for (i = 0; i < o2Dots.length; i++) {
        p = o2Dots[i];
        p.m.visible = active;
        if (active) {
          t = (time * p.speed + p.off) % 1;
          p.m.position.lerpVectors(p.a, p.b, t);
          p.m.position.x += Math.sin(time * 2.5 + p.off * 6.283) * 0.01;
          const bs = 0.8 + t * 0.7;
          p.m.scale.set(bs, bs, bs);
        }
      }

      statusTimer += delta;
      if (statusTimer > 0.6) {
        statusTimer = 0;
        refreshStatus();
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // Earth anchor - the one grabbable thing (moves whole model)
  const earthGroup = new THREE.Group();
  earthGroup.position.set(0, 0.22, -0.08);
  root.add(earthGroup);
  traits(earthGroup, { grab: true });

  const PHI_START = Math.PI * 0.75; // 135 deg
  const PHI_LEN = Math.PI * 1.5;    // 270 deg -> 90 deg wedge missing toward +Z (user)
  const R_CRUST = 0.13;
  const R_MANTLE = 0.122;
  const R_OUTER = 0.066;
  const R_INNER = 0.03;
  const RY_A = Math.PI * 1.25; // 225 deg
  const RY_B = Math.PI * 1.75; // 315 deg

  const matCrust = new THREE.MeshStandardMaterial({
    color: 0x5aa9e6, roughness: 0.55, metalness: 0.05,
    side: THREE.DoubleSide, emissive: 0x5aa9e6, emissiveIntensity: 0.1
  });
  const matMantle = new THREE.MeshStandardMaterial({
    color: 0xef6c2a, roughness: 0.7, metalness: 0.05,
    side: THREE.DoubleSide, emissive: 0xef6c2a, emissiveIntensity: 0.12
  });
  const matOuter = new THREE.MeshStandardMaterial({
    color: 0xffb02e, roughness: 0.45, metalness: 0.3,
    side: THREE.DoubleSide, emissive: 0xff9500, emissiveIntensity: 0.22
  });
  const matInner = new THREE.MeshStandardMaterial({
    color: 0xfff3a0, roughness: 0.35, metalness: 0.4,
    side: THREE.DoubleSide, emissive: 0xffdf6b, emissiveIntensity: 0.45
  });
  const matLand = new THREE.MeshStandardMaterial({ color: 0x4caf6a, roughness: 0.9 });

  const crustG = new THREE.Group();
  const mantleG = new THREE.Group();
  const outerG = new THREE.Group();
  const innerG = new THREE.Group();
  earthGroup.add(crustG);
  earthGroup.add(mantleG);
  earthGroup.add(outerG);
  earthGroup.add(innerG);

  const crustGeo = new THREE.SphereGeometry(R_CRUST, 32, 16, PHI_START, PHI_LEN);
  const mantleGeo = new THREE.SphereGeometry(R_MANTLE, 32, 16, PHI_START, PHI_LEN);
  const outerGeo = new THREE.SphereGeometry(R_OUTER, 28, 14, PHI_START, PHI_LEN);
  const innerGeo = new THREE.SphereGeometry(R_INNER, 24, 12, PHI_START, PHI_LEN);

  const crustMesh = new THREE.Mesh(crustGeo, matCrust);
  crustMesh.name = 'Crust';
  crustG.add(crustMesh);

  const mantleMesh = new THREE.Mesh(mantleGeo, matMantle);
  mantleMesh.name = 'Mantle';
  mantleG.add(mantleMesh);

  const outerMesh = new THREE.Mesh(outerGeo, matOuter);
  outerMesh.name = 'Outer Core';
  outerG.add(outerMesh);

  const innerMesh = new THREE.Mesh(innerGeo, matInner);
  innerMesh.name = 'Inner Core';
  innerG.add(innerMesh);

  // Flat cut faces: rings so layers show as concentric bands, no z-fighting
  const crustRingGeo = new THREE.RingGeometry(R_MANTLE, R_CRUST, 40);
  const mantleRingGeo = new THREE.RingGeometry(R_OUTER, R_MANTLE, 40);
  const outerRingGeo = new THREE.RingGeometry(R_INNER, R_OUTER, 32);
  const innerDiscGeo = new THREE.CircleGeometry(R_INNER, 28);

  function addCut(parent, geo, mat) {
    const a = new THREE.Mesh(geo, mat);
    a.rotation.y = RY_A;
    parent.add(a);
    const b = new THREE.Mesh(geo, mat);
    b.rotation.y = RY_B;
    parent.add(b);
  }
  addCut(crustG, crustRingGeo, matCrust);
  addCut(mantleG, mantleRingGeo, matMantle);
  addCut(outerG, outerRingGeo, matOuter);
  addCut(innerG, innerDiscGeo, matInner);

  // Continents on the back side (outside the cut) to read as Earth
  const landGeo = new THREE.SphereGeometry(0.024, 12, 8);
