  land1.name = 'Continent';
  land1.position.set(-0.041, 0.055, -0.112);
  land1.scale.set(1, 0.35, 1);
  crustG.add(land1);
  const land2 = new THREE.Mesh(landGeo, matLand);
  land2.name = 'Continent';
  land2.position.set(0.052, 0.02, -0.108);
  land2.scale.set(1, 0.35, 1);
  crustG.add(land2);
  const land3 = new THREE.Mesh(landGeo, matLand);
  land3.name = 'Continent';
  land3.position.set(0.005, -0.06, -0.11);
  land3.scale.set(1.2, 0.35, 1);
