      .btnO { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #a97a1e; }
      .btnI { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #8a7a2e; }
      .btnT { color: #ffffff; font-size: 20px; font-weight: 700; }
      .foot { color: #8f96a3; font-size: 18px; text-align: center; }
    </style>
    <div class="card">
