      <span class="sub">Pinch Earth to move it - tap a layer</span>
      <span class="info" id="info">Cut-away view. Tap Crust, Mantle, Outer or Inner Core to explore.</span>
      <div class="row">
        <button class="btnC" id="btn-crust"><span class="btnT">Crust</span></button>
        <button class="btnM" id="btn-mantle"><span class="btnT">Mantle</span></button>
        <button class="btnO" id="btn-outer"><span class="btnT">Outer</span></button>
        <button class="btnI" id="btn-inner"><span class="btnT">Inner</span></button>
      </div>
      <div class="row">
        <button class="btn" id="btn-explode"><span class="btnT" id="explodeLabel">Explode view</span></button>
      </div>
      <span class="foot">Not to scale - crust enlarged to see it</span>
    </div>`, { width: 0.36, position: [0, 0.1, 0.18], rotationY: 0 });
  root.add(main.object3D);

  function makeLabel(nameText, dotColor, pos, rotY) {
    const h = ui(`
      <style>
        .lab { display: flex; flex-direction: row; gap: 10px; align-items: center; justify-content: flex-start; padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 14px; background-color: #1f2228; }
        .dot { width: 20px; height: 20px; border-radius: 10px; background-color: ${dotColor}; }
        .name { color: #ffffff; font-size: 22px; font-weight: 700; }
      </style>
      <button class="lab" id="pick"><span class="dot"> </span><span class="name">${nameText}</span></button>`,
      { width: 0.2, position: pos, rotationY: rotY });
    root.add(h.object3D);
    return h;
  }

  const labelCrust = makeLabel('Crust - 5-70 km', '#5aa9e6', [-0.29, 0.335, 0.0], 0.35);
  const labelMantle = makeLabel('Mantle - 2890 km', '#ef6c2a', [-0.3, 0.235, 0.0], 0.35);
  const labelOuter = makeLabel('Outer Core - liquid', '#ffb02e', [0.29, 0.235, 0.0], -0.35);
  const labelInner = makeLabel('Inner Core - solid', '#fff3a0', [0.29, 0.135, 0.0], -0.35);

  const INFO = {
    'Crust': 'CRUST (5-70 km): thin, cool solid rock. Oceans and continents sit on it. Thinnest under oceans, thickest under mountains.',
    'Mantle': 'MANTLE (to 2,890 km depth): hot rock that flows very slowly. Its motion moves tectonic plates and volcanoes.',
    'Outer Core': 'OUTER CORE (2,890-5,150 km): liquid iron + nickel, 4,000-5,000 C. Its flow creates Earth magnetic field.',
    'Inner Core': 'INNER CORE (radius 1,220 km): solid iron-nickel, about 5,500 C - hotter than the Sun surface - held solid by pressure.'
  };

  let selected = null;
  let explodeTarget = 0;
  let explodeT = 0;

  function select(name) {
    selected = name;
    main.set('info', { text: INFO[name] });
  }

  main.on('btn-crust', 'click', () => select('Crust'));
  main.on('btn-mantle', 'click', () => select('Mantle'));
  main.on('btn-outer', 'click', () => select('Outer Core'));
  main.on('btn-inner', 'click', () => select('Inner Core'));
  main.on('btn-explode', 'click', () => {
    explodeTarget = explodeTarget > 0.5 ? 0 : 1;
    main.set('explodeLabel', { text: explodeTarget > 0.5 ? 'Put back together' : 'Explode view' });
    if (!selected) main.set('info', { text: 'Pulled apart: blue Crust + Mantle stay, orange Outer and yellow Inner Core slide out the cut.' });
  });

  labelCrust.on('pick', 'click', () => select('Crust'));
  labelMantle.on('pick', 'click', () => select('Mantle'));
  labelOuter.on('pick', 'click', () => select('Outer Core'));
  labelInner.on('pick', 'click', () => select('Inner Core'));

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(earthGroup)) {
        const diff = explodeTarget - explodeT;
        const step = 0.35 * delta;
        if (diff > step) explodeT += step;
        else if (diff < -step) explodeT -= step;
        else explodeT = explodeTarget;
        outerG.position.z = 0.1 * explodeT;
        innerG.position.z = 0.2 * explodeT;
      }
      const pulse = 0.5 + 0.5 * Math.sin(time * 3.0);
      matCrust.emissiveIntensity = selected === 'Crust' ? 0.35 + 0.3 * pulse : 0.1;
      matMantle.emissiveIntensity = selected === 'Mantle' ? 0.4 + 0.3 * pulse : 0.12;
      matOuter.emissiveIntensity = selected === 'Outer Core' ? 0.5 + 0.35 * pulse : 0.22;
      matInner.emissiveIntensity = selected === 'Inner Core' ? 0.7 + 0.4 * pulse : 0.45;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
