  const cloudMatDark = new THREE.MeshStandardMaterial({ color: 0x8f96a6, roughness: 0.9 });
  const rainCloud = new THREE.Group();
  rainCloud.position.set(xs[1], 0.2, 0.02);
  rainCloud.name = "London";
  const rc1 = new THREE.Mesh(new THREE.SphereGeometry(0.03, 24, 12), cloudMatRain);
  rc1.name = "London";
  rc1.position.set(0, 0.01, 0);
