  root.add(panel.object3D);

  function refresh() {
    const c = cities[selected];
    panel.set("detail", { text: c.name + " \u2022 " + c.cond + " \u2022 " + fmt(c.tempC) + " \u2022 H " + c.hum + "% \u2022 W " + c.wind + " km/h" });
    panel.set("temp0", { text: fmt(cities[0].tempC) });
