  traits(sunGroup, { grab: true, onPress: () => select(0) });
  traits(rainCloud, { grab: true, onPress: () => select(1) });
  traits(snowCloud, { grab: true, onPress: () => select(2) });

  refresh();

  const baseSunY = 0.2, baseRainY = 0.2, baseSnowY = 0.2;

  return {
    root,
    update(time, delta) {
      const d = Math.min(delta, 0.05);
      if (!isGrabbed(sunGroup)) {
        sunGroup.position.y = baseSunY + Math.sin(time * 1.2) * 0.008;
      }
      rays.rotation.z = time * 0.5;
      const s = 1 + Math.sin(time * 2.2) * 0.04;
      sunGlow.scale.set(s, s, s);

      if (!isGrabbed(rainCloud)) {
        rainCloud.position.y = baseRainY + Math.sin(time * 1.4 + 1.0) * 0.008;
      }
      for (let i = 0; i < drops.length; i++) {
        const m = drops[i];
        m.position.y -= dropSpeed[i] * d;
        if (m.position.y < 0.05) m.position.y = 0.15;
      }

      if (!isGrabbed(snowCloud)) {
        snowCloud.position.y = baseSnowY + Math.sin(time * 1.1 + 2.0) * 0.008;
      }
      for (let i = 0; i < flakes.length; i++) {
        const f = flakes[i];
        f.position.y -= 0.045 * d;
        f.position.x = flakeBaseX[i] + Math.sin(time * 2 + i * 1.1) * 0.008;
        if (f.position.y < 0.05) f.position.y = 0.15;
      }

      const pulse = 1 + Math.sin(time * 3) * 0.03;
      const r = rings[selected];
      if (r) r.scale.set(pulse, pulse, 1);
    }
  };
}

