      .temp { color: #ffcf4d; font-size: 30px; font-weight: 700; text-align: center; }
      .cond { color: #d7dbe2; font-size: 20px; text-align: center; }
      .detail { color: #e8ecf2; font-size: 21px; text-align: center; }
      .unitbtn { display: flex; flex-direction: row; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px; border-radius: 12px; background-color: #2f6fdb; }
      .unittext { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Weather Dashboard</span>
      <span class="sub">Grab a 3D icon or tap a city to select</span>
      <div class="cities">
        <button class="cityA" id="city0"><span class="icon" id="icon0">\u2600</span><span class="cname">Phoenix</span><span class="temp" id="temp0">36\u00B0C</span><span class="cond">Sunny</span></button>
        <button class="city" id="city1"><span class="iconB" id="icon1">\u2602</span><span class="cname">London</span><span class="temp" id="temp1">12\u00B0C</span><span class="cond">Rainy</span></button>
        <button class="city" id="city2"><span class="iconC" id="icon2">\u2601</span><span class="cname">Tokyo</span><span class="temp" id="temp2">21\u00B0C</span><span class="cond">Cloudy</span></button>
      </div>
      <span class="detail" id="detail">Phoenix: Sunny, 36\u00B0C \u2014 hot and clear</span>
      <button class="unitbtn" id="unit"><span class="unittext" id="unitLabel">Show \u00B0F</span></button>
    </div>`, { width: 0.46, position: [0, 0.325, -0.16], rotationY: 0 });
  root.add(panel.object3D);

  const details = [
    'Phoenix: Sunny, hot and clear \u2014 stay hydrated',
    'London: Rainy, cool and wet \u2014 grab an umbrella',
    'Tokyo: Cloudy, mild and overcast \u2014 soft light'
  ];

  function refresh() {
    for (let i = 0; i < 3; i++) {
      panel.set('temp' + i, { text: tempText(cities[i].c) });
      if (i === selected) {
        panel.set('city' + i, { backgroundColor: '#33405a' });
      } else {
        panel.set('city' + i, { backgroundColor: '#2a2e35' });
      }
    }
    const d = cities[selected];
    panel.set('detail', { text: `${d.name}: ${d.cond}, ${tempText(d.c)} \u2014 ${details[selected].split('\u2014')[1]}` });
    panel.set('unitLabel', { text: useC ? 'Show \u00B0F' : 'Show \u00B0C' });
    const targets = [sunGroup.position, rainGroup.position, cloudGroup.position];
    ring.position.set(targets[selected].x, 0.048, targets[selected].z);
  }

  function select(i) {
    selected = i;
    refresh();
  }

  panel.on('city0', 'click', () => select(0));
  panel.on('city1', 'click', () => select(1));
  panel.on('city2', 'click', () => select(2));
  panel.on('unit', 'click', () => { useC = !useC; refresh(); });

  traits(sunGroup, { grab: true, onPress: () => select(0) });
  traits(rainGroup, { grab: true, onPress: () => select(1) });
  traits(cloudGroup, { grab: true, onPress: () => select(2) });

  refresh();

  const dropTop = 0.012;
  const dropRange = 0.045;
  return {
    root,
    update(time) {
      if (!isGrabbed(sunGroup)) {
        raysGroup.rotation.z = time * 0.35;
        const s = 1 + Math.sin(time * 2.2) * 0.04;
        sunCore.scale.set(s, s, s);
      }
      if (!isGrabbed(cloudGroup)) {
        puffs.position.y = 0.04 + Math.sin(time * 1.3) * 0.005;
      }
      if (!isGrabbed(rainGroup)) {
        for (let i = 0; i < 3; i++) {
          const off = (time * 0.038 + i * 0.016) % dropRange;
          rainDrops[i].position.y = dropTop - off;
        }
      }
      const rp = 1 + Math.sin(time * 3) * 0.06;
      ring.scale.set(rp, rp, 1);
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const CENTER = new THREE.Vector3(0, 0.19, -0.05);
  const UP = new THREE.Vector3(0, 1, 0);
  const SQ = Math.SQRT1_2;
  const D_A = new THREE.Vector3(-SQ, 0, SQ);
  const D_B = new THREE.Vector3(SQ, 0, SQ);
  const N_A = new THREE.Vector3(SQ, 0, SQ);
  const N_B = new THREE.Vector3(-SQ, 0, SQ);
  const a_A = Math.atan2(-D_A.z, D_A.x);
  const a_B = Math.atan2(-D_B.z, D_B.x);
  const phiStart = Math.PI * 0.75;
  const phiLength = Math.PI * 1.5;

  const defs = [
    { name: 'Crust', outer: 0.11, inner: 0.102, color: 0x8d6e63, css: '#8d6e63', depth: '0-70 km', sub: '0-70 km' },
    { name: 'Upper Mantle', outer: 0.102, inner: 0.082, color: 0xffb74d, css: '#ffb74d', depth: '10-660 km', sub: 'to 660 km' },
    { name: 'Lower Mantle', outer: 0.082, inner: 0.062, color: 0xef6c00, css: '#ef6c00', depth: '660-2890 km', sub: '660-2890 km' },
    { name: 'Outer Core', outer: 0.062, inner: 0.033, color: 0xffd54f, css: '#ffd54f', depth: '2890-5150 km', sub: '2890-5150 km' },
    { name: 'Inner Core', outer: 0.033, inner: 0.0, color: 0xe53935, css: '#e53935', depth: '5150-6371 km', sub: '5150-6371 km' }
  ];

  const infos = [
    'CRUST - 0-70 km, under 400C - Solid basalt and granite. Thinnest layer. Oceanic 5-10 km, continental up to 70 km. You live on it.',
    'UPPER MANTLE - 10-660 km, to 900C - Solid peridotite with soft asthenosphere. Flows slowly and drags tectonic plates.',
    'LOWER MANTLE - 660-2890 km, about 2000C - Solid hot rock under huge pressure. Largest part of Earth by volume.',
    'OUTER CORE - 2890-5150 km, 4000-5000C - Liquid iron-nickel. Its flowing metal makes Earth magnetic field.',
    'INNER CORE - 5150-6371 km, about 5500C - Solid iron-nickel, Moon-sized. Solid despite heat, squeezed by pressure.'
  ];
  const defaultTitle = 'Cut-away - quarter removed';
  const defaultFact = 'Pinch any layer to lift it. Tap a layer or a label for facts. Crust thickness enlarged - not to scale.';

  const mats = [];
  for (let i = 0; i < 5; i++) {
    const isInner = i === 4;
    const isOuter = i === 3;
    const m = new THREE.MeshStandardMaterial({
      color: defs[i].color,
      roughness: isInner ? 0.35 : 0.75,
      metalness: isInner ? 0.55 : (isOuter ? 0.35 : 0.05),
      side: THREE.DoubleSide
    });
    m.emissive.setHex(defs[i].color);
    m.emissiveIntensity = isInner ? 0.35 : 0;
    mats.push(m);
  }
  const baseInt = [0, 0, 0, 0, 0.35];
  const selInt = [0.55, 0.55, 0.55, 0.55, 0.9];

  const layerGroups = [];
  const thetaDeg = [50, 25, 0, -25, -50];
  const anchorLocals = [];
  const epsList = [];

  for (let i = 0; i < 5; i++) {
    const g = new THREE.Group();
    g.position.copy(CENTER);
    g.name = defs[i].name + '-group';
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(defs[i].outer, 32, 16, phiStart, phiLength),
      mats[i]
    );
    sphere.name = defs[i].name;
    g.add(sphere);
    const eps = i * 0.0012;
    epsList.push(eps);
    const capGeo = new THREE.CircleGeometry(defs[i].outer, 28, -Math.PI / 2, Math.PI);
    const capA = new THREE.Mesh(capGeo, mats[i]);
    capA.name = defs[i].name + '-cutA';
    capA.rotation.y = a_A;
    capA.position.copy(N_A).multiplyScalar(eps);
    g.add(capA);
    const capB = new THREE.Mesh(capGeo, mats[i]);
    capB.name = defs[i].name + '-cutB';
    capB.rotation.y = a_B;
    capB.position.copy(N_B).multiplyScalar(eps);
    g.add(capB);
    root.add(g);
    layerGroups.push(g);

    const rmid = i === 4 ? defs[i].outer * 0.5 : (defs[i].outer + defs[i].inner) * 0.5;
    const th = thetaDeg[i] * Math.PI / 180;
    const anch = new THREE.Vector3().copy(D_B).multiplyScalar(rmid * Math.cos(th))
      .addScaledVector(UP, rmid * Math.sin(th))
      .addScaledVector(N_B, eps + 0.0015);
    anchorLocals.push(anch);
  }

  // stand
  const standMat = new THREE.MeshStandardMaterial({ color: 0x3a3f47, roughness: 0.8, metalness: 0.1 });
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.11, 0.02, 32), standMat);
  base.position.set(CENTER.x, 0.01, CENTER.z);
  base.name = 'StandBase';
  root.add(base);
  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.014, 0.014, 0.06, 16), standMat);
  post.position.set(CENTER.x, 0.05, CENTER.z);
  post.name = 'StandPost';
  root.add(post);

  // magnetic field rings (scenery)
  const magMat = new THREE.MeshBasicMaterial({ color: 0x64b5f6, transparent: true, opacity: 0.32 });
  const mag1 = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.0014, 8, 64), magMat);
  mag1.position.copy(CENTER);
  mag1.rotation.x = 0.45;
  mag1.name = 'MagField1';
  root.add(mag1);
  const mag2 = new THREE.Mesh(new THREE.TorusGeometry(0.185, 0.0012, 8, 64), magMat);
  mag2.position.copy(CENTER);
  mag2.rotation.x = -0.35;
  mag2.rotation.y = 0.6;
  mag2.name = 'MagField2';
  root.add(mag2);

  // leader lines
  const lineMat = new THREE.LineBasicMaterial({ color: 0x9aa0aa, transparent: true, opacity: 0.75 });
  const labelY = [0.32, 0.26, 0.20, 0.14, 0.08];
  const labelX = 0.22;
  const labelZ = 0.07;
  const lineGeos = [];
  const lineArrs = [];
  const labelEdges = [];
  for (let i = 0; i < 5; i++) {
    const edge = new THREE.Vector3(labelX - 0.08, labelY[i], labelZ);
    labelEdges.push(edge);
    const start = new THREE.Vector3().copy(anchorLocals[i]).add(CENTER);
    const arr = new Float32Array(6);
    arr[0] = start.x; arr[1] = start.y; arr[2] = start.z;
    arr[3] = edge.x; arr[4] = edge.y; arr[5] = edge.z;
    const bg = new THREE.BufferGeometry();
    bg.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    const line = new THREE.Line(bg, lineMat);
    line.name = 'Leader-' + defs[i].name;
    root.add(line);
    lineGeos.push(bg);
    lineArrs.push(arr);
  }
  const tmpV = new THREE.Vector3();

  // main panel
  const main = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: left; }
      .subtitle { color: #aeb4bf; font-size: 20px; text-align: left; }
      .fact { color: #d7dbe2; font-size: 22px; text-align: left; }
      .row { display: flex; flex-direction: row; gap: 10px; align-items: center; justify-content: flex-start; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #3a3f47; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Layers of the Earth</span>
      <span class="subtitle" id="ltitle">Cut-away - quarter removed</span>
      <span class="fact" id="fact">Pinch any layer to lift it. Tap a layer or a label for facts. Crust thickness enlarged - not to scale.</span>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next layer</span></button>
        <button class="btn2" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.28, position: [-0.24, 0.27, 0.10], rotationY: 0.4 });
  root.add(main.object3D);

  // small labels, one per layer
  const labelHandles = [];
  for (let i = 0; i < 5; i++) {
    const h = ui(`
      <style>
        .tag { display: flex; flex-direction: row; gap: 10px; align-items: center; justify-content: flex-start; padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 14px; background-color: #2a2e35; }
        .dot { width: 20px; height: 20px; border-radius: 10px; background-color: ${defs[i].css}; }
        .name { color: #ffffff; font-size: 24px; font-weight: 700; text-align: left; }
        .sub { color: #d7dbe2; font-size: 20px; text-align: left; }
      </style>
      <button class="tag" id="pick"><span class="dot"></span><span class="name">${defs[i].name}</span><span class="sub">${defs[i].sub}</span></button>
    `, { width: 0.16, position: [labelX, labelY[i], labelZ], rotationY: -0.15 });
    root.add(h.object3D);
    labelHandles.push(h);
  }

  let selected = -1;
  function select(idx) {
    selected = idx;
    for (let j = 0; j < 5; j++) {
      if (j === idx) mats[j].emissiveIntensity = selInt[j];
      else mats[j].emissiveIntensity = baseInt[j];
    }
    if (idx >= 0 && idx < 5) {
      main.set('ltitle', { text: defs[idx].name + ' - ' + defs[idx].depth });
      main.set('fact', { text: infos[idx] });
    } else {
      main.set('ltitle', { text: defaultTitle });
      main.set('fact', { text: defaultFact });
    }
    for (let k = 0; k < 5; k++) {
      labelHandles[k].set('pick', { backgroundColor: k === idx ? '#3a6ff7' : '#2a2e35' });
    }
  }

  function resetModel() {
    for (let i = 0; i < 5; i++) {
      layerGroups[i].position.copy(CENTER);
      layerGroups[i].quaternion.identity();
    }
    select(-1);
  }

  main.on('next', 'click', () => {
    const n = selected < 0 ? 0 : (selected + 1) % 5;
    select(n);
  });
  main.on('reset', 'click', () => resetModel());
  for (let i = 0; i < 5; i++) {
    const idx = i;
    labelHandles[idx].on('pick', 'click', () => select(idx));
  }
  for (let i = 0; i < 5; i++) {
    const idx = i;
    traits(layerGroups[idx], { grab: true, onPress: () => select(idx) });
  }

  return {
    root,
    update(time, delta) {
      const b = (selected === 4 ? 0.85 : 0.35) + Math.sin(time * 2.2) * 0.12;
      mats[4].emissiveIntensity = b;
      mag1.rotation.y += delta * 0.25;
      mag2.rotation.y -= delta * 0.18;
      for (let i = 0; i < 5; i++) {
        const g = layerGroups[i];
        tmpV.copy(anchorLocals[i]);
        tmpV.applyQuaternion(g.quaternion);
        tmpV.add(g.position);
        const arr = lineArrs[i];
        arr[0] = tmpV.x; arr[1] = tmpV.y; arr[2] = tmpV.z;
        lineGeos[i].attributes.position.needsUpdate = true;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const UP = new THREE.Vector3(0, 1, 0);

  // ---------- materials ----------
  const potMat = new THREE.MeshStandardMaterial({ color: 0xb5653a, roughness: 0.8 });
  const soilMat = new THREE.MeshStandardMaterial({ color: 0x4a3525, roughness: 1 });
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x3ca34a, roughness: 0.7 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x2fbf5a, roughness: 0.6, emissive: 0x1a7a33, emissiveIntensity: 0.06 });
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffd54d, emissive: 0xff8a00, emissiveIntensity: 1.1, roughness: 0.4 });
  const glowMat = new THREE.MeshBasicMaterial({ color: 0xffe082, transparent: true, opacity: 0.22 });
  const waterMat = new THREE.MeshStandardMaterial({ color: 0x2fa9ff, roughness: 0.2 });
  const co2Mat = new THREE.MeshStandardMaterial({ color: 0xc2c7cf, roughness: 0.9 });
  const glucoseMat = new THREE.MeshStandardMaterial({ color: 0xd8f76a, emissive: 0x7aa600, emissiveIntensity: 0.7, roughness: 0.4 });
  const lightArrowMat = new THREE.MeshBasicMaterial({ color: 0xffd93b });
  const waterArrowMat = new THREE.MeshBasicMaterial({ color: 0x3fb7ff });
  const co2ArrowMat = new THREE.MeshBasicMaterial({ color: 0xd6dae0 });
  const o2ArrowMat = new THREE.MeshBasicMaterial({ color: 0x6cf2b2 });

  function staticArrow(parent, from, to, mat, r) {
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = Math.max(0.05, dir.length());
    dir.normalize();
    const g = new THREE.Group();
    g.position.copy(from);
    g.quaternion.setFromUnitVectors(UP, dir);
    const headLen = 0.032;
    const shaftLen = Math.max(0.015, len - headLen);
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1, 10), mat);
    shaft.scale.y = shaftLen;
    shaft.position.set(0, shaftLen / 2, 0);
    const head = new THREE.Mesh(new THREE.ConeGeometry(r * 2.4, headLen, 14), mat);
    head.position.set(0, shaftLen + headLen / 2, 0);
    g.add(shaft); g.add(head);
    parent.add(g);
    return { group: g, from: from.clone(), to: to.clone() };
  }

  // ---------- plant (grabbable whole) ----------
  const plantGroup = new THREE.Group();
  plantGroup.position.set(0, 0, -0.03);
  root.add(plantGroup);

  const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.04, 0.07, 20), potMat);
  pot.position.set(0, 0.035, 0); pot.name = 'Pot';
  plantGroup.add(pot);
  const soil = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.016, 20), soilMat);
  soil.position.set(0, 0.07, 0); soil.name = 'Soil';
  plantGroup.add(soil);
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.007, 0.01, 0.18, 12), stemMat);
  stem.position.set(0, 0.16, 0); stem.name = 'Stem';
  plantGroup.add(stem);

  const leafGeo = new THREE.SphereGeometry(0.035, 20, 12);
  const leafPos = [
    [-0.038, 0.15, 0.01, 0.6], [0.038, 0.17, -0.01, -0.6],
    [-0.032, 0.20, 0.012, 0.55], [0.032, 0.225, -0.008, -0.55]
  ];
  const leaves = [];
  for (let i = 0; i < leafPos.length; i++) {
    const m = new THREE.Mesh(leafGeo, leafMat);
    m.name = 'Leaf';
    m.position.set(leafPos[i][0], leafPos[i][1], leafPos[i][2]);
    m.scale.set(1.25, 0.28, 0.7);
    m.rotation.z = leafPos[i][3];
    m.rotation.y = i * 0.4;
    plantGroup.add(m); leaves.push(m);
  }
  const bud = new THREE.Mesh(new THREE.SphereGeometry(0.016, 16, 10), leafMat);
  bud.position.set(0, 0.262, 0); bud.name = 'LeafBud';
  plantGroup.add(bud);

  const glucose = new THREE.Mesh(new THREE.IcosahedronGeometry(0.018, 0), glucoseMat);
  glucose.name = 'Glucose';
  glucose.position.set(0, 0.205, 0.045);
  glucose.scale.set(0.0001, 0.0001, 0.0001);
  plantGroup.add(glucose);

  // arrows inside plant (move with plant when grabbed)
  const waterArrow = staticArrow(plantGroup, new THREE.Vector3(-0.075, 0.015, 0.045), new THREE.Vector3(-0.012, 0.095, 0.01), waterArrowMat, 0.007);
  const co2Arrow = staticArrow(plantGroup, new THREE.Vector3(0.135, 0.175, 0.025), new THREE.Vector3(0.04, 0.19, 0.01), co2ArrowMat, 0.007);
  const o2Arrow = staticArrow(plantGroup, new THREE.Vector3(0.03, 0.255, 0.012), new THREE.Vector3(0.115, 0.335, 0.025), o2ArrowMat, 0.007);

  const waterFlow = new THREE.Mesh(new THREE.SphereGeometry(0.01, 12, 8), new THREE.MeshBasicMaterial({ color: 0x5cc8ff }));
  waterFlow.name = 'Water'; plantGroup.add(waterFlow);
  const co2FlowA = new THREE.Mesh(new THREE.SphereGeometry(0.009, 12, 8), new THREE.MeshBasicMaterial({ color: 0xffffff }));
  co2FlowA.name = 'CarbonDioxide'; plantGroup.add(co2FlowA);
  const co2FlowB = new THREE.Mesh(new THREE.SphereGeometry(0.007, 12, 8), new THREE.MeshBasicMaterial({ color: 0xffffff }));
  plantGroup.add(co2FlowB);
  const o2a = new THREE.Mesh(new THREE.SphereGeometry(0.009, 12, 8), new THREE.MeshBasicMaterial({ color: 0x8fffc8 }));
  o2a.name = 'Oxygen'; plantGroup.add(o2a);
  const o2b = new THREE.Mesh(new THREE.SphereGeometry(0.007, 12, 8), new THREE.MeshBasicMaterial({ color: 0x8fffc8 }));
  plantGroup.add(o2b);
  const o2c = new THREE.Mesh(new THREE.SphereGeometry(0.006, 12, 8), new THREE.MeshBasicMaterial({ color: 0x8fffc8 }));
  plantGroup.add(o2c);
  const o2Base = new THREE.Vector3(0.04, 0.26, 0.015);

  // ---------- sun (grabbable) ----------
  const sunGroup = new THREE.Group();
  sunGroup.position.set(-0.27, 0.38, -0.12);
  root.add(sunGroup);
  const sunCore = new THREE.Mesh(new THREE.SphereGeometry(0.045, 28, 16), sunMat);
  sunCore.name = 'Sun'; sunGroup.add(sunCore);
  const sunGlow = new THREE.Mesh(new THREE.SphereGeometry(0.062, 20, 12), glowMat);
  sunGlow.name = 'SunGlow'; sunGroup.add(sunGlow);

  // dynamic light beam in root space (sun -> leaf)
  const beamGroup = new THREE.Group();
  root.add(beamGroup);
  const beamShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 1, 10), lightArrowMat);
  beamShaft.name = 'Light';
  const beamHead = new THREE.Mesh(new THREE.ConeGeometry(0.019, 0.04, 14), lightArrowMat);
  beamGroup.add(beamShaft); beamGroup.add(beamHead);
  const lightFlow1 = new THREE.Mesh(new THREE.SphereGeometry(0.011, 12, 8), new THREE.MeshBasicMaterial({ color: 0xfff6c0 }));
  root.add(lightFlow1);
  const lightFlow2 = new THREE.Mesh(new THREE.SphereGeometry(0.009, 12, 8), new THREE.MeshBasicMaterial({ color: 0xfff6c0 }));
  root.add(lightFlow2);

  // ---------- water token (grabbable) ----------
  const waterToken = new THREE.Group();
  waterToken.position.set(-0.20, 0.045, 0.14);
  root.add(waterToken);
  const dropBody = new THREE.Mesh(new THREE.SphereGeometry(0.025, 20, 14), waterMat);
  dropBody.name = 'Water'; dropBody.scale.set(1, 1.15, 1);
  waterToken.add(dropBody);
  const dropTip = new THREE.Mesh(new THREE.ConeGeometry(0.017, 0.028, 16), waterMat);
  dropTip.position.set(0, 0.036, 0); dropTip.name = 'Water';
  waterToken.add(dropTip);
  const puddle = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.006, 20), waterMat);
  puddle.position.set(0, -0.032, 0);
  waterToken.add(puddle);

  // ---------- CO2 token (grabbable cloud) ----------
  const co2Token = new THREE.Group();
  co2Token.position.set(0.20, 0.13, 0.12);
  root.add(co2Token);
  const puffGeo = new THREE.SphereGeometry(0.022, 16, 10);
  const p1 = new THREE.Mesh(puffGeo, co2Mat); p1.name = 'CarbonDioxide'; co2Token.add(p1);
  const p2 = new THREE.Mesh(puffGeo, co2Mat); p2.position.set(0.032, 0.008, 0.005); p2.scale.set(0.8, 0.8, 0.8); p2.name = 'CarbonDioxide'; co2Token.add(p2);
  const p3 = new THREE.Mesh(puffGeo, co2Mat); p3.position.set(-0.03, 0.01, -0.004); p3.scale.set(0.7, 0.7, 0.7); co2Token.add(p3);

  // ---------- state + main panel ----------
  const state = { light: true, water: false, co2: false };
  let glucoseTarget = 0.0001;

  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; width: 500px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .eq { color: #ffe082; font-size: 20px; text-align: center; }
      .status { color: #8ef0b2; font-size: 22px; font-weight: 700; text-align: center; }
      .hint { color: #d7dbe2; font-size: 20px; text-align: center; }
      .fact { color: #cdd5e0; font-size: 19px; text-align: center; }
      .row { flex-direction: row; gap: 10px; justify-content: center; align-items: center; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="eq">6CO2 + 6H2O + light = sugar + 6O2</span>
      <span class="status" id="status">Add water + CO2</span>
      <span class="hint">Pinch the blue drop + grey cloud to the plant, or tap buttons. Pinch plant + Sun to move them.</span>
      <div class="row">
        <button class="btn" id="btnLight"><span class="btn-text" id="tLight">Light ON</span></button>
        <button class="btn" id="btnWater"><span class="btn-text" id="tWater">Water OFF</span></button>
        <button class="btn" id="btnCo2"><span class="btn-text" id="tCo2">CO2 OFF</span></button>
      </div>
      <button class="btn" id="btnFact"><span class="btn-text">Next fact</span></button>
      <span class="fact" id="fact">Leaves use green chlorophyll to catch light.</span>
    </div>`, { width: 0.30, position: [0.23, 0.22, 0.12], rotationY: -0.35 });
  root.add(info.object3D);

  function mkLabel(text, color, pos) {
    const h = ui(`
      <style>
        .pill { flex-direction: column; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #1f2228; width: 280px; }
        .txt { color: ${color}; font-size: 22px; font-weight: 700; text-align: center; }
      </style>
      <div class="pill"><span class="txt">${text}</span></div>`, { width: 0.14, position: pos, rotationY: 0 });
    root.add(h.object3D);
    return h;
  }
  mkLabel('Light energy', '#ffd93b', [-0.14, 0.325, 0.0]);
  mkLabel('Water to roots', '#5cc8ff', [-0.11, 0.055, 0.12]);
  mkLabel('CO2 in', '#d6dae0', [0.165, 0.20, 0.08]);
  mkLabel('O2 out', '#6cf2b2', [0.165, 0.345, 0.06]);

  const facts = [
    'Leaves use green chlorophyll to catch light.',
    'Roots absorb water. Tiny leaf holes (stomata) let CO2 in.',
    'The plant keeps sugar as food and releases oxygen for us.',
    'Try it: turn all three ON and watch sugar + oxygen appear!'
  ];
  let factIdx = 0;

  function refresh() {
    const done = state.light && state.water && state.co2;
    waterArrow.group.visible = state.water;
    waterFlow.visible = state.water;
    co2Arrow.group.visible = state.co2;
    co2FlowA.visible = state.co2; co2FlowB.visible = state.co2;
    beamGroup.visible = state.light;
    lightFlow1.visible = state.light; lightFlow2.visible = state.light;
    o2Arrow.group.visible = done;
    o2a.visible = done; o2b.visible = done; o2c.visible = done;
    glucoseTarget = done ? 1 : 0.0001;
    let sTxt = 'GO! Making sugar + O2';
    let sCol = '#8ef0b2';
    if (!state.light) { sTxt = 'Needs light - tap the Sun'; sCol = '#ffd93b'; }
    else if (!state.water && !state.co2) { sTxt = 'Add water + CO2'; sCol = '#ffb3b3'; }
    else if (!state.water) { sTxt = 'Add water'; sCol = '#7cc4ff'; }
    else if (!state.co2) { sTxt = 'Add CO2'; sCol = '#d6dae0'; }
    info.set('status', { text: sTxt, color: sCol });
    info.set('tLight', { text: state.light ? 'Light ON' : 'Light OFF' });
    info.set('btnLight', { backgroundColor: state.light ? '#2e9e52' : '#3a4048' });
    info.set('tWater', { text: state.water ? 'Water ON' : 'Water OFF' });
    info.set('btnWater', { backgroundColor: state.water ? '#2e9e52' : '#3a4048' });
    info.set('tCo2', { text: state.co2 ? 'CO2 ON' : 'CO2 OFF' });
    info.set('btnCo2', { backgroundColor: state.co2 ? '#2e9e52' : '#3a4048' });
  }
  function nextFact() {
    factIdx = (factIdx + 1) % facts.length;
    info.set('fact', { text: facts[factIdx] });
  }
  info.on('btnLight', 'click', () => { state.light = !state.light; refresh(); });
  info.on('btnWater', 'click', () => { state.water = !state.water; refresh(); });
  info.on('btnCo2', 'click', () => { state.co2 = !state.co2; refresh(); });
  info.on('btnFact', 'click', nextFact);

  traits(plantGroup, { grab: true, onPress: nextFact });
  traits(sunGroup, { grab: true, onPress: () => { state.light = !state.light; refresh(); } });
  traits(waterToken, { grab: true, onPress: () => { state.water = !state.water; refresh(); } });
  traits(co2Token, { grab: true, onPress: () => { state.co2 = !state.co2; refresh(); } });

  refresh();

  // ---------- per-frame temps (no allocation in update) ----------
  const tmpFrom = new THREE.Vector3();
  const tmpTo = new THREE.Vector3();
  const tmpDir = new THREE.Vector3();
  const leafLocal = new THREE.Vector3(0, 0.21, 0);
  const wFrom = waterArrow.from, wTo = waterArrow.to;
  const cFrom = co2Arrow.from, cTo = co2Arrow.to;

  return {
    root,
    update(time, delta) {
      // light beam follows sun + plant (both grabbable)
      tmpFrom.copy(sunGroup.position);
      tmpTo.copy(leafLocal).applyQuaternion(plantGroup.quaternion).add(plantGroup.position);
      tmpDir.copy(tmpTo).sub(tmpFrom);
      const fullLen = Math.max(0.08, tmpDir.length());
      tmpDir.normalize();
      beamGroup.position.copy(tmpFrom).addScaledVector(tmpDir, 0.055);
      beamGroup.quaternion.setFromUnitVectors(UP, tmpDir);
      const eff = Math.max(0.06, fullLen - 0.075);
      const headL = 0.04;
      const shaftL = Math.max(0.02, eff - headL);
      beamShaft.scale.set(1, shaftL, 1);
      beamShaft.position.set(0, shaftL / 2, 0);
      beamHead.position.set(0, shaftL + headL / 2, 0);
      if (state.light) {
        const t1 = (time * 0.45) % 1;
        const t2 = (time * 0.45 + 0.5) % 1;
        lightFlow1.position.copy(beamGroup.position).addScaledVector(tmpDir, t1 * eff);
        lightFlow2.position.copy(beamGroup.position).addScaledVector(tmpDir, t2 * eff);
        const s = 1 + Math.sin(time * 4) * 0.06;
        sunGlow.scale.set(s, s, s);
      }
      if (state.water) {
        const t = (time * 0.9) % 1;
        waterFlow.position.lerpVectors(wFrom, wTo, t);
      }
      if (state.co2) {
        const tA = (time * 0.7) % 1;
        const tB = (time * 0.7 + 0.5) % 1;
        co2FlowA.position.lerpVectors(cFrom, cTo, tA);
        co2FlowB.position.lerpVectors(cFrom, cTo, tB);
      }
      const done = state.light && state.water && state.co2;
      if (done) {
        const b1 = (time * 0.5) % 1, b2 = (time * 0.5 + 0.33) % 1, b3 = (time * 0.5 + 0.66) % 1;
        o2a.position.set(o2Base.x + Math.sin(time * 2.0) * 0.008, o2Base.y + b1 * 0.12, o2Base.z);
        o2b.position.set(o2Base.x + Math.sin(time * 2.0 + 2.1) * 0.01, o2Base.y + b2 * 0.12, o2Base.z);
        o2c.position.set(o2Base.x + Math.sin(time * 2.0 + 4.2) * 0.01, o2Base.y + b3 * 0.12, o2Base.z);
        leafMat.emissiveIntensity = 0.35 + Math.sin(time * 3) * 0.12;
      } else {
        leafMat.emissiveIntensity = 0.06;
      }
      // glucose grows when complete
      const gs = glucose.scale.x + (glucoseTarget - glucose.scale.x) * Math.min(1, delta * 3);
      glucose.scale.set(gs, gs, gs);
      glucose.rotation.y += delta * (done ? 1.2 : 0.2);

      // grab-to-feed: bring tokens close to plant
      if (!state.water) {
        const dx = waterToken.position.x - plantGroup.position.x;
        const dy = waterToken.position.y - (plantGroup.position.y + 0.08);
        const dz = waterToken.position.z - plantGroup.position.z;
        if (dx * dx + dy * dy + dz * dz < 0.0144) { state.water = true; refresh(); }
      }
      if (!state.co2) {
        const dx = co2Token.position.x - plantGroup.position.x;
        const dy = co2Token.position.y - (plantGroup.position.y + 0.15);
        const dz = co2Token.position.z - plantGroup.position.z;
        if (dx * dx + dy * dy + dz * dz < 0.0144) { state.co2 = true; refresh(); }
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
