  const coffeeMat = new THREE.MeshStandardMaterial({ color: 0x3b2314, roughness: 0.25 });

  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.042, 0.036, 0.095, 32), bodyMat);
  body.position.set(0, 0.0475, 0);
  body.name = 'Coffee Mug';
  mugGroup.add(body);

  const rim = new THREE.Mesh(new THREE.TorusGeometry(0.0395, 0.0035, 12, 32), bodyMat);
  rim.rotation.x = Math.PI / 2;
  rim.position.set(0, 0.095, 0);
  mugGroup.add(rim);

  const coffee = new THREE.Mesh(new THREE.CircleGeometry(0.036, 32), coffeeMat);
  coffee.rotation.x = -Math.PI / 2;
  coffee.position.set(0, 0.082, 0);
  coffee.name = 'Coffee';
  mugGroup.add(coffee);

  const handle = new THREE.Mesh(new THREE.TorusGeometry(0.024, 0.0075, 12, 24, Math.PI), bodyMat);
  handle.rotation.z = -Math.PI / 2;
  handle.position.set(0.038, 0.05, 0);
  mugGroup.add(handle);

  // Steam puffs (children of mug so they follow when carried, rise slowly)
  const steamMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.28 });
  const steamGeo = new THREE.SphereGeometry(0.009, 12, 8);
  const steam = [];
  const steamOffsets = [0, 0.027, 0.053];
  const steamX = [0, 0.012, -0.01];
  const steamZ = [0, 0.005, -0.006];
  for (let i = 0; i < 3; i++) {
    const s = new THREE.Mesh(steamGeo, steamMat);
    s.position.set(steamX[i], 0.11, steamZ[i]);
    s.scale.setScalar(0.7 + i * 0.2);
    mugGroup.add(s);
    steam.push(s);
  }

  traits(mugGroup, { grab: true });

  const card = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .price { color: #ffcf7a; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .hint { color: #9fb0c3; font-size: 20px; }
      .row { flex-direction: row; gap: 10px; align-items: center; justify-content: flex-start; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #3a3f48; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Cloud Mug — 350 ml</span>
      <span class="price" id="price">$18.00</span>
      <span class="body" id="mat">Glazed stoneware ceramic. Dishwasher + microwave safe.</span>
      <span class="hint" id="hint">Pinch the mug to pick it up.</span>
      <div class="row">
        <button class="btn" id="cream"><span class="btn-text">Cream</span></button>
        <button class="btn2" id="sage"><span class="btn-text">Sage</span></button>
        <button class="btn2" id="terra"><span class="btn-text">Terra</span></button>
      </div>
      <div class="row">
        <button class="btn2" id="fill"><span class="btn-text" id="fillLabel">Fill: Coffee</span></button>
      </div>
    </div>`, { width: 0.32, position: [0.16, 0.21, 0.03], rotationY: -0.3 });
  root.add(card.object3D);

  card.on('cream', 'click', () => {
    bodyMat.color.setHex(0xede6d6);
    card.set('hint', { text: 'Cream glaze — classic stoneware.' });
  });
  card.on('sage', 'click', () => {
    bodyMat.color.setHex(0xa8c3a0);
    card.set('hint', { text: 'Sage glaze — same stoneware, new color.' });
  });
  card.on('terra', 'click', () => {
    bodyMat.color.setHex(0xc96f4a);
    card.set('hint', { text: 'Terracotta glaze — same stoneware, new color.' });
  });

  let isCoffee = true;
  card.on('fill', 'click', () => {
    isCoffee = !isCoffee;
    if (isCoffee) {
      coffeeMat.color.setHex(0x3b2314);
      card.set('fillLabel', { text: 'Fill: Coffee' });
      card.set('hint', { text: 'Hot coffee — watch the steam.' });
    } else {
      coffeeMat.color.setHex(0x8fb573);
      card.set('fillLabel', { text: 'Fill: Herbal Tea' });
      card.set('hint', { text: 'Light herbal tea. Pinch mug to lift.' });
    }
  });

  let wasHeld = false;
  return {
    root,
    update(time) {
      // Slow steam rise, loops every ~2.6s (under 0.05 m/s)
      for (let i = 0; i < 3; i++) {
        const p = ((time * 0.03 + steamOffsets[i]) % 0.08);
        steam[i].position.y = 0.105 + p;
        steam[i].position.x = steamX[i] + Math.sin(time * 1.2 + i * 2.1) * 0.004;
        const sc = 0.6 + p * 8.0;
        steam[i].scale.setScalar(sc);
      }
      const held = isGrabbed(mugGroup);
      if (held && !wasHeld) {
        card.set('hint', { text: 'Nice — light + sturdy. Stoneware keeps heat.' });
      }
      if (!held && wasHeld) {
        card.set('hint', { text: 'Set it back on the saucer. Try a glaze.' });
      }
      wasHeld = held;
    }
  };
}

