    info.set('glazeName', { text: 'Sage glaze - dishwasher safe' });
  });
  info.on('glazeClay', 'click', () => {
    bodyMat.color.setHex(0xc47a56);
    info.set('glazeName', { text: 'Clay glaze - dishwasher safe' });
  });

  return {
    root,
    update(time) {
      // Steam rise loop (slow, under 0.05 m/s)
      for (let i = 0; i < 3; i++) {
        const m = steamMeshes[i];
        const mt = steamMats[i];
        const off = steamOff[i];
        const ph = (time * 0.22 + off) % 1;
        m.position.set(
          Math.sin(ph * 6.28 + off * 12.0) * 0.008,
          0.055 + ph * 0.09,
          Math.cos(ph * 6.28 + off * 9.0) * 0.006
        );
        const s = 0.7 + ph * 1.3;
        m.scale.set(s, s, s);
        mt.opacity = 0.36 * (1 - ph);
      }
      // Pulsing grab hint on desk, calms when held
      if (isGrabbed(mug)) {
        hintMat.opacity = 0.15;
        hintRing.scale.set(1, 1, 1);
      } else {
        const p = 1 + Math.sin(time * 2.0) * 0.05;
        hintRing.scale.set(p, p, p);
        hintMat.opacity = 0.45 + Math.sin(time * 2.0) * 0.12;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Quiz data ----------
  const baseQs = [
    { a: 3, b: 4 },
    { a: 6, b: 7 },
    { a: 8, b: 5 },
    { a: 9, b: 6 },
    { a: 7, b: 7 }
  ];

  function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const t = arr[i];
      arr[i] = arr[j];
      arr[j] = t;
    }
    return arr;
  }

  function makeOptions(a, b) {
    const correct = a * b;
    const set = [correct];
    // candidate offsets to make plausible wrong answers
    const pool = [1, -1, 2, -2, 3, -3, a, -a, b, -b, 10, -10, 5, -5, 4, -4];
    shuffle(pool);
    let pi = 0;
    let guard = 0;
    while (set.length < 4 && guard < 200) {
      guard++;
      let cand;
      if (pi < pool.length) {
        cand = correct + pool[pi++];
      } else {
        cand = correct + Math.floor(Math.random() * 21) - 10;
      }
      if (cand <= 0 || cand === correct) continue;
      let dup = false;
      for (let k = 0; k < set.length; k++) if (set[k] === cand) dup = true;
      if (!dup) set.push(cand);
    }
    return shuffle(set);
  }

  const quiz = baseQs.map(function (q) {
    return { a: q.a, b: q.b, correct: q.a * q.b, options: makeOptions(q.a, q.b) };
  });

  let qIndex = 0;
  let score = 0;
  let answered = false;
  let finished = false;
  const results = [null, null, null, null, null];

  // ---------- 3D scenery ----------
  const platformGeo = new THREE.BoxGeometry(0.34, 0.012, 0.24);
  const platformMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.9 });
  const platform = new THREE.Mesh(platformGeo, platformMat);
  platform.position.set(-0.16, 0.006, -0.02);
  platform.name = 'Platform';
  root.add(platform);

  const boardMat = new THREE.MeshStandardMaterial({ color: 0x1f2228, roughness: 0.85 });
  const boardGeo = new THREE.BoxGeometry(0.30, 0.24, 0.008);
  const board = new THREE.Mesh(boardGeo, boardMat);
  board.name = 'Board';
  board.position.set(-0.16, 0.19, -0.115);
  root.add(board);

  const dotsGeo = new THREE.SphereGeometry(0.011, 16, 10);
  const dotsMat = new THREE.MeshStandardMaterial({ color: 0x4da3ff, roughness: 0.4 });
  const MAXDOTS = 81;
  const dots = new THREE.InstancedMesh(dotsGeo, dotsMat, MAXDOTS);
  dots.name = 'ArrayDots';
  dots.position.set(-0.16, 0.19, -0.105);
  root.add(dots);

  const dummy = new THREE.Object3D();
  const SPACING = 0.028;

  function layoutDots(a, b) {
    const n = a * b;
    dots.count = n;
    let idx = 0;
    for (let r = 0; r < a; r++) {
      for (let c = 0; c < b; c++) {
        dummy.position.set(
          (c - (b - 1) / 2) * SPACING,
          ((a - 1) / 2 - r) * SPACING,
          0
        );
        dummy.rotation.set(0, 0, 0);
        dummy.scale.setScalar(1);
        dummy.updateMatrix();
        dots.setMatrixAt(idx, dummy.matrix);
        idx++;
      }
    }
    dots.instanceMatrix.needsUpdate = true;
  }

  // Score stars in 3D
  const starGeo = new THREE.OctahedronGeometry(0.016);
  const pendingMat = new THREE.MeshStandardMaterial({ color: 0x555b66, roughness: 0.7 });
  const earnedMat = new THREE.MeshStandardMaterial({ color: 0xffd84d, emissive: 0xffb400, emissiveIntensity: 0.9, roughness: 0.3 });
  const stars = [];
  for (let i = 0; i < 5; i++) {
    const s = new THREE.Mesh(starGeo, pendingMat);
    s.name = 'ScoreStar' + i;
    s.position.set(-0.28 + i * 0.06, 0.345, -0.08);
    root.add(s);
    stars.push(s);
  }
  function refreshStars() {
    for (let i = 0; i < 5; i++) {
      stars[i].material = results[i] === true ? earnedMat : pendingMat;
    }
  }

  // Grabbable lucky star
  const luckyGeo = new THREE.OctahedronGeometry(0.025);
  const luckyMat = new THREE.MeshStandardMaterial({ color: 0xffd84d, emissive: 0xff9d00, emissiveIntensity: 0.7, roughness: 0.3 });
  const luckyStar = new THREE.Mesh(luckyGeo, luckyMat);
  luckyStar.name = 'LuckyStar';
  const luckyBase = { x: 0.10, y: 0.075, z: 0.16 };
  luckyStar.position.set(luckyBase.x, luckyBase.y, luckyBase.z);
  root.add(luckyStar);

  const pedGeo = new THREE.CylinderGeometry(0.035, 0.04, 0.008, 24);
  const pedMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.9 });
  const pedestal = new THREE.Mesh(pedGeo, pedMat);
  pedestal.position.set(luckyBase.x, 0.004, luckyBase.z);
  root.add(pedestal);

  // ---------- UI panel ----------
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .prog { color: #aeb6c2; font-size: 20px; text-align: center; }
      .ques { color: #ffd84d; font-size: 48px; font-weight: 700; text-align: center; }
      .feed { color: #d7dbe2; font-size: 22px; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 10px; justify-content: center; align-items: center; }
      .ans { width: 210px; height: 68px; border-radius: 14px; background-color: #2f6fdb; display: flex; align-items: center; justify-content: center; padding-top: 8px; padding-bottom: 8px; padding-left: 8px; padding-right: 8px; }
      .anstxt { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
      .nav { display: flex; flex-direction: row; gap: 10px; justify-content: center; align-items: center; }
      .next { width: 210px; height: 56px; border-radius: 12px; background-color: #2e9e5b; display: flex; align-items: center; justify-content: center; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; }
      .nexttxt { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      .restart { width: 210px; height: 56px; border-radius: 12px; background-color: #3a3f47; display: flex; align-items: center; justify-content: center; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; }
      .restarttxt { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Multiplication Quiz</span>
      <span class="prog" id="prog">Question 1 of 5 - Score: 0</span>
      <span class="ques" id="ques">3 x 4 = ?</span>
      <span class="feed" id="feed">Pinch an answer! Grab the gold star for luck.</span>
      <div class="row" id="row0">
        <button class="ans" id="ans0"><span class="anstxt" id="ans0t">12</span></button>
        <button class="ans" id="ans1"><span class="anstxt" id="ans1t">11</span></button>
      </div>
      <div class="row" id="row1">
        <button class="ans" id="ans2"><span class="anstxt" id="ans2t">15</span></button>
        <button class="ans" id="ans3"><span class="anstxt" id="ans3t">16</span></button>
      </div>
      <div class="nav">
        <button class="next" id="nextBtn"><span class="nexttxt" id="nextTxt">Next</span></button>
        <button class="restart" id="restartBtn"><span class="restarttxt">Restart</span></button>
      </div>
    </div>
  `, { width: 0.36, position: [0.19, 0.21, 0.02], rotationY: -0.28 });
  root.add(panel.object3D);

  const BLUE = '#2f6fdb';
  const GREEN = '#2e9e5b';
  const RED = '#c0392b';
  const DIM = '#3a3f47';

  function renderQuestion() {
    const q = quiz[qIndex];
    panel.set('prog', { text: 'Question ' + (qIndex + 1) + ' of 5 - Score: ' + score });
    panel.set('ques', { text: q.a + ' x ' + q.b + ' = ?' });
    panel.set('feed', { text: 'See ' + q.a + ' rows of ' + q.b + ' dots. Pick an answer!', color: '#d7dbe2' });
    for (let i = 0; i < 4; i++) {
      panel.set('ans' + i + 't', { text: '' + q.options[i] });
      panel.set('ans' + i, { backgroundColor: BLUE });
    }
    panel.set('row0', { display: 'flex' });
    panel.set('row1', { display: 'flex' });
    panel.set('nextBtn', { display: 'none' });
    dotsMat.color.setHex(0x4da3ff);
    layoutDots(q.a, q.b);
  }

  function handleAnswer(i) {
    if (finished || answered) return;
    const q = quiz[qIndex];
    answered = true;
    const chosen = q.options[i];
    const isCorrect = chosen === q.correct;
    if (isCorrect) {
      score++;
      results[qIndex] = true;
      panel.set('feed', { text: 'Correct! ' + q.a + ' x ' + q.b + ' = ' + q.correct, color: '#7bf0a0' });
      dotsMat.color.setHex(0x2e9e5b);
    } else {
      results[qIndex] = false;
      panel.set('feed', { text: 'Not quite. You picked ' + chosen + '. Try Next!', color: '#ff9a8a' });
      dotsMat.color.setHex(0xc0392b);
    }
    // highlight buttons
    for (let k = 0; k < 4; k++) {
      if (q.options[k] === q.correct) {
        panel.set('ans' + k, { backgroundColor: GREEN });
      } else if (k === i && !isCorrect) {
        panel.set('ans' + k, { backgroundColor: RED });
      } else {
        panel.set('ans' + k, { backgroundColor: DIM });
      }
    }
    panel.set('prog', { text: 'Question ' + (qIndex + 1) + ' of 5 - Score: ' + score });
    panel.set('nextBtn', { display: 'flex' });
    panel.set('nextTxt', { text: qIndex === 4 ? 'See results' : 'Next' });
    refreshStars();
  }

  function handleNext() {
    if (finished) return;
    if (!answered) {
      panel.set('feed', { text: 'Pick an answer first!', color: '#ffd84d' });
      return;
    }
    qIndex++;
    if (qIndex >= 5) {
      finished = true;
      let msg = '';
      if (score === 5) msg = 'Perfect! You are a times-table star!';
      else if (score >= 4) msg = 'Great job! Almost perfect!';
      else if (score >= 3) msg = 'Good work! Keep practicing!';
      else msg = 'Nice try! Practice makes perfect!';
      panel.set('ques', { text: 'Done! ' + score + ' / 5' });
      panel.set('feed', { text: msg + ' Press Restart to play again.', color: '#ffd84d' });
      panel.set('prog', { text: 'Finished - Final score: ' + score });
      panel.set('row0', { display: 'none' });
      panel.set('row1', { display: 'none' });
      panel.set('nextBtn', { display: 'none' });
      luckyStar.scale.setScalar(score >= 3 ? 1.5 : 1.15);
      return;
    }
    answered = false;
    renderQuestion();
  }

  function handleRestart() {
    qIndex = 0;
    score = 0;
    answered = false;
    finished = false;
    for (let i = 0; i < 5; i++) results[i] = null;
    luckyStar.scale.setScalar(1);
    refreshStars();
    renderQuestion();
    panel.set('feed', { text: 'Fresh quiz! Pinch an answer!', color: '#d7dbe2' });
  }

  panel.on('ans0', 'click', function () { handleAnswer(0); });
  panel.on('ans1', 'click', function () { handleAnswer(1); });
  panel.on('ans2', 'click', function () { handleAnswer(2); });
  panel.on('ans3', 'click', function () { handleAnswer(3); });
  panel.on('nextBtn', 'click', handleNext);
  panel.on('restartBtn', 'click', handleRestart);

  traits(luckyStar, {
    grab: true,
    onPress: function () {
      if (finished) return;
      if (answered) return;
      const q = quiz[qIndex];
      panel.set('feed', { text: 'Hint: ' + q.a + ' x ' + q.b + ' means ' + q.a + ' groups of ' + q.b + ' dots. Count!', color: '#ffd84d' });
    }
  });

  // initial paint
  refreshStars();
  renderQuestion();

  const boardBaseY = 0.19;

  return {
    root,
    update: function (time, delta) {
      if (!isGrabbed(luckyStar)) {
        luckyStar.rotation.y += delta * 0.8;
        luckyStar.position.y = luckyBase.y + Math.sin(time * 1.6) * 0.007;
      }
      board.position.y = boardBaseY + Math.sin(time * 1.2) * 0.003;
      dots.position.y = boardBaseY + Math.sin(time * 1.2) * 0.003;
      for (let i = 0; i < 5; i++) {
        if (results[i] === true) {
          const s = 1 + Math.sin(time * 3 + i * 0.9) * 0.12;
          stars[i].scale.setScalar(s);
          stars[i].rotation.y += delta * 1.2;
        } else {
          stars[i].scale.setScalar(1);
        }
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
