    const s = new THREE.Mesh(orbGeo, m);
    s.name = 'ScoreOrb' + (i + 1);
    s.position.set((i - 2) * 0.045, 0, 0);
    scoreGroup.add(s);
    orbMeshes.push(s);
    orbMats.push(m);
  }

