        </div>
        <div class="arow">
          <button class="opt" id="ans2"><span class="optT" id="ans2t">10</span></button>
          <button class="opt" id="ans3"><span class="optT" id="ans3t">16</span></button>
        </div>
      </div>
      <button class="next" id="nextBtn"><span class="nextT" id="nextBtnT">Next</span></button>
      <button class="again" id="againBtn"><span class="nextT" id="againBtnT">Restart quiz</span></button>
    </div>`, { width: 0.34, position: [0.18, 0.24, 0.03], rotationY: -0.25 });
  root.add(panel.object3D);

  // ---------- Quiz state ----------
  let current = 0;
  let score = 0;
  let locked = false;
  let finished = false;
  let correctValue = 12;
  let correctPos = 0;
  let currentOptions = [12, 14, 10, 16];
  const results = [0, 0, 0, 0, 0];

  function buildOptions(a, b, idx) {
    const correct = a * b;
    const cands = [correct + 2, correct - 2, correct + 3, correct - 3, correct + 5, correct - 5, correct + 10, correct - 10, correct + 1, correct - 1, correct + a, correct + b];
    const picks = [];
    for (let i = 0; i < cands.length && picks.length < 3; i++) {
      const v = cands[(i + idx * 3) % cands.length];
      if (v > 0 && v !== correct && picks.indexOf(v) === -1) picks.push(v);
    }
    let extra = correct + 4;
    while (picks.length < 3) {
      if (extra !== correct && picks.indexOf(extra) === -1) picks.push(extra);
      extra += 3;
    }
    const pos = (idx * 3 + 1) % 4;
    const opts = [];
    let pi = 0;
    for (let k = 0; k < 4; k++) {
      if (k === pos) opts.push(correct);
      else { opts.push(picks[pi]); pi++; }
    }
    return { opts, pos, correct };
  }

  function refreshArray(a, b) {
    const spacing = 0.024;
    let k = 0;
    for (let r = 0; r < a; r++) {
      for (let c = 0; c < b; c++) {
        const x = (c - (b - 1) / 2) * spacing;
        const z = (r - (a - 1) / 2) * spacing;
        dummy.position.set(x, 0.023, z);
        dummy.rotation.set(0, 0, 0);
        dummy.updateMatrix();
        blocks.setMatrixAt(k, dummy.matrix);
        blocks.setColorAt(k, (r % 2 === 0) ? colA : colB);
        k++;
      }
    }
    blocks.count = k;
    blocks.instanceMatrix.needsUpdate = true;
    if (blocks.instanceColor) blocks.instanceColor.needsUpdate = true;
  }

  function refreshOrbs() {
    for (let i = 0; i < 5; i++) {
      const m = orbMats[i];
      if (results[i] === 1) { m.color.setHex(0x22c55e); m.emissive.setHex(0x22c55e); }
      else if (results[i] === 2) { m.color.setHex(0xef4444); m.emissive.setHex(0xef4444); }
      else if (i === current && !finished) { m.color.setHex(0xffffff); m.emissive.setHex(0x888888); }
      else { m.color.setHex(0x555c66); m.emissive.setHex(0x000000); }
    }
  }

  function showQuestion() {
    locked = false;
    const q = QUESTIONS[current];
    const built = buildOptions(q.a, q.b, current);
    currentOptions = built.opts;
    correctPos = built.pos;
    correctValue = built.correct;
    panel.set('prog', { text: 'Question ' + (current + 1) + ' of 5' });
    panel.set('ques', { text: q.a + ' x ' + q.b + ' = ?' });
    panel.set('hint', { text: q.a + ' rows x ' + q.b + ' cols - count the blocks!' });
    panel.set('feed', { text: 'Pick an answer below' });
    panel.set('score', { text: 'Score: ' + score });
    for (let i = 0; i < 4; i++) {
      panel.set('ans' + i + 't', { text: '' + currentOptions[i] });
      panel.set('ans' + i, { backgroundColor: '#2f6fdb' });
    }
    panel.set('nextBtnT', { text: current === 4 ? 'Finish' : 'Next' });
    refreshArray(q.a, q.b);
    refreshOrbs();
  }

  function showResults() {
    panel.set('prog', { text: 'Quiz complete!' });
    panel.set('ques', { text: score + ' / 5' });
    let msg = 'You scored ' + score + ' of 5. Press Restart to play again!';
    if (score === 5) msg = 'Perfect 5/5! Grab the gold star!';
    else if (score >= 3) msg = 'Great job! ' + score + ' of 5. Grab the star!';
    panel.set('feed', { text: msg });
    panel.set('hint', { text: 'Final score - well done!' });
    panel.set('nextBtnT', { text: 'Done' });
    panel.set('score', { text: 'Score: ' + score });
    refreshOrbs();
  }

  function answer(i) {
    if (locked || finished) return;
    locked = true;
    const chosen = currentOptions[i];
    const q = QUESTIONS[current];
    if (chosen === correctValue) {
      score++;
      results[current] = 1;
      panel.set('feed', { text: 'Correct! ' + q.a + ' x ' + q.b + ' = ' + correctValue });
    } else {
      results[current] = 2;
      panel.set('feed', { text: chosen + ' is not it - ' + q.a + ' x ' + q.b + ' = ' + correctValue });
    }
    for (let k = 0; k < 4; k++) {
      if (k === correctPos) panel.set('ans' + k, { backgroundColor: '#22a06b' });
      else if (k === i) panel.set('ans' + k, { backgroundColor: '#ef4444' });
      else panel.set('ans' + k, { backgroundColor: '#3a4048' });
    }
    panel.set('score', { text: 'Score: ' + score });
    refreshOrbs();
  }

  function next() {
    if (finished) return;
    if (!locked) {
      panel.set('feed', { text: 'Pick an answer first!' });
      return;
    }
    current++;
    if (current >= 5) {
      finished = true;
      showResults();
    } else {
      showQuestion();
    }
  }

  function restart() {
    current = 0;
    score = 0;
    locked = false;
    finished = false;
    for (let i = 0; i < 5; i++) results[i] = 0;
    showQuestion();
  }

  panel.on('ans0', 'click', () => answer(0));
  panel.on('ans1', 'click', () => answer(1));
  panel.on('ans2', 'click', () => answer(2));
  panel.on('ans3', 'click', () => answer(3));
  panel.on('nextBtn', 'click', next);
  panel.on('againBtn', 'click', restart);

  traits(star, {
    grab: true,
    onPress: () => {
      if (finished) panel.set('feed', { text: 'You are a star! Final: ' + score + '/5' });
      else panel.set('feed', { text: 'Good luck! Q' + (current + 1) + ': ' + QUESTIONS[current].a + ' x ' + QUESTIONS[current].b });
    }
  });

  showQuestion();

  const starBaseY = 0.07;
  return {
    root,
    update(time, delta) {
      if (!isGrabbed(star)) {
        star.rotation.y += delta * 0.7;
        star.position.y = starBaseY + Math.sin(time * 2.2) * 0.006;
        if (finished) {
          const s = 1 + Math.sin(time * 5) * 0.1;
          star.scale.set(s, s, s);
        } else {
          star.scale.set(1, 1, 1);
        }
      }
      for (let i = 0; i < 5; i++) {
        if (!finished && i === current) {
          const s = 1 + Math.sin(time * 4) * 0.15;
          orbMeshes[i].scale.set(s, s, s);
        } else {
          orbMeshes[i].scale.set(1, 1, 1);
        }
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const HABIT_NAMES = ['Drink Water', 'Read 10 min', 'Move 30 min'];
  const HABIT_COLORS = [0x38bdf8, 0xfbbf24, 0x4ade80];
  const HABIT_CSS = ['#38bdf8', '#fbbf24', '#4ade80'];
  const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const DATES = [9, 10, 11, 12, 13, 14, 15];
  const TODAY = 3;
  const ROW_Z = [0.13, 0.05, -0.03];
  const CELL_X0 = -0.04;
  const CELL_DX = 0.038;
  const CELL_Y = 0.034;
  const ICON_X = -0.18;
  const ICON_Y = 0.11;

  const state = [
    [true, true, true, false, false, false, false],
    [false, true, true, false, false, false, false],
    [true, false, true, false, false, false, false]
  ];

  // Materials
  const todoMat = new THREE.MeshStandardMaterial({ color: 0x2e333b, roughness: 0.85 });
  const todayMat = new THREE.MeshStandardMaterial({ color: 0x5a6270, roughness: 0.7 });
  const doneMats = HABIT_COLORS.map((c) => new THREE.MeshStandardMaterial({
    color: c, roughness: 0.35, emissive: c, emissiveIntensity: 0.55
  }));
  const iconMats = HABIT_COLORS.map((c) => new THREE.MeshStandardMaterial({
    color: c, roughness: 0.35, emissive: c, emissiveIntensity: 0.3
  }));

  // Base plate
  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.44, 0.012, 0.26),
    new THREE.MeshStandardMaterial({ color: 0x22262d, roughness: 0.9 })
  );
  base.name = 'Base';
  base.position.set(0, 0.006, 0.05);
  root.add(base);

  // 3D day grid: 3 habits x 7 days
  const cellGeo = new THREE.BoxGeometry(0.032, 0.032, 0.032);
  const cells = [];
  for (let h = 0; h < 3; h++) {
    cells.push([]);
    for (let d = 0; d < 7; d++) {
      const m = new THREE.Mesh(cellGeo, todoMat);
      m.name = 'Habit' + h + '-' + DAYS[d];
      m.position.set(CELL_X0 + d * CELL_DX, CELL_Y, ROW_Z[h]);
      root.add(m);
      cells[h].push(m);
    }
  }

  // 3 grabbable habit icons, one per row
  const iconGeo0 = new THREE.SphereGeometry(0.028, 24, 16);
  const iconGeo1 = new THREE.BoxGeometry(0.046, 0.032, 0.022);
  const iconGeo2 = new THREE.TorusGeometry(0.024, 0.0095, 12, 24);
  const iconGeos = [iconGeo0, iconGeo1, iconGeo2];
  const icons = [];
  for (let h = 0; h < 3; h++) {
    const m = new THREE.Mesh(iconGeos[h], iconMats[h]);
    m.name = HABIT_NAMES[h];
    m.position.set(ICON_X, ICON_Y, ROW_Z[h]);
    root.add(m);
    icons.push(m);
  }

  // ---- UI panel ----
  let habitBlocks = '';
  for (let h = 0; h < 3; h++) {
    habitBlocks += `<div class="habit"><div class="top"><span class="dot${h}">●</span><span class="hname">${HABIT_NAMES[h]}</span><span class="streak" id="streak-${h}">Streak</span></div><div class="days">`;
    for (let d = 0; d < 7; d++) {
      habitBlocks += `<button class="day" id="cell-${h}-${d}"><span class="daytext" id="t-${h}-${d}">${DAYS[d].charAt(0)} ${DATES[d]}</span></button>`;
    }
    habitBlocks += `</div></div>`;
  }

  const markup = `<style>
    .card { flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #1f2228; width: 560px; }
    .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
    .subtitle { color: #aeb4c0; font-size: 20px; text-align: center; }
    .habit { flex-direction: column; gap: 8px; padding-top: 12px; padding-bottom: 12px; padding-left: 14px; padding-right: 14px; border-radius: 14px; background-color: #2a2e35; }
    .top { flex-direction: row; gap: 8px; align-items: center; }
    .dot0 { color: #38bdf8; font-size: 24px; font-weight: 700; }
    .dot1 { color: #fbbf24; font-size: 24px; font-weight: 700; }
    .dot2 { color: #4ade80; font-size: 24px; font-weight: 700; }
    .hname { color: #ffffff; font-size: 22px; font-weight: 700; width: 150px; }
    .streak { color: #ffd166; font-size: 20px; font-weight: 700; }
    .days { flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
    .day { width: 60px; height: 48px; border-radius: 12px; background-color: #3a3f48; align-items: center; justify-content: center; }
    .daytext { color: #e8ebf0; font-size: 20px; font-weight: 700; text-align: center; }
    .footer { color: #d7dbe2; font-size: 21px; font-weight: 700; text-align: center; }
    .reset { border-radius: 12px; background-color: #454c59; padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; align-items: center; justify-content: center; }
    .resettext { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
    .hint { color: #8b93a1; font-size: 18px; text-align: center; }
  </style><div class="card"><span class="title">Habit Tracker • Nov 9-15</span><span class="subtitle">Today Thu 12 • Tap a day to check it off</span>${habitBlocks}<span class="footer" id="overall">0/21 done</span><button class="reset" id="reset"><span class="resettext">Reset week</span></button><span class="hint">Tap cubes or buttons to check • Pinch a floating shape to grab it • Tap it for today</span></div>`;

  const panel = ui(markup, { width: 0.44, position: [0.02, 0.33, -0.15], rotationY: 0 });
  root.add(panel.object3D);

  function getCount(h) {
    let c = 0;
    for (let d = 0; d < 7; d++) if (state[h][d]) c++;
    return c;
  }
  function getStreak(h) {
    let idx = TODAY;
    if (!state[h][idx]) idx = TODAY - 1;
    let s = 0;
    for (let d = idx; d >= 0; d--) {
      if (state[h][d]) s++;
      else break;
    }
    return s;
  }

  function refreshHabit(h) {
    const c = getCount(h);
    const s = getStreak(h);
    let txt = s + '-day streak • ' + c + '/7';
    if (s === 0) txt = 'No streak yet • ' + c + '/7';
    if (s === 1) txt = '1-day streak • ' + c + '/7';
    panel.set('streak-' + h, { text: txt });
    for (let d = 0; d < 7; d++) {
      const done = state[h][d];
      const label = done ? '✓' : (DAYS[d].charAt(0) + ' ' + DATES[d]);
      panel.set('t-' + h + '-' + d, { text: label, color: done ? '#13202a' : '#e8ebf0' });
      let bg = '#3a3f48';
      if (done) bg = HABIT_CSS[h];
      else if (d === TODAY) bg = '#5f6775';
      panel.set('cell-' + h + '-' + d, { backgroundColor: bg });
      cells[h][d].material = done ? doneMats[h] : (d === TODAY ? todayMat : todoMat);
    }
    icons[h].scale.setScalar(1 + s * 0.07);
  }

  function refreshOverall() {
    let total = 0;
    for (let h = 0; h < 3; h++) total += getCount(h);
    const pct = Math.round((total / 21) * 100);
    let msg = total + '/21 done this week • ' + pct + '%';
    if (total === 21) msg = 'Perfect week! 21/21 • 100%';
    else if (total >= 14) msg += ' • Keep it up!';
    panel.set('overall', { text: msg });
  }

  function toggle(h, d) {
    state[h][d] = !state[h][d];
    refreshHabit(h);
    refreshOverall();
  }

  for (let h = 0; h < 3; h++) {
    for (let d = 0; d < 7; d++) {
      const hh = h;
      const dd = d;
      panel.on('cell-' + hh + '-' + dd, 'click', () => toggle(hh, dd));
    }
  }
  panel.on('reset', 'click', () => {
    for (let h = 0; h < 3; h++) for (let d = 0; d < 7; d++) state[h][d] = false;
    for (let h = 0; h < 3; h++) refreshHabit(h);
    refreshOverall();
  });

  // 3D interactions (direct children of root only)
  for (let h = 0; h < 3; h++) {
    for (let d = 0; d < 7; d++) {
      const hh = h;
      const dd = d;
      traits(cells[hh][dd], { onPress: () => toggle(hh, dd) });
    }
  }
  for (let h = 0; h < 3; h++) {
    const hh = h;
    traits(icons[hh], { grab: true, onPress: () => toggle(hh, TODAY) });
  }

  for (let h = 0; h < 3; h++) refreshHabit(h);
  refreshOverall();

  return {
    root,
    update(time, delta) {
      for (let h = 0; h < 3; h++) {
        const m = icons[h];
        if (isGrabbed(m)) continue;
        m.position.y = ICON_Y + Math.sin(time * 1.3 + h * 2.094) * 0.006;
        m.rotation.y += delta * 0.5;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Base tray ----------
  const trayMat = new THREE.MeshStandardMaterial({ color: 0x23262e, roughness: 0.9, metalness: 0.05 });
  const tray = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.01, 48), trayMat);
  tray.name = 'BuildTray';
  tray.position.set(0, 0.005, 0.0);
  root.add(tray);

  // Build-zone ring hint (where to assemble)
  const ringMat = new THREE.MeshStandardMaterial({
    color: 0x2f6fdb, emissive: 0x2f6fdb, emissiveIntensity: 0.7, roughness: 0.5
  });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.085, 0.0035, 10, 48), ringMat);
  ring.name = 'BuildZone';
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(0, 0.012, -0.04);
  root.add(ring);

  // ---------- Atoms ----------
  const oxyMat = new THREE.MeshStandardMaterial({ color: 0xe23b3b, roughness: 0.45, metalness: 0.05 });
  const hydMat = new THREE.MeshStandardMaterial({ color: 0xf2f5f7, roughness: 0.5, metalness: 0.02 });
  const hydMat2 = new THREE.MeshStandardMaterial({ color: 0xf2f5f7, roughness: 0.5, metalness: 0.02 });
  const oxyGeo = new THREE.SphereGeometry(0.035, 28, 16);
  const hydGeo = new THREE.SphereGeometry(0.025, 24, 12);

  const oxygen = new THREE.Mesh(oxyGeo, oxyMat);
  oxygen.name = 'Oxygen';
  const O_HOME = new THREE.Vector3(-0.14, 0.045, 0.08);
  oxygen.position.copy(O_HOME);
  root.add(oxygen);
  traits(oxygen, { grab: true });

  const hydrogen1 = new THREE.Mesh(hydGeo, hydMat);
  hydrogen1.name = 'Hydrogen1';
  const H1_HOME = new THREE.Vector3(0.02, 0.035, 0.12);
  hydrogen1.position.copy(H1_HOME);
  root.add(hydrogen1);
  traits(hydrogen1, { grab: true });

  const hydrogen2 = new THREE.Mesh(hydGeo, hydMat2);
  hydrogen2.name = 'Hydrogen2';
  const H2_HOME = new THREE.Vector3(0.16, 0.035, 0.08);
  hydrogen2.position.copy(H2_HOME);
  root.add(hydrogen2);
  traits(hydrogen2, { grab: true });

  // Small dark discs under homes so users see start spots
  const spotGeo = new THREE.CylinderGeometry(0.032, 0.032, 0.002, 24);
  const spotMatO = new THREE.MeshBasicMaterial({ color: 0x7a2a2a });
  const spotMatH = new THREE.MeshBasicMaterial({ color: 0x8a919c });
  const spotO = new THREE.Mesh(spotGeo, spotMatO);
  spotO.position.set(O_HOME.x, 0.011, O_HOME.z);
  root.add(spotO);
  const spotH1 = new THREE.Mesh(spotGeo, spotMatH);
  spotH1.position.set(H1_HOME.x, 0.011, H1_HOME.z);
  root.add(spotH1);
  const spotH2 = new THREE.Mesh(spotGeo, spotMatH);
  spotH2.position.set(H2_HOME.x, 0.011, H2_HOME.z);
  root.add(spotH2);

  // ---------- Bonds (shown when atoms touch) ----------
  const bondGeo = new THREE.CylinderGeometry(0.008, 0.008, 1, 12);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0xc7ccd4, roughness: 0.4 });
  const bond1 = new THREE.Mesh(bondGeo, bondMat);
  bond1.name = 'Bond1';
  bond1.visible = false;
  root.add(bond1);
  const bond2 = new THREE.Mesh(bondGeo, bondMat);
  bond2.name = 'Bond2';
  bond2.visible = false;
  root.add(bond2);

  // ---------- Info panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; width: 520px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .body { color: #d7dbe2; font-size: 22px; text-align: center; }
      .row { flex-direction: row; align-items: center; justify-content: center; gap: 10px; }
      .dotO { width: 22px; height: 22px; border-radius: 11px; background-color: #e23b3b; }
      .dotH { width: 18px; height: 18px; border-radius: 9px; background-color: #f2f5f7; }
      .lab { color: #d7dbe2; font-size: 20px; }
      .status { color: #ffd166; font-size: 23px; font-weight: 700; text-align: center; }
      .detail { color: #aab0bc; font-size: 20px; text-align: center; }
      .btnrow { flex-direction: row; gap: 12px; align-items: center; justify-content: center; }
      .check { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px; border-radius: 12px; background-color: #2ea44f; }
      .reset { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px; border-radius: 12px; background-color: #3a3f48; }
      .btntext { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build Water - H2O</span>
      <span class="body">Grab the big red O + 2 small white H. Touch BOTH H to the O in a V-shape, then press Check.</span>
      <div class="row">
        <span class="dotO"></span><span class="lab">Oxygen x1</span>
        <span class="dotH"></span><span class="lab">Hydrogen x2</span>
      </div>
      <span class="status" id="status">Bring both H to touch O, then press Check.</span>
      <span class="detail" id="detail">Need: 1 O + 2 H touching (O-H under 9 cm)</span>
      <div class="btnrow">
        <button class="check" id="check"><span class="btntext">Check: is this water?</span></button>
        <button class="reset" id="reset"><span class="btntext">Reset</span></button>
      </div>
    </div>`, { width: 0.34, position: [0.27, 0.24, -0.06], rotationY: -0.35 });
  root.add(panel.object3D);

  const BOND_OK = 0.09;
  const SHOW_BOND = 0.125;

  function describe() {
    const d1 = oxygen.position.distanceTo(hydrogen1.position);
    const d2 = oxygen.position.distanceTo(hydrogen2.position);
    const dh = hydrogen1.position.distanceTo(hydrogen2.position);
    return { d1, d2, dh };
  }

  function cm(m) { return Math.round(m * 100); }

  panel.on('check', 'click', () => {
    const { d1, d2, dh } = describe();
    const detail = 'O-H1: ' + cm(d1) + ' cm, O-H2: ' + cm(d2) + ' cm, H-H: ' + cm(dh) + ' cm';
    panel.set('detail', { text: detail });

    const b1 = d1 <= BOND_OK;
    const b2 = d2 <= BOND_OK;

    if (b1 && b2) {
      if (dh < 0.045) {
        panel.set('status', { text: 'Almost! Both touch O but the H atoms overlap. Spread them into a V.', color: '#ffd166' });
      } else {
        panel.set('status', { text: 'YES! That is water! 1 O + 2 H in a bent V (104.5 deg). You built H2O!', color: '#7bff9e' });
      }
    } else if (b1 && !b2) {
      panel.set('status', { text: 'Close! One H is bonded. Bring the 2nd H to touch the O.', color: '#ffd166' });
    } else if (!b1 && b2) {
      panel.set('status', { text: 'Close! One H is bonded. Bring the other H to touch the O.', color: '#ffd166' });
    } else {
      if (d1 < d2) {
        panel.set('status', { text: 'Not yet. Keep going: bring BOTH white H atoms to touch the red O.', color: '#ff9a9a' });
      } else {
        panel.set('status', { text: 'Not yet. Keep going: bring BOTH white H atoms to touch the red O.', color: '#ff9a9a' });
      }
    }
  });

  panel.on('reset', 'click', () => {
    oxygen.position.copy(O_HOME);
    hydrogen1.position.copy(H1_HOME);
    hydrogen2.position.copy(H2_HOME);
    panel.set('status', { text: 'Bring both H to touch O, then press Check.', color: '#ffd166' });
    panel.set('detail', { text: 'Need: 1 O + 2 H touching (O-H under 9 cm)' });
  });

  // ---------- Per-frame bond layout (no allocation) ----------
  const tmpMid = new THREE.Vector3();
  const tmpDir = new THREE.Vector3();
  const UP = new THREE.Vector3(0, 1, 0);
  const tmpQ = new THREE.Quaternion();

  function layoutBond(mesh, a, b, dist) {
    if (dist > SHOW_BOND) {
      mesh.visible = false;
      return;
    }
    mesh.visible = true;
    tmpMid.copy(a).add(b).multiplyScalar(0.5);
    mesh.position.copy(tmpMid);
    tmpDir.copy(b).sub(a);
    const len = Math.max(tmpDir.length(), 0.001);
    mesh.scale.set(1, len, 1);
    tmpDir.divideScalar(len);
    tmpQ.setFromUnitVectors(UP, tmpDir);
    mesh.quaternion.copy(tmpQ);
  }

  let pulse = 0;

  return {
    root,
    update(time) {
      const d1 = oxygen.position.distanceTo(hydrogen1.position);
      const d2 = oxygen.position.distanceTo(hydrogen2.position);
      layoutBond(bond1, oxygen.position, hydrogen1.position, d1);
      layoutBond(bond2, oxygen.position, hydrogen2.position, d2);

      // Gentle glow on the build-zone ring; green when water is correct
      pulse += 0.016;
      const good = d1 <= BOND_OK && d2 <= BOND_OK;
      if (good) {
        ringMat.emissive.setHex(0x2ea44f);
        ringMat.color.setHex(0x2ea44f);
        ring.scale.setScalar(1 + Math.sin(time * 4) * 0.03);
      } else {
        ringMat.emissive.setHex(0x2f6fdb);
        ringMat.color.setHex(0x2f6fdb);
        ring.scale.setScalar(1 + Math.sin(time * 1.5) * 0.015);
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  const D2 = ["MO","TU","WE","TH","FR","SA","SU"];
  const DFULL = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];

  const now = new Date();
  const todayIdx = (now.getDay() + 6) % 7;
  const monday = new Date(now);
  monday.setDate(now.getDate() - todayIdx);
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);
  let weekLabel = MONTHS[monday.getMonth()] + " " + monday.getDate() + "–" + sunday.getDate();
  if (monday.getMonth() !== sunday.getMonth()) {
    weekLabel = MONTHS[monday.getMonth()] + " " + monday.getDate() + " – " + MONTHS[sunday.getMonth()] + " " + sunday.getDate();
  }
  const todayName = DFULL[todayIdx];
  const todayX = (todayIdx - 3) * 0.07;
  const rowZ = [-0.18, -0.07, 0.04];

  const habits = [
    { name: "Drink Water", color: 0x38bdf8, checked: [true, true, true, false, false, false, false] },
    { name: "Read 15 min", color: 0xfbbf24, checked: [false, true, true, false, false, false, false] },
    { name: "Move 20 min", color: 0x4ade80, checked: [false, false, true, false, false, false, false] }
  ];

  function streakFor(arr) {
    let start = arr[todayIdx] ? todayIdx : todayIdx - 1;
    let s = 0;
    for (let i = start; i >= 0; i--) {
      if (arr[i]) s++;
      else break;
    }
    return s;
  }
  function countFor(arr) {
    let n = 0;
    for (let i = 0; i < 7; i++) if (arr[i]) n++;
    return n;
  }

  const uncheckedMat = new THREE.MeshStandardMaterial({ color: 0x363d47, roughness: 0.75, metalness: 0.05 });
  const checkedMats = [
    new THREE.MeshStandardMaterial({ color: 0x38bdf8, emissive: 0x38bdf8, emissiveIntensity: 0.55, roughness: 0.35 }),
    new THREE.MeshStandardMaterial({ color: 0xfbbf24, emissive: 0xf59e0b, emissiveIntensity: 0.55, roughness: 0.35 }),
    new THREE.MeshStandardMaterial({ color: 0x4ade80, emissive: 0x22c55e, emissiveIntensity: 0.55, roughness: 0.35 })
  ];
  const rowBaseMat = new THREE.MeshStandardMaterial({ color: 0x20242b, roughness: 0.9 });
  const todayMat = new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0xffb700, emissiveIntensity: 0.5, roughness: 0.4 });
  const markerMats = [
    new THREE.MeshStandardMaterial({ color: 0x38bdf8, emissive: 0x38bdf8, emissiveIntensity: 0.6, roughness: 0.4 }),
    new THREE.MeshStandardMaterial({ color: 0xfbbf24, emissive: 0xf59e0b, emissiveIntensity: 0.6, roughness: 0.4 }),
    new THREE.MeshStandardMaterial({ color: 0x4ade80, emissive: 0x22c55e, emissiveIntensity: 0.6, roughness: 0.4 })
  ];
  const trophyMat = new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0xff9f1c, emissiveIntensity: 0.7, roughness: 0.3, metalness: 0.4 });
  const pedMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 });

  const cellGeo = new THREE.BoxGeometry(0.038, 0.016, 0.038);
  const rowGeo = new THREE.BoxGeometry(0.56, 0.008, 0.08);
  const todayGeo = new THREE.BoxGeometry(0.055, 0.006, 0.31);
  const markerGeo = new THREE.SphereGeometry(0.022, 24, 16);
  const trophyGeo = new THREE.OctahedronGeometry(0.028);
  const pedGeo = new THREE.CylinderGeometry(0.035, 0.042, 0.016, 24);

  for (let r = 0; r < 3; r++) {
    const base = new THREE.Mesh(rowGeo, rowBaseMat);
    base.position.set(0, 0.004, rowZ[r]);
    base.name = "RowBase" + r;
    root.add(base);
  }

  const todayStrip = new THREE.Mesh(todayGeo, todayMat);
  todayStrip.position.set(todayX, 0.005, -0.07);
  todayStrip.name = "TodayColumn";
  root.add(todayStrip);

  for (let r = 0; r < 3; r++) {
    const m = new THREE.Mesh(markerGeo, markerMats[r]);
    m.position.set(-0.33, 0.028, rowZ[r]);
    m.name = habits[r].name + " marker";
    root.add(m);
  }

  const grid = [];
  const cellList = [];
  for (let r = 0; r < 3; r++) {
    grid[r] = [];
    for (let c = 0; c < 7; c++) {
      const mesh = new THREE.Mesh(cellGeo, uncheckedMat);
      mesh.position.set((c - 3) * 0.07, 0.022, rowZ[r]);
      mesh.name = habits[r].name + " " + DFULL[c];
      mesh.userData.r = r;
      mesh.userData.c = c;
      mesh.userData.pop = 0;
      mesh.scale.set(1, 1, 1);
      root.add(mesh);
      grid[r][c] = mesh;
      cellList.push(mesh);
    }
  }

  const trophyBaseY = 0.10;
  const trophy = new THREE.Mesh(trophyGeo, trophyMat);
  trophy.position.set(0.31, trophyBaseY, 0.12);
  trophy.name = "Trophy";
  root.add(trophy);
  const ped = new THREE.Mesh(pedGeo, pedMat);
  ped.position.set(0.31, 0.008, 0.12);
  ped.name = "Pedestal";
  root.add(ped);

  const mainMarkup = `
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .week { color: #ffd166; font-size: 21px; font-weight: 700; }
      .sub { color: #c8cdd5; font-size: 19px; }
      .info0 { color: #7dd3fc; font-size: 21px; font-weight: 700; }
      .info1 { color: #fcd34d; font-size: 21px; font-weight: 700; }
      .info2 { color: #86efac; font-size: 21px; font-weight: 700; }
      .total { color: #ffffff; font-size: 21px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
      .btn2 { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #353b44; }
      .hint { color: #9aa1ad; font-size: 18px; }
    </style>
    <div class="card">
      <span class="title">Habit Tracker</span>
      <span class="week" id="week">${weekLabel}</span>
      <span class="sub">Gold column = today (${todayName}). Tap a puck to check it off.</span>
      <span class="info0" id="info0">Water</span>
      <span class="info1" id="info1">Read</span>
      <span class="info2" id="info2">Move</span>
      <span class="total" id="total">0 / 21</span>
      <button class="btn" id="todayBtn"><span class="btn-text">Check off today ✓</span></button>
      <button class="btn2" id="reset"><span class="btn-text">Reset week</span></button>
      <span class="hint">Grab the gold star when all 3 are done today.</span>
    </div>`;

  const info = ui(mainMarkup, { width: 0.30, position: [0.26, 0.22, 0.0], rotationY: -0.4 });
  root.add(info.object3D);

  let daySpans = "";
  for (let i = 0; i < 7; i++) {
    const cls = i === todayIdx ? "dtoday" : "d";
    daySpans += `<span class="${cls}">${D2[i]}</span>`;
  }
  const headerMarkup = `
    <style>
      .dbar { flex-direction: row; gap: 10px; padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #1a1d22; align-items: center; justify-content: center; }
      .d { color: #9aa1ad; font-size: 20px; font-weight: 700; }
      .dtoday { color: #1a1d22; font-size: 20px; font-weight: 700; background-color: #ffd166; border-radius: 8px; padding-top: 2px; padding-bottom: 2px; padding-left: 6px; padding-right: 6px; }
    </style>
    <div class="dbar">${daySpans}</div>`;
  const header = ui(headerMarkup, { width: 0.50, position: [0, 0.075, -0.28], rotationY: 0 });
  root.add(header.object3D);

  let allTodayDone = false;

  function syncCell(r, c) {
    const on = habits[r].checked[c];
    grid[r][c].material = on ? checkedMats[r] : uncheckedMat;
  }
  function refresh() {
    for (let r = 0; r < 3; r++) {
      const s = streakFor(habits[r].checked);
      const n = countFor(habits[r].checked);
      const label = habits[r].name + ": " + s + "-day streak • " + n + "/7";
      info.set("info" + r, { text: label });
    }
    let total = 0;
    for (let r = 0; r < 3; r++) total += countFor(habits[r].checked);
    let msg = total + " / 21 pucks • Keep going!";
    if (total >= 21) msg = "21 / 21 — Perfect week!";
    else if (total >= 12) msg = total + " / 21 pucks • Strong week!";
    info.set("total", { text: msg });
    allTodayDone = habits[0].checked[todayIdx] && habits[1].checked[todayIdx] && habits[2].checked[todayIdx];
  }

  function doToggle(r, c) {
    habits[r].checked[c] = !habits[r].checked[c];
    syncCell(r, c);
    grid[r][c].userData.pop = 1;
    refresh();
  }

  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 7; c++) {
      syncCell(r, c);
    }
  }
  refresh();

  for (let i = 0; i < cellList.length; i++) {
    const mesh = cellList[i];
    const r = mesh.userData.r;
    const c = mesh.userData.c;
    traits(mesh, { onPress: () => doToggle(r, c) });
  }
  traits(trophy, { grab: true });

  info.on("todayBtn", "click", () => {
    for (let r = 0; r < 3; r++) {
      if (!habits[r].checked[todayIdx]) {
        habits[r].checked[todayIdx] = true;
        syncCell(r, todayIdx);
        grid[r][todayIdx].userData.pop = 1;
      }
    }
    refresh();
  });
  info.on("reset", "click", () => {
    for (let r = 0; r < 3; r++) {
      for (let c = 0; c < 7; c++) {
        habits[r].checked[c] = false;
        syncCell(r, c);
      }
    }
    refresh();
  });

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < cellList.length; i++) {
        const m = cellList[i];
        let p = m.userData.pop;
        if (p > 0) {
          p -= delta * 2.5;
          if (p < 0) p = 0;
          m.userData.pop = p;
          const s = 1 + 0.35 * p;
          m.scale.set(s, s, s);
        }
      }
      todayMat.emissiveIntensity = 0.45 + 0.2 * Math.sin(time * 2.2);
      if (!isGrabbed(trophy)) {
        const speed = allTodayDone ? 2.6 : 0.8;
        trophy.rotation.y += delta * speed;
        trophy.position.y = trophyBaseY + Math.sin(time * 2.0) * 0.008;
        const target = allTodayDone ? 1.35 : 1.0;
        const cur = trophy.scale.x;
        const next = cur + (target - cur) * Math.min(1, delta * 5);
        trophy.scale.set(next, next, next);
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const BOND_DIST = 0.075;
  const CARRY_DIST = 0.09;
  const OVERLAP = 0.034;

  // Desk mat
  const mat = new THREE.Mesh(
    new THREE.CylinderGeometry(0.30, 0.30, 0.01, 48),
    new THREE.MeshStandardMaterial({ color: 0x191c21, roughness: 0.95 })
  );
  mat.position.set(0, 0.005, 0.02);
  root.add(mat);

  // Build pad (target zone)
  const pad = new THREE.Mesh(
    new THREE.CylinderGeometry(0.13, 0.13, 0.008, 40),
    new THREE.MeshStandardMaterial({ color: 0x232833, roughness: 0.8, emissive: 0x2f6fdb, emissiveIntensity: 0.18 })
  );
  pad.position.set(0, 0.009, 0.02);
  pad.name = 'BuildPad';
  root.add(pad);

  // Atoms
  const O_GEOM = new THREE.SphereGeometry(0.035, 28, 16);
  const H_GEOM = new THREE.SphereGeometry(0.025, 24, 12);
  const O_MAT = new THREE.MeshStandardMaterial({ color: 0xe53b3b, roughness: 0.35, metalness: 0.05 });
  const O_MAT2 = new THREE.MeshStandardMaterial({ color: 0xd94848, roughness: 0.35, metalness: 0.05 });
  const H_MAT = new THREE.MeshStandardMaterial({ color: 0xf2f4f7, roughness: 0.5 });
  const H_MAT2 = new THREE.MeshStandardMaterial({ color: 0xdfe6ee, roughness: 0.5 });

  const oStarts = [
    [-0.12, 0.045, -0.06],
    [0.12, 0.045, -0.06]
  ];
  const hStarts = [
    [-0.16, 0.035, 0.13],
    [0.0, 0.035, 0.15],
    [0.16, 0.035, 0.13]
  ];

  const oxygens = [];
  const hydrogens = [];
  const prevO = [];

  for (let i = 0; i < 2; i++) {
    const m = new THREE.Mesh(O_GEOM, i === 0 ? O_MAT : O_MAT2);
    m.name = 'Oxygen';
    m.position.set(oStarts[i][0], oStarts[i][1], oStarts[i][2]);
    root.add(m);
    traits(m, {
      grab: true,
      onPress: () => panel.set('detail', { text: 'Oxygen (red): you need exactly 1 of these in water.' })
    });
    oxygens.push(m);
    prevO.push(m.position.clone());
  }
  for (let i = 0; i < 3; i++) {
    const m = new THREE.Mesh(H_GEOM, i === 2 ? H_MAT2 : H_MAT);
    m.name = 'Hydrogen';
    m.position.set(hStarts[i][0], hStarts[i][1], hStarts[i][2]);
    root.add(m);
    traits(m, {
      grab: true,
      onPress: () => panel.set('detail', { text: 'Hydrogen (white): you need exactly 2 of these in water.' })
    });
    hydrogens.push(m);
  }

  // Bonds (2 O x 3 H = 6 possible)
  const bondGeom = new THREE.CylinderGeometry(0.008, 0.008, 1, 10);
  const bondMat = new THREE.MeshStandardMaterial({ color: 0x9aa3b2, roughness: 0.4, metalness: 0.3 });
  const bonds = [];
  for (let oi = 0; oi < 2; oi++) {
    for (let hi = 0; hi < 3; hi++) {
      const b = new THREE.Mesh(bondGeom, bondMat);
      b.visible = false;
      b.name = 'Bond';
      root.add(b);
      bonds.push({ mesh: b, oi, hi });
    }
  }

  // Success halo
  const halo = new THREE.Mesh(
    new THREE.TorusGeometry(0.075, 0.006, 12, 40),
    new THREE.MeshStandardMaterial({ color: 0x3ddc84, emissive: 0x3ddc84, emissiveIntensity: 0.9, roughness: 0.4 })
  );
  halo.rotation.x = -Math.PI / 2;
  halo.visible = false;
  root.add(halo);

  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .sub { color: #d7dbe2; font-size: 21px; text-align: center; }
      .legend { flex-direction: row; gap: 12px; align-items: center; justify-content: center; }
      .leg { color: #c9cfd8; font-size: 20px; }
      .live { color: #9fd0ff; font-size: 21px; text-align: center; }
      .status { color: #ffffff; font-size: 24px; font-weight: 700; text-align: center; padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #3a3f47; }
      .detail { color: #d7dbe2; font-size: 20px; text-align: center; }
      .row { flex-direction: row; gap: 12px; align-items: center; justify-content: center; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px; border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px; border-radius: 12px; background-color: #3a3f47; }
      .btn-text { color: #ffffff; font-size: 23px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build Water (H2O)</span>
      <span class="sub">Pinch atoms to grab. Stick 2 white H onto 1 red O. Grab O to lift the molecule.</span>
      <div class="legend"><span class="leg">Red = O</span><span class="leg">White = H</span><span class="leg">Grey stick = bond</span></div>
      <span class="live" id="live">Bonds: 0</span>
      <span class="status" id="status">Press CHECK when joined</span>
      <span class="detail" id="detail">Tip: bonds appear when centers touch. Spares go to the side.</span>
      <div class="row">
        <button class="btn" id="check"><span class="btn-text">CHECK</span></button>
        <button class="btn2" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.38, position: [0, 0.30, -0.20], rotationY: 0 });
  root.add(panel.object3D);

  function dist(a, b) { return a.position.distanceTo(b.position); }

  function evaluate() {
    const bonded = [[], []];
    let overlap = false;
    for (let oi = 0; oi < 2; oi++) {
      for (let hi = 0; hi < 3; hi++) {
        const d = dist(oxygens[oi], hydrogens[hi]);
        if (d < BOND_DIST) {
          bonded[oi].push(hi);
          if (d < OVERLAP) overlap = true;
        }
      }
    }
    const c0 = bonded[0].length;
    const c1 = bonded[1].length;

    // H-H only cluster (no O bond but Hs touching each other)
    let hhClose = false;
    for (let a = 0; a < 3; a++) {
      for (let b = a + 1; b < 3; b++) {
        if (hydrogens[a].position.distanceTo(hydrogens[b].position) < 0.055) hhClose = true;
      }
    }

    let ok = false;
    let title = '';
    let msg = '';
    let good = false;

    const waterOi = (c0 === 2) ? 0 : (c1 === 2 ? 1 : -1);
    if (waterOi !== -1 && !overlap) {
      // check spares crowding the water cluster
      const oPos = oxygens[waterOi].position;
      let crowded = false;
      const otherOi = waterOi === 0 ? 1 : 0;
      if (oPos.distanceTo(oxygens[otherOi].position) < 0.14) crowded = true;
      for (let hi = 0; hi < 3; hi++) {
        if (bonded[waterOi].indexOf(hi) === -1) {
          if (oPos.distanceTo(hydrogens[hi].position) < 0.11) crowded = true;
          for (const bh of bonded[waterOi]) {
            if (hydrogens[bh].position.distanceTo(hydrogens[hi].position) < 0.09) crowded = true;
          }
        }
      }
      // H-H spread check for nice bent shape
      const hA = hydrogens[bonded[waterOi][0]];
      const hB = hydrogens[bonded[waterOi][1]];
      const hh = hA.position.distanceTo(hB.position);
      ok = true;
      good = true;
      if (crowded) {
        title = 'YES — that is water!';
        msg = 'H2O found, but a spare atom is touching it. Move spares aside for a clean molecule. Real water is bent at 104.5 deg.';
      } else if (hh < 0.045 || hh > 0.115) {
        title = 'YES — that is water!';
        msg = 'H2O found (1 O + 2 H). Try a wide V shape: Hs on different sides of O, about 104.5 deg apart.';
      } else {
        title = 'YES — perfect water!';
        msg = 'H2O: 1 oxygen + 2 hydrogens in a bent V. Grab the red O to lift your molecule.';
      }
    } else if (waterOi !== -1 && overlap) {
      title = 'Almost — too squashed';
      msg = 'That O has 2 H, but centers overlap. Pull each H out a little so grey sticks just touch.';
    } else if (c0 >= 3 || c1 >= 3) {
      title = 'NO — too many H';
      msg = 'That oxygen holds 3 H. Water needs exactly 2. Pull one H off.';
    } else if (c0 === 1 && c1 === 1) {
      title = 'NO — split up';
      msg = 'You have two OH pieces. Put BOTH white H on the SAME red O.';
    } else if (c0 === 1 || c1 === 1) {
      title = 'Almost — need one more H';
      msg = 'That oxygen has 1 H. Bring a second white H to the same red O.';
    } else if (c0 === 0 && c1 === 0) {
      // check nearness
      let nearest = 10;
      for (let oi = 0; oi < 2; oi++) for (let hi = 0; hi < 3; hi++) nearest = Math.min(nearest, dist(oxygens[oi], hydrogens[hi]));
      if (nearest < 0.13) {
        title = 'Not yet — closer!';
        msg = 'Keep pushing H into O until a grey bond stick pops up.';
      } else if (hhClose) {
        title = 'Not water yet';
        msg = 'White H touching white H is not water. Hs must each touch the SAME red O.';
      } else {
        title = 'Not yet';
        msg = 'Pick any red O and press 2 white H against it until grey sticks appear, then CHECK.';
      }
    } else {
      title = 'NO — not water';
      msg = 'Water is exactly 1 O + 2 H joined. Rearrange and CHECK again.';
    }
    return { ok, title, msg, good };
  }

  panel.on('check', 'click', () => {
    const r = evaluate();
    panel.set('status', { text: r.title, backgroundColor: r.ok ? '#1f8a4c' : '#8a2f2f' });
    panel.set('detail', { text: r.msg });
  });

  panel.on('reset', 'click', () => {
    for (let i = 0; i < 2; i++) {
      oxygens[i].position.set(oStarts[i][0], oStarts[i][1], oStarts[i][2]);
      prevO[i].copy(oxygens[i].position);
    }
    for (let i = 0; i < 3; i++) hydrogens[i].position.set(hStarts[i][0], hStarts[i][1], hStarts[i][2]);
    panel.set('status', { text: 'Press CHECK when joined', backgroundColor: '#3a3f47' });
    panel.set('detail', { text: 'Tip: bonds appear when centers touch. Spares go to the side.' });
  });

  // Preallocated temps (no allocation in update)
  const tmpDelta = new THREE.Vector3();
  const tmpMid = new THREE.Vector3();
  const tmpDir = new THREE.Vector3();
  const UP = new THREE.Vector3(0, 1, 0);
  const tmpQ = new THREE.Quaternion();
  let lastSig = -1;

  function clampAtom(p, r) {
    if (p.x < -0.35) p.x = -0.35;
    if (p.x > 0.35) p.x = 0.35;
    if (p.z < -0.22) p.z = -0.22;
    if (p.z > 0.25) p.z = 0.25;
    const minY = r + 0.004;
    if (p.y < minY) p.y = minY;
    if (p.y > 0.45) p.y = 0.45;
  }

  return {
    root,
    update(time, delta) {
      // Carry bonded H with a grabbed O so water can be lifted together
      for (let oi = 0; oi < 2; oi++) {
        const o = oxygens[oi];
        tmpDelta.copy(o.position).sub(prevO[oi]);
        const moved = tmpDelta.length();
        if (isGrabbed(o) && moved > 0.00001 && moved < 0.05) {
          for (let hi = 0; hi < 3; hi++) {
            const h = hydrogens[hi];
            if (isGrabbed(h)) continue;
            if (o.position.distanceTo(h.position) < CARRY_DIST) {
              h.position.add(tmpDelta);
              clampAtom(h.position, 0.025);
            }
          }
        }
        prevO[oi].copy(o.position);
      }

      for (let i = 0; i < 2; i++) clampAtom(oxygens[i].position, 0.035);
      for (let i = 0; i < 3; i++) clampAtom(hydrogens[i].position, 0.025);

      // Bonds
      let bondCount = 0;
      let c0 = 0;
      let c1 = 0;
      for (let k = 0; k < bonds.length; k++) {
        const bd = bonds[k];
        const o = oxygens[bd.oi];
        const h = hydrogens[bd.hi];
        tmpDir.subVectors(h.position, o.position);
        const d = tmpDir.length();
        if (d < BOND_DIST && d > 0.0001) {
          bondCount++;
          if (bd.oi === 0) c0++; else c1++;
          const m = bd.mesh;
          m.visible = true;
          tmpMid.addVectors(o.position, h.position).multiplyScalar(0.5);
          m.position.copy(tmpMid);
          m.scale.set(1, d, 1);
          tmpDir.normalize();
          tmpQ.setFromUnitVectors(UP, tmpDir);
          m.quaternion.copy(tmpQ);
        } else {
          bd.mesh.visible = false;
        }
      }

      // Halo for a finished water
      let waterOi = -1;
      if (c0 === 2) waterOi = 0;
      else if (c1 === 2) waterOi = 1;
      if (waterOi !== -1) {
        halo.visible = true;
        const o = oxygens[waterOi];
        halo.position.set(o.position.x, 0.014, o.position.z);
        const s = 1 + Math.sin(time * 4) * 0.06;
        halo.scale.set(s, s, 1);
        pad.material.emissiveIntensity = 0.45;
      } else {
        halo.visible = false;
        pad.material.emissiveIntensity = 0.18;
      }

      const sig = bondCount * 10 + (waterOi + 1);
      if (sig !== lastSig) {
        lastSig = sig;
        if (waterOi !== -1) panel.set('live', { text: 'Bonds: ' + bondCount + ' — looks like H2O! Press CHECK' });
        else panel.set('live', { text: 'Bonds: ' + bondCount + ' (need 2 on one O)' });
      }
    }
  };
}

