  halo1.position.copy(dome.position);
  halo1.scale.setScalar(1.35);
  halo1.raycast = () => {};
  root.add(halo1);

  const haloMat2 = new THREE.MeshBasicMaterial({
    color: 0x22e0ff,
    transparent: true,
    opacity: 0.09,
