  halo2.position.copy(dome.position);
  halo2.scale.setScalar(1.9);
  halo2.raycast = () => {};
  root.add(halo2);

  // ---------------------------------------------------------------------------
  // Info panel
  // ---------------------------------------------------------------------------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
