      .hint { color: #9aa3af; font-size: 20px; }
      .row { flex-direction: row; align-items: center; gap: 14px; }
      .swatch { width: 48px; height: 48px; border-radius: 12px; background-color: #22e0ff; }
      .name { color: #ffffff; font-size: 26px; font-weight: 700; }
      .count { color: #d7dbe2; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Color Button</span>
      <span class="hint">Poke or pinch the glowing dome to change its color.</span>
      <div class="row">
        <div class="swatch" id="swatch"></div>
        <span class="name" id="name">Cyan</span>
      </div>
      <span class="count" id="count">Pressed 0 times</span>
    </div>`, { width: 0.30, position: [0.27, 0.13, 0], rotationY: -0.42 });
  root.add(panel.object3D);

  // ---------------------------------------------------------------------------
  // State
  // ---------------------------------------------------------------------------
  let colorIndex = 0;
  let pressCount = 0;
  let pulse = 0; // 0..1, decays after each press

  function applyColor(i) {
    const hex = COLORS[i].hex;
    domeMat.color.setHex(hex);
    domeMat.emissive.setHex(hex);
    ringMat.color.setHex(hex);
    ringMat.emissive.setHex(hex);
    haloMat1.color.setHex(hex);
    haloMat2.color.setHex(hex);
    discMat.color.setHex(hex);
  }

  function refreshPanel() {
    panel.set('name', { text: COLORS[colorIndex].name });
    panel.set('swatch', { backgroundColor: hexString(COLORS[colorIndex].hex) });
    panel.set('count', { text: 'Pressed ' + pressCount + (pressCount === 1 ? ' time' : ' times') });
  }

  function press() {
    colorIndex = (colorIndex + 1) % COLORS.length;
    pressCount += 1;
    pulse = 1;
    applyColor(colorIndex);
    refreshPanel();
  }

  applyColor(0);
  refreshPanel();

  traits(dome, { onPress: press });
  traits(base, { onPress: press });

  // ---------------------------------------------------------------------------
  // Per-frame animation: breathing glow plus a decaying "press" flash
  // ---------------------------------------------------------------------------
  return {
    root,
    update(time, delta) {
      const d = Math.min(delta, 0.05);
      pulse = Math.max(0, pulse - d * 3.2);

      const p = pulse;
      const breathe = 0.5 + 0.5 * Math.sin(time * 2.2);

      // Squash the dome while flashing
      dome.scale.set(1 + 0.10 * p, 0.72 * (1 - 0.22 * p), 1 + 0.10 * p);

      domeMat.emissiveIntensity = 1.0 + 1.4 * p + 0.35 * breathe;
      ringMat.emissiveIntensity = 0.8 + 1.3 * p + 0.40 * breathe;

      halo1.scale.setScalar(1.35 * (1 + 0.30 * p + 0.05 * breathe));
      halo2.scale.setScalar(1.90 * (1 + 0.22 * p + 0.06 * breathe));
      haloMat1.opacity = 0.18 + 0.15 * p + 0.05 * breathe;
      haloMat2.opacity = 0.08 + 0.07 * p + 0.03 * breathe;
      discMat.opacity = 0.20 + 0.13 * p + 0.06 * breathe;

      // Slow spin on the glowing ring
      ring.rotation.z = time * 0.4;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const COLORS = [
    { hex: 0x38e1ff, name: 'Aqua' },
    { hex: 0xff4fa3, name: 'Magenta' },
    { hex: 0x7dff6b, name: 'Lime' },
    { hex: 0xffd23d, name: 'Amber' },
    { hex: 0xa06bff, name: 'Violet' },
    { hex: 0xff6b3d, name: 'Ember' },
    { hex: 0x3d7bff, name: 'Blue' },
    { hex: 0xf2f5ff, name: 'White' },
  ];

  // ---- Plinth (sits on the desk) ----
  const plinth = new THREE.Mesh(
    new THREE.CylinderGeometry(0.08, 0.086, 0.02, 40, 1),
    new THREE.MeshStandardMaterial({ color: 0x22262c, roughness: 0.85, metalness: 0.2 }),
  );
  plinth.name = 'ButtonPlinth';
  plinth.position.set(0, 0.01, 0.06);
  root.add(plinth);

  // ---- Glowing halo on the plinth surface ----
  const glowMat = new THREE.MeshBasicMaterial({
    color: COLORS[0].hex,
    transparent: true,
    opacity: 0.35,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const haloGeo = new THREE.CircleGeometry(0.088, 40);
  const halo = new THREE.Mesh(haloGeo, glowMat);
  halo.name = 'ButtonHalo';
  halo.rotation.x = -Math.PI / 2;
  halo.position.set(0, 0.0215, 0.06);
  root.add(halo);

  // ---- Accent ring around the button ----
  const ringMat = new THREE.MeshBasicMaterial({ color: COLORS[0].hex });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.081, 0.0045, 12, 48), ringMat);
  ring.name = 'ButtonRing';
  ring.rotation.x = -Math.PI / 2;
  ring.position.set(0, 0.0215, 0.06);
  root.add(ring);

  // ---- The pressable button itself ----
  const btnMat = new THREE.MeshStandardMaterial({
    color: COLORS[0].hex,
    emissive: COLORS[0].hex,
    emissiveIntensity: 0.9,
    roughness: 0.3,
    metalness: 0.15,
  });
  const button = new THREE.Mesh(new THREE.CylinderGeometry(0.052, 0.058, 0.028, 36, 1), btnMat);
  button.name = 'GlowButton';
  const BUTTON_Y = 0.034;
  button.position.set(0, BUTTON_Y, 0.06);
  root.add(button);

  // ---- Instruction / status panel ----
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; align-items: center; gap: 8px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 22px; padding-right: 22px;
              background-color: #1a1d22; border-radius: 18px; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .hint { color: #aab2be; font-size: 20px; text-align: center; }
      .row { display: flex; flex-direction: row; align-items: center; gap: 12px; }
      .swatch { width: 34px; height: 34px; border-radius: 10px; background-color: #38e1ff; }
      .name { color: #ffffff; font-size: 26px; font-weight: 700; }
      .count { color: #8f98a6; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Glow Button</span>
      <span class="hint">Press the glowing disc</span>
      <div class="row">
        <div class="swatch" id="swatch"></div>
        <span class="name" id="colorName">Aqua</span>
      </div>
      <span class="count" id="count">Pressed 0 times</span>
    </div>`, { width: 0.3, position: [0, 0.21, 0.02] });
  root.add(panel.object3D);

  // ---- State ----
  let index = 0;
  let pressCount = 0;
  let pressAnim = 1; // 0 = fully pushed down, 1 = resting
  let burst = 0;

  const targetColor = new THREE.Color(COLORS[0].hex);
  const targetEmissive = new THREE.Color(COLORS[0].hex);

  const hexString = (hex) => '#' + hex.toString(16).padStart(6, '0');

  traits(button, {
    onPress: () => {
      index = (index + 1) % COLORS.length;
      pressCount += 1;
      pressAnim = 0;
      burst = 1;
      const c = COLORS[index];
      targetColor.setHex(c.hex);
      targetEmissive.setHex(c.hex);
      btnMat.emissiveIntensity = 1.9;
      panel.set('colorName', { text: c.name });
      panel.set('swatch', { backgroundColor: hexString(c.hex) });
      panel.set('count', { text: 'Pressed ' + pressCount + (pressCount === 1 ? ' time' : ' times') });
    },
  });

  return {
    root,
    update(time, delta) {
      const d = Math.min(delta, 0.1);

      // Smoothly blend toward the new colour.
      const k = Math.min(1, d * 10);
      btnMat.color.lerp(targetColor, k);
      btnMat.emissive.lerp(targetEmissive, k);
      glowMat.color.lerp(targetColor, k);
      ringMat.color.lerp(targetColor, k);

      // Press travel: snap down, ease back up.
      pressAnim = Math.min(1, pressAnim + d * 6);
      const eased = pressAnim * pressAnim * (3 - 2 * pressAnim);
      button.position.y = BUTTON_Y - 0.011 * (1 - eased);

      // Glow: gentle breathing plus a flare on each press.
      burst = Math.max(0, burst - d * 1.6);
      btnMat.emissiveIntensity += (0.9 + 0.35 * Math.sin(time * 2.2) + 1.1 * burst - btnMat.emissiveIntensity) * Math.min(1, d * 8);
      glowMat.opacity = 0.24 + 0.08 * (0.5 + 0.5 * Math.sin(time * 2.6)) + 0.4 * burst;

      const s = 1 + 0.05 * Math.sin(time * 2.6) + 0.3 * burst;
      halo.scale.set(s, s, s);
      const rs = 1 + 0.02 * Math.sin(time * 2.2 + 1.0);
      ring.scale.set(rs, rs, 1);
    },
  };
}

