      <div class="row"><div class="left"><span class="dotR">●</span><span class="fname">Apple</span><span class="fprice">$1.20</span></div><span class="status" id="appleStatus">On table</span></div>
      <div class="row"><div class="left"><span class="dotY">●</span><span class="fname">Banana</span><span class="fprice">$0.80</span></div><span class="status" id="bananaStatus">On table</span></div>
      <div class="row"><div class="left"><span class="dotO">●</span><span class="fname">Orange</span><span class="fprice">$1.50</span></div><span class="status" id="orangeStatus">On table</span></div>
      <div class="totalBox"><span class="totalLabel">Basket total</span><span class="totalVal" id="total">$0.00</span></div>
      <span class="count" id="count">0 of 3 fruits in basket</span>
      <button class="btn" id="reset"><span class="btn-text">Reset basket</span></button>
    </div>`, { width: 0.31, position: [0.30, 0.23, 0.0], rotationY: -0.35 });
  root.add(panel.object3D);

  function refreshPanel() {
    let total = 0;
    let n = 0;
    for (const f of fruits) {
      if (f.inBasket) { total += f.price; n += 1; }
    }
    const totalStr = '$' + total.toFixed(2);
    panel.set('total', { text: totalStr });
    let countStr = n + ' of 3 fruits in basket';
    if (n === 3) countStr = 'All 3 fruits in basket!';
    panel.set('count', { text: countStr });
    for (const f of fruits) {
      if (f.inBasket) panel.set(f.statusId, { text: 'In basket', color: '#7dff9b' });
      else panel.set(f.statusId, { text: 'On table', color: '#9aa0ab' });
    }
  }
  refreshPanel();

  panel.on('reset', 'click', () => {
    for (const f of fruits) {
      f.inBasket = false;
      f.wasGrabbed = false;
      f.group.position.set(f.home[0], f.home[1], f.home[2]);
    }
    banana.rotation.set(0, 0.5, 0.15);
    refreshPanel();
  });

  const basketX = 0;
  const basketZ = -0.05;
  let panelDirty = false;

  return {
    root,
    update(time, delta) {
      const d = Math.min(delta, 0.05);
      panelDirty = false;
      let hover = false;

      for (const f of fruits) {
        const g = f.group;
        const grabbed = isGrabbed(g);
        if (grabbed) {
          if (f.inBasket) {
            f.inBasket = false;
            panelDirty = true;
          }
          f.wasGrabbed = true;
          const dx = g.position.x - basketX;
          const dz = g.position.z - basketZ;
          if (dx * dx + dz * dz < 0.0144 && g.position.y < 0.26) hover = true;
        } else {
          if (f.inBasket) {
            const k = Math.min(1, d * 10);
            g.position.x += (f.slot[0] - g.position.x) * k;
            g.position.y += (f.slot[1] - g.position.y) * k;
            g.position.z += (f.slot[2] - g.position.z) * k;
            f.wasGrabbed = false;
          } else {
            if (f.wasGrabbed) {
              const dx = g.position.x - basketX;
              const dz = g.position.z - basketZ;
              const dist2 = dx * dx + dz * dz;
              if (dist2 < 0.010 && g.position.y < 0.22 && g.position.y > 0.015) {
                f.inBasket = true;
                g.position.set(f.slot[0], f.slot[1], f.slot[2]);
                panelDirty = true;
              }
              f.wasGrabbed = false;
            }
            if (!f.inBasket && g.position.y > f.restY) {
              g.position.y -= d * 0.3;
              if (g.position.y < f.restY) g.position.y = f.restY;
            }
            if (!f.inBasket && g.position.y < f.restY) g.position.y = f.restY;
          }
        }
      }

      if (panelDirty) refreshPanel();

      rimMat.emissiveIntensity = hover ? 0.9 + 0.4 * Math.sin(time * 7) : 0.25;

      let inCount = 0;
      for (const f of fruits) if (f.inBasket) inCount += 1;
      arrow.visible = inCount < 3;
      if (arrow.visible) {
        arrow.position.y = 0.29 + 0.012 * Math.sin(time * 2.2);
        arrow.rotation.y = time * 0.8;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Helix parameters ----------
  const N = 14;               // number of base pairs
  const RISE = 0.024;         // vertical distance between base pairs (m)
  const RADIUS = 0.058;       // helix radius (m)
  const TWIST = 0.62;         // radians of twist per base pair (~35.5°)
  const BEAD_R = 0.0115;      // backbone bead radius
  const LINK_R = 0.0075;      // backbone link radius
  const RUNG_R = 0.0058;      // base-pair rung radius

  const SEQ = 'ATGCCTAGGTACGA';
  const COMP = { A: 'T', T: 'A', G: 'C', C: 'G' };
  const BASE_COLOR = { A: 0x4bd66b, T: 0xff5d5d, G: 0x4f9dff, C: 0xffd24b };
  const STRAND_A = 0x9fd8ff;
  const STRAND_B = 0xffc48f;

  const yOf = (i) => (i - (N - 1) / 2) * RISE;

  // Points along the two sugar-phosphate backbones
  const ptsA = [];
  const ptsB = [];
  for (let i = 0; i < N; i++) {
    const a = i * TWIST;
    const y = yOf(i);
    ptsA.push(new THREE.Vector3(Math.cos(a) * RADIUS, y, Math.sin(a) * RADIUS));
    ptsB.push(new THREE.Vector3(
      Math.cos(a + Math.PI) * RADIUS, y, Math.sin(a + Math.PI) * RADIUS,
    ));
  }

  // ---------- Shared geometry & materials ----------
  const beadGeo = new THREE.SphereGeometry(1, 12, 8);
  const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 8);

  const beadMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.32, metalness: 0.25 });
  const linkMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.45, metalness: 0.15 });
  const rungMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.6, metalness: 0.05 });

  const beads = new THREE.InstancedMesh(beadGeo, beadMat, N * 2);
  const links = new THREE.InstancedMesh(cylGeo, linkMat, (N - 1) * 2);
  const rungs = new THREE.InstancedMesh(cylGeo, rungMat, N * 2);
  beads.name = 'BackboneBeads';
  links.name = 'BackboneLinks';
  rungs.name = 'BasePairs';
  beads.frustumCulled = false;
  links.frustumCulled = false;
  rungs.frustumCulled = false;

  const dummy = new THREE.Object3D();
  const UP = new THREE.Vector3(0, 1, 0);
  const _dir = new THREE.Vector3();
  const _mid = new THREE.Vector3();
  const _col = new THREE.Color();

  function placeCylinder(mesh, index, p1, p2, radius) {
    _dir.subVectors(p2, p1);
    const len = _dir.length();
    _mid.addVectors(p1, p2).multiplyScalar(0.5);
    dummy.position.copy(_mid);
    dummy.quaternion.setFromUnitVectors(UP, _dir.normalize());
    dummy.scale.set(radius, len, radius);
    dummy.updateMatrix();
    mesh.setMatrixAt(index, dummy.matrix);
  }

  // Backbone beads
  let bi = 0;
  for (let i = 0; i < N; i++) {
    for (let s = 0; s < 2; s++) {
      const p = s === 0 ? ptsA[i] : ptsB[i];
      dummy.position.copy(p);
      dummy.quaternion.identity();
      dummy.scale.setScalar(BEAD_R);
      dummy.updateMatrix();
      beads.setMatrixAt(bi, dummy.matrix);
      beads.setColorAt(bi, _col.setHex(s === 0 ? STRAND_A : STRAND_B));
      bi++;
    }
  }

  // Backbone links (sugar-phosphate chain between beads)
  let li = 0;
  for (let i = 0; i < N - 1; i++) {
    placeCylinder(links, li, ptsA[i], ptsA[i + 1], LINK_R);
    links.setColorAt(li, _col.setHex(STRAND_A));
    li++;
    placeCylinder(links, li, ptsB[i], ptsB[i + 1], LINK_R);
    links.setColorAt(li, _col.setHex(STRAND_B));
    li++;
  }

  // Base-pair rungs: half from each backbone to the axis, coloured by base
  const center = new THREE.Vector3();
  let ri = 0;
  for (let i = 0; i < N; i++) {
    const b = SEQ[i];
    center.set(0, yOf(i), 0);

    placeCylinder(rungs, ri, center, ptsA[i], RUNG_R);
    rungs.setColorAt(ri, _col.setHex(BASE_COLOR[b]));
    ri++;

    placeCylinder(rungs, ri, center, ptsB[i], RUNG_R);
    rungs.setColorAt(ri, _col.setHex(BASE_COLOR[COMP[b]]));
    ri++;
  }

  beads.instanceMatrix.needsUpdate = true;
  links.instanceMatrix.needsUpdate = true;
  rungs.instanceMatrix.needsUpdate = true;
  if (beads.instanceColor) beads.instanceColor.needsUpdate = true;
  if (links.instanceColor) links.instanceColor.needsUpdate = true;
  if (rungs.instanceColor) rungs.instanceColor.needsUpdate = true;

  beads.computeBoundingSphere();
  links.computeBoundingSphere();
  rungs.computeBoundingSphere();

  // ---------- The grabbable helix ----------
  const helix = new THREE.Group();
  helix.name = 'DNAHelix';
  helix.add(beads, links, rungs);
  helix.position.set(0, 0.19, 0);
  root.add(helix);

  // ---------- Info panel ----------
  const facts = [
    'Two strands twist around one axis, about 10.5 base pairs per full turn.',
    'A always pairs with T (2 hydrogen bonds); G always pairs with C (3).',
    'Each base pair sits 0.34 nm above the next, so one turn is 3.4 nm.',
    'The strands are antiparallel: one runs 5\u2032\u21923\u2032, the other 3\u2032\u21925\u2032.',
    'Your cells hold about 3 billion base pairs \u2014 roughly 2 m of DNA each.',
  ];
  let factIndex = 0;
  let spinning = true;

  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px;
              background-color: #1c1f26; width: 460px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #cfd6e0; font-size: 21px; }
      .row { flex-direction: row; align-items: center; gap: 8px; }
      .dot { width: 16px; height: 16px; border-radius: 8px; }
      .dotA { background-color: #4bd66b; }
      .dotT { background-color: #ff5d5d; }
      .dotG { background-color: #4f9dff; }
      .dotC { background-color: #ffd24b; }
      .lbl { color: #cfd6e0; font-size: 19px; margin-right: 10px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { background-color: #3a3f4a; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DNA Double Helix</span>
      <span class="body" id="fact">Pinch the helix to pick it up and turn it around.</span>
      <div class="row">
        <div class="dot dotA"></div><span class="lbl">A</span>
        <div class="dot dotT"></div><span class="lbl">T</span>
        <div class="dot dotG"></div><span class="lbl">G</span>
        <div class="dot dotC"></div><span class="lbl">C</span>
      </div>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next fact</span></button>
        <button class="btn btn2" id="spin"><span class="btn-text" id="spinlabel">Spin: on</span></button>
      </div>
    </div>`, { width: 0.34, position: [0.3, 0.25, 0], rotationY: -0.4 });
  root.add(info.object3D);

  function nextFact() {
    factIndex = (factIndex + 1) % facts.length;
    info.set('fact', { text: facts[factIndex] });
  }

  info.on('next', 'click', nextFact);
  info.on('spin', 'click', () => {
    spinning = !spinning;
    info.set('spinlabel', { text: spinning ? 'Spin: on' : 'Spin: off' });
  });

  traits(helix, { grab: true, onPress: nextFact });

  // ---------- Frame update ----------
  return {
    root,
    update(time, delta) {
      if (spinning && !isGrabbed(helix)) {
        helix.rotation.y += Math.min(delta, 0.05) * 0.35;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- helix
  const helix = new THREE.Group();
  helix.name = 'DNA';
  helix.position.set(-0.09, 0.16, 0);
  helix.rotation.y = 0.35;
  root.add(helix);

  const R = 0.05;      // helix radius
  const H = 0.28;      // height
  const TURNS = 2.5;   // full twists

  const _m = new THREE.Matrix4();
  const _c = new THREE.Color();
  const up = new THREE.Vector3(0, 1, 0);

  // --- sugar-phosphate backbones: two strands of beads -------------------
  const N = 48;
  const sphereGeo = new THREE.SphereGeometry(0.011, 12, 8);
  const backboneMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.35, metalness: 0.2,
  });
  const backbone = new THREE.InstancedMesh(sphereGeo, backboneMat, N * 2);
  backbone.name = 'backbone';

  const strandColors = [0x7f9cff, 0xffa04d];
  let k = 0;
  for (let s = 0; s < 2; s++) {
    for (let i = 0; i < N; i++) {
      const t = i / (N - 1);
      const a = t * TURNS * Math.PI * 2 + s * Math.PI;
      _m.makeTranslation(Math.cos(a) * R, t * H - H / 2, Math.sin(a) * R);
      backbone.setMatrixAt(k, _m);
      _c.setHex(strandColors[s]);
      backbone.setColorAt(k, _c);
      k++;
    }
  }
  backbone.instanceMatrix.needsUpdate = true;
  backbone.instanceColor.needsUpdate = true;
  helix.add(backbone);

  // --- base pairs: 12 rungs, each split into two coloured bases ----------
  const PAIRS = [
    ['A', 'T'], ['G', 'C'], ['T', 'A'], ['C', 'G'], ['G', 'C'], ['A', 'T'],
    ['C', 'G'], ['T', 'A'], ['A', 'T'], ['G', 'C'], ['C', 'G'], ['A', 'T'],
  ];
  const BASE_COLORS = { A: 0xff5a5a, T: 0x5aa9ff, G: 0x5ce08a, C: 0xffd24d };

  const rungGeo = new THREE.CylinderGeometry(0.005, 0.005, 1, 6, 1);
  const rungMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 0.5, metalness: 0.05,
  });
  const rungs = new THREE.InstancedMesh(rungGeo, rungMat, PAIRS.length * 2);
  rungs.name = 'basePairs';

  const pa = new THREE.Vector3();
  const pb = new THREE.Vector3();
  const dir = new THREE.Vector3();
  const mid = new THREE.Vector3();
  const q = new THREE.Quaternion();
  const scl = new THREE.Vector3(1, R, 1);

  let r = 0;
  for (let i = 0; i < PAIRS.length; i++) {
    const t = (i + 0.5) / PAIRS.length;
    const a = t * TURNS * Math.PI * 2;
    const y = t * H - H / 2;
    pa.set(Math.cos(a) * R, y, Math.sin(a) * R);
    pb.set(-Math.cos(a) * R, y, -Math.sin(a) * R);
    dir.subVectors(pb, pa).normalize();
    q.setFromUnitVectors(up, dir);

    mid.copy(pa).addScaledVector(dir, R * 0.5);
    _m.compose(mid, q, scl);
    rungs.setMatrixAt(r, _m);
    _c.setHex(BASE_COLORS[PAIRS[i][0]]);
    rungs.setColorAt(r, _c);
    r++;

    mid.copy(pa).addScaledVector(dir, R * 1.5);
    _m.compose(mid, q, scl);
    rungs.setMatrixAt(r, _m);
    _c.setHex(BASE_COLORS[PAIRS[i][1]]);
    rungs.setColorAt(r, _c);
    r++;
  }
  rungs.instanceMatrix.needsUpdate = true;
  rungs.instanceColor.needsUpdate = true;
  helix.add(rungs);

  // ---------------------------------------------------------------- panel
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px;
              background-color: #1a1d22; border-width: 1px; border-color: #333a44; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .body { color: #cfd6e0; font-size: 20px; }
      .row { flex-direction: row; gap: 10px; align-items: center; }
      .btn { padding-top: 9px; padding-bottom: 9px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .alt { background-color: #3b4250; }
      .btntext { color: #ffffff; font-size: 19px; font-weight: 700; }
      .dot { width: 16px; height: 16px; border-radius: 8px; }
      .dotA { background-color: #ff5a5a; }
      .dotT { background-color: #5aa9ff; }
      .dotG { background-color: #5ce08a; }
      .dotC { background-color: #ffd24d; }
      .lbl { color: #cfd6e0; font-size: 18px; }
    </style>
    <div class="card">
      <span class="title">DNA double helix</span>
      <span class="body" id="fact">Pinch the helix to pick it up and turn it in your hand.</span>
      <div class="row">
        <button class="btn" id="spin"><span class="btntext" id="spinlabel">Spin</span></button>
        <button class="btn alt" id="turn"><span class="btntext">Turn 90°</span></button>
      </div>
      <div class="row">
        <button class="btn alt" id="factbtn"><span class="btntext">Next fact</span></button>
      </div>
      <div class="row">
        <div class="dot dotA"></div><span class="lbl">A</span>
        <div class="dot dotT"></div><span class="lbl">T</span>
        <div class="dot dotG"></div><span class="lbl">G</span>
        <div class="dot dotC"></div><span class="lbl">C</span>
      </div>
    </div>`, { width: 0.34, position: [0.28, 0.17, 0.02], rotationY: -0.4 });
  root.add(info.object3D);

  // ---------------------------------------------------------------- state
  const facts = [
    'The two strands are antiparallel: they run in opposite directions.',
    'A always pairs with T (2 hydrogen bonds); G pairs with C (3 hydrogen bonds).',
    'One full turn of B-DNA covers about 10 base pairs and rises 3.4 nm.',
    'Each of your cells holds roughly 3 billion base pairs of DNA.',
    'The double helix was described in 1953, using Rosalind Franklin’s X-ray images.',
    'The sugar-phosphate backbones sit on the outside; the bases point inward.',
  ];
  let factIndex = 0;

  const SPIN_SPEED = 0.5;   // rad/s -> rim speed 0.025 m/s
  const TURN_SPEED = 0.9;   // rad/s -> rim speed 0.045 m/s
  let spinning = false;
  let targetAngle = helix.rotation.y;

  function setSpin(on) {
    spinning = on;
    if (!on) targetAngle = helix.rotation.y;
    info.set('spinlabel', { text: on ? 'Stop' : 'Spin' });
    info.set('spin', { backgroundColor: on ? '#c2410c' : '#2f6fdb' });
  }

  info.on('spin', 'click', () => setSpin(!spinning));
  info.on('turn', 'click', () => {
    if (spinning) setSpin(false);
    targetAngle = helix.rotation.y + Math.PI / 2;
  });
  info.on('factbtn', 'click', () => {
    factIndex = (factIndex + 1) % facts.length;
    info.set('fact', { text: facts[factIndex] });
  });

  traits(helix, { grab: true, onPress: () => setSpin(!spinning) });

  // ---------------------------------------------------------------- loop
  return {
    root,
    update(time, delta) {
      if (isGrabbed(helix)) {
        targetAngle = helix.rotation.y; // resync, never fight the hand
        return;
      }
      if (spinning) {
        helix.rotation.y += SPIN_SPEED * delta;
        targetAngle = helix.rotation.y;
      } else {
        const d = targetAngle - helix.rotation.y;
        if (Math.abs(d) > 1e-4) {
          const step = Math.min(Math.abs(d), TURN_SPEED * delta);
          helix.rotation.y += Math.sign(d) * step;
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
