  const appleGeo = new THREE.SphereGeometry(0.035, 24, 14);
  const stemGeo = new THREE.CylinderGeometry(0.004, 0.005, 0.02, 8);
  const leafGeo = new THREE.SphereGeometry(0.012, 12, 8);
  const orangeGeo = new THREE.SphereGeometry(0.033, 24, 14);
  const tipGeo = new THREE.SphereGeometry(0.006, 10, 8);

  // Apple
