  aStem.position.y = 0.04;
  apple.add(aStem);
  const aLeaf = new THREE.Mesh(leafGeo, leafMat);
  aLeaf.scale.set(1.5, 0.4, 0.8);
  aLeaf.position.set(0.014, 0.042, 0);
  aLeaf.rotation.z = 0.5;
  apple.add(aLeaf);
  apple.position.set(-0.26, 0.043, 0.10);
  root.add(apple);
  traits(apple, { grab: true });

  // Banana (curved torus lying flat)
  const banana = new THREE.Group();
  banana.name = 'Banana';
  const bananaInner = new THREE.Group();
  bananaInner.rotation.x = Math.PI / 2;
  bananaInner.rotation.z = 0.4;
  banana.add(bananaInner);
  const arc = 1.9;
  const R = 0.032;
  const bananaTube = new THREE.Mesh(new THREE.TorusGeometry(R, 0.011, 12, 22, arc), bananaMat);
  bananaTube.name = 'Banana';
  bananaInner.add(bananaTube);
  const tip0 = new THREE.Mesh(tipGeo, tipMat);
  tip0.position.set(R, 0, 0);
  bananaInner.add(tip0);
  const tip1 = new THREE.Mesh(tipGeo, tipMat);
  tip1.position.set(R * Math.cos(arc), R * Math.sin(arc), 0);
  bananaInner.add(tip1);
  banana.position.set(0, 0.021, 0.14);
  root.add(banana);
  traits(banana, { grab: true });

  // Orange
  const orange = new THREE.Group();
  orange.name = 'Orange';
  const orangeBody = new THREE.Mesh(orangeGeo, orangeMat);
  orangeBody.name = 'Orange';
  orange.add(orangeBody);
  const oStem = new THREE.Mesh(stemGeo, stemMat);
