    { group: banana, name: 'Banana', price: 0.60, home: new THREE.Vector3(0, 0.021, 0.14), slot: new THREE.Vector3(0.038, 0.052, -0.12), restY: 0.013, inBasket: false, pop: -10 },
    { group: orange, name: 'Orange', price: 0.90, home: new THREE.Vector3(0.26, 0.041, 0.10), slot: new THREE.Vector3(0.0, 0.105, -0.14), restY: 0.033, inBasket: false, pop: -10 }
  ];

  // ---------- Main panel ----------
  const main = ui(`
