      <span class="row" id="row-orange">Orange $0.90 — table</span>
      <span class="total" id="total">Total: $0.00</span>
      <span class="sub" id="hint">Basket is empty</span>
      <button class="btn" id="reset"><span class="btn-text">Reset fruit</span></button>
    </div>`, { width: 0.28, position: [0.27, 0.23, -0.04], rotationY: -0.38 });
  root.add(main.object3D);

  function refresh() {
    let total = 0;
    let count = 0;
    for (let i = 0; i < fruits.length; i++) {
      if (fruits[i].inBasket) { total += fruits[i].price; count++; }
    }
    main.set('total', { text: 'Total: $' + total.toFixed(2) });
    const ids = ['row-apple', 'row-banana', 'row-orange'];
    for (let i = 0; i < fruits.length; i++) {
      const inB = fruits[i].inBasket;
      const label = fruits[i].name + ' $' + fruits[i].price.toFixed(2) + (inB ? ' — in basket!' : ' — table');
      main.set(ids[i], { text: label, color: inB ? '#7dff9b' : '#d7dbe2' });
    }
    let hint = 'Basket is empty';
    if (count === 1) hint = '1 fruit in basket';
    if (count === 2) hint = '2 fruits in basket';
    if (count === 3) hint = 'All 3! Yummy!';
    main.set('hint', { text: hint });
  }
  refresh();

  main.on('reset', 'click', () => {
    for (let i = 0; i < fruits.length; i++) {
      fruits[i].group.position.copy(fruits[i].home);
      fruits[i].group.scale.set(1, 1, 1);
      fruits[i].inBasket = false;
    }
    refresh();
  });

  // ---------- Small price tags ----------
  function tag(text, pos) {
    const h = ui(`
      <style>
        .tag { padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #2a2e35; align-items: center; justify-content: center; }
        .t { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      </style>
      <div class="tag"><span class="t">${text}</span></div>`, { width: 0.14, position: pos });
    root.add(h.object3D);
    return h;
  }
  tag('Apple $1.20', [-0.26, 0.125, 0.03]);
  tag('Banana $0.60', [0, 0.125, 0.07]);
  tag('Orange $0.90', [0.26, 0.125, 0.03]);

  return {
    root,
    update(time, delta) {
      const d = Math.min(delta, 0.05);
      let anyHover = false;

      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const p = f.group.position;
        const dx = p.x - BASKET_X;
        const dz = p.z - BASKET_Z;
        const distSq = dx * dx + dz * dz;
        const inside = distSq < BASKET_R * BASKET_R && p.y > BASKET_BOT && p.y < BASKET_TOP;
        const held = isGrabbed(f.group);

        if (held) {
          const hover = distSq < 0.0121 && p.y > 0.03 && p.y < 0.34;
          if (hover) anyHover = true;
          if (f.inBasket && !inside) {
            f.inBasket = false;
            refresh();
          }
          // pop scale back to normal while held
          const s = f.group.scale.x;
          if (s > 1.01) {
            const ns = Math.max(1, s - d * 2.5);
            f.group.scale.set(ns, ns, ns);
          }
        } else {
          if (!f.inBasket && inside) {
            f.inBasket = true;
            f.pop = time;
            refresh();
          }
          if (f.inBasket) {
            const k = Math.min(1, d * 5);
            p.x += (f.slot.x - p.x) * k;
            p.y += (f.slot.y - p.y) * k;
            p.z += (f.slot.z - p.z) * k;
            const age = time - f.pop;
            let target = 1;
            if (age < 0.35) target = 1 + 0.45 * (1 - age / 0.35);
            const cs = f.group.scale.x;
            const ns = cs + (target - cs) * Math.min(1, d * 12);
            f.group.scale.set(ns, ns, ns);
          } else {
            // settle to desk if released in mid-air outside basket
            if (p.y > f.restY + 0.002) {
              p.y = Math.max(f.restY, p.y - d * 0.25);
            } else if (p.y < f.restY - 0.002) {
              p.y = f.restY;
            }
            const cs2 = f.group.scale.x;
            if (cs2 !== 1) f.group.scale.set(1, 1, 1);
          }
        }
      }

      hoverRing.visible = anyHover;
      if (anyHover) {
        const pulse = 1 + 0.06 * Math.sin(time * 7);
        hoverRing.scale.set(pulse, pulse, 1);
        hoverMat.opacity = 0.65 + 0.3 * Math.sin(time * 7);
        rimMat.emissiveIntensity = 0.9;
      } else {
        rimMat.emissiveIntensity = 0.0;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const TAU = Math.PI * 2;

  // ---------------- materials (shared) ----------------
  const bodyMat = new THREE.MeshStandardMaterial({ color: 0x2c313a, roughness: 0.42, metalness: 0.75 });
  const rimMat = new THREE.MeshStandardMaterial({ color: 0x99a2ae, roughness: 0.28, metalness: 0.9 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf3f0e8, roughness: 0.95, metalness: 0.0 });
  const inkMat = new THREE.MeshStandardMaterial({ color: 0x22262c, roughness: 0.6, metalness: 0.1 });
  const handMat = new THREE.MeshStandardMaterial({ color: 0x1b1f25, roughness: 0.45, metalness: 0.4 });
  const secondMat = new THREE.MeshStandardMaterial({
    color: 0xd94a3d, roughness: 0.5, metalness: 0.2,
    emissive: 0x54110d, emissiveIntensity: 0.6,
  });

  // ---------------- the clock ----------------
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  clock.position.set(-0.13, 0, 0);
  root.add(clock);

  // foot
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.052, 0.061, 0.016, 32), bodyMat);
  base.name = 'ClockBase';
  base.position.y = 0.008;
  clock.add(base);

  // neck
  const stem = new THREE.Mesh(new THREE.BoxGeometry(0.028, 0.046, 0.020), bodyMat);
  stem.name = 'ClockStem';
  stem.position.y = 0.032;
  clock.add(stem);

  // round case, flat faces pointing at the user
  const bodyGeo = new THREE.CylinderGeometry(0.085, 0.085, 0.030, 48);
  bodyGeo.rotateX(Math.PI / 2);
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.name = 'ClockBody';
  body.position.y = 0.115;
  clock.add(body);

  // dial
  const face = new THREE.Mesh(new THREE.CircleGeometry(0.076, 48), faceMat);
  face.name = 'ClockFace';
  face.position.set(0, 0.115, 0.0154);
  clock.add(face);

  const bezel = new THREE.Mesh(new THREE.RingGeometry(0.076, 0.0845, 48), rimMat);
  bezel.name = 'ClockBezel';
  bezel.position.set(0, 0.115, 0.0152);
  clock.add(bezel);

  // hour ticks
  const tickGeo = new THREE.BoxGeometry(0.0035, 0.008, 0.0018);
  const tickBigGeo = new THREE.BoxGeometry(0.0055, 0.013, 0.0018);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    const big = i % 3 === 0;
    const t = new THREE.Mesh(big ? tickBigGeo : tickGeo, inkMat);
    const r = 0.0615;
    t.position.set(Math.sin(a) * r, 0.115 + Math.cos(a) * r, 0.0168);
    t.rotation.z = -a;
    clock.add(t);
  }

  // hands (each on its own pivot, pointing up at 12)
  const hourGeo = new THREE.BoxGeometry(0.0075, 0.038, 0.0015);
  hourGeo.translate(0, 0.038 / 2 - 0.006, 0);
  const minuteGeo = new THREE.BoxGeometry(0.0055, 0.056, 0.0015);
  minuteGeo.translate(0, 0.056 / 2 - 0.006, 0);
  const secondGeo = new THREE.BoxGeometry(0.0022, 0.064, 0.0012);
  secondGeo.translate(0, 0.064 / 2 - 0.010, 0);

  const hourHand = new THREE.Group();
  hourHand.name = 'HourHand';
  hourHand.position.set(0, 0.115, 0.0190);
  hourHand.add(new THREE.Mesh(hourGeo, handMat));
  clock.add(hourHand);

  const minuteHand = new THREE.Group();
  minuteHand.name = 'MinuteHand';
  minuteHand.position.set(0, 0.115, 0.0205);
  minuteHand.add(new THREE.Mesh(minuteGeo, handMat));
  clock.add(minuteHand);

  const secondHand = new THREE.Group();
  secondHand.name = 'SecondHand';
  secondHand.position.set(0, 0.115, 0.0225);
  secondHand.add(new THREE.Mesh(secondGeo, secondMat));
  clock.add(secondHand);

  // centre hub
  const hubGeo = new THREE.CylinderGeometry(0.0075, 0.0075, 0.009, 24);
  hubGeo.rotateX(Math.PI / 2);
  const hub = new THREE.Mesh(hubGeo, rimMat);
  hub.name = 'ClockHub';
  hub.position.set(0, 0.115, 0.0205);
  clock.add(hub);

  // ---------------- readout panel ----------------
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; align-items: center; gap: 10px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 24px; padding-right: 24px;
              background-color: #191c21; border-radius: 22px; }
      .title { color: #8f9aab; font-size: 18px; font-weight: 700; text-align: center; }
      .time { color: #ffffff; font-size: 66px; font-weight: 700; text-align: center; }
      .sub { color: #cdd4de; font-size: 19px; text-align: center; }
      .row { display: flex; flex-direction: row; gap: 12px; margin-top: 6px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px;
             border-radius: 14px; background-color: #2b3038; }
      .btn-text { color: #eaf0f8; font-size: 19px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">DESK CLOCK</span>
      <span class="time" id="time">--:--</span>
      <span class="sub">Pinch to move · press the clock to switch format</span>
      <div class="row">
        <button class="btn" id="fmt"><span class="btn-text" id="fmt-text">12-hour</span></button>
        <button class="btn" id="sec"><span class="btn-text" id="sec-text">Second hand: on</span></button>
      </div>
    </div>`, { width: 0.30, position: [0.14, 0.13, 0.03], rotationY: -0.35 });
  root.add(panel.object3D);

  // ---------------- time logic ----------------
  const tzOffsetMs = new Date().getTimezoneOffset() * 60000; // local = UTC - offset

  let use24 = true;
  let showSeconds = true;
  let curH = -1;
  let curM = -1;

  function pad2(n) { return n < 10 ? '0' + n : '' + n; }

  function renderDigital() {
    let txt;
    if (use24) {
      txt = pad2(curH) + ':' + pad2(curM);
    } else {
      const h12 = curH % 12 === 0 ? 12 : curH % 12;
      txt = h12 + ':' + pad2(curM) + (curH < 12 ? ' AM' : ' PM');
    }
    panel.set('time', { text: txt });
  }

  function renderFormatLabel() {
    panel.set('fmt-text', { text: use24 ? '12-hour' : '24-hour' });
  }

  function renderSecondsLabel() {
    panel.set('sec-text', { text: showSeconds ? 'Second hand: on' : 'Second hand: off' });
  }

  function toggleFormat() {
    use24 = !use24;
    renderFormatLabel();
    if (curH >= 0) renderDigital();
  }

  function toggleSeconds() {
    showSeconds = !showSeconds;
    secondHand.visible = showSeconds;
    renderSecondsLabel();
  }

  renderFormatLabel();
  renderSecondsLabel();

  panel.on('fmt', 'click', toggleFormat);
  panel.on('sec', 'click', toggleSeconds);

  traits(clock, { grab: true, onPress: toggleFormat });

  return {
    root,
    update(time, delta) {
      const localSec = (Date.now() - tzOffsetMs) / 1000;
      const s = Math.floor(localSec) % 60;
      const m = Math.floor(localSec / 60) % 60;
      const h = Math.floor(localSec / 3600) % 24;

      if (h !== curH || m !== curM) {
        curH = h;
        curM = m;
        renderDigital();
      }

      hourHand.rotation.z = -(((h % 12) + m / 60 + s / 3600) / 12) * TAU;
      minuteHand.rotation.z = -(((m + s / 60) / 60)) * TAU;
      if (showSeconds) {
        secondHand.rotation.z = -((localSec % 60) / 60) * TAU;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const TAU = Math.PI * 2;

  // ---------- materials ----------
  const metalMat = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.42, metalness: 0.6 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x1a1d22, roughness: 0.5, metalness: 0.35 });
  const faceMat = new THREE.MeshStandardMaterial({ color: 0xf1efe7, roughness: 0.9, metalness: 0.0 });
  const tickMat = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.6, metalness: 0.25 });
  const secMat = new THREE.MeshStandardMaterial({
    color: 0xe0503a, roughness: 0.35, metalness: 0.2, emissive: 0x40100a, emissiveIntensity: 0.6,
  });

  // ---------- clock body ----------
  const clock = new THREE.Group();
  clock.name = 'DeskClock';
  root.add(clock);

  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.056, 0.062, 0.014, 40), metalMat);
  base.name = 'ClockBase';
  base.position.set(0, 0.007, -0.004);
  clock.add(base);

  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.011, 0.013, 0.042, 20), metalMat);
  stem.position.set(0, 0.032, -0.005);
  clock.add(stem);

