  const tickGeo = new THREE.BoxGeometry(1, 1, 1);
  const ticks = new THREE.InstancedMesh(tickGeo, tickMat, 60);
  ticks.name = 'Ticks';
  const m4 = new THREE.Matrix4();
  const q = new THREE.Quaternion();
  const p = new THREE.Vector3();
  const s = new THREE.Vector3();
  const zAxis = new THREE.Vector3(0, 0, 1);
  for (let i = 0; i < 60; i++) {
    const major = i % 5 === 0;
    const ang = (i / 60) * TAU;
    const len = major ? 0.015 : 0.007;
    const wid = major ? 0.006 : 0.0025;
    const rIn = major ? 0.058 : 0.066;
    const rMid = rIn + len / 2;
    p.set(Math.sin(ang) * rMid, Math.cos(ang) * rMid, 0.0102);
    q.setFromAxisAngle(zAxis, -ang);
    s.set(wid, len, 0.002);
    m4.compose(p, q, s);
