  }

  const hourHand = makeHand('HourHand', 0.042, 0.009, 0.004, 0.009, 0.012, darkMat);
  const minuteHand = makeHand('MinuteHand', 0.062, 0.006, 0.004, 0.011, 0.014, darkMat);
  const secondHand = makeHand('SecondHand', 0.066, 0.0028, 0.002, 0.016, 0.016, secMat);

  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.0065, 0.0065, 0.006, 20), darkMat);
  cap.rotation.x = Math.PI / 2;
  cap.position.z = 0.018;
  cap.name = 'CenterCap';
  head.add(cap);

  // ---------- digital panel ----------
  let use24 = true;
  let lastKey = '';

  const panel = ui(`
    <style>
      .card { flex-direction: column; align-items: flex-start; gap: 10px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 24px; padding-right: 24px;
              border-radius: 20px; background-color: #1a1d22; width: 360px; }
      .time { color: #ffffff; font-size: 68px; font-weight: 700; }
      .sub { color: #9aa3ae; font-size: 20px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="time" id="time">--:--</span>
      <span class="sub" id="sub">Reading your device clock</span>
      <button class="btn" id="fmt"><span class="btn-text" id="fmtLabel">Format: 24-hour</span></button>
    </div>`, { width: 0.24, position: [0.235, 0.15, 0.03], rotationY: -0.34 });
  root.add(panel.object3D);

