  // ---------- timekeeping ----------
  const tzOffsetMs = -new Date().getTimezoneOffset() * 60000;
  const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const pad = (n) => (n < 10 ? '0' + n : '' + n);

  return {
