    update(time) {
      const now = Date.now() + tzOffsetMs;
      const secOfDay = (now % 86400000) / 1000;
      const h24 = Math.floor(secOfDay / 3600);
      const mins = Math.floor((secOfDay % 3600) / 60);
      const secs = secOfDay % 60;

      // clockwise rotation as seen by the viewer = negative Z rotation
      hourHand.rotation.z = -(((h24 % 12) + mins / 60 + secs / 3600) / 12) * TAU;
      minuteHand.rotation.z = -((mins + secs / 60) / 60) * TAU;
      secondHand.rotation.z = -(secs / 60) * TAU;

      const si = Math.floor(secs);
      const key = h24 + ':' + mins + ':' + si;
      if (key !== lastKey) {
        lastKey = key;

        let timeText;
        if (use24) {
          timeText = pad(h24) + ':' + pad(mins);
        } else {
          const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
          timeText = h12 + ':' + pad(mins);
        }
        panel.set('time', { text: timeText });

        const dayIdx = (((Math.floor(now / 86400000) + 4) % 7) + 7) % 7;
        const suffix = use24 ? '' : (h24 < 12 ? ' · AM' : ' · PM');
        panel.set('sub', { text: WEEKDAYS[dayIdx] + suffix + ' · ' + pad(si) + 's' });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- lamp assembly (static, press-to-toggle) ----------
  const lamp = new THREE.Group();
  lamp.position.set(-0.13, 0, 0);
