  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.095, 0.024, 36), metal);
  base.name = 'LampBase';
  base.position.y = 0.012;
  lamp.add(base);

  // small glowing power button on top of the base
  const buttonMat = new THREE.MeshStandardMaterial({
    color: 0x767e8c, roughness: 0.5, metalness: 0.2,
    emissive: 0xffb020, emissiveIntensity: 0,
  });
  const button = new THREE.Mesh(new THREE.CylinderGeometry(0.017, 0.017, 0.009, 24), buttonMat);
  button.name = 'PowerButton';
  button.position.set(0, 0.0285, 0.048);
  lamp.add(button);

  // stem
  const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.009, 0.012, 0.19, 16), metal);
  stem.name = 'Stem';
  stem.position.y = 0.119;
  lamp.add(stem);

  const elbow = new THREE.Mesh(new THREE.SphereGeometry(0.016, 20, 12), metal);
  elbow.name = 'Elbow';
  elbow.position.set(0, 0.214, 0);
  lamp.add(elbow);

  // angled arm
  const aStart = new THREE.Vector3(0, 0.214, 0);
  const aEnd = new THREE.Vector3(0, 0.285, 0.075);
  const armDir = new THREE.Vector3().subVectors(aEnd, aStart);
  const armLen = armDir.length();
  const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, armLen, 12), metal);
  arm.name = 'Arm';
  arm.position.copy(aStart).addScaledVector(armDir, 0.5);
  arm.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), armDir.clone().normalize());
  lamp.add(arm);

  // shade
  const TILT = 0.22;              // radians, leans toward the user
  const CT = Math.cos(TILT);      // 0.9759
  const ST = Math.sin(TILT);      // 0.2182
  const shade = new THREE.Mesh(
    new THREE.CylinderGeometry(0.024, 0.058, 0.08, 32, 1, true),
    shadeMat,
  );
  shade.name = 'LampShade';
  shade.position.set(0, 0.246, 0.0837);
  shade.rotation.x = -TILT;
  lamp.add(shade);

  // bulb
  const bulbMat = new THREE.MeshStandardMaterial({
    color: 0xfff6e0, emissive: 0xffe6a8, emissiveIntensity: 0, roughness: 0.25,
  });
  const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.022, 20, 12), bulbMat);
  bulb.name = 'Bulb';
  bulb.position.set(0, 0.218, 0.090);
  lamp.add(bulb);

  // soft halo around the bulb
  const glowMat = new THREE.MeshBasicMaterial({
    color: 0xffe9b8, transparent: true, opacity: 0,
    depthWrite: false, blending: THREE.AdditiveBlending,
  });
  const glow = new THREE.Mesh(new THREE.SphereGeometry(0.045, 20, 12), glowMat);
  glow.name = 'BulbGlow';
  glow.position.copy(bulb.position);
  lamp.add(glow);

  // light cone in the air
  const coneMat = new THREE.MeshBasicMaterial({
    color: 0xffe4a8, transparent: true, opacity: 0, side: THREE.DoubleSide,
    depthWrite: false, blending: THREE.AdditiveBlending,
  });
  const cone = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.11, 0.19, 24, 1, true), coneMat);
  cone.name = 'LightCone';
  cone.position.set(0, bulb.position.y - CT * 0.095, bulb.position.z + ST * 0.095);
  cone.rotation.x = -TILT;
  lamp.add(cone);

  // pool of light on the desk
  const poolMat = new THREE.MeshBasicMaterial({
    color: 0xffe4a8, transparent: true, opacity: 0,
    depthWrite: false, blending: THREE.AdditiveBlending,
  });
  const pool = new THREE.Mesh(new THREE.CircleGeometry(0.11, 32), poolMat);
  pool.name = 'LightPool';
  pool.rotation.x = -Math.PI / 2;
  pool.position.set(0, 0.004, 0.132);
  lamp.add(pool);

  // ---------- control panel ----------
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              background-color: #1b1e24; border-radius: 18px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .status { color: #9aa3b2; font-size: 24px; font-weight: 600; }
      .btn { display: flex; align-items: center; justify-content: center;
             padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .hint { color: #8b93a1; font-size: 18px; }
    </style>
    <div class="card">
      <span class="title">Desk Lamp</span>
      <span class="status" id="status">Off</span>
      <button class="btn" id="toggle"><span class="btn-text" id="btnText">Switch on</span></button>
      <span class="hint">Press the lamp or the button</span>
    </div>`, { width: 0.3, position: [0.24, 0.18, 0.0], rotationY: -0.4 });
  root.add(panel.object3D);

  // ---------- toggle logic ----------
  let on = false;
  let level = 0;      // eased brightness 0..1
  let flicker = 0;    // seconds of warm-up flicker left

  function setOn(next) {
    if (next === on) return;
    on = next;
    if (on) flicker = 0.34;
    panel.set('status', { text: on ? 'On' : 'Off', color: on ? '#ffd68a' : '#9aa3b2' });
    panel.set('btnText', { text: on ? 'Switch off' : 'Switch on' });
    panel.set('toggle', { backgroundColor: on ? '#8a5b12' : '#2f6fdb' });
  }

  panel.on('toggle', 'click', () => setOn(!on));
  traits(lamp, { onPress: () => setOn(!on) });

  return {
    root,
    update(time, delta) {
      const d = Math.min(delta, 0.05);

      const target = on ? 1 : 0;
      level += (target - level) * Math.min(1, d * 10);
      if (!on && level < 0.002) level = 0;

      let b = level;
      if (flicker > 0) {
        flicker -= d;
        b = level * (0.45 + 0.55 * Math.abs(Math.sin(time * 38)));
      }

      bulbMat.emissiveIntensity = b * 2.6;
      shadeMat.emissiveIntensity = b * 0.18;
      glowMat.opacity = b * 0.3;
      coneMat.opacity = b * 0.075;
      poolMat.opacity = b * 0.22;
      buttonMat.emissiveIntensity = on ? 0.9 : 0.0;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  /* ───────────── materials ───────────── */
  const bodyMat = new THREE.MeshStandardMaterial({ color: 0x3a4756, metalness: 0.65, roughness: 0.35 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x1d242c, metalness: 0.55, roughness: 0.5 });
  const innerMat = new THREE.MeshStandardMaterial({
    color: 0xfff3dd, emissive: 0xffcf87, emissiveIntensity: 0,
    roughness: 0.95, metalness: 0, side: THREE.BackSide,
  });
  const bulbMat = new THREE.MeshStandardMaterial({
    color: 0xfff6e6, emissive: 0xffd79a, emissiveIntensity: 0, roughness: 0.25, metalness: 0,
  });
  const switchMat = new THREE.MeshStandardMaterial({
    color: 0x99a1ac, emissive: 0xffc46b, emissiveIntensity: 0, metalness: 0.45, roughness: 0.4,
  });
  const coneMat = new THREE.MeshBasicMaterial({
    color: 0xffdcaa, transparent: true, opacity: 0, vertexColors: true,
    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
  });
  const haloMat = new THREE.MeshBasicMaterial({
    color: 0xffdcaa, transparent: true, opacity: 0,
    blending: THREE.AdditiveBlending, depthWrite: false,
  });
  const poolMat = new THREE.MeshBasicMaterial({
    color: 0xffdcaa, transparent: true, opacity: 0, vertexColors: true,
    blending: THREE.AdditiveBlending, depthWrite: false,
  });

  /* ───────────── base + switch ───────────── */
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.070, 0.076, 0.016, 32), bodyMat);
  base.name = 'LampBase';
  base.position.set(0, 0.008, 0);
  root.add(base);

  const switchBtn = new THREE.Mesh(new THREE.CylinderGeometry(0.019, 0.019, 0.010, 20), switchMat);
  switchBtn.name = 'LampSwitch';
  switchBtn.position.set(0, 0.0205, 0.044);
  root.add(switchBtn);

  /* ───────────── arms ───────────── */
  const UP = new THREE.Vector3(0, 1, 0);
  function rod(ax, ay, az, bx, by, bz, radius, mat) {
    const a = new THREE.Vector3(ax, ay, az);
    const dir = new THREE.Vector3(bx - ax, by - ay, bz - az);
    const len = dir.length();
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, len, 12), mat);
    mesh.position.copy(a).addScaledVector(dir, 0.5);
    dir.normalize();
    mesh.quaternion.setFromUnitVectors(UP, dir);
    return mesh;
  }

  const elbow = new THREE.Vector3(0, 0.27, -0.055);
  const neck = new THREE.Vector3(0, 0.30, 0.06);

  const armLow = rod(0, 0.016, -0.01, elbow.x, elbow.y, elbow.z, 0.0095, bodyMat);
  armLow.name = 'LampArmLower';
  root.add(armLow);

  const armHigh = rod(elbow.x, elbow.y, elbow.z, neck.x, neck.y, neck.z, 0.0085, bodyMat);
  armHigh.name = 'LampArmUpper';
  root.add(armHigh);

  const jointGeo = new THREE.SphereGeometry(1, 16, 10);
  function joint(x, y, z, r) {
    const m = new THREE.Mesh(jointGeo, darkMat);
    m.position.set(x, y, z);
    m.scale.setScalar(r);
    return m;
  }
  root.add(joint(0, 0.016, -0.01, 0.014));
  root.add(joint(elbow.x, elbow.y, elbow.z, 0.0135));
  root.add(joint(neck.x, neck.y, neck.z, 0.013));

  /* ───────────── head (tilted 20° toward the user) ───────────── */
  const headEuler = new THREE.Euler(-0.35, 0, 0);
  const headQ = new THREE.Quaternion().setFromEuler(headEuler);
  function hp(x, y, z) {
    return new THREE.Vector3(x, y, z).applyEuler(headEuler).add(neck);
  }

  // cap that closes the top of the shade
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.031, 0.031, 0.012, 24), bodyMat);
  cap.position.copy(hp(0, 0, 0));
  cap.quaternion.copy(headQ);
  root.add(cap);

  // outer shade shell
  const shadeOuter = new THREE.Mesh(
    new THREE.CylinderGeometry(0.030, 0.066, 0.082, 32, 1, true), bodyMat,
  );
  shadeOuter.name = 'LampShade';
  shadeOuter.position.copy(hp(0, -0.041, 0));
  shadeOuter.quaternion.copy(headQ);
  root.add(shadeOuter);

  // inner reflective surface
  const shadeInner = new THREE.Mesh(
    new THREE.CylinderGeometry(0.028, 0.064, 0.080, 32, 1, true), innerMat,
  );
  shadeInner.name = 'LampShadeInner';
  shadeInner.position.copy(shadeOuter.position);
  shadeInner.quaternion.copy(headQ);
  root.add(shadeInner);

  // bulb
  const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.017, 20, 12), bulbMat);
  bulb.name = 'LampBulb';
  bulb.position.copy(hp(0, -0.048, 0));
  root.add(bulb);

  const halo = new THREE.Mesh(new THREE.SphereGeometry(0.034, 16, 10), haloMat);
  halo.position.copy(bulb.position);
  halo.visible = false;
  root.add(halo);

  /* ───────────── the visible cone of light ───────────── */
  const CONE_H = 0.24;
  const coneGeo = new THREE.CylinderGeometry(0.022, 0.120, CONE_H, 24, 1, true);
  const cPos = coneGeo.attributes.position;
  const cCol = new Float32Array(cPos.count * 3);
  for (let i = 0; i < cPos.count; i++) {
    const t = (cPos.getY(i) + CONE_H / 2) / CONE_H;   // 0 at bottom, 1 at top
    const v = 0.10 + 0.90 * t;
    cCol[i * 3] = v; cCol[i * 3 + 1] = v; cCol[i * 3 + 2] = v;
  }
  coneGeo.setAttribute('color', new THREE.BufferAttribute(cCol, 3));

  const lightCone = new THREE.Mesh(coneGeo, coneMat);
  lightCone.name = 'LampLightCone';
  lightCone.position.copy(hp(0, -0.048 - CONE_H / 2, 0));
  lightCone.quaternion.copy(headQ);
  lightCone.visible = false;
  root.add(lightCone);

  /* ───────────── pool of light on the desk ───────────── */
  const poolGeo = new THREE.CircleGeometry(0.13, 40);
  const pPos = poolGeo.attributes.position;
  const pCol = new Float32Array(pPos.count * 3);
  for (let i = 0; i < pPos.count; i++) {
    const d = Math.sqrt(pPos.getX(i) * pPos.getX(i) + pPos.getY(i) * pPos.getY(i)) / 0.13;
    const f = Math.max(0, 1 - d);
    const v = f * f;
    pCol[i * 3] = v; pCol[i * 3 + 1] = v; pCol[i * 3 + 2] = v;
  }
  poolGeo.setAttribute('color', new THREE.BufferAttribute(pCol, 3));

  const pool = new THREE.Mesh(poolGeo, poolMat);
  pool.name = 'LampLightPool';
  pool.rotation.x = -Math.PI / 2;
  pool.position.set(0, 0.004, 0.16);
  pool.visible = false;
  root.add(pool);

  /* ───────────── control panel ───────────── */
  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 8px; width: 460px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .status { color: #8b93a1; font-size: 24px; font-weight: 700; }
      .hint { color: #c8ccd4; font-size: 20px; }
      .btn { display: flex; align-items: center; justify-content: center;
             padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Desk lamp</span>
      <span class="status" id="status">Off</span>
      <span class="hint">Press the shade, the switch or the base.</span>
      <button class="btn" id="power"><span class="btn-text" id="powerText">Switch on</span></button>
    </div>`, { width: 0.30, position: [0.26, 0.17, -0.03], rotationY: -0.42 });
  root.add(panel.object3D);

  /* ───────────── state ───────────── */
  let isOn = false;
  let glow = 0;

  function refreshUI() {
    panel.set('status', { text: isOn ? 'On' : 'Off', color: isOn ? '#ffd479' : '#8b93a1' });
    panel.set('powerText', { text: isOn ? 'Switch off' : 'Switch on' });
  }
  function toggle() {
    isOn = !isOn;
    refreshUI();
  }
  refreshUI();

  traits(shadeOuter, { onPress: toggle });
  traits(switchBtn, { onPress: toggle });
  traits(base, { onPress: toggle });
  panel.on('power', 'click', toggle);

  /* ───────────── animation ───────────── */
  return {
    root,
    update(time, delta) {
      const target = isOn ? 1 : 0;
      const step = Math.min(1, delta * 8);
      glow += (target - glow) * step;
      if (Math.abs(glow - target) < 0.003) glow = target;

      bulbMat.emissiveIntensity = glow * 3.0;
      innerMat.emissiveIntensity = glow * 1.2;
      switchMat.emissiveIntensity = glow * 1.4;

      coneMat.opacity = glow * 0.16;
      haloMat.opacity = glow * 0.22;
      poolMat.opacity = glow * 0.34;

      const on = glow > 0.01;
      lightCone.visible = on;
      halo.visible = on;
      pool.visible = on;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- shared geometry ----------
  const sphereGeo = new THREE.SphereGeometry(1, 24, 14);
  const unitCyl = new THREE.CylinderGeometry(1, 1, 1, 10, 1);
  const unitCone = new THREE.ConeGeometry(1, 1, 14, 1);
  const UP = new THREE.Vector3(0, 1, 0);

  // ---------- plant: pot, soil, stem ----------
  const pot = new THREE.Mesh(
    new THREE.CylinderGeometry(0.042, 0.030, 0.062, 24, 1),
    new THREE.MeshStandardMaterial({ color: 0xb96a3e, roughness: 0.9 })
  );
  pot.position.set(0, 0.031, 0);
  pot.name = 'Pot';
  root.add(pot);

  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0385, 0.0385, 0.012, 24, 1),
    new THREE.MeshStandardMaterial({ color: 0x35261d, roughness: 1 })
  );
  soil.position.set(0, 0.058, 0);
  soil.name = 'Soil';
  root.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0038, 0.0055, 0.17, 8, 1),
    new THREE.MeshStandardMaterial({ color: 0x3f8f3a, roughness: 0.85 })
  );
  stem.position.set(0, 0.145, 0);
  stem.name = 'Stem';
  root.add(stem);

  // ---------- leaves ----------
  const leafMat = new THREE.MeshStandardMaterial({
    color: 0x53b04c, roughness: 0.75, emissive: 0x0d3d0d, emissiveIntensity: 0.5,
  });
  const TILT = 0.42;
  const leaves = [];
  function addLeaf(angle, y, len, wid) {
    const leaf = new THREE.Mesh(sphereGeo, leafMat);
    leaf.scale.set(len, 0.0055, wid);
    leaf.rotation.set(0, -angle, TILT);
    const reach = len * 0.85;
    leaf.position.set(
      Math.cos(angle) * reach * Math.cos(TILT),
      y + reach * Math.sin(TILT),
      Math.sin(angle) * reach * Math.cos(TILT)
    );
    leaf.name = 'Leaf';
    root.add(leaf);
    leaves.push(leaf);
    return leaf;
  }
  addLeaf(0.35, 0.100, 0.042, 0.023);
  addLeaf(2.75, 0.135, 0.046, 0.025);
  addLeaf(4.45, 0.170, 0.038, 0.021);
  addLeaf(1.30, 0.200, 0.032, 0.018);

  // ---------- the Sun (grabbable) ----------
  const sunGroup = new THREE.Group();
  sunGroup.position.set(-0.26, 0.36, -0.10);
  sunGroup.name = 'Sun';

  const sunBall = new THREE.Mesh(
    sphereGeo,
    new THREE.MeshStandardMaterial({
      color: 0xffd24a, emissive: 0xffa000, emissiveIntensity: 1.1, roughness: 0.45,
    })
  );
  sunBall.scale.setScalar(0.048);
  sunBall.name = 'SunBall';
  sunGroup.add(sunBall);

  const sunGlow = new THREE.Mesh(
    sphereGeo,
    new THREE.MeshBasicMaterial({
      color: 0xffd070, transparent: true, opacity: 0.22,
      depthWrite: false, blending: THREE.AdditiveBlending,
    })
  );
  sunGlow.scale.setScalar(0.078);
  sunGroup里 = null; // placeholder guard (removed below)
  sunGroup.add(sunGlow);
  root.add(sunGroup);

  // ---------- arrows ----------
  function makeArrow(color, radius) {
    const mat = new THREE.MeshStandardMaterial({
      color, emissive: color, emissiveIntensity: 0.22, roughness: 0.35, metalness: 0.15,
    });
    const g = new THREE.Group();
    const shaft = new THREE.Mesh(unitCyl, mat);
    const head = new THREE.Mesh(unitCone, mat);
    g.add(shaft);
    g.add(head);
    root.add(g);
    return {
      group: g, shaft, head, mat, radius,
      a: new THREE.Vector3(), b: new THREE.Vector3(), d: new THREE.Vector3(),
    };
  }

  function placeArrow(ar, ax, ay, az, bx, by, bz) {
    const A = ar.a.set(ax, ay, az);
    const B = ar.b.set(bx, by, bz);
    const d = ar.d.subVectors(B, A);
    const len = Math.max(d.length(), 0.0001);
    d.divideScalar(len);
    const headLen = Math.min(0.028, len * 0.4);
    const shaftLen = len - headLen;
    ar.group.position.copy(A);
    ar.group.quaternion.setFromUnitVectors(UP, d);
    ar.shaft.scale.set(ar.radius, shaftLen, ar.radius);
    ar.shaft.position.set(0, shaftLen * 0.5, 0);
    ar.head.scale.set(ar.radius * 2.6, headLen, ar.radius * 2.6);
    ar.head.position.set(0, shaftLen + headLen * 0.5, 0);
  }

  const arrowLight = makeArrow(0xffd23f, 0.0042);
  const arrowWater = makeArrow(0x3a8bff, 0.0032);
  const arrowCo2 = makeArrow(0x9aa8b8, 0.0032);
  const arrowO2 = makeArrow(0x5fe6ff, 0.0032);

  placeArrow(arrowWater, 0.145, 0.020, 0.150, 0.038, 0.032, 0.052);
  placeArrow(arrowCo2, 0.190, 0.152, 0.030, 0.062, 0.132, 0.012);
  placeArrow(arrowO2, 0.020, 0.225, 0.020, 0.195, 0.325, 0.020);
  // the light beam is positioned every frame so it follows the Sun
  placeArrow(arrowLight, -0.216, 0.338, -0.083, -0.005, 0.235, 0.0);

  // ---------- floating labels ----------
  function chip(text, color, pos, rotY) {
    const h = ui(`
      <style>
        .c { width: 380px; padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
             border-radius: 16px; background-color: #14171c; border-width: 2px; border-color: ${color};
             align-items: center; justify-content: center; }
        .t { color: ${color}; font-size: 32px; font-weight: 700; text-align: center; }
      </style>
      <div class="c"><span class="t">${text}</span></div>`,
      { width: 0.14, position: pos, rotationY: rotY });
    root.add(h.object3D);
    return h;
  }
  chip('Light', '#ffd23f', [-0.25, 0.270, 0.030], 0.35);
  chip('CO₂', '#9aa8b8', [0.275, 0.145, 0.040], -0.40);
  chip('O₂', '#5fe6ff', [0.275, 0.345, 0.040], -0.40);
  chip('H₂O', '#3a8bff', [0.225, 0.055, 0.165], -0.50);

  // ---------- explanation panel ----------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; width: 520px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 20px; background-color: #1d2128; }
      .title { color: #ffffff; font-size: 34px; font-weight: 700; }
      .eq { color: #9be89b; font-size: 21px; }
      .body { color: #d7dbe2; font-size: 23px; }
      .row { flex-direction: row; gap: 8px; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
             border-radius: 12px; background-color: #2c313a;
             align-items: center; justify-content: center; }
      .bt { color: #ffffff; font-size: 19px; font-weight: 700; text-align: center; }
      .hint { color: #8f98a6; font-size: 19px; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="eq">6CO₂ + 6H₂O + light → C₆H₁₂O₆ + 6O₂</span>
      <span class="body" id="fact">Plants use light, water and carbon dioxide to make sugar. Oxygen is released.</span>
      <div class="row">
        <button class="btn" id="b-light"><span class="bt">Light</span></button>
        <button class="btn" id="b-water"><span class="bt">Water</span></button>
        <button class="btn" id="b-co2"><span class="bt">CO₂</span></button>
        <button class="btn" id="b-o2"><span class="bt">O₂</span></button>
      </div>
      <span class="hint">Pinch the Sun to move it · press a leaf</span>
    </div>`,
    { width: 0.26, position: [-0.27, 0.115, 0.09], rotationY: 0.55 });
  root.add(panel.object3D);

  // ---------- state & interaction ----------
  const arrows = { light: arrowLight, water: arrowWater, co2: arrowCo2, o2: arrowO2 };
  const KEYS = ['light', 'water', 'co2', 'o2'];
  const FACTS = {
    light: 'Chlorophyll in the leaves absorbs sunlight. That light energy drives the whole reaction.',
    water: 'Roots take up water from the soil. It travels up the stem and into the leaves.',
    co2: 'Carbon dioxide from the air enters the leaf through tiny pores called stomata.',
    o2: 'Oxygen is a by-product. It leaves the leaf through the stomata and goes into the air.',
  };

  let selected = 'light';
  let leafGlow = 0;

  function select(name, text) {
    selected = name;
    for (const k of KEYS) {
      arrows[k].mat.emissiveIntensity = (k === name) ? 1.0 : 0.18;
      panel.set('b-' + k, { backgroundColor: (k === name) ? '#4a5561' : '#2c313a' });
    }
    if (text) panel.set('fact', { text });
  }

  panel.on('b-light', 'click', () => select('light', FACTS.light));
  panel.on('b-water', 'click', () => select('water', FACTS.water));
  panel.on('b-co2', 'click', () => select('co2', FACTS.co2));
  panel.on('b-o2', 'click', () => select('o2', FACTS.o2));

  traits(sunGroup, {
    grab: true,
    onPress: () => select('light', 'The Sun is the energy source: its light is absorbed by chlorophyll.'),
  });

  for (const leaf of leaves) {
    traits(leaf, {
      onPress: () => {
        leafGlow = 1;
        select(selected, 'Leaves are the food factories of the plant — chloroplasts inside them capture light.');
      },
    });
  }

  select('light', 'Plants use light, water and carbon dioxide to make sugar. Oxygen is released.');

  // ---------- animation ----------
  const lightEnd = new THREE.Vector3(-0.005, 0.235, 0.0);
  const tmp = new THREE.Vector3();

  return {
    root,
    update(time, delta) {
      // the light beam always points from the Sun to the top of the plant
      const sp = sunGroup.position;
      tmp.subVectors(lightEnd, sp).normalize().multiplyScalar(0.055);
      placeArrow(
        arrowLight,
        sp.x + tmp.x, sp.y + tmp.y, sp.z + tmp.z,
        lightEnd.x, lightEnd.y, lightEnd.z
      );

      // soft breathing glow on the highlighted arrow
      arrows[selected].mat.emissiveIntensity = 0.75 + 0.35 * Math.sin(time * 3.0);

      // sun halo pulse
      sunGlow.scale.setScalar(0.078 * (1 + 0.05 * Math.sin(time * 2.2)));

      // leaf press flash
      if (leafGlow > 0) leafGlow = Math.max(0, leafGlow - delta * 1.5);
      leafMat.emissiveIntensity = 0.5 + leafGlow * 1.6;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const center = new THREE.Vector3(0, 0.17, -0.02);
  const PHI = Math.PI * 1.45; // a wedge (about 100°) is cut out of every shell

  const layers = [
    { name: 'Crust', r: 0.090, color: 0x5f8140,
      fact: '5–70 km thick. Solid rock, the thinnest layer — we live on it.' },
    { name: 'Mantle', r: 0.078, color: 0xc2603a,
      fact: 'About 2,900 km thick. Hot rock that creeps slowly and drives the tectonic plates.' },
    { name: 'Outer core', r: 0.049, color: 0xf2a33c,
      fact: 'About 2,260 km thick. Liquid iron and nickel; its swirling motion creates Earth\'s magnetic field.' },
    { name: 'Inner core', r: 0.022, color: 0xfbe9a0,
      fact: 'Solid iron-nickel ball, radius about 1,220 km, nearly as hot as the Sun\'s surface (~5,400 °C).' },
  ];

  // --- info panel -----------------------------------------------------------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1c1f25; }
      .title { color: #ffffff; font-size: 26px; font-weight: 700; }
      .name { color: #ffcc66; font-size: 22px; font-weight: 700; }
      .fact { color: #d7dbe2; font-size: 19px; }
      .row { flex-direction: row; gap: 6px; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px;
             border-radius: 10px; background-color: #2a2e35; }
      .btn-text { color: #ffffff; font-size: 16px; }
    </style>
    <div class="card">
      <span class="title">Layers of the Earth</span>
      <span class="name" id="lname">Press a layer</span>
      <span class="fact" id="lfact">A cut-away model: press any visible shell, or use the buttons below.</span>
      <div class="row">
        <button class="btn" id="b0"><span class="btn-text">Crust</span></button>
        <button class="btn" id="b1"><span class="btn-text">Mantle</span></button>
        <button class="btn" id="b2"><span class="btn-text">Outer core</span></button>
        <button class="btn" id="b3"><span class="btn-text">Inner core</span></button>
      </div>
    </div>`, { width: 0.36, position: [0.30, 0.19, 0.02], rotationY: -0.5 });
  root.add(panel.object3D);

  const meshes = [];

  function select(i) {
    panel.set('lname', { text: layers[i].name });
    panel.set('lfact', { text: layers[i].fact });
    for (let k = 0; k < meshes.length; k++) {
      meshes[k].material.emissiveIntensity = k === i ? 0.55 : (k >= 2 ? 0.25 : 0.05);
    }
  }

  layers.forEach((L, i) => {
    const geo = new THREE.SphereGeometry(L.r, 32, 16, 0, PHI, 0, Math.PI);
    const mat = new THREE.MeshStandardMaterial({
      color: L.color, roughness: 0.75, metalness: 0.05,
      emissive: L.color, emissiveIntensity: i >= 2 ? 0.25 : 0.05,
      side: THREE.DoubleSide,
    });
    const m = new THREE.Mesh(geo, mat);
    m.name = L.name;
    m.position.copy(center);
    m.rotation.set(0.22, Math.PI, 0);
    root.add(m);
    traits(m, { onPress: () => select(i) });
    meshes.push(m);
    panel.on('b' + i, 'click', () => select(i));
  });

  return {
    root,
    update(time) {
      // very slow sway so every shell stays reachable and the cutaway stays facing the user
      const sway = Math.sin(time * 0.35) * 0.55;
      for (let i = 0; i < meshes.length; i++) {
        if (isGrabbed(meshes[i])) continue;
        meshes[i].rotation.y = Math.PI + sway;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const V = THREE.Vector3;
  const UP = new V(0, 1, 0);
  const PLANT_X = -0.06;

  /* ------------------------- the plant ------------------------- */
  const pot = new THREE.Mesh(
    new THREE.CylinderGeometry(0.042, 0.032, 0.062, 22),
    new THREE.MeshStandardMaterial({ color: 0xb4653c, roughness: 0.9 }),
  );
  pot.name = 'Pot';
  pot.position.set(PLANT_X, 0.031, 0);
  root.add(pot);

  const soil = new THREE.Mesh(
    new THREE.CylinderGeometry(0.039, 0.039, 0.012, 22),
    new THREE.MeshStandardMaterial({ color: 0x3b2a1e, roughness: 1 }),
  );
  soil.name = 'Soil';
  soil.position.set(PLANT_X, 0.064, 0);
  root.add(soil);

  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0055, 0.008, 0.16, 10),
    new THREE.MeshStandardMaterial({ color: 0x387f42, roughness: 0.8 }),
  );
  stem.name = 'Stem';
  stem.position.set(PLANT_X, 0.146, 0);
  root.add(stem);

  const leafGeo = new THREE.SphereGeometry(0.032, 18, 12);
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x45a85a, roughness: 0.65 });
  const leafDefs = [
    { x: 0.036, y: 0.098, z: 0.004, ry: 0.35, rz: 0.30, s: 1.00 },
    { x: -0.036, y: 0.126, z: -0.004, ry: -2.75, rz: -0.30, s: 1.00 },
    { x: 0.032, y: 0.158, z: -0.014, ry: -0.55, rz: 0.25, s: 0.92 },
    { x: -0.030, y: 0.184, z: 0.012, ry: 2.90, rz: -0.25, s: 0.88 },
    { x: 0.000, y: 0.222, z: 0.000, ry: 0.90, rz: 0.00, s: 0.75 },
  ];
  leafDefs.forEach((d, i) => {
    const leaf = new THREE.Mesh(leafGeo, leafMat);
    leaf.name = 'Leaf' + (i + 1);
    leaf.position.set(PLANT_X + d.x, d.y, d.z);
    leaf.rotation.set(0, d.ry, d.rz);
    leaf.scale.set(1.35 * d.s, 0.24 * d.s, 0.62 * d.s);
    root.add(leaf);
  });

  const shadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.075, 24),
    new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.22, depthWrite: false }),
  );
  shadow.name = 'Shadow';
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(PLANT_X, 0.001, 0);
  root.add(shadow);

  /* ------------------------- the sun ------------------------- */
  const sunPos = new V(-0.29, 0.275, -0.01);
  const sun = new THREE.Mesh(
    new THREE.SphereGeometry(0.045, 28, 16),
    new THREE.MeshStandardMaterial({
      color: 0xffd45a, emissive: 0xffb300, emissiveIntensity: 1.1, roughness: 0.4,
    }),
  );
  sun.name = 'Sun';
  sun.position.copy(sunPos);
  root.add(sun);

  const sunGlow = new THREE.Mesh(
    new THREE.SphereGeometry(0.075, 20, 12),
    new THREE.MeshBasicMaterial({ color: 0xffc247, transparent: true, opacity: 0.13, depthWrite: false }),
  );
  sunGlow.name = 'SunGlow';
  sunGlow.position.copy(sunPos);
  root.add(sunGlow);

  /* ------------------------- arrows ------------------------- */
  const arrowDefs = [
    { key: 'light', s: new V(-0.255, 0.268, -0.01), e: new V(-0.060, 0.232, 0.000), color: 0xffd54a, speed: 0.55, head: 0.030 },
    { key: 'co2', s: new V(0.145, 0.100, 0.030), e: new V(0.008, 0.128, 0.005), color: 0xc3cdd8, speed: 0.35, head: 0.026 },
    { key: 'o2', s: new V(0.005, 0.196, 0.010), e: new V(0.115, 0.258, 0.020), color: 0xff9fc4, speed: 0.35, head: 0.026 },
    { key: 'h2o', s: new V(-0.060, 0.012, 0.145), e: new V(-0.058, 0.055, 0.045), color: 0x38bdf8, speed: 0.32, head: 0.024 },
  ];

  const arrowMats = [];
  const flows = [];
  const dotGeo = new THREE.SphereGeometry(0.0075, 8, 6);

  for (const d of arrowDefs) {
    const dir = new V().subVectors(d.e, d.s);
    const len = dir.length();
    const unit = dir.clone().normalize();

    const mat = new THREE.MeshStandardMaterial({
      color: d.color, emissive: d.color, emissiveIntensity: 0.5, roughness: 0.4,
    });
    arrowMats.push({ mat, color: d.color });

    const shaftLen = Math.max(len - d.head, 0.005);
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.0045, 0.0045, shaftLen, 10), mat);
    shaft.position.y = shaftLen / 2;
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.0115, d.head, 14), mat);
    head.position.y = shaftLen + d.head / 2;

    const group = new THREE.Group();
    group.name = 'Arrow_' + d.key;
    group.add(shaft, head);
    group.position.copy(d.s);
    group.quaternion.setFromUnitVectors(UP, unit);
    root.add(group);

    const dotMat = new THREE.MeshBasicMaterial({ color: d.color });
    const dots = [];
    for (let i = 0; i < 3; i++) {
      const dot = new THREE.Mesh(dotGeo, dotMat);
      dot.name = 'Flow_' + d.key + '_' + i;
      dot.position.copy(d.s);
      root.add(dot);
      dots.push(dot);
    }
    flows.push({ s: d.s.clone(), dir: unit, len, speed: d.speed, dots });
  }

  /* ------------------------- content ------------------------- */
  const steps = [
    'Plants trap light energy in their leaves, inside tiny green structures called chloroplasts.',
    'Light energy splits water (H2O) pulled up from the roots. Oxygen (O2) is released and energy is stored.',
    'That stored energy drives the Calvin cycle, which takes in carbon dioxide (CO2) and builds glucose (C6H12O6).',
    'Overall: 6 CO2 + 6 H2O + light -> C6H12O6 + 6 O2. Water up, CO2 in, O2 and sugar out.',
  ];

  const notes = {
    light: 'Chlorophyll in the chloroplasts absorbs the light energy. Only energy enters here, no atoms.',
    co2: 'Carbon dioxide slips in through tiny pores in the leaf called stomata. Its carbon atoms end up in glucose.',
    h2o: 'Water is taken up by the roots and pulled up the stem in tubes called xylem to reach the leaves.',
    o2: 'Oxygen is a by-product: it is released when water molecules are split, and it leaves through the stomata.',
  };

  let stepIndex = 0;
  let lightOn = true;
  let note = null;

  const panel = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 10px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              border-radius: 20px; background-color: #191d23; }
      .title { color: #eaf6e6; font-size: 30px; font-weight: 700; }
      .body { color: #d5dbe3; font-size: 21px; }
      .row { display: flex; flex-direction: row; align-items: center; gap: 12px; }
      .btn { padding-top: 9px; padding-bottom: 9px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f7d4f; border-width: 0px; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
      .hint { color: #8d97a4; font-size: 17px; }
    </style>
    <div class="card">
      <span class="title">Photosynthesis</span>
      <span class="body" id="step">Plants trap light energy in their leaves, inside tiny green structures called chloroplasts.</span>
      <div class="row">
        <button class="btn" id="next"><span class="btn-text">Next step</span></button>
      </div>
      <span class="hint" id="hint">Press the Sun to switch light off and on.</span>
    </div>`, { width: 0.30, position: [0, 0.32, -0.14] });
  root.add(panel.object3D);

  function refreshPanel() {
    if (!lightOn) {
      panel.set('step', { text: 'Light is off. Without light the light reactions stop: no oxygen is released and no glucose is made.' });
      panel.set('hint', { text: 'Press the Sun to switch the light back on.' });
    } else if (note) {
      panel.set('step', { text: note });
      panel.set('hint', { text: 'Press a label or use Next step to keep going.' });
    } else {
      panel.set('step', { text: steps[stepIndex] });
      panel.set('hint', { text: 'Press the Sun to switch light off and on.' });
    }
  }

  /* ------------------------- labels on the arrows ------------------------- */
  function makeLabel(key, text, color, position, rotationY) {
    const h = ui(`
      <style>
        .pill { display: flex; flex-direction: row; align-items: center; justify-content: center;
                width: 112px; height: 48px; border-radius: 24px;
                background-color: #12151b; border-width: 0px; border-color: #ffffff; }
        .t { font-size: 25px; font-weight: 700; color: ${color}; }
      </style>
      <button class="pill" id="pill"><span class="t">${text}</span></button>`,
      { width: 0.10, position, rotationY });
    h.on('pill', 'click', () => {
      note = notes[key];
      refreshPanel();
    });
    root.add(h.object3D);
    return h;
  }

  makeLabel('light', 'Light', '#ffd54a', [-0.215, 0.315, 0.05], 0.30);
  makeLabel('co2', 'CO2', '#c3cdd8', [0.185, 0.075, 0.07], -0.35);
  makeLabel('o2', 'O2', '#ff9fc4', [0.190, 0.275, 0.07], -0.35);
  makeLabel('h2o', 'H2O', '#38bdf8', [0.035, 0.035, 0.155], -0.10);

  /* ------------------------- state changes ------------------------- */
  function setLight(on) {
    lightOn = on;
    for (const a of arrowMats) {
      if (on) {
        a.mat.color.setHex(a.color);
        a.mat.emissive.setHex(a.color);
        a.mat.emissiveIntensity = 0.5;
      } else {
        a.mat.color.setHex(0x39404a);
        a.mat.emissive.setHex(0x0b0f14);
        a.mat.emissiveIntensity = 0.0;
      }
    }
    for (const f of flows) for (const d of f.dots) d.visible = on;
    sun.material.emissiveIntensity = on ? 1.1 : 0.08;
    sun.material.color.setHex(on ? 0xffd45a : 0x6b6252);
    sunGlow.material.opacity = on ? 0.13 : 0.03;
    sunGlow.scale.setScalar(1);
    refreshPanel();
  }

  traits(sun, { onPress: () => setLight(!lightOn) });

  panel.on('next', 'click', () => {
    note = null;
    stepIndex = (stepIndex + 1) % steps.length;
    refreshPanel();
  });

  refreshPanel();

  /* ------------------------- loop ------------------------- */
  return {
    root,
    update(time) {
      if (!lightOn) return;
      for (let a = 0; a < flows.length; a++) {
        const f = flows[a];
        for (let i = 0; i < f.dots.length; i++) {
          const t = (time * f.speed + i / f.dots.length) % 1;
          const dot = f.dots[i];
          dot.position.copy(f.s).addScaledVector(f.dir, t * f.len);
          const fade = Math.min(1, Math.min(t, 1 - t) * 7);
          dot.scale.setScalar(0.35 + 0.65 * fade);
        }
      }
      sunGlow.scale.setScalar(1 + Math.sin(time * 2.1) * 0.07);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- sizes (metres) -------------------------------------------------
  const R = 0.085;                 // outer radius of the model
  const KM = R / 6371;             // metres per real kilometre
  const rInnerCore = 1220 * KM;    // ~0.016
  const rOuterCore = 3480 * KM;    // ~0.046
  const rCrustIn = 0.079;          // crust drawn far thicker than reality

  const LAYERS = [
    {
      name: 'Crust', color: 0x2f7d5a, cut: 0x4fae82, chip: '#2f7d5a',
      rIn: rCrustIn, rOut: R, glow: 0.04, segW: 48, segH: 24,
      depth: 'Surface down to about 70 km',
      l1: 'Thin rocky skin, 5-70 km thick.',
      l2: 'Under 1% of the radius - drawn thicker here.'
    },
    {
      name: 'Mantle', color: 0xb8492a, cut: 0xd2663c, chip: '#b8492a',
      rIn: rOuterCore, rOut: rCrustIn, glow: 0.0, segW: 40, segH: 20,
      depth: '35 km down to 2,890 km',
      l1: 'Hot silicate rock, 1,000 to 3,700 C.',
      l2: 'Solid, yet it creeps and drives the plates.'
    },
    {
      name: 'Outer core', color: 0xef8a2b, cut: 0xffab52, chip: '#ef8a2b',
      rIn: rInnerCore, rOut: rOuterCore, glow: 0.12, segW: 32, segH: 16,
      depth: '2,890 km down to 5,150 km',
      l1: 'Liquid iron and nickel, 4,000-5,000 C.',
      l2: 'Its swirling currents make the magnetic field.'
    },
    {
      name: 'Inner core', color: 0xffd94d, cut: 0xffe98f, chip: '#ffd94d',
      rIn: 0, rOut: rInnerCore, glow: 0.45, segW: 24, segH: 12,
      depth: '5,150 km down to the centre, 6,371 km',
      l1: 'A solid iron-nickel ball, 1,220 km radius.',
      l2: 'About 5,400 C - as hot as the Sun surface.'
    }
  ];

  // ---------- the cut-away model --------------------------------------------
  const pivot = new THREE.Group();          // the grabbable object
  pivot.name = 'EarthCutaway';
  pivot.position.set(-0.10, 0.108, 0.01);
  root.add(pivot);

  const tilt = new THREE.Group();           // tip the opening toward the user
  tilt.rotation.x = 0.22;
  pivot.add(tilt);

  const spin = new THREE.Group();           // gentle showcase rotation
  tilt.add(spin);

  // A 90 degree wedge is removed, centred on +Z (toward the user).
  const PHI_START = Math.PI * 0.75;
  const PHI_LEN = Math.PI * 1.5;

  for (let i = 0; i < LAYERS.length; i++) {
    const L = LAYERS[i];

    L.surfMat = new THREE.MeshStandardMaterial({
      color: L.color, roughness: 0.86, metalness: 0.06,
      emissive: new THREE.Color(L.color), emissiveIntensity: L.glow
    });
    L.cutMat = new THREE.MeshStandardMaterial({
      color: L.cut, roughness: 0.95, metalness: 0.0,
      emissive: new THREE.Color(L.cut), emissiveIntensity: 0.12,
      side: THREE.DoubleSide
    });

    // curved outer surface of the shell
    const shell = new THREE.Mesh(
      new THREE.SphereGeometry(L.rOut, L.segW, L.segH, PHI_START, PHI_LEN),
      L.surfMat
    );
    shell.name = L.name;
    spin.add(shell);

    // two flat half-annulus walls where the wedge was removed
    const ringGeo = new THREE.RingGeometry(
      Math.max(L.rIn, 0.0006), L.rOut, 28, 1, 0, Math.PI
    );
    const wallA = new THREE.Mesh(ringGeo, L.cutMat);
    wallA.rotation.y = -Math.PI * 0.75;
    spin.add(wallA);

    const wallB = new THREE.Mesh(ringGeo, L.cutMat);
    wallB.rotation.y = -Math.PI * 0.25;
    spin.add(wallB);
  }

  // ---------- control panel --------------------------------------------------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 18px; padding-right: 18px; border-radius: 18px;
              background-color: #1b1e24; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .depth { color: #9aa4b2; font-size: 18px; }
      .row { flex-direction: row; gap: 8px; }
      .btn { padding-top: 9px; padding-bottom: 9px; padding-left: 12px; padding-right: 12px;
             border-radius: 12px; background-color: #2a2e35; }
      .btn-text { color: #eef2f7; font-size: 18px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 19px; }
    </style>
    <div class="card">
      <span class="title" id="lname">Layers of the Earth</span>
      <span class="depth" id="ldepth">Cut-away sphere, not to exact scale</span>
      <div class="row">
        <button class="btn" id="b0"><span class="btn-text">Crust</span></button>
        <button class="btn" id="b1"><span class="btn-text">Mantle</span></button>
      </div>
      <div class="row">
        <button class="btn" id="b2"><span class="btn-text">Outer core</span></button>
        <button class="btn" id="b3"><span class="btn-text">Inner core</span></button>
      </div>
      <span class="body" id="l1">Press a layer name to light it up.</span>
      <span class="body" id="l2">Pinch the model to pick it up.</span>
    </div>`, { width: 0.30, position: [0.17, 0.15, 0.02], rotationY: -0.32 });
  root.add(panel.object3D);

  let selected = -1;

  function select(i) {
    selected = i;
    for (let k = 0; k < LAYERS.length; k++) {
      const L = LAYERS[k];
      const on = (k === i);
      L.surfMat.emissiveIntensity = on ? L.glow + 0.55 : L.glow;
      L.cutMat.emissiveIntensity = on ? 0.5 : 0.12;
      panel.set('b' + k, { backgroundColor: on ? L.chip : '#2a2e35' });
    }
    if (i < 0) {
      panel.set('lname', { text: 'Layers of the Earth' });
      panel.set('ldepth', { text: 'Cut-away sphere, not to exact scale' });
      panel.set('l1', { text: 'Press a layer name to light it up.' });
      panel.set('l2', { text: 'Pinch the model to pick it up.' });
    } else {
      const L = LAYERS[i];
      panel.set('lname', { text: L.name });
      panel.set('ldepth', { text: L.depth });
      panel.set('l1', { text: L.l1 });
      panel.set('l2', { text: L.l2 });
    }
  }

  for (let k = 0; k < LAYERS.length; k++) {
    const index = k;
    panel.on('b' + index, 'click', () => {
      select(selected === index ? -1 : index);
    });
  }

  // the whole model can be pinched and moved
  traits(pivot, { grab: true });

  return {
    root,
    update(time) {
      if (isGrabbed(pivot)) return;         // never fight the user's hand
      // very slow sway so surface points stay far below 0.05 m/s
      spin.rotation.y = Math.sin(time * 0.35) * 0.30;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- data
  const cities = [
    { name: 'Tokyo',    cond: 'Sunny',         c: 24, hi: 27, lo: 18 },
    { name: 'London',   cond: 'Rain',          c: 13, hi: 15, lo: 9  },
    { name: 'New York', cond: 'Partly cloudy', c: 18, hi: 21, lo: 12 },
  ];
  const units = [true, true, true]; // true = °C for that city

  const conv = (c, isC) => Math.round(isC ? c : (c * 9) / 5 + 32);

  // ------------------------------------------------- shared geometry / mats
  const sphereGeo = new THREE.SphereGeometry(1, 20, 12);
  const rayGeo = new THREE.BoxGeometry(0.009, 0.028, 0.009);
  const dropGeo = new THREE.BoxGeometry(0.006, 0.022, 0.006);

  const sunMat = new THREE.MeshStandardMaterial({
    color: 0xffcf3d, emissive: 0xff8a00, emissiveIntensity: 0.85, roughness: 0.45,
  });
  const cloudMat = new THREE.MeshStandardMaterial({ color: 0xeef3fb, roughness: 0.95 });
  const cloudGreyMat = new THREE.MeshStandardMaterial({ color: 0xb7c2d3, roughness: 0.95 });
  const rainMat = new THREE.MeshStandardMaterial({
    color: 0x59a8ff, emissive: 0x1a4a8a, emissiveIntensity: 0.6, roughness: 0.35,
  });

  const puff = (x, y, z, s, mat) => {
    const m = new THREE.Mesh(sphereGeo, mat);
    m.position.set(x, y, z);
    m.scale.set(s, s * 0.9, s);
    return m;
  };

  // ---------------------------------------------------------------- sun
  function makeSunIcon() {
    const g = new THREE.Group();
    g.name = 'SunIcon';

    const core = new THREE.Mesh(sphereGeo, sunMat);
    core.name = 'SunCore';
    core.scale.setScalar(0.036);
    g.add(core);

    const rays = new THREE.Group();
    rays.name = 'SunRays';
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      const r = new THREE.Mesh(rayGeo, sunMat);
      r.position.set(Math.cos(a) * 0.056, Math.sin(a) * 0.056, 0);
      r.rotation.z = a - Math.PI / 2;
      rays.add(r);
    }
    g.add(rays);
    g.userData.rays = rays;
    return g;
  }

  // --------------------------------------------------------------- rain
  function makeRainIcon() {
    const g = new THREE.Group();
    g.name = 'RainIcon';

    g.add(puff(-0.028, 0.004, 0.000, 0.026, cloudGreyMat));
    g.add(puff(0.028, 0.000, 0.000, 0.024, cloudGreyMat));
    g.add(puff(0.000, 0.020, 0.004, 0.030, cloudGreyMat));
    g.add(puff(0.000, -0.006, 0.010, 0.026, cloudGreyMat));

    const drops = [];
    for (let i = 0; i < 3; i++) {
      const d = new THREE.Mesh(dropGeo, rainMat);
      d.name = 'RainDrop';
      d.position.set(-0.026 + i * 0.026, -0.040, 0.004);
      g.add(d);
      drops.push(d);
    }
    g.userData.drops = drops;
    return g;
  }

  // -------------------------------------------------------- partly cloudy
  function makePartlyIcon() {
    const g = new THREE.Group();
    g.name = 'PartlyCloudyIcon';

    const core = new THREE.Mesh(sphereGeo, sunMat);
    core.name = 'SunCore';
    core.position.set(-0.030, 0.022, -0.014);
    core.scale.setScalar(0.028);
    g.add(core);

    for (let i = 0; i < 5; i++) {
      const a = Math.PI * 0.55 + (i / 4) * Math.PI * 0.55;
      const r = new THREE.Mesh(rayGeo, sunMat);
      r.position.set(-0.030 + Math.cos(a) * 0.044, 0.022 + Math.sin(a) * 0.044, -0.014);
      r.rotation.z = a - Math.PI / 2;
      g.add(r);
    }

    g.add(puff(-0.018, -0.008, 0.014, 0.026, cloudMat));
    g.add(puff(0.026, -0.012, 0.012, 0.022, cloudMat));
    g.add(puff(0.004, 0.002, 0.016, 0.026, cloudMat));
    g.add(puff(0.006, -0.020, 0.018, 0.020, cloudMat));
    return g;
  }

  // ---------------------------------------------------------------- panel
  const colHtml = cities.map((c, i) => `
    <div class="col">
      <span class="city" id="city${i}">${c.name}</span>
      <span class="temp" id="temp${i}">--</span>
      <span class="cond" id="cond${i}">${c.cond}</span>
      <span class="hl" id="hl${i}">--</span>
    </div>`).join('');

  const panel = ui(`
    <style>
      .app { flex-direction: column; gap: 12px; width: 620px;
             padding-top: 16px; padding-bottom: 16px; padding-left: 24px; padding-right: 24px;
             background-color: #1b1f26; border-radius: 22px; }
      .head { flex-direction: row; align-items: center; justify-content: space-between; }
      .headLeft { flex-direction: column; gap: 2px; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .sub { color: #8f9bb0; font-size: 17px; }
      .unitBtn { padding-top: 8px; padding-bottom: 8px; padding-left: 18px; padding-right: 18px;
                 background-color: #2f6fdb; border-radius: 12px; }
      .unitText { color: #ffffff; font-size: 20px; font-weight: 700; }
      .row { flex-direction: row; gap: 16px; }
      .col { flex-direction: column; align-items: center; gap: 4px; width: 180px;
             padding-top: 12px; padding-bottom: 12px; padding-left: 8px; padding-right: 8px;
             background-color: #252b34; border-radius: 16px; }
      .city { color: #c8d2e2; font-size: 20px; font-weight: 700; }
      .temp { color: #ffffff; font-size: 42px; font-weight: 700; }
      .cond { color: #8fc7ff; font-size: 18px; }
      .hl { color: #8792a5; font-size: 16px; }
      .hint { color: #7d8798; font-size: 16px; text-align: center; }
    </style>
    <div class="app">
      <div class="head">
        <div class="headLeft">
          <span class="title">Weather now</span>
          <span class="sub" id="sub">Live board · 3 cities</span>
        </div>
        <button class="unitBtn" id="units"><span class="unitText" id="unitText">°C</span></button>
      </div>
      <div class="row">${colHtml}</div>
      <span class="hint">Pinch an icon to lift it · poke it to switch that city's units</span>
    </div>`, { width: 0.56, position: [0, 0.26, -0.06] });
  root.add(panel.object3D);

  function refresh() {
    for (let i = 0; i < cities.length; i++) {
      const c = cities[i];
      const isC = units[i];
      panel.set('temp' + i, { text: conv(c.c, isC) + '°' + (isC ? 'C' : 'F') });
      panel.set('hl' + i, { text: 'H ' + conv(c.hi, isC) + '°    L ' + conv(c.lo, isC) + '°' });
    }
    const allC = units[0] && units[1] && units[2];
    const allF = !units[0] && !units[1] && !units[2];
    panel.set('unitText', { text: allC ? '°C' : allF ? '°F' : 'Mixed' });
  }
  refresh();

  panel.on('units', 'click', () => {
    const allC = units[0] && units[1] && units[2];
    const v = !allC;
    units[0] = units[1] = units[2] = v;
    refresh();
    panel.set('sub', { text: 'All cities in °' + (v ? 'C' : 'F') });
  });

  // ---------------------------------------------------------------- icons
  const icons = [makeSunIcon(), makeRainIcon(), makePartlyIcon()];
  const xs = [-0.18, 0, 0.18];
  const iconY = 0.085;
  const iconZ = 0.115;

  icons.forEach((g, i) => {
    g.position.set(xs[i], iconY, iconZ);
    g.userData.pulse = 0;
    root.add(g);
    traits(g, {
      grab: true,
      onPress: () => {
        units[i] = !units[i];
        refresh();
        g.userData.pulse = 1;
        const c = cities[i];
        panel.set('sub', { text: c.name + ' shown in °' + (units[i] ? 'C' : 'F') });
      },
    });
  });

  const sunRays = icons[0].userData.rays;
  const drops = icons[1].userData.drops;

  // ---------------------------------------------------------------- loop
  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta || 0.016, 0.05);

      // Tokyo sun: slow spin of the rays (rotation only, no drift)
      if (!isGrabbed(icons[0])) sunRays.rotation.z = time * 0.3;

      // London rain: slow falling drops that wrap around
      if (!isGrabbed(icons[1])) {
        for (let i = 0; i < drops.length; i++) {
          const phase = (time * 0.035 + i * 0.014) % 0.032;
          drops[i].position.y = -0.040 - phase;
        }
      }

      // press feedback: quick pop that settles back
      for (let i = 0; i < icons.length; i++) {
        const g = icons[i];
        if (isGrabbed(g)) continue;
        const p = g.userData.pulse || 0;
        if (p > 0.002) {
          g.userData.pulse = p * Math.exp(-dt * 7);
          g.scale.setScalar(1 + 0.12 * g.userData.pulse);
        } else if (p !== 0) {
          g.userData.pulse = 0;
          g.scale.setScalar(1);
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
