    </style>
    <div class="card">
      <span class="title">Stoneware Mug</span>
      <span class="price" id="price">$12.00</span>
      <div class="row"><span class="label">Material</span><span class="value">Glazed stoneware</span></div>
      <div class="row"><span class="label">Capacity</span><span class="value">350 ml</span></div>
      <div class="row"><span class="label">Glaze</span><span class="value" id="glaze">Sand</span></div>
