export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  /* ------------------------------------------------------------------ *
   * Decorative "×" floating at the left — grabbable so hands have work
   * ------------------------------------------------------------------ */
  const crossGroup = new THREE.Group();
  crossGroup.name = 'TimesSign';
  const barGeo = new THREE.BoxGeometry(0.11, 0.021, 0.021);
  const barMat = new THREE.MeshStandardMaterial({
    color: 0xffd166, emissive: 0xc47a00, emissiveIntensity: 0.55, roughness: 0.45, metalness: 0.15,
  });
  const barA = new THREE.Mesh(barGeo, barMat);
  barA.rotation.z = Math.PI / 4;
  const barB = new THREE.Mesh(barGeo, barMat);
  barB.rotation.z = -Math.PI / 4;
  crossGroup.add(barA, barB);
  crossGroup.position.set(-0.30, 0.16, 0.03);
  root.add(crossGroup);
  traits(crossGroup, { grab: true });

  /* ------------------------------------------------------------------ *
   * Score tower (grows one block per answered question)
   * ------------------------------------------------------------------ */
  const cubeGeo = new THREE.BoxGeometry(0.05, 0.05, 0.05);
  const cubeGood = new THREE.MeshStandardMaterial({
    color: 0x2fd07a, emissive: 0x0e8c4a, emissiveIntensity: 0.6, roughness: 0.5,
  });
  const cubeBad = new THREE.MeshStandardMaterial({
    color: 0xe05252, emissive: 0x8a1f1f, emissiveIntensity: 0.5, roughness: 0.5,
  });
  const cubes = [];
  const pops = [];
  const TOWER_X = 0.30;
  const TOWER_Z = 0.05;

  function addCube(good) {
    const n = cubes.length;
    const cube = new THREE.Mesh(cubeGeo, good ? cubeGood : cubeBad);
    cube.name = 'ScoreCube' + (n + 1);
    cube.position.set(TOWER_X, 0.03 + n * 0.056, TOWER_Z);
    cube.rotation.y = n * 0.28;
    cube.scale.setScalar(0.2);
    root.add(cube);
    cubes.push(cube);
    pops.push({ mesh: cube, t: 0 });
  }

  /* ------------------------------------------------------------------ *
   * Quiz data
   * ------------------------------------------------------------------ */
  const base = [[7, 8], [6, 9], [12, 4], [9, 7], [8, 8]];
  const TOTAL = base.length;

  const questions = base.map(function (pair, i) {
    const a = pair[0];
    const b = pair[1];
    const correct = a * b;
    const opts = [correct];
    const cands = [correct + a, correct - a, correct + b, correct - b,
                   correct + 10, correct - 10, correct + 2, correct - 2];
    for (let c = 0; c < cands.length && opts.length < 4; c++) {
      const v = cands[c];
      if (v > 0 && opts.indexOf(v) === -1) opts.push(v);
    }
    // put the right answer in a different slot for each question
    const ci = opts.indexOf(correct);
    const ti = (i * 3 + 1) % 4;
    const tmp = opts[ti];
    opts[ti] = opts[ci];
    opts[ci] = tmp;
    return { a: a, b: b, correct: correct, options: opts };
  });

  /* ------------------------------------------------------------------ *
   * Panel
   * ------------------------------------------------------------------ */
  const panel = ui(`
    <style>
      .panel { display: flex; flex-direction: column; gap: 14px; width: 472px;
               padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
               border-radius: 22px; background-color: #1c1f26; }
      .head { display: flex; flex-direction: row; align-items: center; justify-content: space-between; }
      .title { color: #ffffff; font-size: 26px; font-weight: 700; }
      .score { color: #7fd1ff; font-size: 24px; font-weight: 700; }
      .q { color: #ffd166; font-size: 44px; font-weight: 700; text-align: center; }
      .grid { display: flex; flex-direction: column; gap: 12px; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .opt { display: flex; align-items: center; justify-content: center;
             width: 230px; height: 62px; border-radius: 14px;
             background-color: #2f3540; border-width: 0px; }
      .ot { color: #ffffff; font-size: 30px; font-weight: 700; }
      .fb { color: #a9b2c0; font-size: 21px; text-align: center; }
      .restart { display: none; align-items: center; justify-content: center;
                 width: 472px; height: 60px; border-radius: 14px; background-color: #2f6fdb; }
      .rt { color: #ffffff; font-size: 26px; font-weight: 700; }
    </style>
    <div class="panel">
      <div class="head">
        <span class="title">Multiplication Quiz</span>
        <span class="score" id="score">Score 0/5</span>
      </div>
      <span class="q" id="question"></span>
      <div class="grid" id="grid">
        <div class="row">
          <button class="opt" id="opt0"><span class="ot" id="opt0t"></span></button>
          <button class="opt" id="opt1"><span class="ot" id="opt1t"></span></button>
        </div>
        <div class="row">
          <button class="opt" id="opt2"><span class="ot" id="opt2t"></span></button>
          <button class="opt" id="opt3"><span class="ot" id="opt3t"></span></button>
        </div>
      </div>
      <button class="restart" id="restart"><span class="rt">Play again</span></button>
      <span class="fb" id="fb"></span>
    </div>`, { width: 0.40, position: [0, 0.23, 0] });
  root.add(panel.object3D);

  /* ------------------------------------------------------------------ *
   * State machine
   * ------------------------------------------------------------------ */
  let idx = 0;
  let score = 0;
  let answered = false;
  let waiting = false;
  let waitT = 0;
  let finished = false;

  function updateScore() {
    panel.set('score', { text: 'Score ' + score + '/' + TOTAL });
  }

  function showQuestion(i) {
    const q = questions[i];
    panel.set('question', { text: q.a + ' × ' + q.b + ' = ?' });
    for (let k = 0; k < 4; k++) {
      panel.set('opt' + k, { backgroundColor: '#2f3540', display: 'flex' });
      panel.set('opt' + k + 't', { text: String(q.options[k]) });
    }
    panel.set('fb', { text: 'Press the answer you think is right', color: '#a9b2c0' });
  }

  function answer(k) {
    if (answered || finished) return;
    const q = questions[idx];
    const chosen = q.options[k];
    answered = true;
    waiting = true;
    waitT = 0;

    if (chosen === q.correct) {
      score += 1;
      panel.set('opt' + k, { backgroundColor: '#1f7a4a' });
      panel.set('fb', { text: 'Correct!', color: '#59d98a' });
      addCube(true);
    } else {
      const ci = q.options.indexOf(q.correct);
      panel.set('opt' + k, { backgroundColor: '#8a2b2b' });
      panel.set('opt' + ci, { backgroundColor: '#1f7a4a' });
      panel.set('fb', {
        text: 'Not quite — ' + q.a + ' × ' + q.b + ' = ' + q.correct,
        color: '#ff9a9a',
      });
      addCube(false);
    }
    updateScore();
  }

  function showEnd() {
    panel.set('question', { text: 'Quiz complete!' });
    panel.set('grid', { display: 'none' });
    panel.set('restart', { display: 'flex' });
    let msg = 'You scored ' + score + ' out of ' + TOTAL + '.';
    if (score === TOTAL) msg = 'Perfect score — ' + TOTAL + ' out of ' + TOTAL + '!';
    else if (score >= 3) msg = 'Nice work — ' + score + ' out of ' + TOTAL + '.';
    panel.set('fb', { text: msg, color: score >= 3 ? '#59d98a' : '#ffd166' });
  }

  function advance() {
    answered = false;
    idx += 1;
    if (idx >= TOTAL) {
      finished = true;
      showEnd();
    } else {
      showQuestion(idx);
    }
  }

  for (let k = 0; k < 4; k++) {
    (function (slot) {
      panel.on('opt' + slot, 'click', function () { answer(slot); });
    })(k);
  }

  panel.on('restart', 'click', function () {
    if (!finished) return;
    finished = false;
    waiting = false;
    answered = false;
    idx = 0;
    score = 0;
    waitT = 0;
    for (let i = 0; i < cubes.length; i++) root.remove(cubes[i]);
    cubes.length = 0;
    pops.length = 0;
    panel.set('restart', { display: 'none' });
    panel.set('grid', { display: 'flex' });
    updateScore();
    showQuestion(0);
  });

  updateScore();
  showQuestion(0);

  /* ------------------------------------------------------------------ *
   * Per-frame animation
   * ------------------------------------------------------------------ */
  let crossAngle = 0;

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(crossGroup)) {
        crossAngle += delta * 0.35;
        crossGroup.rotation.y = crossAngle;
      }

      for (let i = pops.length - 1; i >= 0; i--) {
        const p = pops[i];
        p.t += delta * 4;
        const s = Math.min(1, p.t);
        const eased = 1 - (1 - s) * (1 - s);
        p.mesh.scale.setScalar(0.2 + 0.8 * eased);
        if (s >= 1) {
          p.mesh.scale.setScalar(1);
          pops.splice(i, 1);
        }
      }

      if (waiting) {
        waitT += delta;
        if (waitT > 1.3) {
          waiting = false;
          advance();
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------- quiz data ----------------
  const TOTAL = 5;
  const QUIZ = [
    { q: '6 × 7', a: 42, opts: [36, 42, 48, 54] },
    { q: '8 × 9', a: 72, opts: [63, 81, 72, 76] },
    { q: '7 × 12', a: 84, opts: [74, 84, 94, 82] },
    { q: '9 × 9', a: 81, opts: [72, 81, 90, 99] },
    { q: '5 × 14', a: 70, opts: [65, 60, 75, 70] },
  ];
  const results = [0, 0, 0, 0, 0]; // 0 = unanswered, 1 = right, 2 = wrong

  // ---------------- 3D progress tiles ----------------
  const tileGeo = new THREE.BoxGeometry(0.036, 0.036, 0.036);
  const matIdle = new THREE.MeshStandardMaterial({ color: 0x39404f, emissive: 0x0b0e13, roughness: 0.6 });
  const matActive = new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0xb37a00, emissiveIntensity: 0.9, roughness: 0.4 });
  const matRight = new THREE.MeshStandardMaterial({ color: 0x3ecf78, emissive: 0x1a8f45, emissiveIntensity: 0.9, roughness: 0.4 });
  const matWrong = new THREE.MeshStandardMaterial({ color: 0xe2584f, emissive: 0x8f2721, emissiveIntensity: 0.9, roughness: 0.4 });

  const tiles = [];
  for (let i = 0; i < TOTAL; i++) {
    const tile = new THREE.Mesh(tileGeo, matIdle);
    tile.name = 'ProgressTile' + (i + 1);
    tile.position.set((i - (TOTAL - 1) / 2) * 0.056, 0.05, 0.16);
    root.add(tile);
    tiles.push(tile);
  }

  // ---------------- quiz panel ----------------
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 22px;
              background-color: #1c1f26; width: 560px; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .row { flex-direction: row; justify-content: space-between; align-items: center;
             gap: 12px; width: 512px; }
      .meta { color: #9aa3b0; font-size: 20px; }
      .score { color: #ffd166; font-size: 22px; font-weight: 700; }
      .question { color: #ffffff; font-size: 34px; font-weight: 700; text-align: center; width: 512px; }
      .btn { width: 250px; height: 66px; border-radius: 14px; background-color: #2b3140;
             justify-content: center; align-items: center; }
      .btn-text { color: #ffffff; font-size: 26px; font-weight: 700; }
      .actions { flex-direction: row; justify-content: center; width: 512px; }
      .action { width: 260px; height: 58px; border-radius: 14px; background-color: #2f6fdb;
                justify-content: center; align-items: center; }
      .action-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .feedback { color: #9aa3b0; font-size: 20px; text-align: center; width: 512px; }
    </style>
    <div class="card">
      <span class="title">Multiplication Quiz</span>
      <div class="row">
        <span class="meta" id="meta">Question 1 of 5</span>
        <span class="score" id="score">Score 0 / 5</span>
      </div>
      <span class="question" id="question">6 × 7 = ?</span>
      <div class="row" id="row0">
        <button class="btn" id="a0"><span class="btn-text" id="a0t">36</span></button>
        <button class="btn" id="a1"><span class="btn-text" id="a1t">42</span></button>
      </div>
      <div class="row" id="row1">
        <button class="btn" id="a2"><span class="btn-text" id="a2t">48</span></button>
        <button class="btn" id="a3"><span class="btn-text" id="a3t">54</span></button>
      </div>
      <span class="feedback" id="feedback">Pinch a number to answer.</span>
      <div class="actions">
        <button class="action" id="action"><span class="action-text" id="actiont">Next question</span></button>
      </div>
    </div>`, { width: 0.4, position: [0, 0.26, 0] });
  root.add(panel.object3D);

  // ---------------- state ----------------
  let qIndex = 0;
  let score = 0;
  let phase = 'answering'; // 'answering' | 'answered' | 'results'

  function refreshTiles() {
    for (let i = 0; i < TOTAL; i++) {
      let m = matIdle;
      if (results[i] === 1) m = matRight;
      else if (results[i] === 2) m = matWrong;
      else if (phase !== 'results' && i === qIndex) m = matActive;
      tiles[i].material = m;
    }
  }

  function showQuestion() {
    const item = QUIZ[qIndex];
    phase = 'answering';
    panel.set('meta', { text: 'Question ' + (qIndex + 1) + ' of ' + TOTAL });
    panel.set('score', { text: 'Score ' + score + ' / ' + TOTAL });
    panel.set('question', { text: item.q + ' = ?' });
    panel.set('feedback', { text: 'Pinch a number to answer.', color: '#9aa3b0' });
    panel.set('row0', { display: 'flex' });
    panel.set('row1', { display: 'flex' });
    for (let i = 0; i < 4; i++) {
      panel.set('a' + i + 't', { text: String(item.opts[i]) });
      panel.set('a' + i, { backgroundColor: '#2b3140' });
    }
    panel.set('action', { display: 'none' });
    refreshTiles();
  }

  function choose(i) {
    if (phase !== 'answering') return;
    const item = QUIZ[qIndex];
    const correct = item.opts.indexOf(item.a);
    phase = 'answered';

    if (i === correct) {
      score++;
      results[qIndex] = 1;
      panel.set('a' + i, { backgroundColor: '#2f9e5f' });
      panel.set('feedback', { text: 'Correct!   ' + item.q + ' = ' + item.a, color: '#5ee08a' });
    } else {
      results[qIndex] = 2;
      panel.set('a' + i, { backgroundColor: '#b23b36' });
      panel.set('a' + correct, { backgroundColor: '#2f9e5f' });
      panel.set('feedback', { text: 'Not quite.   ' + item.q + ' = ' + item.a, color: '#ff8a80' });
    }

    panel.set('score', { text: 'Score ' + score + ' / ' + TOTAL });
    panel.set('actiont', { text: qIndex < TOTAL - 1 ? 'Next question' : 'See results' });
    panel.set('action', { display: 'flex' });
    refreshTiles();
  }

  function showResults() {
    phase = 'results';
    panel.set('meta', { text: 'Quiz complete' });
    panel.set('question', { text: score + ' / ' + TOTAL + ' correct' });
    panel.set('row0', { display: 'none' });
    panel.set('row1', { display: 'none' });
    let msg = 'Keep practising — you will get there.';
    if (score === TOTAL) msg = 'Perfect score! Every answer right.';
    else if (score >= 3) msg = 'Nice work! Almost all of them.';
    panel.set('feedback', { text: msg, color: '#ffd166' });
    panel.set('actiont', { text: 'Play again' });
    panel.set('action', { display: 'flex' });
    refreshTiles();
  }

  function resetQuiz() {
    qIndex = 0;
    score = 0;
    for (let i = 0; i < TOTAL; i++) results[i] = 0;
    showQuestion();
  }

  // ---------------- wiring ----------------
  for (let i = 0; i < 4; i++) {
    panel.on('a' + i, 'click', () => choose(i));
  }

  panel.on('action', 'click', () => {
    if (phase === 'answered') {
      if (qIndex < TOTAL - 1) {
        qIndex++;
        showQuestion();
      } else {
        showResults();
      }
    } else if (phase === 'results') {
      resetQuiz();
    }
  });

  showQuestion();

  return {
    root,
    update(time) {
      for (let i = 0; i < TOTAL; i++) {
        const t = tiles[i];
        t.position.y = 0.05 + Math.sin(time * 1.2 + i * 0.6) * 0.006;
        t.rotation.y = Math.sin(time * 0.6 + i * 0.8) * 0.3;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ------------------------------------------------------------------ data
  const cities = [
    { name: 'San Francisco', condition: 'Cloudy', tempC: 16, humidity: 72, wind: 18, kind: 'cloud' },
    { name: 'Tokyo',         condition: 'Rain',   tempC: 22, humidity: 83, wind: 14, kind: 'rain'  },
    { name: 'Cairo',         condition: 'Sunny',  tempC: 34, humidity: 25, wind: 11, kind: 'sun'   },
  ];
  const xs = [-0.26, 0, 0.26];
  const cardY = 0.10;
  const iconY = 0.20;

  let useF = false;
  let selected = -1;
  const fmt = (c) => (useF ? Math.round((c * 9) / 5 + 32) + '\u00B0F' : Math.round(c) + '\u00B0C');

  // ------------------------------------------------------- shared resources
  const sphereGeo = new THREE.SphereGeometry(1, 20, 12);
  const dropGeo = new THREE.SphereGeometry(1, 8, 6);
  const rayGeo = new THREE.CylinderGeometry(0.0032, 0.0032, 0.016, 6);
  const dummy = new THREE.Object3D();
  const drops = [];

  // ------------------------------------------------------------------ icons
  function makeSun() {
    const g = new THREE.Group();
    const core = new THREE.Mesh(
      sphereGeo,
      new THREE.MeshStandardMaterial({ color: 0xffcf3d, emissive: 0xff9a00, emissiveIntensity: 0.9, roughness: 0.45 }),
    );
    core.name = 'SunCore';
    core.scale.setScalar(0.030);
    g.add(core);

    const rays = new THREE.InstancedMesh(
      rayGeo,
      new THREE.MeshStandardMaterial({ color: 0xffc63a, emissive: 0xff8c00, emissiveIntensity: 0.7, roughness: 0.5 }),
      8,
    );
    rays.name = 'SunRays';
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * Math.PI * 2;
      dummy.position.set(Math.cos(a) * 0.044, Math.sin(a) * 0.044, 0);
      dummy.rotation.set(0, 0, a - Math.PI / 2);
      dummy.scale.setScalar(1);
      dummy.updateMatrix();
      rays.setMatrixAt(i, dummy.matrix);
    }
    rays.instanceMatrix.needsUpdate = true;
    g.add(rays);
    return g;
  }

  function makeCloud(color) {
    const g = new THREE.Group();
    const mat = new THREE.MeshStandardMaterial({ color, roughness: 0.95, metalness: 0 });
    const blobs = [
      [0.0,    0.006, 0.030],
      [-0.027, -0.005, 0.021],
      [0.026,  -0.004, 0.023],
      [0.012,   0.019, 0.019],
    ];
    for (let i = 0; i < blobs.length; i++) {
      const b = blobs[i];
      const m = new THREE.Mesh(sphereGeo, mat);
      m.name = 'CloudBlob' + i;
      m.position.set(b[0], b[1], 0);
      m.scale.set(b[2], b[2] * 0.82, b[2] * 0.92);
      g.add(m);
    }
    return g;
  }

  function addRain(g) {
    const dropMat = new THREE.MeshStandardMaterial({
      color: 0x63b8ff, emissive: 0x1f6fd0, emissiveIntensity: 0.7, roughness: 0.3,
    });
    for (let i = 0; i < 3; i++) {
      const d = new THREE.Mesh(dropGeo, dropMat);
      d.name = 'RainDrop' + i;
      d.scale.set(0.0035, 0.0085, 0.0035);
      d.position.set(-0.024 + i * 0.024, -0.034, 0);
      g.add(d);
      drops.push({ mesh: d, phase: i / 3 });
    }
  }

  const icons = [];
  for (let i = 0; i < cities.length; i++) {
    const c = cities[i];
    let g;
    if (c.kind === 'sun') {
      g = makeSun();
    } else if (c.kind === 'rain') {
      g = makeCloud(0x93a3b8);
      addRain(g);
    } else {
      g = makeCloud(0xe2e9f3);
    }
    g.name = 'Icon_' + c.name.replace(/\s/g, '');
    g.position.set(xs[i], iconY, 0.02);
    root.add(g);
    icons.push(g);
  }

  // -------------------------------------------------------------- city cards
  const cards = [];
  for (let i = 0; i < cities.length; i++) {
    const c = cities[i];
    const h = ui(`
      <style>
        .card { flex-direction: column; align-items: center; gap: 2px;
                padding-top: 12px; padding-bottom: 12px; padding-left: 10px; padding-right: 10px;
                border-radius: 16px; background-color: #22262d;
                border-width: 2px; border-color: #343b47; }
        .city { color: #e9eef5; font-size: 24px; font-weight: 700; text-align: center; }
        .cond { color: #8e99a8; font-size: 19px; }
        .temp { color: #ffffff; font-size: 42px; font-weight: 700; }
      </style>
      <div class="card" id="card${i}">
        <span class="city" id="city${i}">${c.name}</span>
        <span class="cond" id="cond${i}">${c.condition}</span>
        <span class="temp" id="temp${i}">${fmt(c.tempC)}</span>
      </div>`, { width: 0.21, position: [xs[i], cardY, -0.03] });
    root.add(h.object3D);
    cards.push(h);
