      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .detail { color: #97a2b1; font-size: 19px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btntext { color: #ffffff; font-size: 19px; font-weight: 700; }
    </style>
    <div class="hdr">
      <div class="col">
        <span class="title">Weather Dashboard</span>
        <span class="detail" id="detail1">Press a city card</span>
        <span class="detail" id="detail2">for humidity and wind</span>
      </div>
      <button class="btn" id="unit"><span class="btntext" id="unitLabel">Switch to \u00B0F</span></button>
    </div>`, { width: 0.44, position: [0, 0.325, -0.10] });
  root.add(header.object3D);

  // ------------------------------------------------------------ interaction
  function paintSelection() {
    for (let i = 0; i < cards.length; i++) {
      const on = i === selected;
      cards[i].set('card' + i, { backgroundColor: on ? '#2f6fdb' : '#22262d' });
      cards[i].set('cond' + i, { color: on ? '#dbe7ff' : '#8e99a8' });
    }
  }

  function select(i) {
    selected = i;
    paintSelection();
    const c = cities[i];
    header.set('detail1', { text: c.name + ' \u00B7 ' + c.condition });
    header.set('detail2', { text: 'Humidity ' + c.humidity + '% \u00B7 Wind ' + c.wind + ' km/h' });
