  for (let i = 0; i < cards.length; i++) {
    const idx = i;
    cards[i].on('card' + i, 'click', () => select(idx));
    traits(icons[i], { onPress: () => select(idx), grab: true });
  }

  header.on('unit', 'click', () => {
    useF = !useF;
    for (let i = 0; i < cards.length; i++) {
      cards[i].set('temp' + i, { text: fmt(cities[i].tempC) });
    }
    header.set('unitLabel', { text: useF ? 'Switch to \u00B0C' : 'Switch to \u00B0F' });
  });

  // ----------------------------------------------------------------- update
  return {
    root,
    update(time) {
      for (let i = 0; i < drops.length; i++) {
        const d = drops[i];
        const p = (time * 0.8 + d.phase) % 1;
        d.mesh.position.y = -0.026 - p * 0.044;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---- Week model -------------------------------------------------------
  const now = new Date();
  const todayIdx = (now.getDay() + 6) % 7; // 0 = Monday … 6 = Sunday

  const habits = [
    { name: 'Reading', cls: 'c0', color: 0x4a8cff, css: '#4a8cff',
      checks: [false, false, false, false, false, false, false] },
    { name: 'Exercise', cls: 'c1', color: 0x3ddc84, css: '#3ddc84',
      checks: [false, false, false, false, false, false, false] },
    { name: 'Meditation', cls: 'c2', color: 0xffa64a, css: '#ffa64a',
      checks: [false, false, false, false, false, false, false] },
  ];

  // Seed a few days so a streak is visible the moment it appears.
  for (let k = 0; k < 3; k++) {
    const d = todayIdx - k;
    if (d >= 0) habits[0].checks[d] = true;
  }
  if (todayIdx >= 0) habits[1].checks[todayIdx] = true;

  const dayLetters = ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'];

  function streakOf(h) {
    let i = todayIdx;
    if (!h.checks[i]) i = todayIdx - 1; // today not done yet: count up to yesterday
    let s = 0;
    while (i >= 0 && h.checks[i]) { s++; i--; }
    return s;
  }

  // ---- 2D panel ---------------------------------------------------------
  const rows = habits.map((h, hi) => {
    const days = dayLetters.map((letter, d) =>
      `<button class="day${d === todayIdx ? ' today' : ''}" id="h${hi}d${d}">` +
      `<span class="daytext" id="h${hi}d${d}t">${letter}</span></button>`
    ).join('');
    return `<div class="row">
      <div class="swatch ${h.cls}"></div>
      <span class="name">${h.name}</span>
      ${days}
      <span class="streak" id="s${hi}">0 days</span>
    </div>`;
  }).join('');

  const panel = ui(`
    <style>
      .panel { flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
               padding-left: 20px; padding-right: 20px; background-color: #1a1d22; border-radius: 22px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #98a1ac; font-size: 19px; }
      .row { flex-direction: row; align-items: center; gap: 6px; }
      .swatch { width: 16px; height: 16px; border-radius: 8px; }
      .c0 { background-color: #4a8cff; }
      .c1 { background-color: #3ddc84; }
      .c2 { background-color: #ffa64a; }
      .name { width: 130px; color: #ffffff; font-size: 21px; font-weight: 600; }
      .day { width: 46px; height: 46px; border-radius: 12px; background-color: #2a2e35;
             border-width: 0px; border-color: #2a2e35; align-items: center; justify-content: center; }
      .today { border-width: 3px; border-color: #7d8794; }
      .daytext { color: #8b939d; font-size: 17px; font-weight: 600; }
      .streak { width: 90px; color: #d7dbe2; font-size: 18px; font-weight: 600; text-align: right; }
      .total { color: #98a1ac; font-size: 18px; }
    </style>
    <div class="panel">
      <span class="title">This week</span>
      <span class="sub">Tap a day to check it off. Tap a tower to toggle today.</span>
      ${rows}
      <span class="total" id="total">0 of 21 check-ins</span>
    </div>`, { width: 0.46, position: [0, 0.31, -0.08] });
  root.add(panel.object3D);

  // ---- 3D streak towers -------------------------------------------------
  const cubeGeo = new THREE.BoxGeometry(0.026, 0.024, 0.026);
  const puckGeo = new THREE.CylinderGeometry(0.036, 0.036, 0.012, 24);
  const puckMat = new THREE.MeshStandardMaterial({ color: 0x33383f, roughness: 0.85, metalness: 0.1 });

  const towerX = [-0.16, 0, 0.16];
  const towerCounts = [0, 0, 0];
  const towerCubes = [];

  habits.forEach((h, hi) => {
    const blockMat = new THREE.MeshStandardMaterial({
      color: h.color, emissive: h.color, emissiveIntensity: 0.28, roughness: 0.45, metalness: 0.05,
    });

    const puck = new THREE.Mesh(puckGeo, puckMat);
    puck.name = 'Tower_' + h.name;
    puck.position.set(towerX[hi], 0.006, 0.12);
    root.add(puck);

    const name = h.name;
    traits(puck, {
      onPress: () => {
        const habit = habits.find((x) => x.name === name);
        habit.checks[todayIdx] = !habit.checks[todayIdx];
        refresh();
      },
    });

    const cubes = [];
    for (let i = 0; i < 7; i++) {
      const c = new THREE.Mesh(cubeGeo, blockMat);
      c.name = 'Block_' + h.name + '_' + i;
      c.position.set(towerX[hi], 0.024 + i * 0.028, 0.12);
      c.scale.setScalar(0.001);
      c.visible = false;
      root.add(c);
      cubes.push(c);
    }
    towerCubes.push(cubes);
  });

  // ---- State -> visuals -------------------------------------------------
  function refresh() {
    let total = 0;
    for (let hi = 0; hi < habits.length; hi++) {
      const h = habits[hi];
      let count = 0;
      for (let d = 0; d < 7; d++) {
        const on = h.checks[d];
        if (on) count++;
        panel.set('h' + hi + 'd' + d, {
          backgroundColor: on ? h.css : '#2a2e35',
          color: on ? '#10131a' : '#8b939d',
        });
        panel.set('h' + hi + 'd' + d + 't', { color: on ? '#10131a' : '#8b939d' });
      }
      towerCounts[hi] = count;
      total += count;
      const s = streakOf(h);
      panel.set('s' + hi, { text: s === 1 ? '1 day' : s + ' days' });
    }
    panel.set('total', { text: total + ' of 21 check-ins this week' });
  }

  // Wire up the 21 day buttons.
  habits.forEach((h, hi) => {
    for (let d = 0; d < 7; d++) {
      panel.on('h' + hi + 'd' + d, 'click', () => {
        h.checks[d] = !h.checks[d];
        refresh();
      });
    }
  });

  refresh();

  return {
    root,
    update(time, delta) {
      const dt = delta || 0.016;
      const k = Math.min(1, dt * 9);
      for (let hi = 0; hi < 3; hi++) {
        const cubes = towerCubes[hi];
        const target = towerCounts[hi];
        for (let i = 0; i < 7; i++) {
          const c = cubes[i];
          const goal = i < target ? 1 : 0.001;
          const cur = c.scale.x;
          const next = cur + (goal - cur) * k;
          c.scale.setScalar(next);
          c.visible = next > 0.06;
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- desk mat
  const mat = new THREE.Mesh(
    new THREE.PlaneGeometry(0.78, 0.46),
    new THREE.MeshBasicMaterial({ color: 0x0d1117, transparent: true, opacity: 0.2, depthWrite: false }),
  );
  mat.rotation.x = -Math.PI / 2;
  mat.position.set(0, 0.001, 0.05);
  root.add(mat);

  // ---------------------------------------------------------------- materials
  const geoH = new THREE.SphereGeometry(0.028, 24, 16);
  const geoO = new THREE.SphereGeometry(0.042, 28, 18);
  const matH = new THREE.MeshStandardMaterial({
    color: 0xeef2f8, roughness: 0.3, metalness: 0.1,
    emissive: 0x1a1e26, emissiveIntensity: 0.4,
  });
  const matO = new THREE.MeshStandardMaterial({
    color: 0xe8402c, roughness: 0.4, metalness: 0.06,
    emissive: 0x3a0d06, emissiveIntensity: 0.5,
  });

  // ---------------------------------------------------------------- the atoms
  const specs = [
    { type: 'H', pos: [-0.26, 0.028, 0.10] },
    { type: 'H', pos: [-0.13, 0.028, 0.10] },
    { type: 'O', pos: [0.00, 0.042, 0.10] },
    { type: 'O', pos: [0.15, 0.042, 0.10] },
    { type: 'H', pos: [0.28, 0.028, 0.10] },
  ];

  const facts = {
    H: 'Hydrogen: 1 proton, 1 electron, no neutrons — the lightest element.',
    O: 'Oxygen: 8 protons, 8 neutrons, 8 electrons — about 21% of the air you breathe.',
  };

  const atoms = [];
  for (let i = 0; i < specs.length; i++) {
    const spec = specs[i];
    const mesh = new THREE.Mesh(spec.type === 'H' ? geoH : geoO, spec.type === 'H' ? matH : matO);
    mesh.name = spec.type === 'H' ? 'Hydrogen' : 'Oxygen';
    mesh.position.set(spec.pos[0], spec.pos[1], spec.pos[2]);
    root.add(mesh);
    const type = spec.type;
    const home = spec.pos.slice();
    traits(mesh, {
      grab: true,
      onPress: () => panel.set('status', { text: facts[type], color: '#9ecbff' }),
    });
    atoms.push({ mesh, type, home });
  }

  // ---------------------------------------------------------------- bonds
  const BOND_POOL = 10;
  const bondGeo = new THREE.CylinderGeometry(0.010, 0.010, 1, 8, 1);
  const bondMat = new THREE.MeshStandardMaterial({
    color: 0xa9b6c8, roughness: 0.55, metalness: 0.1,
    emissive: 0x1b2027, emissiveIntensity: 0.5,
  });
  const bonds = [];
  for (let i = 0; i < BOND_POOL; i++) {
    const b = new THREE.Mesh(bondGeo, bondMat);
    b.name = 'Bond';
    b.visible = false;
    root.add(b);
    bonds.push(b);
  }

  function bondLimit(a, b) {
    if (a === 'H' && b === 'H') return 0.080;
    if (a === 'O' && b === 'O') return 0.110;
    return 0.095; // H–O
  }

  // ---------------------------------------------------------------- analysis
  function analyze() {
    const n = atoms.length;
    const parent = [0, 1, 2, 3, 4];
    function find(x) {
      while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
      return x;
    }
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const d = atoms[i].mesh.position.distanceTo(atoms[j].mesh.position);
        if (d < bondLimit(atoms[i].type, atoms[j].type)) {
          const ri = find(i);
          const rj = find(j);
          if (ri !== rj) parent[ri] = rj;
        }
      }
    }
    const groups = new Map();
    for (let i = 0; i < n; i++) {
      const r = find(i);
      let g = groups.get(r);
      if (!g) { g = { H: 0, O: 0, size: 0 }; groups.set(r, g); }
      g[atoms[i].type] += 1;
      g.size += 1;
    }
    let best = null;
    let water = false;
    groups.forEach((g) => {
      if (g.H === 2 && g.O === 1) water = true;
      if (g.size > 1 && (!best || g.size > best.size)) best = g;
    });
    return { water, best };
  }

  function check() {
    const result = analyze();
    if (result.water) {
      panel.set('status', {
        text: '\u2714 That\u2019s water! H\u2082O \u2014 two hydrogen atoms bonded to one oxygen atom.',
        color: '#7ef0a8',
      });
      return;
    }
    const best = result.best;
    if (!best) {
      panel.set('status', {
        text: 'Nothing is bonded yet. Push two hydrogens and one oxygen together until they touch, then check again.',
        color: '#f5c86b',
      });
      return;
    }
    const H = best.H;
    const O = best.O;
    let msg;
    if (H === 2 && O === 0) msg = 'That\u2019s H\u2082, hydrogen gas. Add one oxygen atom to make water.';
    else if (H === 0 && O === 2) msg = 'That\u2019s O\u2082, oxygen gas. Add two hydrogen atoms to make water.';
    else if (H === 2 && O === 2) msg = 'That\u2019s H\u2082O\u2082, hydrogen peroxide. Remove one oxygen.';
    else if (H === 1 && O === 1) msg = 'That\u2019s a hydroxyl group (OH). Add one more hydrogen.';
    else if (H === 3 && O === 1) msg = 'That\u2019s hydronium (H\u2083O\u207a). Remove one hydrogen.';
    else msg = 'That cluster has ' + H + ' hydrogen and ' + O + ' oxygen atoms. Water needs exactly 2 H and 1 O.';
    panel.set('status', { text: msg, color: '#f5c86b' });
  }

  // ---------------------------------------------------------------- panel
  const panel = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1b1f26; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #a8b0bd; font-size: 21px; }
      .row { flex-direction: row; align-items: center; gap: 16px; }
      .legend-h { color: #ffffff; font-size: 20px; }
      .legend-o { color: #ff7a63; font-size: 20px; }
      .status { color: #d7dbe2; font-size: 21px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 24px; padding-right: 24px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-alt { padding-top: 12px; padding-bottom: 12px; padding-left: 24px; padding-right: 24px;
                 border-radius: 12px; background-color: #343a44; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="sub">Water is H&#8322;O: two hydrogen atoms and one oxygen atom.</span>
      <div class="row">
        <span class="legend-h">&#9679; Hydrogen</span>
        <span class="legend-o">&#9679; Oxygen</span>
      </div>
      <span class="status" id="status">Pinch an atom to pick it up. Atoms bond when they touch.</span>
      <div class="row">
        <button class="btn" id="check"><span class="btn-text">Check</span></button>
        <button class="btn-alt" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.42, position: [0, 0.31, -0.14] });
  root.add(panel.object3D);

  panel.on('check', 'click', check);
  panel.on('reset', 'click', () => {
    for (let i = 0; i < atoms.length; i++) {
      const a = atoms[i];
      a.mesh.position.set(a.home[0], a.home[1], a.home[2]);
    }
    panel.set('status', {
      text: 'Atoms reset. Pinch an atom to pick it up \u2014 atoms bond when they touch.',
      color: '#d7dbe2',
    });
  });

  // ---------------------------------------------------------------- loop
  const UP = new THREE.Vector3(0, 1, 0);
  const dir = new THREE.Vector3();

  return {
    root,
    update() {
      let used = 0;
      for (let i = 0; i < atoms.length; i++) {
        for (let j = i + 1; j < atoms.length; j++) {
          if (used >= bonds.length) break;
          const pa = atoms[i].mesh.position;
          const pb = atoms[j].mesh.position;
          if (pa.distanceTo(pb) >= bondLimit(atoms[i].type, atoms[j].type)) continue;
          dir.subVectors(pb, pa);
          const len = dir.length();
          if (len < 1e-5) continue;
          const bond = bonds[used++];
          bond.visible = true;
          bond.position.copy(pa).add(pb).multiplyScalar(0.5);
          dir.multiplyScalar(1 / len);
          bond.quaternion.setFromUnitVectors(UP, dir);
          bond.scale.set(1, len, 1);
        }
      }
      for (let k = used; k < bonds.length; k++) bonds[k].visible = false;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- work tray
  const tray = new THREE.Mesh(
    new THREE.BoxGeometry(0.38, 0.01, 0.28),
    new THREE.MeshStandardMaterial({ color: 0x232830, roughness: 0.9, metalness: 0.05 }),
  );
  tray.position.set(-0.19, 0.005, 0.09);
  tray.name = 'Tray';
  root.add(tray);

  // ---------------------------------------------------------------- atoms
  const R_O = 0.032;
  const R_H = 0.020;
  const TOP = 0.010; // top surface of the tray

  const geoO = new THREE.SphereGeometry(R_O, 28, 18);
  const geoH = new THREE.SphereGeometry(R_H, 22, 14);
  const matO = new THREE.MeshStandardMaterial({ color: 0xd6503c, roughness: 0.42, metalness: 0.08 });
  const matH = new THREE.MeshStandardMaterial({ color: 0xe9eff7, roughness: 0.5, metalness: 0.05 });

  const specs = [
    { type: 'O', home: [-0.30, TOP + R_O, 0.03] },
    { type: 'O', home: [-0.19, TOP + R_O, 0.03] },
    { type: 'H', home: [-0.30, TOP + R_H, 0.15] },
    { type: 'H', home: [-0.19, TOP + R_H, 0.15] },
    { type: 'H', home: [-0.08, TOP + R_H, 0.03] },
    { type: 'H', home: [-0.08, TOP + R_H, 0.15] },
  ];

  const atoms = specs.map((s, i) => {
    const isO = s.type === 'O';
    const mesh = new THREE.Mesh(isO ? geoO : geoH, isO ? matO : matH);
    mesh.position.set(s.home[0], s.home[1], s.home[2]);
    mesh.name = (isO ? 'Oxygen' : 'Hydrogen') + '_' + (i + 1);
    root.add(mesh);
    return { mesh, type: s.type, radius: isO ? R_O : R_H, home: s.home };
  });

  // ---------------------------------------------------------------- bond rods
  const UP = new THREE.Vector3(0, 1, 0);
  const vDir = new THREE.Vector3();
  const bondGeo = new THREE.CylinderGeometry(1, 1, 1, 12, 1, false);
  const bondMat = new THREE.MeshStandardMaterial({
    color: 0xbcd4ff, emissive: 0x24405f, emissiveIntensity: 0.7, roughness: 0.45,
  });
  const bonds = [];
  for (let i = 0; i < 2; i++) {
    const b = new THREE.Mesh(bondGeo, bondMat);
    b.name = 'Bond_' + (i + 1);
    b.visible = false;
    root.add(b);
    bonds.push(b);
  }

  function hideBonds() {
    bonds[0].visible = false;
    bonds[1].visible = false;
  }

  function placeBond(mesh, a, b) {
    vDir.subVectors(b, a);
    const len = vDir.length();
    if (len < 1e-6) { mesh.visible = false; return; }
    mesh.position.copy(a).addScaledVector(vDir, 0.5);   // midpoint
    mesh.quaternion.setFromUnitVectors(UP, vDir.divideScalar(len));
    mesh.scale.set(0.007, len, 0.007);
    mesh.visible = true;
  }

  // ---------------------------------------------------------------- UI panel
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px;
              background-color: #1c2027; width: 460px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #cfd6e0; font-size: 21px; }
      .result { color: #cfd6e0; font-size: 23px; font-weight: 700; }
      .hint { color: #8b94a3; font-size: 19px; }
      .row { flex-direction: row; gap: 12px; }
      .btn { flex-direction: row; align-items: center; justify-content: center;
             padding-top: 12px; padding-bottom: 12px; padding-left: 20px; padding-right: 20px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn2 { background-color: #3a4049; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Build a water molecule</span>
      <span class="body">Pinch an atom and drag it. Water is 1 oxygen plus 2 hydrogens.</span>
      <span class="result" id="result">Bring atoms together, then press Check.</span>
      <span class="hint" id="hint">Red sphere = oxygen, white sphere = hydrogen.</span>
      <div class="row">
        <button class="btn" id="check"><span class="btn-text">Check</span></button>
        <button class="btn btn2" id="reset"><span class="btn-text">Reset</span></button>
      </div>
    </div>`, { width: 0.36, position: [0.26, 0.17, 0.02], rotationY: -0.35 });
  root.add(info.object3D);

  // ---------------------------------------------------------------- facts on tap
  const facts = {
    O: 'Oxygen: 8 protons, 8 neutrons, 8 electrons. It forms 2 bonds.',
    H: 'Hydrogen: 1 proton, 1 electron. It forms 1 bond.',
  };
  for (let i = 0; i < atoms.length; i++) {
    const a = atoms[i];
    traits(a.mesh, {
      grab: true,
      onPress: () => info.set('hint', { text: facts[a.type] }),
    });
  }

  // ---------------------------------------------------------------- analysis
  const parent = new Array(atoms.length).fill(0);

  function find(i) {
    while (parent[i] !== i) { parent[i] = parent[parent[i]]; i = parent[i]; }
    return i;
  }

  function check() {
    for (let i = 0; i < atoms.length; i++) parent[i] = i;

    // join atoms that are close enough to count as bonded
    for (let i = 0; i < atoms.length; i++) {
      for (let j = i + 1; j < atoms.length; j++) {
        const d = atoms[i].mesh.position.distanceTo(atoms[j].mesh.position);
        if (d < atoms[i].radius + atoms[j].radius + 0.022) {
          const ra = find(i);
          const rb = find(j);
          if (ra !== rb) parent[ra] = rb;
        }
      }
    }

    const groups = new Map();
    for (let i = 0; i < atoms.length; i++) {
      const r = find(i);
      if (!groups.has(r)) groups.set(r, []);
      groups.get(r).push(i);
    }

    let waterList = null;
    let best = null;
    let bestScore = -1;
    let bestO = 0;
    let bestH = 0;

    groups.forEach((list) => {
      let o = 0;
      for (let k = 0; k < list.length; k++) if (atoms[list[k]].type === 'O') o++;
      const h = list.length - o;
      if (o === 1 && h === 2 && waterList === null) waterList = list;
      const score = list.length * 10 + o;
      if (score > bestScore) { bestScore = score; best = list; bestO = o; bestH = h; }
    });

    if (waterList) {
      let oIdx = -1;
      const hs = [];
      for (let k = 0; k < waterList.length; k++) {
        const idx = waterList[k];
        if (atoms[idx].type === 'O') oIdx = idx; else hs.push(idx);
      }
      placeBond(bonds[0], atoms[oIdx].mesh.position, atoms[hs[0]].mesh.position);
      placeBond(bonds[1], atoms[oIdx].mesh.position, atoms[hs[1]].mesh.position);
      info.set('result', { text: 'Water! H2O - one oxygen bonded to two hydrogens.', color: '#8fe3a8' });
      info.set('hint', { text: 'The two O-H bonds sit at about 104.5 degrees.' });
      return;
    }

    hideBonds();

    if (!best || best.length < 2) {
      info.set('result', { text: 'Nothing is bonded yet - push the atoms until they touch.', color: '#f0b46a' });
      return;
    }

    let msg = 'Not a molecule yet - try again.';
    if (bestO === 1 && bestH === 1) {
      msg = 'That is a hydroxyl group (OH). Add one more hydrogen.';
    } else if (bestO === 1 && bestH === 3) {
      msg = 'That is a hydronium ion, H3O+. Water needs exactly two H.';
    } else if (bestO === 1 && bestH === 0) {
      msg = 'One lone oxygen. Bring two hydrogens to it.';
    } else if (bestO === 2 && bestH === 2) {
      msg = 'That is hydrogen peroxide, H2O2. Water has only one O.';
    } else if (bestO === 2 && bestH === 0) {
      msg = 'Two oxygens touching. Oxygen wants hydrogen here.';
    } else if (bestO === 0 && bestH === 2) {
      msg = 'Hydrogen gas, H2. Now bring in an oxygen.';
    } else if (bestO === 0 && bestH === 1) {
      msg = 'A single hydrogen atom. It needs an oxygen partner.';
    } else if (bestO === 2 && bestH === 1) {
      msg = 'Two oxygens and one hydrogen - not a molecule we want.';
    }
    info.set('result', { text: msg, color: '#f0b46a' });
    info.set('hint', { text: 'Water = 1 oxygen + 2 hydrogens.' });
  }

  function reset() {
    for (let i = 0; i < atoms.length; i++) {
      const a = atoms[i];
      a.mesh.position.set(a.home[0], a.home[1], a.home[2]);
    }
    hideBonds();
    info.set('result', { text: 'Fresh atoms. Drag them together.', color: '#cfd6e0' });
    info.set('hint', { text: 'Red sphere = oxygen, white sphere = hydrogen.' });
  }

  info.on('check', 'click', check);
  info.on('reset', 'click', reset);

  // ---------------------------------------------------------------- runtime
  return {
    root,
    update() {
      // A bond drawing is only valid until the user moves an atom again.
      if (bonds[0].visible || bonds[1].visible) {
        for (let i = 0; i < atoms.length; i++) {
          if (isGrabbed(atoms[i].mesh)) { hideBonds(); break; }
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- data
  const HABITS = [
    { name: 'Drink water', color: 0x34c759, hex: '#34c759' },
    { name: 'Read 20 min', color: 0x3d8bfd, hex: '#3d8bfd' },
    { name: 'Walk 5k steps', color: 0xff9f0a, hex: '#ff9f0a' },
  ];
  const state = HABITS.map(() => [false, false, false, false, false, false, false]);

  let today = 2; // Wednesday fallback
  try {
    const d = new Date();
    today = (d.getDay() + 6) % 7; // Mon = 0 … Sun = 6
  } catch (e) {
    today = 2;
  }

  // ---------------------------------------------------------------- layout
  const CELL = 0.044;
  const GAP_X = 0.052;
  const ROW_GAP = 0.072;
  const GRID_CX = 0.06;
  const TOP_Y = 0.225;
  const MID_Y = TOP_Y - ROW_GAP; // centre row / board centre
  const colX = (d) => GRID_CX + (d - 3) * GAP_X;
  const rowY = (h) => TOP_Y - h * ROW_GAP;

  // ---------------------------------------------------------------- board
  const board = new THREE.Mesh(
    new THREE.PlaneGeometry(0.4, 0.218),
    new THREE.MeshStandardMaterial({ color: 0x14171b, roughness: 0.95, metalness: 0.0 }),
  );
  board.name = 'Board';
  board.position.set(GRID_CX, MID_Y, -0.014);
  root.add(board);

  const todayBar = new THREE.Mesh(
    new THREE.PlaneGeometry(0.048, 0.218),
    new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.1, depthWrite: false }),
  );
  todayBar.name = 'TodayColumn';
  todayBar.position.set(colX(today), MID_Y, -0.01);
  root.add(todayBar);

  // ---------------------------------------------------------------- tiles
  const tileGeo = new THREE.BoxGeometry(CELL, CELL, 0.014);
  const offMat = new THREE.MeshStandardMaterial({ color: 0x2b3037, roughness: 0.8, metalness: 0.15 });
  const onMats = HABITS.map(
    (h) =>
      new THREE.MeshStandardMaterial({
        color: h.color,
        emissive: h.color,
        emissiveIntensity: 0.45,
        roughness: 0.45,
        metalness: 0.1,
      }),
  );

  const tiles = [];
  for (let h = 0; h < 3; h++) {
    for (let d = 0; d < 7; d++) {
      const tile = new THREE.Mesh(tileGeo, offMat);
      tile.name = 'Habit' + h + 'Day' + d;
      tile.position.set(colX(d), rowY(h), 0);
      root.add(tile);
      tiles.push({ mesh: tile, h, d, pop: 0 });
      traits(tile, { onPress: () => toggle(h, d) });
    }
  }

  // ---------------------------------------------------------------- check marks
  const shape = new THREE.Shape();
  shape.moveTo(-0.42, 0.02);
  shape.lineTo(-0.14, -0.3);
  shape.lineTo(0.44, 0.36);
  shape.lineTo(0.3, 0.5);
  shape.lineTo(-0.14, -0.02);
  shape.lineTo(-0.3, 0.18);
  shape.closePath();

  const checkGeo = new THREE.ShapeGeometry(shape);
  checkGeo.center();
  const checkMat = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    side: THREE.DoubleSide,
    transparent: true,
    opacity: 0.95,
    depthWrite: false,
  });
  const checks = new THREE.InstancedMesh(checkGeo, checkMat, 21);
  checks.name = 'CheckMarks';
  checks.frustumCulled = false;
  root.add(checks);

  const _m = new THREE.Matrix4();
  const _q = new THREE.Quaternion();
  const _p = new THREE.Vector3();
  const _s = new THREE.Vector3();
  const CHECK_SIZE = 0.028;

  function setCheck(idx, x, y, on) {
    _p.set(x, y, 0.0085);
    const s = on ? CHECK_SIZE : 0;
    _s.set(s, s, s);
    _m.compose(_p, _q, _s);
    checks.setMatrixAt(idx, _m);
  }

  // ---------------------------------------------------------------- panels
  const titleHandle = ui(
    `
    <style>
      .card { flex-direction: column; gap: 5px; padding-top: 12px; padding-bottom: 12px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #b9c0c9; font-size: 19px; }
      .prog { color: #6fd08c; font-size: 19px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">This Week</span>
      <span class="sub">Tap a square to check a habit off.</span>
      <span class="prog" id="progress">0 of 21 check-ins</span>
    </div>`,
    { width: 0.42, position: [0.06, 0.375, 0] },
  );
  root.add(titleHandle.object3D);

  const dayHandle = ui(
    `
    <style>
      .row { flex-direction: row; align-items: center; justify-content: center; gap: 12px;
             padding-top: 7px; padding-bottom: 7px; padding-left: 4px; padding-right: 4px;
             border-radius: 14px; background-color: #1a1d22; }
      .d { width: 40px; text-align: center; font-size: 21px; font-weight: 700;
           color: #8b939d; border-radius: 8px; }
    </style>
    <div class="row">
      <span class="d" id="d0">M</span>
      <span class="d" id="d1">T</span>
      <span class="d" id="d2">W</span>
      <span class="d" id="d3">T</span>
      <span class="d" id="d4">F</span>
      <span class="d" id="d5">S</span>
      <span class="d" id="d6">S</span>
    </div>`,
    { width: 0.36, position: [0.06, 0.29, 0] },
  );
  root.add(dayHandle.object3D);
  dayHandle.set('d' + today, { color: '#ffffff', backgroundColor: '#333a44' });

  const habitHandles = [];
  for (let h = 0; h < 3; h++) {
    const handle = ui(
      `
      <style>
        .h { flex-direction: column; gap: 2px; padding-top: 5px; padding-bottom: 5px;
             padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #1a1d22; }
        .toprow { flex-direction: row; align-items: center; gap: 8px; }
        .dot { width: 12px; height: 12px; border-radius: 6px; background-color: ${HABITS[h].hex}; }
        .name { color: #ffffff; font-size: 22px; font-weight: 700; }
        .streak { color: #8b939d; font-size: 17px; }
      </style>
      <div class="h">
        <div class="toprow">
          <div class="dot"></div>
          <span class="name">${HABITS[h].name}</span>
        </div>
        <span class="streak" id="streak${h}">Streak: 0 days</span>
      </div>`,
      { width: 0.2, position: [-0.26, rowY(h), 0] },
    );
    root.add(handle.object3D);
    habitHandles.push(handle);
  }

  // ---------------------------------------------------------------- logic
  function streakFor(h) {
    const days = state[h];
    let i = today;
    if (!days[i]) i -= 1; // today is still open, count from yesterday
    let n = 0;
    while (i >= 0 && days[i]) {
      n += 1;
      i -= 1;
    }
    return n;
  }

  function refresh() {
    let total = 0;
    for (let h = 0; h < 3; h++) {
      let all = true;
      for (let d = 0; d < 7; d++) {
        const idx = h * 7 + d;
        const on = state[h][d];
        const t = tiles[idx];
        t.mesh.material = on ? onMats[h] : offMat;
        setCheck(idx, t.mesh.position.x, t.mesh.position.y, on);
        if (on) total += 1;
        else all = false;
      }
      const s = streakFor(h);
      let txt;
      if (all) txt = 'Perfect week! 7/7';
      else if (s === 0) txt = 'Streak: 0 days';
      else if (s === 1) txt = 'Streak: 1 day';
      else txt = 'Streak: ' + s + ' days';
      habitHandles[h].set('streak' + h, { text: txt, color: s > 0 ? HABITS[h].hex : '#8b939d' });
    }
    checks.instanceMatrix.needsUpdate = true;
    titleHandle.set('progress', { text: total + ' of 21 check-ins this week' });
  }

  function toggle(h, d) {
    state[h][d] = !state[h][d];
    const t = tiles[h * 7 + d];
    t.pop = 1;
    refresh();
  }

  refresh();

  // ---------------------------------------------------------------- update
  return {
    root,
    update(time, delta) {
      const step = Math.min(delta, 0.1);
      const k = 1 - Math.pow(0.0005, step);
      for (let i = 0; i < tiles.length; i++) {
        const t = tiles[i];
        if (t.pop > 0) t.pop = Math.max(0, t.pop - step * 3.5);
        const base = state[t.h][t.d] ? 1.07 : 1.0;
        const target = base + t.pop * 0.22;
        const cur = t.mesh.scale.x;
        t.mesh.scale.setScalar(cur + (target - cur) * k);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
