    new THREE.MeshStandardMaterial({ color: 0x7a5228, roughness: 0.9, side: THREE.DoubleSide }),
  );
  base.rotation.x = -Math.PI / 2;
  base.position.y = 0.004;
  basket.add(base);

  root.add(basket);

  /* ----------------------------------------------------------------- fruits */
  const apple = new THREE.Mesh(
    new THREE.SphereGeometry(0.026, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0xd0342c, roughness: 0.45 }),
  );
  apple.name = 'Apple';
  apple.scale.set(1, 0.94, 1);
  const stem = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0022, 0.0028, 0.015, 6),
    new THREE.MeshStandardMaterial({ color: 0x5a3a1e, roughness: 0.9 }),
  );
  stem.position.y = 0.030;
  apple.add(stem);
  apple.position.set(-0.03, 0.026, 0.09);

  const banana = new THREE.Mesh(
    new THREE.TorusGeometry(0.030, 0.0105, 10, 30, 2.1),
