    new THREE.SphereGeometry(0.026, 24, 16),
    new THREE.MeshStandardMaterial({ color: 0xef8a1c, roughness: 0.85 }),
  );
  orange.name = 'Orange';
  orange.scale.set(1, 0.96, 1);
  orange.position.set(0.11, 0.026, 0.12);

  const HALF_PI = Math.PI / 2;

  const items = [
    {
      id: 'apple', label: 'Apple', price: 1.25, obj: apple, restY: 0.026,
      home: new THREE.Vector3(-0.03, 0.026, 0.09),
      slot: new THREE.Vector3(BX + 0.028, 0.032, BZ + 0.016),
      slotRot: [0, 0, 0],
    },
    {
      id: 'banana', label: 'Banana', price: 0.60, obj: banana, restY: 0.012,
      home: new THREE.Vector3(0.05, 0.012, 0.035),
      slot: new THREE.Vector3(BX, 0.040, BZ - 0.024),
      slotRot: [-HALF_PI, 0, 0],
    },
    {
      id: 'orange', label: 'Orange', price: 1.10, obj: orange, restY: 0.026,
      home: new THREE.Vector3(0.11, 0.026, 0.12),
      slot: new THREE.Vector3(BX - 0.028, 0.032, BZ + 0.014),
      slotRot: [0, 0, 0],
    },
  ];

  for (const it of items) {
    it.inBasket = false;
    it.wasGrabbed = false;
    root.add(it.obj);
  }

  /* ------------------------------------------------------------------ panel */
  const info = ui(`
    <style>
      .card { flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1b1f25; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .hint { color: #98a2b0; font-size: 18px; }
      .row { display: flex; flex-direction: row; justify-content: space-between; align-items: center;
             padding-top: 7px; padding-bottom: 7px; padding-left: 12px; padding-right: 12px;
             border-radius: 10px; background-color: #24282f; }
      .name { color: #e7ebf0; font-size: 21px; }
      .price { color: #e7ebf0; font-size: 21px; font-weight: 700; }
      .totalRow { display: flex; flex-direction: row; justify-content: space-between; align-items: center;
                  padding-top: 6px; padding-bottom: 2px; padding-left: 12px; padding-right: 12px; }
      .totalLabel { color: #98a2b0; font-size: 20px; }
      .totalValue { color: #6fe3a0; font-size: 28px; font-weight: 700; }
      .btn { display: flex; flex-direction: row; align-items: center; justify-content: center;
             padding-top: 9px; padding-bottom: 9px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btnText { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="hint" id="hint">Pinch a fruit and drop it in the basket.</span>
      <div class="row" id="row-apple">
        <span class="name" id="apple-name">Apple</span>
        <span class="price" id="apple-price">$1.25</span>
      </div>
      <div class="row" id="row-banana">
        <span class="name" id="banana-name">Banana</span>
        <span class="price" id="banana-price">$0.60</span>
      </div>
      <div class="row" id="row-orange">
        <span class="name" id="orange-name">Orange</span>
        <span class="price" id="orange-price">$1.10</span>
      </div>
      <div class="totalRow">
        <span class="totalLabel">Basket total</span>
        <span class="totalValue" id="total">$0.00</span>
      </div>
      <button class="btn" id="empty"><span class="btnText">Empty the basket</span></button>
    </div>`, { width: 0.30, position: [-0.235, 0.175, -0.05], rotationY: 0.38 });
  root.add(info.object3D);

  function refresh() {
    let total = 0;
    for (const it of items) {
      if (it.inBasket) total += it.price;
      const col = it.inBasket ? '#8ef0b0' : '#e7ebf0';
      info.set(it.id + '-name', { color: col });
      info.set(it.id + '-price', { color: col });
      info.set('row-' + it.id, { backgroundColor: it.inBasket ? '#25402f' : '#24282f' });
    }
    info.set('total', { text: money(total) });
  }

  for (const it of items) {
    traits(it.obj, {
      grab: true,
      onPress: () => info.set('hint', { text: it.label + ' — ' + money(it.price) + ' each' }),
    });
  }

  info.on('empty', 'click', () => {
    for (const it of items) {
      it.inBasket = false;
      if (!isGrabbed(it.obj)) {
        it.obj.position.copy(it.home);
        it.obj.rotation.set(it.slotRot[0], it.slotRot[1], it.slotRot[2]);
      }
    }
    refresh();
    info.set('hint', { text: 'Basket emptied — try again.' });
  });

  refresh();

  /* ----------------------------------------------------------------- update */
  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);

      for (let i = 0; i < items.length; i++) {
        const it = items[i];
        const o = it.obj;

        if (isGrabbed(o)) {
          it.wasGrabbed = true;
          if (it.inBasket) { it.inBasket = false; refresh(); }
          continue;
        }

        // just released — did it land in the basket?
        if (it.wasGrabbed) {
          it.wasGrabbed = false;
          const dx = o.position.x - BX;
          const dz = o.position.z - BZ;
          if (dx * dx + dz * dz < RIM_R * RIM_R && o.position.y > -0.03 && o.position.y < 0.26) {
            it.inBasket = true;
            o.position.copy(it.slot);
            o.rotation.set(it.slotRot[0], it.slotRot[1], it.slotRot[2]);
            refresh();
            continue;
          }
        }

        if (it.inBasket) {
          o.position.lerp(it.slot, Math.min(1, 12 * dt));
        } else {
          if (o.position.y > it.restY) {
            o.position.y = Math.max(it.restY, o.position.y - 0.4 * dt);
          }
          if (o.position.x < -0.36) o.position.x = -0.36;
          else if (o.position.x > 0.36) o.position.x = 0.36;
          if (o.position.z < -0.22) o.position.z = -0.22;
          else if (o.position.z > 0.24) o.position.z = 0.24;
        }
      }
    },
  };
}

