  const bananaCurve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-0.052, 0.005, 0.028),
    new THREE.Vector3(-0.030, -0.012, 0.004),
    new THREE.Vector3(0.000, -0.016, -0.008),
    new THREE.Vector3(0.030, -0.012, 0.004),
    new THREE.Vector3(0.052, 0.005, 0.028),
  ]);
  const bananaBody = new THREE.Mesh(new THREE.TubeGeometry(bananaCurve, 20, 0.013, 8, false), bananaMat);
  bananaBody.name = 'BananaBody';
  bananaG.add(bananaBody);
  bananaG.position.set(0, 0.030, 0.12);
  root.add(bananaG);

  // ---------- orange ----------
  const orangeG = new THREE.Group();
  orangeG.name = 'Orange';
  const orangeBody = new THREE.Mesh(sphereGeo, orangeMat);
  orangeBody.name = 'OrangeBody';
  orangeG.add(orangeBody);
  const orangeStem = new THREE.Mesh(smallStemGeo, stemMat);
  orangeStem.position.set(0, 0.032, 0);
  orangeG.add(orangeStem);
  orangeG.position.set(0.16, 0.030, 0.12);
  root.add(orangeG);

  // ---------- fruit bookkeeping ----------
  const fruits = [
    { mesh: appleG, home: new THREE.Vector3(-0.16, 0.028, 0.12), homeY: 0.028, price: 1.20, nameId: 'nameA', inBasket: false, slot: 0 },
    { mesh: bananaG, home: new THREE.Vector3(0.00, 0.030, 0.12), homeY: 0.030, price: 0.50, nameId: 'nameB', inBasket: false, slot: 0 },
    { mesh: orangeG, home: new THREE.Vector3(0.16, 0.030, 0.12), homeY: 0.030, price: 0.90, nameId: 'nameO', inBasket: false, slot: 0 },
  ];

  // ---------- info / price panel ----------
  const info = ui(`
    <style>
      .card { display: flex; flex-direction: column; gap: 6px; width: 520px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
              background-color: #1f2228; border-radius: 18px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .hint { color: #9aa3af; font-size: 19px; }
      .row { display: flex; flex-direction: row; justify-content: space-between; align-items: center; }
      .name { color: #9aa3af; font-size: 22px; }
      .price { color: #e6e9ee; font-size: 22px; }
      .totrow { display: flex; flex-direction: row; justify-content: space-between; align-items: center;
                margin-top: 8px; }
      .totlabel { color: #ffffff; font-size: 24px; font-weight: 700; }
      .total { color: #ffd166; font-size: 26px; font-weight: 700; }
      .btn { display: flex; flex-direction: row; align-items: center; justify-content: center;
             margin-top: 8px; padding-top: 9px; padding-bottom: 9px; padding-left: 14px; padding-right: 14px;
             background-color: #2f6fdb; border-radius: 12px; }
      .btntext { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Fruit Basket</span>
      <span class="hint">Pinch a fruit and drop it into the basket.</span>
      <div class="row"><span class="name" id="nameA">Apple</span><span class="price">$1.20</span></div>
      <div class="row"><span class="name" id="nameB">Banana</span><span class="price">$0.50</span></div>
      <div class="row"><span class="name" id="nameO">Orange</span><span class="price">$0.90</span></div>
      <div class="totrow"><span class="totlabel">Total</span><span class="total" id="total">$0.00</span></div>
      <button class="btn" id="reset"><span class="btntext">Empty basket</span></button>
    </div>`, { width: 0.26, position: [0.25, 0.17, 0.02], rotationY: -0.42 });
  root.add(info.object3D);

  // ---------- basket state ----------
  const contents = [];

  function refreshUI() {
    let total = 0;
    for (let i = 0; i < fruits.length; i++) {
      const f = fruits[i];
      if (f.inBasket) total += f.price;
      info.set(f.nameId, { color: f.inBasket ? '#8fe39a' : '#9aa3af' });
    }
    info.set('total', { text: '$' + total.toFixed(2) });
  }

  function addToBasket(f) {
    if (f.inBasket) return;
    f.inBasket = true;
    contents.push(f);
    f.slot = contents.length - 1;
    refreshUI();
  }

  function removeFromBasket(f) {
    if (!f.inBasket) return;
    const i = contents.indexOf(f);
    if (i >= 0) contents.splice(i, 1);
    f.inBasket = false;
    for (let k = 0; k < contents.length; k++) contents[k].slot = k;
    refreshUI();
  }

  info.on('reset', 'click', () => {
    for (let i = 0; i < fruits.length; i++) {
      const f = fruits[i];
      if (isGrabbed(f.mesh)) continue;
      f.inBasket = false;
      f.mesh.position.copy(f.home);
    }
    contents.length = 0;
    refreshUI();
  });

  refreshUI();

  // ---------- hand interaction ----------
  for (let i = 0; i < fruits.length; i++) {
    traits(fruits[i].mesh, { grab: true });
  }

  // ---------- per-frame motion ----------
  const tmpTarget = new THREE.Vector3();
  const tmpDelta = new THREE.Vector3();

  function moveTowards(pos, target, maxStep) {
    tmpDelta.subVectors(target, pos);
    const d = tmpDelta.length();
    if (d <= maxStep) {
      pos.copy(target);
      return;
    }
    pos.addScaledVector(tmpDelta, maxStep / d);
  }

  return {
    root,
    update(time, delta) {
      const step = SLOW * Math.min(delta, 0.05);
      for (let i = 0; i < fruits.length; i++) {
        const f = fruits[i];
        const mesh = f.mesh;

        if (isGrabbed(mesh)) {
          if (f.inBasket) removeFromBasket(f); // taking it out refunds it
          continue;
        }

        if (!f.inBasket) {
          const dx = mesh.position.x - BX;
          const dz = mesh.position.z - BZ;
          if (dx * dx + dz * dz < DROP_R2 && mesh.position.y < 0.20) {
            addToBasket(f);
          }
        }

        if (f.inBasket) {
          const a = (f.slot / 3) * Math.PI * 2 + Math.PI / 2;
          tmpTarget.set(
            BX + Math.cos(a) * SLOT_R,
            FLOOR_TOP + f.homeY,
            BZ + Math.sin(a) * SLOT_R,
          );
        } else {
          tmpTarget.copy(f.home);
        }
        moveTowards(mesh.position, tmpTarget, step);
      }
    },
  };
}
